local E = ns.DB.entries
E["npc:amber-kearnen"] = {t="npc",n="Amber Kearnen",z="stormwind",s="Amber Kearnen is a sharp-eyed operative of SI:7 stationed deep in Westfall. From her concealed vantage point overlooking the plains, she monitors the illicit activities of the Defias Brotherhood on behalf of Master Mathias Shaw.",h="Amber Kearnen is a sharp-eyed operative of SI:7 stationed deep in Westfall.",sec={{t="Eyes on the Tower",b="Ranked as a Ground Level Operative within SI:7, Amber Kearnen serves as one of Stormwind's most trusted field scouts. Rather than walking the halls of Stormwind Keep, she operates under the open skies of Westfall, watching over an abandoned watchtower commandeered by the Defias Brotherhood. Under the direct leadership of Master Mathias Shaw, Kearnen provides critical oversight and briefing for covert operatives sent to neutralize Defias threats and gather intelligence across the contested countryside.",sp=0},{t="A Deadly Assignment",b="Her vigilance is concentrated on Klaven Mortwake, an operative of the Defias Brotherhood who has fortified himself in the coastal watchtower. Kearnen aids infiltrating rogues with reconnaissance and sniper support, guiding them past patrolling sentries to reach Klaven's sanctum and secure his clandestine journal. Her sharp marksmanship and steady hand make her indispensable to the Crown's shadow operations against the rebellion.",sp=1}},faq={{q="Who is Amber Kearnen?",a="Amber Kearnen is an operative of SI:7, Stormwind's elite intelligence division. She serves as a ground-level scout and sniper, currently tasked with tracking Defias operations in Westfall.",al={"amber kearnen","who is kearnen","agent kearnen"}},{q="Where can Amber Kearnen be found?",a="She is positioned in the wilds of Westfall, keeping watch near the abandoned Alliance watchtower occupied by the Defias Brotherhood.",al={"amber kearnen location","where is kearnen","where is amber kearnen"}},{q="What is her connection to Mathias Shaw?",a="She answers directly to Master Mathias Shaw, the leader of SI:7. Shaw holds her abilities in the highest regard, trusting her to guide high-priority covert missions in the field.",al={"kearnen mathias shaw","who does kearnen work for"}},{q="What role does she play in Klaven's Tower?",a="Kearnen monitors the watchtower held by Klaven Mortwake. She briefs Alliance rogues dispatched by SI:7, providing the tactical oversight needed to slip inside, bypass Defias guards, and retrieve Klaven's journal.",al={"klavens tower","amber kearnen klavens tower","what does she do at the tower"}}},ang={["class:Rogue"]="For Alliance rogues proving their tradecraft, Agent Kearnen serves as your primary contact in the field, helping coordinate the infiltration of Klaven's Tower.",["faction:Alliance"]="Kearnen represents Stormwind's proactive covert wing, working behind enemy lines in Westfall to undermine the Defias Brotherhood without alarming the populace."},kw={"amber","defias","kearnen","klaven mortwake","klaven's tower","mathias shaw","rogue","si:7","sniper","westfall"},rel={"npc:mathias-shaw","quest:2359","topic:defias-brotherhood","zone:westfall","quest:2300","topic:alliance"},src={"Amber Kearnen"}}
E["npc:anchorite-delan"] = {t="npc",n="Anchorite Delan",z="stormwind",s="Anchorite Delan is a draenei priest stationed inside Darkshire Town Hall in Duskwood. Hearing of the blighted forest's pervasive undeath and malevolent shadows, he traveled here to offer the Light's guidance and aid the embattled townspeople.",h="Anchorite Delan is a draenei priest stationed inside Darkshire Town Hall in Duskwood.",sec={{t="A Light in the Shadows",b="When word reached the draenei of Duskwood's dire predicament—a realm suffocated by creeping shadows, ravenous beasts, and relentless undead—Anchorite Delan took it upon himself to journey south. Stationing himself within the Darkshire Town Hall alongside local administrators, he works tirelessly to offer the holy solace of the Light to the beleaguered citizenry. Coordinating alongside representatives like Emissary Taluun, Delan directs willing travelers to lend a hand wherever the town's beleaguered Night Watch cannot stretch.",sp=0}},faq={{q="Who is Anchorite Delan?",a="Anchorite Delan is a draenei priest residing in Darkshire Town Hall. Moved by accounts of the encroaching undead and dark magic menacing Duskwood, he journeyed to the town to help the residents resist the lingering evil.",al={"delan darkshire","who is anchorite delan","draenei in darkshire"}},{q="What is an anchorite?",a="Among the draenei, an anchorite is a dedicated priest and spiritual guide devoted to the Holy Light. They minister to the spiritual welfare of their people and actively battle unholy forces and despair.",al={"what is an anchorite","draenei anchorites","anchorite meaning"}},{q="Why did Anchorite Delan come to Darkshire?",a="Delan came to Darkshire specifically to counter the undeath and darkness plaguing the region. Duskwood's desperate struggles drew him to offer spiritual protection and direct able-bodied adventurers to assist the embattled locals.",al={"why is delan here","delan purpose duskwood","why draenei in duskwood"}},{q="How is Delan connected to Emissary Taluun?",a="Emissary Taluun directs travelers from Stormwind toward Darkshire to meet Delan. Upon their arrival, Delan urges these adventurers to protect the citizens and turn back the shadows menacing the region.",al={"emissary taluun connection","taluun delan","travel to darkshire quest"}}},ang={["class:Priest"]="Priests will recognize a fellow devotee of the Light in Delan, who chose to bring comfort and holy protection to one of the most haunted and dangerous settlements in the Eastern Kingdoms.",["faction:Alliance"]="Delan represents the bonds forming between the newly arrived draenei and established Alliance communities, stepping forward to aid human settlements in dire need."},kw={"anchorite delan","darkshire","delan","draenei","duskwood","taluun","town hall"},rel={"subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood"},src={"Anchorite Delan"}}
E["npc:archmage-malin"] = {t="npc",n="Archmage Malin",z="stormwind",s="Archmage Malin is a senior human wizard stationed just outside the Wizard's Sanctum in Stormwind City's Mage Quarter. A former pupil of Archmage Trelane, Malin coordinates arcane affairs and field operatives dispatched to recover magical artifacts and rare reagents across the Eastern Kingdoms.",h="Archmage Malin is a senior human wizard stationed just outside the Wizard's Sanctum in Stormwind City's Mage...",sec={{t="Watcher of the Wizard's Sanctum",b="Standing sentinel beneath the towering spiral of the Wizard's Sanctum, Archmage Malin serves as a central point of contact for the arcane practitioners of Stormwind. He learned his craft under the tutelage of Archmage Trelane, a storied mage whose scattered legacy Malin now strives to protect. While younger acolytes study theory within the tower's swirling blue portals, Malin keeps his focus trained outward on matters across the realm that demand magical oversight.",sp=0},{t="Eyes in the Highlands",b="Much of Malin's attention is directed north to the perilous ruins of the Arathi Highlands. To recover Archmage Trelane's lost possessions and secure delicate spell components, Malin dispatched his trusted associates, Skuerto and Apprentice Kryten, into the field. Coordinating these distant operations from the capital, Malin relies on capable Alliance travelers to carry instructions, supplies, and intelligence to his agents operating in hostile territory.",sp=0}},faq={{q="Who is Archmage Malin?",a="Archmage Malin is a high-ranking human mage of Stormwind City. Positioned outside the entrance to the Wizard's Sanctum in the Mage Quarter, he oversees research initiatives, dispatches field apprentices, and helps maintain order among the capital's magical practitioners.",al={"archmage malin lore","who is malin","malin stormwind"}},{q="What is Malin's connection to Archmage Trelane?",a="Archmage Trelane was Malin's original master and mentor. Malin retains deep loyalty to Trelane, actively coordinating efforts to locate and recover his former master's personal belongings and magical relics scattered across the Arathi Highlands.",al={"malin trelane","who was malin master","archmage trelane connection"}},{q="Why does Malin send adventurers to the Arathi Highlands?",a="Malin has two agents stationed in the Arathi Highlands: Skuerto and Apprentice Kryten. Because the journey is dangerous and communication difficult, Malin enlists traveling adventurers to reach his field operatives with vital requests, magical supplies, and instructions regarding the recovery of Trelane's artifacts.",al={"malin request quest","why arathi","skuerto quest"}},{q="Where can Archmage Malin be found?",a="He stands outside the base of the Wizard's Sanctum tower, at the heart of the Mage Quarter in Stormwind City, overlooking the ramps that lead up into the sanctum's portal chamber.",al={"where is malin","archmage malin location","malin map"}}},ang={["class:Mage"]="For Alliance mages visiting the Wizard's Sanctum, Malin represents the bridge between formal academy study in Stormwind and the hazardous realities of recovering lost relics in the wild.",["faction:Alliance"]="Malin's operatives in Arathi work to secure powerful artifacts before they can fall into the hands of the Syndicate, the Boulderfist ogres, or the Horde."},kw={"arathi highlands","archmage malin","kryten","mage quarter","malin","skuerto","stormwind","trelane","wizard's sanctum"},rel={"subzone:mage-quarter","zone:stormwind","npc:skuerto","quest:690","zone:arathi","subzone:sanctum-stromgarde-keep","topic:alliance","topic:stormwind-kingdom"},src={"Archmage Malin"}}
E["npc:argos-nightwhisper"] = {t="npc",n="Argos Nightwhisper",z="stormwind",s="Argos Nightwhisper is a night elf emissary found in the Park district of Stormwind City. He serves as an Alliance contact directing adventurers toward Teldrassil to aid his people against spreading corruption.",h="Argos Nightwhisper is a night elf emissary found in the Park district of Stormwind City.",sec={{t="A Kaldorei in the Human Capital",b="Argos Nightwhisper resides among the growing night elf presence in Stormwind, often lingering in the lush, secluded Park district crafted to remind the kaldorei of their ancestral woodlands. Like many of his kin stationed in the human kingdom, Argos acts as a bridge between the newfound allies across the Great Sea. Deeply concerned by reports filtering across the ocean, he urges capable Alliance champions to journey west to Darnassus and assist in purging the dark taint creeping through the roots of Teldrassil.",sp=0}},faq={{q="Who is Argos Nightwhisper?",a="Argos Nightwhisper is a night elf residing in Stormwind City. He represents the interests of Darnassus in the eastern Alliance capital, helping organize travelers and directing adventurers to take passage to Kalimdor.",al={"argos nightwhisper","who is argos","argos stormwind"}},{q="Where can Argos Nightwhisper be found?",a="In Stormwind, night elves commonly gather in the Park, an enclave shaped with moonwells and greenery to suit kaldorei customs.",al={"argos location","where is argos","find argos nightwhisper"}},{q="What does Argos ask adventurers to do?",a="Argos directs Alliance adventurers to travel abroad to Teldrassil. He warns of spreading corruption threatening the woodlands of Kalimdor and sends capable fighters to report to night elf authorities in Darnassus.",al={"corruption abroad quest","argos quest","why go to darnassus"}},{q="Is Argos related to other Nightwhispers?",a="While he shares his family name with other night elves such as Falorn and Evelle Nightwhisper, he keeps to his duties connecting the capital of Stormwind with Darnassus.",al={"nightwhisper family","argos relatives"}}},ang={["race:NightElf"]="For kaldorei traveling far from Kalimdor, Argos is a familiar face coordinating passage back to Teldrassil and keeping an eye on threats endangering the home boughs.",["faction:Alliance"]="Argos serves as an early link between the Eastern Kingdoms and Kalimdor, encouraging young Alliance heroes to cross the sea and aid the night elves."},kw={"argos","corruption abroad","darnassus","kaldorei","nightwhisper","park","stormwind","teldrassil"},rel={"subzone:park","zone:darnassus","quest:3765","topic:night-elf","topic:stormwind-kingdom"},src={"Argos Nightwhisper"}}
E["npc:baros-alexston"] = {t="npc",n="Baros Alexston",z="stormwind",s="Baros Alexston is the Chief Architect of Stormwind City, stationed within the City Hall overlooking Cathedral Square. A former member of the Stonemasons Guild who helped rebuild the capital after the First War, he chose to accept an official post rather than follow his old friend Edwin VanCleef into open rebellion.",h="Baros Alexston is the Chief Architect of Stormwind City, stationed within the City Hall overlooking Cathedral...",sec={{t="From the Farmstead to the Scaffold",b="Baros grew up on the Alexston Farmstead in the rolling grasslands of Westfall. During his youth, thieves overran and torched his family's homestead, forcing his father to hurriedly stash their most cherished heirlooms across the grounds before fleeing. Baros eventually journeyed to the capital and joined the Stonemasons Guild, dedicating years of grueling labor alongside Guildmaster Edwin VanCleef to raise Stormwind anew from the ashes of the First War.",sp=0},{t="A Bitter Parting of Ways",b="When the rebuilding drew to an end, the House of Nobles reneged on the agreed payment, leading to furious protests, the dissolution of the Stonemasons Guild, and deadly street riots. As VanCleef led the disenfranchised artisans into exile to form the Defias Brotherhood, the nobles offered Baros the prestigious position of City Architect on the condition that he disavow the uprising. Harboring ideological disagreements with the guild's path toward violent banditry, Baros accepted the offer, cementing a tragic rift between himself and his former comrades.",sp=1},{t="The Ghost in the Dead Mines",b="From his desk in City Hall, Baros continues overseeing the maintenance of the capital, carrying political ties that include a discreet favor owed to him by Mathias Shaw of SI:7. Yet his past refuses to stay buried. Following the fall of VanCleef within the depths of the Deadmines, an unsent letter addressed personally to Baros rests upon the Defias leader's corpse—a testament to a bond severed by politics, treason, and the blood shed over Stormwind's foundation stones.",sp=1}},faq={{q="Where can I find Baros Alexston?",a="Baros Alexston is stationed inside Stormwind City Hall, situated right along the northern side of Cathedral Square in Stormwind City.",al={"baros alexston location","where is baros alexston","baros stormwind"}},{q="What is Baros Alexston's role in Stormwind?",a="He serves as the Chief Architect of Stormwind City. He manages the ongoing construction, municipal upkeep, and architectural planning of the capital.",al={"baros job","baros title","what does baros do"}},{q="How does Baros know Edwin VanCleef?",a="They were close colleagues in the Stonemasons Guild who labored side by side rebuilding Stormwind after the First War. When the House of Nobles refused to pay the workers, VanCleef led a rebellion, whereas Baros stayed behind to accept the post of City Architect.",al={"baros and vancleef","did baros know edwin","baros stonemasons"}},{q="Why didn't Baros join the Defias Brotherhood?",a="Baros held ideological disagreements with the guild's descent into violent revolt. When the House of Nobles offered him the position of City Architect if he refused to follow VanCleef, Baros chose civic order over an outlaw life.",al={"why did baros stay","baros defias split","why did baros betray stonemasons"}},{q="What is the unsent letter found on Edwin VanCleef?",a="Upon Edwin VanCleef's death in the Deadmines, adventurers recover an unsent letter written directly to Baros Alexston, revealing lingering personal resentment and unresolved history between the two former craftsmen.",al={"unsent letter quest","vancleef unsent letter","letter to baros"},sp=1},{q="What is Baros Alexston's connection to Westfall?",a="Baros grew up on the Alexston Farmstead in Westfall. His family fled after thieves burned the property, and Baros later recruits adventurers to reclaim his childhood possessions, including his very first compass.",al={"alexston farmstead","baros westfall","baros childhood"}}},ang={["faction:Alliance"]="Baros Alexston represents the painful compromises made within the Alliance, illustrating how the betrayal of the Stonemasons Guild tore apart craftsmen who poured their lives into rebuilding the capital.",["class:Rogue"]="For rogues navigating the shadows of the capital, Baros provides a link to Master Mathias Shaw and SI:7, who hold quiet debts to the architect despite his past ties to VanCleef.",["race:Human"]="Human adventurers from Westfall will recognize Baros's surname from the overgrown, ruined farmstead now overrun by thieves and gnolls."},kw={"alexston","architect","baros","cathedral square","city hall","defias","farmstead","stonemasons","unsent letter","vancleef"},rel={"npc:edwin-vancleef","topic:stonemasons-guild","topic:defias-brotherhood","quest:373","quest:399","subzone:alexston-farmstead","npc:mathias-shaw","topic:house-of-nobles"},src={"Baros Alexston"}}
E["npc:bartleby"] = {t="npc",n="Bartleby",z="stormwind",s="Bartleby is a bellicose drunkard loitering within the Pig and Whistle Tavern in Stormwind's Old Town. Known for his stubborn grip on his ale, he serves as an early martial test for aspiring warriors looking to prove their mettle in a good old-fashioned tavern brawl.",h="Bartleby is a bellicose drunkard loitering within the Pig and Whistle Tavern in Stormwind's Old Town.",sec={{t="A Fixture at the Pig and Whistle",b="Tucked away in the narrow, cobblestone alleys of Old Town, the Pig and Whistle Tavern draws a rougher, more weathered crowd than the pristine taprooms of the Cathedral Square. Bartleby is one of its most persistent fixtures. Clinging tightly to his favorite mug and fueled by cheap ale, he spends his days nursing grievances and picking fights with anyone unfortunate enough to disturb his drinking.",sp=0},{t="A Warrior's Rite of Passage",b="While Bartleby looks like any other neighborhood drunk, Stormwind's warrior trainers see practical value in him. Harry Burlguard regularly directs fledgling fighters to track Bartleby down and relieve him of his mug. Reclaiming the heirloom requires trading bare-knuckle blows with the intoxicated brawler, proving whether a novice warrior possesses the grit to handle an unruly opponent up close.",sp=0}},faq={{q="Who is Bartleby?",a="Bartleby is an unruly tavern patron residing in the Pig and Whistle Tavern in Stormwind City's Old Town. He is known for getting thoroughly intoxicated and refusing to part with his mug without a fistfight.",al={"bartleby lore","who is bartleby","bartleby stormwind"}},{q="Where can I find Bartleby?",a="You can find Bartleby drinking on the ground floor of the Pig and Whistle Tavern, located in the Old Town district of Stormwind.",al={"bartleby location","where is bartleby","bartleby pig and whistle"}},{q="Why do warriors need to fight him?",a="Harry Burlguard, a warrior trainer in Old Town, sends young recruits to Bartleby as a trial of raw combat ability. Taking Bartleby's mug by force demonstrates that a recruit can handle unexpected physical brawls and overcome tough, stubborn opposition.",al={"why beat bartleby","warrior quest bartleby","bartleby purpose"}},{q="What happens when you confront him?",a="When challenged for his prized mug, Bartleby drinks a potion to bolster his fortitude and turns hostile, initiating an unarmed brawl right in the middle of the tavern until he is beaten into submission.",al={"fight bartleby","beat bartleby quest","bartleby brawl"}},{q="Does Bartleby belong to any faction or organization?",a="Bartleby is simply a civilian citizen of Stormwind and a habitual drunkard. He has no known affiliations with criminal syndicates like the Defias Brotherhood or the city guard.",al={"is bartleby defias","bartleby faction","bartleby alliance"}},{q="Why won't he just hand over his mug?",a="Bartleby is belligerent, heavily intoxicated, and obstinate. He views anyone asking for his drink or mug as an insult, preferring to settle the matter with his fists rather than part with his booze.",al={"bartlebys mug","bartleby ale mug","why fight for mug"}}},ang={["class:Warrior"]="Every young warrior training in Stormwind remembers their duel with Bartleby. Disarming a stubborn drunk of his mug serves as a memorable rite of passage in hand-to-hand combat.",["race:Human"]="Bartleby represents the gritty, working-class side of Stormwind's Old Town, where local disputes are settled over overturned barstools rather than royal decree."},kw={"bartleby","brawl","burlguard","drunk","mug","old town","pig and whistle","tavern","warrior"},rel={"subzone:pig-and-whistle-tavern","quest:1640","quest:1639","quest:1665","subzone:old-town","zone:stormwind","topic:stormwind-kingdom"},src={"Bartleby"}}
E["npc:bishop-delavey"] = {t="npc",n="Bishop DeLavey",z="stormwind",s="Bishop DeLavey is a senior representative of the Church of the Holy Light stationed within the Petitioner's Chamber in Stormwind Keep. Acting on matters of state and faith, he quietly oversees sensitive court affairs that the Crown cannot publicly address.",h="Bishop DeLavey is a senior representative of the Church of the Holy Light stationed within the Petitioner's...",sec={{t="A Bishop at Court",b="While Archbishop Benedictus tends to the Cathedral of Light, Bishop DeLavey resides among the nobility and petitioners of Stormwind Keep. He serves as an ecclesiastical liaison to the court, balancing spiritual counsel with the kingdom's political reality. His position allows him to hear whispered rumors and delicate palace grievances before they ever reach the ears of Highlord Bolvar Fordragon or the young King Anduin.",sp=0},{t="A Delicate Inquiry",b="When a vital diplomat dispatched to meet Lady Jaina Proudmoore in Theramore failed to arrive, the court kept the disappearance under strict secrecy to avoid widespread panic. Suspecting the insidious reach of the Defias Brotherhood, DeLavey bypassed normal guard protocols. Instead, he mobilized private channels and discreet adventurers, using contacts like the fisherman Jorgen to establish ties with covert informants such as Elling Trias.",sp=1}},faq={{q="Where can Bishop DeLavey be found?",a="Bishop DeLavey stands inside the Petitioner's Chamber within Stormwind Keep, just off the main entryway where subjects gather to petition the royal court.",al={"delavey location","where is bishop delavey","delavey keep"}},{q="What is his role in Stormwind Keep?",a="He represents the Church of the Holy Light at the royal court, managing ecclesiastical affairs, advising nobility, and handling sensitive issues for the kingdom discreetly.",al={"delavey job","who is bishop delavey","what does delavey do"}},{q="Why is he investigating the missing diplomat?",a="The diplomat vanished en route to meet Lady Jaina Proudmoore in Theramore. DeLavey suspects Defias interference and uses quiet, trusted channels to investigate before news of the crisis can panic the public.",al={"missing diplomat delavey","why does delavey care about the diplomat"}},{q="How is DeLavey connected to Elling Trias?",a="DeLavey utilizes a network of intermediaries, including the fisherman Jorgen, to pass messages to Elling Trias—a master of cheese who secretly gathers intelligence for SI:7.",al={"delavey and trias","delavey si7 contact"},sp=1}},ang={["class:Priest"]="DeLavey exemplifies the church's deep political involvement in Stormwind, showing that faith in the Holy Light often intersects with statecraft and covert affairs.",["faction:Alliance"]="His clandestine investigation seeks to protect the fragile peace between Stormwind and Lady Jaina Proudmoore's outpost of Theramore."},kw={"bishop delavey","delavey","elling trias","holy light","jorgen","missing diplomat","petitioner's chamber","stormwind keep"},rel={"quest:1241","subzone:petitioner-s-chamber","subzone:stormwind-keep","npc:elling-trias","npc:jorgen","npc:jaina-proudmoore","topic:defias-brotherhood","topic:church-of-the-holy-light"},src={"Bishop DeLavey"}}
E["npc:bolvar-fordragon"] = {t="npc",n="Bolvar Fordragon",z="stormwind",s="Highlord Bolvar Fordragon serves as the Regent of Stormwind and Supreme Commander of its armed forces following the mysterious disappearance of King Varian Wrynn. Standing beside the young boy-king Anduin Wrynn in Stormwind Keep, he strives to hold the kingdom together amid escalating domestic turmoil. Though fiercely honorable, Bolvar often finds his martial decisions influenced and stalled by royal advisor Lady Katrana Prestor.",h="Highlord Bolvar Fordragon serves as the Regent of Stormwind and Supreme Commander of its armed forces...",sec={{t="Regent of the Realm",b="When King Varian vanished en route to a peace summit on Theramore Isle, Stormwind was thrown into political disarray. Ten-year-old Prince Anduin was crowned to maintain continuity, but actual governing power fell to Highlord Bolvar Fordragon as Regent. Bolvar is a venerated paladin devoted to the crown, yet he faces immense strain. Stormwind's military is thinly stretched across Westfall, Redridge, and Duskwood. Compounding these crises, Bolvar frequently defers to the counsel of Lady Katrana Prestor, whose dismissive advice consistently blocks him from committing royal troops to peripheral towns.",sp=0},{t="A Web of Deceit",b="Behind the scenes in the royal court, Bolvar's hands are tied tighter than he realizes. While town magistrates and frontier marshals beg for reinforcements against the Defias Brotherhood and Blackrock orcs, Lady Prestor subtly manipulates royal decrees and belittles all reports of danger. Bolvar respects the nobility's counsel and hesitates to move without undeniable proof, unwittingly leaving the crown paralyzed. Only when compelling evidence arrives—such as investigative warnings from Theramore or missing field officers—does the Regent bypass standard court decorum to enlist independent adventurers.",sp=1}},faq={{q="Why is Bolvar ruling instead of King Varian?",a="King Varian Wrynn disappeared under suspicious circumstances while traveling by ship to a diplomatic summit at Theramore Isle. In his absence, Varian's ten-year-old son Anduin was crowned king to preserve political order, while Highlord Bolvar was appointed Regent to govern the kingdom and command its armies until the king is found.",al={"where is the king","why is bolvar in charge","who is the regent"}},{q="Why won't Bolvar send soldiers to help Redridge or Westfall?",a="Stormwind's standing armies are stretched thin guarding the core territories and borders. Furthermore, Bolvar's chief advisor, Lady Katrana Prestor, repeatedly questions the urgency of reports from places like Lakeshire, calling them exaggerations and advising against allocating royal forces. Lacking military proof, Bolvar instead deputizes independent adventurers to intervene.",al={"why no stormwind army","why won't bolvar send help","lakeshire troops"}},{q="What is Bolvar's relationship with Lady Katrana Prestor?",a="Lady Katrana Prestor is the premier royal councilor to the throne of Stormwind. Bolvar respects her political acumen and deep knowledge of noble affairs. However, she continually uses her influence to counsel restraint, urging him to dismiss rumors of dragons, orcs, and Defias plots.",al={"bolvar and prestor","who is lady prestor to bolvar"}},{q="What is Bolvar's connection to young Prince Anduin?",a="Bolvar is not related to Anduin, but he acts as the young king's fierce protector, guardian, and mentor. Bolvar stands beside Anduin's throne in Stormwind Keep, shielding the boy from court intrigue and ensuring that the Wrynn dynasty remains secure until Varian returns.",al={"anduin and bolvar","is bolvar anduin's father"}}},ang={["class:Paladin"]="Bolvar represents the pinnacle of the Alliance's martial paladins, embodying steadfast devotion to the Light and unyielding duty to his people despite mounting political subterfuge.",["faction:Alliance"]="As Supreme Commander of Stormwind, Bolvar is the administrative head of the human military, balancing localized rebellions with broader Alliance obligations."},kw={"anduin wrynn","bolvar","fordragon","highlord","katrana prestor","regent","stormwind keep"},rel={"npc:anduin-wrynn","npc:onyxia","zone:stormwind","topic:varian-wrynn","topic:defias-brotherhood","npc:magistrate-solomon","subzone:theramore-isle","npc:jaina-proudmoore"},src={"Bolvar Fordragon"}}
E["npc:brother-kristoff"] = {t="npc",n="Brother Kristoff",z="stormwind",s="Brother Kristoff is a human member of the Church of the Holy Light stationed in Stormwind's Cathedral Square. He can be found standing outdoors near the grand statue of Uther the Lightbringer. Preoccupied with theological study, he frequently seeks out practical literature to weave into sermons on spiritual strength.",h="Brother Kristoff is a human member of the Church of the Holy Light stationed in Stormwind's Cathedral Square.",sec={{t="A Preacher by the Statue",b="Brother Kristoff serves the Church of the Holy Light from the open courtyard of Cathedral Square, lingering in the shadow of the great monument to Uther the Lightbringer. Unlike some clerics who remain secluded within the marble cloisters of the Cathedral of Light, Kristoff works among the citizens and pilgrims passing through the plaza. In preparing his discourses—such as sermons on the Fortitude of the Spirit—he draws upon grounded, worldly analogies. He famously looks to technical treatises like 'The Stresses of Iron' to explain how the mortal soul endures pressure, comparing the inner resolve granted by the Holy Light to the tempered strength of worked metal.",sp=0}},faq={{q="Who is Brother Kristoff?",a="Brother Kristoff is a human priest and scholar of the Church of the Holy Light. He is stationed outside the Cathedral of Light in Stormwind's Cathedral Square, right near the monumental statue of Uther the Lightbringer.",al={"brother kristoff lore","who is kristoff","kristoff stormwind"}},{q="What does Brother Kristoff do in Cathedral Square?",a="Kristoff prepares sermons and addresses on matters of the Light and faith. Notably, he works on a lecture discussing the Fortitude of the Spirit, seeking out references from metallurgy texts to illustrate spiritual resilience.",al={"kristoff purpose","kristoff role","why is brother kristoff standing outside"}},{q="Why does Brother Kristoff need a book about iron?",a="Kristoff seeks the treatise 'The Stresses of Iron' to enrich his sermon on fortitude. He uses the material properties of iron under stress as an earthly metaphor to explain how devotion to the Holy Light fortifies the mortal spirit against adversity.",al={"the stresses of iron","speaking of fortitude book","why does kristoff want metallurgy"}}},ang={["class:Priest"]="Priests studying in Cathedral Square will appreciate Kristoff's grounded approach to the liturgy, as he draws on tangible, worldly arts to teach the deeper mysteries of inner fortitude.",["profession:Blacksmithing"]="Smiths may find it amusing that a cleric of the Light turns to texts on iron stresses and metallurgy to teach the clergy about resilience."},kw={"brother kristoff","cathedral of light","cathedral square","fortitude","kristoff","stresses of iron","uther statue"},rel={"subzone:cathedral-square","subzone:cathedral-of-light","topic:church-of-the-holy-light","quest:343","quest:346","topic:light","topic:stormwind-kingdom"},src={"Brother Kristoff"}}
E["npc:brother-wilhelm"] = {t="npc",n="Brother Wilhelm",z="stormwind",s="Brother Wilhelm is a human paladin trainer stationed in Goldshire within Elwynn Forest. Tucked away behind the village blacksmith, he instructs young defenders of the Holy Light taking their first steps outside Northshire Abbey.",h="Brother Wilhelm is a human paladin trainer stationed in Goldshire within Elwynn Forest.",sec={{t="A Guide in Goldshire",b="While Northshire Valley provides initial shelter for fledgling champions of the Light, those stepping into the broader world of Elwynn Forest often seek out Brother Wilhelm. Stationed just behind the busy smithy in Goldshire, he trains newly minted paladins in their sacred duties, providing guidance and lessons as they transition from abbey novices to sworn protectors of the realm.",sp=0},{t="The Path of the Tome",b="Wilhelm plays a crucial role in directing aspiring paladins along their holy journey, helping them seek out the Tome of Divinity. Through this vital rite, initiates learn the weight of sacrifice and the power of divine redemption, testing their devotion so they may wield the Light to resurrect fallen comrades and uphold justice across the Kingdom of Stormwind.",sp=0}},faq={{q="Where can I find Brother Wilhelm?",a="Brother Wilhelm is located in Goldshire in Elwynn Forest. He stands just behind the village blacksmith workshop, ready to train and guide aspiring paladins.",al={"wilhelm location","where is brother wilhelm","find brother wilhelm"}},{q="What services does Brother Wilhelm provide?",a="He serves as a paladin class trainer, teaching new spells, martial blessings, and holy techniques to young paladins adventuring through Elwynn Forest.",al={"what does wilhelm do","paladin trainer goldshire","brother wilhelm trainer"}},{q="Is Brother Wilhelm part of the Brotherhood of Northshire?",a="His title and proximity to Northshire Abbey suggest close ties to the holy orders of the Brotherhood of Northshire, though he operates primarily in service to the Church of the Holy Light and the Kingdom of Stormwind.",al={"is wilhelm brotherhood of northshire","wilhelm faction","who does brother wilhelm serve"}},{q="What is his role in the Tome of Divinity quest?",a="Wilhelm directs human paladins who have grown in power toward their sacred quest for the Tome of Divinity, guiding them through the trials necessary to earn the sacred blessing of resurrection.",al={"tome of divinity wilhelm","resurrection quest wilhelm","goldshire paladin quest"}}},ang={["class:Paladin"]="Brother Wilhelm is your first mentor once you leave Northshire Valley, guiding your growth and opening the sacred path toward mastering the Tome of Divinity.",["race:Human"]="A familiar face of the realm's holy tradition, Brother Wilhelm embodies the enduring faith of the Church of the Holy Light defending Elwynn's heartland."},kw={"brother wilhelm","brotherhood of northshire","elwynn forest","goldshire","holy light","paladin trainer","tome of divinity"},rel={"subzone:goldshire","zone:elwynn","quest:2997","topic:light","topic:brotherhood-of-northshire","topic:knights-of-the-silver-hand"},src={"Brother Wilhelm"}}
E["npc:collin-mauren"] = {t="npc",n="Collin Mauren",z="stormwind",s="Collin Mauren is a human mage residing in the Mage Quarter of Stormwind City. A scholarly researcher and crafter of incantations, he experiments with exotic natural reagents to devise unique utility spells. Among his pursuits is assisting his acquaintance, the gnome engineer and explorer Gaxim Rustfizzle, with specialized arcane scrolls.",h="Collin Mauren is a human mage residing in the Mage Quarter of Stormwind City.",sec={{t="Scholar of the Arcane",b="Situated within Stormwind's bustling Mage Quarter, Collin Mauren spends his days pursuing the quieter, more practical applications of magic. Rather than chasing raw elemental power, he focuses on crafting arcane formulas that solve specific, logistical problems. Collin often turns to natural anomalies and raw components scavenged across Azeroth, weaving their intrinsic properties into functional magic scrolls and reagents for friends and travelers alike.",sp=0},{t="Aiding Gaxim Rustfizzle",b="Collin maintains a close correspondence and friendship with the gnomish tinker Gaxim Rustfizzle. When Gaxim needed a reliable way to communicate across great distances during his travels, Collin designed a specialized messaging spell. To anchor the spell, he utilizes the whirling debris left behind by Westfall's erratic Dust Devils, capturing the essence of shifting wind to ensure long-distance messages reach his adventurous colleague.",sp=0},{t="Exotic Studies in Stonetalon",b="Beyond his work with local elementals, Collin's research extends clear across the Great Sea to the crags of Kalimdor. Curiously captivated by the resilient hides of basilisks native to the Stonetalon Mountains, Collin seeks out their scales to synthesize new spells. Travelers venturing into Kalimdor frequently receive his requests for these rare hides, fueling Collin's ongoing fascination with how primal creature anatomy can stabilize complex enchantments.",sp=0}},faq={{q="Where can Collin Mauren be found?",a="Collin Mauren is located in the Mage Quarter of Stormwind City, tucked among the towers and shops frequented by the capital's arcane scholars.",al={"collin mauren location","where is collin mauren","collin mauren stormwind"}},{q="What kind of magic does Collin specialize in?",a="Collin specializes in applied enchantments and utility spells. Rather than combat evocations, he experiments with raw natural components—such as elemental debris and beast scales—to devise long-distance messaging scrolls and unique dweomers.",al={"collin mauren research","what does collin mauren do","collin mauren magic"}},{q="Who is Gaxim Rustfizzle and how is Collin connected to him?",a="Gaxim Rustfizzle is an adventurous gnome tinkerer and a friend of Collin. Collin supports Gaxim's distant journeys by providing him with custom-crafted communication scrolls.",al={"gaxim rustfizzle friend","collin and gaxim","who is gaxim rustfizzle"}},{q="Why does Collin need elemental debris from Westfall?",a="Collin uses the essence of Westfall's elemental Dust Devils to power a messaging spell. The windy debris of the elementals carries the harmonic energy required to craft reliable communication scrolls.",al={"devils in westfall quest","why dust devils","westfall dust devils quest"}},{q="Why is Collin interested in the Stonetalon Mountains?",a="Collin studies the magical properties of basilisk scales native to the Stonetalon Mountains in Kalimdor. He uses their sturdy, naturally resistant hides as reagent bases to synthesize new incantations.",al={"stonetalon basilisks","retrieval for mauren","stonetalon scales collin"}},{q="Is Collin aligned with the Kirin Tor?",a="While Collin resides in the Mage Quarter and practices the traditions common among Alliance wizards, he functions primarily as an independent researcher and reagent crafter rather than an active Dalaran representative.",al={"is collin kirin tor","collin mauren dalaran","mage quarter collin"}}},ang={["class:Mage"]="Collin exemplifies the experimental craft of spell creation, demonstrating how earthly reagents like elemental debris and basilisk scales can be harnessed to weave utility magic.",["race:Human"]="Living quietly in Stormwind's Mage Quarter, Collin represents the scholarly pursuits of human wizards who study the broader world from the heart of the capital.",["faction:Alliance"]="Collin facilitates communication and trade across the Alliance by supplying adventurers with utility magic spanning from Westfall to Kalimdor."},kw={"basilisk","collin mauren","dust devils","gaxim rustfizzle","mage quarter","stonetalon","stormwind","westfall"},rel={"npc:gaxim-rustfizzle","subzone:mage-quarter","zone:stormwind","quest:1076","quest:1077","quest:1078","quest:1075","zone:westfall"},src={"Collin Mauren"}}
E["npc:count-remington-ridgewell"] = {t="npc",n="Count Remington Ridgewell",z="stormwind",s="Count Remington Ridgewell is a wealthy human aristocrat found in the Petitioner's Chamber within Stormwind Keep. As a member of the House of Nobles, he prides himself on curating the finest private collection of rare historical artifacts, heirlooms, and fine art in the kingdom.",h="Count Remington Ridgewell is a wealthy human aristocrat found in the Petitioner's Chamber within Stormwind...",sec={{t="A Connoisseur of Antiquities",b="Remington Ridgewell represents the elite tastes of the House of Nobles, taking immense pride in his family's personal museum of jewelry and artifacts. Rather than concerning himself with military campaigns or local uprisings, the Count spends his considerable wealth acquiring relics from fallen civilizations and fallen houses across Azeroth. To expand his prestigious gallery, he finances daring adventurers and employs field agents such as Mayara Brightwing, dispatching them to retrieve priceless oddities from perilous ruins, from the mountain redoubts of Alterac to the volcanic wastes of the Burning Steppes.",sp=0}},faq={{q="Who is Count Remington Ridgewell?",a="Count Remington Ridgewell is a human noble and collector of antiquities stationed in the Petitioner's Chamber of Stormwind Keep. He uses his family fortune to acquire valuable relics, jewels, and art from across the world.",al={"who is remington ridgewell","remington ridgewell","count ridgewell"}},{q="What artifacts does Count Ridgewell seek?",a="Ridgewell hires adventurers to recover lost heirlooms for his museum. Notable acquisitions include the Perenolde Tiara from the ruins of Alterac and historical Dark Iron dwarf treasures retrieved from the Ruins of Thaurissan.",al={"ridgewell quests","perenolde tiara quest","what does he want"}},{q="Who is Mayara Brightwing?",a="Mayara Brightwing is an agent employed by Count Ridgewell. He sent her to the Burning Steppes to scout for antiquities within the ancient Ruins of Thaurissan.",al={"mayara brightwing connection","who is mayara"}},{q="Where can Count Remington Ridgewell be found?",a="He resides in the Petitioner's Chamber inside Stormwind Keep, alongside various other nobles and dignitaries seeking audience with the royal court.",al={"where is count ridgewell","ridgewell location","petitioner's chamber noble"}}},ang={["faction:Alliance"]="For Alliance mercenaries, Count Ridgewell represents a lucrative patron willing to pay handsomely for reclaimed relics of fallen northern kingdoms and lost dwarven cities.",["race:Human"]="As a member of Stormwind's House of Nobles, Ridgewell exemplifies the wealthy aristocracy that prioritizes cultural prestige and art collecting despite the kingdom's political instability."},kw={"house of nobles","mayara brightwing","museum","perenolde tiara","petitioner's chamber","remington ridgewell","ridgewell","stormwind keep"},rel={"subzone:petitioner-s-chamber","subzone:stormwind-keep","quest:543","topic:house-of-nobles","topic:alterac-kingdom","subzone:ruins-of-thaurissan","subzone:ruins-of-alterac","zone:burningsteppes"},src={"Count Remington Ridgewell"}}
E["npc:daphne-stilwell"] = {t="npc",n="Daphne Stilwell",z="stormwind",s="Daphne Stilwell tends an isolated orchard nestled atop the coastal cliffs of Westfall overlooking the Longshore. Together with her husband Jordan, she fled turmoil in the north and relocated south, quietly aiding the Church of the Holy Light while defending her home from nearby outlaws.",h="Daphne Stilwell tends an isolated orchard nestled atop the coastal cliffs of Westfall overlooking the...",sec={{t="A Life on the Cliffs",b="Perched on the bluffs to the west of Moonbrook and the exit of the Deadmines, Daphne Stilwell manages a secluded homestead and apple orchard. From below along the Longshore or above on gryphon routes south to Stranglethorn Vale, the small farm looks quiet and unassuming. Yet running a homestead in modern Westfall is anything but safe. Despite the encroaching bandits and roaming scavengers, Daphne diligently works her trees and keeps watch over her isolated patch of land.",sp=0},{t="Refugees of the North",b="Before settling in the hills of Westfall, Daphne and her husband Jordan lived in Lordaeron near Pyrewood Village, working in what is now Shadowfang Keep. When darkness and disaster overtook the region, they were driven southward along with thousands of other human refugees. In Stormwind's orbit, Jordan's renowned craftsmanship and Daphne's steady presence led them to forge close ties with the Church of the Holy Light, providing support and holy arms to paladins of the Silver Hand.",sp=0},{t="Defending the Farm",b="Living so close to the Deadmines puts Daphne square in the path of the Defias Brotherhood. While Jordan travels or labors on forging holy weaponry outside the capital, Daphne is frequently left to maintain their coastal home alone. When brigands raided the farmstead seeking retribution or plunder, Daphne picked up arms and fought alongside aspiring paladins sent by the Cathedral, proving herself remarkably fierce and capable in the heat of battle.",sp=1}},faq={{q="Who is Daphne Stilwell?",a="Daphne Stilwell is a human homesteader living in an isolated farmhouse above Westfall's Longshore. She is the wife of the famed blacksmith Jordan Stilwell, with whom she escaped the devastated northern kingdoms.",al={"who is daphne","daphne stilwell info","stilwell wife"}},{q="Where did Daphne come from?",a="Daphne previously lived in the north near Pyrewood Village and worked at what is now known as Shadowfang Keep before calamity drove her and Jordan southward to the lands of Stormwind.",al={"daphne origin","where is daphne from","is daphne gilnean"}},{q="Why is her farm attacked by the Defias Brotherhood?",a="Her farm sits on the cliffs directly overlooking the southern waters of Westfall, right above the exit tunnels of the Deadmines. Its proximity to the Defias stronghold makes it an easy target for outlaws looking to raid supplies or remove meddlers.",al={"why do defias attack daphne","defias farm attack","stilwell farm bandits"}},{q="What is Daphne's connection to paladins?",a="Her husband Jordan aids the Church of the Holy Light by forging sanctified weapons. As part of their trials for the Tome of Valor, paladins of the Silver Hand are dispatched to Westfall to safeguard Daphne from bandit attacks.",al={"paladin quest daphne","tome of valor daphne","why do paladins visit daphne"}},{q="Can Daphne defend herself?",a="Yes. When the Defias assault her orchard, she does not cower; she draws a weapon and directly battles the attackers alongside any paladins defending the homestead.",al={"does daphne fight","is daphne a warrior"}},{q="How do you reach her farmhouse?",a="Her farm is tucked on the clifftops of south-western Westfall, situated southwest of Moonbrook near the Deadmines secret cove exit overlooking the Longshore.",al={"where is daphne farm","how to get to stilwell farm","daphne stilwell location"}}},ang={["class:Paladin"]="Daphne Stilwell is a vital figure in the trials of the Tome of Valor; defending her from ruthless Defias marauders proves a paladin's devotion to protecting the innocent.",["faction:Alliance"]="The Stilwells embody the plight of displaced northern refugees who continue to serve the Alliance and the Church of the Holy Light despite the perils of the Westfall frontier."},kw={"daphne stilwell","defias brotherhood","jordan stilwell","longshore","orchard","pyrewood village","shadowfang keep","tome of valor","westfall"},rel={"npc:jordan-stilwell","quest:1649","zone:westfall","subzone:longshore","topic:defias-brotherhood","topic:church-of-the-holy-light","zone:shadowfang","zone:deadmines"},src={"Daphne Stilwell"}}
E["npc:dashel-stonefist"] = {t="npc",n="Dashel Stonefist",z="stormwind",s="Dashel Stonefist is a notorious dwarven brawler found loitering among the shaded alleys of Old Town in Stormwind City. Nicknamed \"Fist\" for his quick temper and heavy hands, he is a familiar fixture of the city's rougher underbelly. Beneath his thuggish exterior, he maintains quietly dangerous connections that draw the eye of covert investigators.",h="Dashel Stonefist is a notorious dwarven brawler found loitering among the shaded alleys of Old Town in...",sec={{t="A Brawler in Old Town",b="Tucked away in the narrow, cobblestone backstreets of Old Town, Dashel Stonefist looks like any other drunken, combative dwarf looking for an excuse to throw a punch. Locals and city guards know him simply as \"Fist,\" a moniker earned through countless street fights and scuffles outside tavern doors. Yet Dashel is far more than a simple tavern brawler; his presence in Old Town puts him right at the nexus of Stormwind's underworld, where smugglers, cutpurses, and political agitators exchange coin and rumors away from the prying eyes of Cathedral Square.",sp=0},{t="The Diplomat's Disappearance",b="When a high-ranking diplomat goes missing on a secret voyage abroad, covert royal investigators track whispers of treachery straight to Dashel. Stonefist serves as a street-level contact for the Defias Brotherhood within Stormwind's very walls, possessing critical knowledge about the abduction. Far from a willing informant, Dashel refuses to speak until beaten into submission, revealing that the conspiracy reaches far deeper into the kingdom's politics than a simple kidnapping.",sp=1}},faq={{q="Who is Dashel Stonefist?",a="Dashel Stonefist is a dwarf living in Old Town, Stormwind City. Nicknamed \"Fist\" for his violent reputation and brawling habits, he serves as a low-level cutthroat and informant embedded in the capital's shadowy quarters.",al={"who is dashel","who is fist","dashel stonefist lore"}},{q="Where can I find Dashel Stonefist?",a="He can be found standing outside in Old Town within Stormwind City, tucked among the district's back alleys near the city's rogue and warrior haunts.",al={"dashel location","where is dashel stonefist","find dashel"}},{q="Why do investigators need to fight him?",a="During the investigation into the missing royal diplomat, leads point directly to Dashel as a collaborator. Because he is fiercely loyal to his shady employers and respects only force, investigators must beat him in a bare-knuckle brawl before he will spill what he knows.",al={"why attack dashel","subdue dashel stonefist","fight dashel"},sp=1},{q="What is his connection to the Defias Brotherhood?",a="Dashel operates as an inside operative and messenger for the Defias Brotherhood within Stormwind. He helps coordinate local contacts and street muscle to keep the Brotherhood's plans concealed from the City Guard.",al={"is dashel defias","dashel stonefist defias","defias in stormwind"},sp=1},{q="Who is the missing diplomat connected to Dashel?",a="The official story pursued by royal agents involves an unnamed diplomat who vanished en route to Theramore.",al={"who is the missing diplomat","missing diplomat questline","king varian missing"},sp=2},{q="Is Dashel related to any other known dwarves?",a="He shares a surname with Telda Stonefist, suggesting a familial connection, though Dashel's criminal ties in Stormwind set him apart from reputable dwarven society.",al={"telda stonefist relative","dashel stonefist family","stonefist family"}}},ang={["class:Rogue"]="For rogues navigating Old Town's criminal web, Dashel is an example of an operative who talks too much once his jaw is rattled—a warning about trusting brute muscle with delicate secrets.",["race:Dwarf"]="While many Ironforge dwarves in Stormwind work as honored smiths, mountaineers, or emissaries, Stonefist shows that dwarves are just as capable of falling into street-corner thuggery and treason.",["faction:Alliance"]="Dashel represents the quiet rot inside Stormwind's capital, proving that the Defias Brotherhood's reach extends past the farms of Westfall and straight into the sovereign city."},kw={"brawler","dashel","defias","fist","missing diplomat","old town","stonefist","stormwind"},rel={"quest:1241","subzone:old-town","zone:stormwind","topic:stormwind-kingdom","topic:dwarf"},src={"Dashel Stonefist"}}
E["npc:donyal-tovald"] = {t="npc",n="Donyal Tovald",z="stormwind",s="Donyal Tovald is a human steward serving in the Royal Library within Stormwind Keep. Under an initiative begun by the young King Anduin Wrynn, he oversees the care of the kingdom's books and works to distribute copies of historical texts to the broader public.",h="Donyal Tovald is a human steward serving in the Royal Library within Stormwind Keep.",sec={{t="Steward of Stormwind's History",b="Located in the quiet alcoves of the Royal Library wing within Stormwind Keep, Donyal Tovald tends to the kingdom's vast collection of historical accounts, scrolls, and scholarly volumes. While the library primarily serves the nobility and royal court, young King Anduin Wrynn has sponsored an initiative to make knowledge more accessible to ordinary citizens. Tovald handles the preservation and copying of these texts, helping ensure that the lessons and triumphs of the Alliance are not forgotten amidst the kingdom's turbulent political climate.",sp=0}},faq={{q="Who is Donyal Tovald?",a="Donyal Tovald is a human librarian stationed in the Royal Library of Stormwind Keep. He maintains the kingdom's archives and manages an initiative backed by King Anduin Wrynn to distribute copies of historical books to the public.",al={"who is tovald","royal librarian","donyal tovald lore"}},{q="Where can I find Donyal Tovald?",a="He can be found inside the Royal Library wing on the eastern side of Stormwind Keep, surrounded by bookshelves and historical scrolls.",al={"donyal tovald location","where is tovald","how to find tovald"}},{q="Why is he handing out books to citizens?",a="Young King Anduin Wrynn sponsored a royal project to educate the public and share knowledge. Donyal Tovald serves as the steward overseeing the reproduction and distribution of these royal manuscripts.",al={"anduin book initiative","stormwind library project","why does he give books"}},{q="Is he affiliated with the House of Nobles or the clergy?",a="Tovald operates directly under the crown as a keeper of royal archives within Stormwind Keep, focusing on historical and scholarly texts rather than ecclesiastical or political doctrine.",al={"is tovald church of light","tovald faction"}}},ang={["race:Human"]="For humans of Stormwind, Tovald represents an effort to rebuild and preserve their culture and recorded history following the First War and the reconstruction of the capital.",["class:Mage"]="Mages visiting Stormwind Keep may appreciate Tovald's dedication to preserving written knowledge, even if the texts are primarily historical rather than arcane."},kw={"anduin wrynn","books","donyal tovald","history","librarian","royal library","stormwind keep"},rel={"subzone:royal-library","subzone:stormwind-keep","quest:579","zone:stormwind","topic:stormwind-kingdom"},src={"Donyal Tovald"}}
E["npc:duthorian-rall"] = {t="npc",n="Duthorian Rall",z="stormwind",s="Duthorian Rall is a respected human knight of the Silver Hand stationed within Stormwind's Cathedral of Light. Renowned as one of the most influential paladins in the Alliance, he oversees the training and spiritual trials of emerging holy warriors. He guides recruits through solemn vows of charity, valor, and devotion to defend Azeroth against the Scourge and lurking domestic threats.",h="Duthorian Rall is a respected human knight of the Silver Hand stationed within Stormwind's Cathedral of Light.",sec={{t="A Pillar of the Silver Hand",b="Standing within the vaulted transept of the Cathedral of Light, Duthorian Rall represents the venerable traditions of the Knights of the Silver Hand. With the kingdom unsettled by internal strife and the missing King Varian Wrynn, Duthorian shoulders the vital duty of instilling righteous discipline in fresh initiates. Respected paladins in the field, including Brother Wilhelm in Northshire and Brandur Ironhammer in Dun Morogh, direct promising recruits to his guidance to begin their sacred trials.",sp=0},{t="Trials of Compassion and Life",b="Duthorian teaches that martial power without moral foundation is hollow. Through the Tome of Divinity, he tests a paladin's capacity for empathy, requiring acts of mercy and selfless service across Stormwind before entrusting them with deeper mysteries. His trials culminate in testing candidates with the Symbol of Life near Heroes' Vigil, sending them to aid wounded allies and teach them to channel the Light's miraculous power to restore fallen comrades from death.",sp=0},{t="The Price of Valor",b="Beyond spiritual contemplation, Duthorian demands resolute courage in the face of peril. In his tests of valor, he cautions aspirants that their vows may demand their lives. He tests this resolve by sending initiates into dangerous territory—such as defending Daphne Stilwell against Defias renegades in Westfall—before directing them on toward master smith Jordan Stilwell outside Ironforge and granting them holy steeds worthy of their station.",sp=1}},faq={{q="Who is Duthorian Rall?",a="Duthorian Rall is a prominent knight of the Silver Hand residing in the Cathedral of Light within Stormwind City. He serves as an instructor and spiritual mentor for new paladins, testing their devotion and courage on behalf of the Church of the Holy Light.",al={"duthorian rall lore","who is duthorian","cathedral paladin duthorian"}},{q="Where can Duthorian Rall be found?",a="He can be found standing in the eastern wing of the Cathedral of Light, located at the heart of the Cathedral Square in Stormwind City.",al={"where is duthorian rall","duthorian rall location","how to find duthorian"}},{q="What is his connection to the Tome of Divinity?",a="Duthorian provides paladins with the Book of Divinity and guides them through trials of humility, compassion, and rescue. Fulfilling his trials proves an initiate is worthy to wield the Light's power of resurrection.",al={"tome of divinity duthorian","redemption quest duthorian","symbol of life quest"}},{q="Why does Duthorian send paladins to Westfall?",a="During the trial for the Tome of Valor, Duthorian sends paladins to protect Daphne Stilwell from Defias bandits on her farm in Westfall, demonstrating their willingness to sacrifice themselves to defend the innocent.",al={"daphne stilwell quest","tome of valor westfall","westfall paladin quest"}},{q="What rewards does Duthorian grant to paladins who pass his trials?",a="Successful paladins earn key holy capabilities through his guidance, including the sacred gift of resurrection, the ability to sense undead, protective armaments such as the Bastion of Stormwind, and eventually their summoned warhorse.",al={"duthorian quest rewards","what do you get from duthorian"}},{q="Who sends adventurers to Duthorian initially?",a="Aspirants are typically directed to him by introductory paladin trainers in starting settlements, including Brother Wilhelm in Northshire Valley and Brandur Ironhammer in Kharanos.",al={"who sends you to duthorian","duthorian breadcrumb quest"}}},ang={["class:Paladin"]="Duthorian Rall is one of your primary spiritual mentors in Stormwind, testing your compassion and valor through foundational trials that unlock the power of resurrection, divine senses, and your warhorse.",["faction:Alliance"]="As an influential leader within the Silver Hand, Duthorian ensures that the Alliance's defenders remain morally upright and capable of defending the realm against bandits and undead alike.",["race:Human"]="Anchored in Stormwind's Cathedral of Light, Duthorian represents the enduring devotion and chivalric discipline central to human faith and society."},kw={"cathedral of light","daphne stilwell","duthorian rall","jordan stilwell","paladin trainer","silver hand","stormwind","symbol of life","tome of divinity","tome of valor"},rel={"subzone:cathedral-of-light","quest:1641","quest:1649","quest:1653","npc:brother-wilhelm","npc:brandur-ironhammer","npc:daphne-stilwell","npc:jordan-stilwell"},src={"Duthorian Rall"}}
E["npc:elling-trias"] = {t="npc",n="Elling Trias",z="stormwind",s="Elling Trias manages Trias' Cheese, a small storefront nestled in the bustling Trade District of Stormwind City. While he presents himself as a jovial and passionate purveyor of dairy, he quietly operates as one of the kingdom's most connected information brokers. Behind wheels of cheese and cordial banter, Trias maintains an ear to the ground that reaches across continents.",h="Elling Trias manages Trias' Cheese, a small storefront nestled in the bustling Trade District of Stormwind...",sec={{t="The Master Cheesemonger",b="To the casual customer strolling the Trade District, Elling Trias is merely an artisan dedicated to fine curds, working his shop alongside his wife Elaine and son Ben. He enthusiastically hawks wheels of cheese and chats amicably with townsfolk. Yet those in the know understand that Trias' Cheese is one of the most reliable fronts in Stormwind. The steady hum of city commerce provides perfect cover for operatives, courtiers, and adventurers who need to trade quiet words without drawing the attention of the city watch.",sp=0},{t="A Web of Whispers",b="Elling's network of informants and allies is staggering for a shopkeeper. He maintains ties with Master Mathias Shaw of SI:7, coordinates with Church contacts like Bishop DeLavey, and corresponds with agents as far afield as Darkshire, Theramore Isle, and the distant Plaguelands near Hearthglen. When odd rumors surface—whether concerning highway bandits or quiet movements in the countryside—Trias often pieces the puzzle together long before the royal court takes notice.",sp=0},{t="The Missing Diplomat",b="When a high-ranking diplomat vanishes on a voyage to Theramore, Elling Trias becomes an essential pivot in unraveling the conspiracy. Directing investigators to his contacts—including an estranged operative named Jorgen and old friend Tyrion—Trias helps unmask the Defias Brotherhood's hand in the abduction. Despite his sharp wit and cynical banter, Elling recognizes that the plot reaches deep into the heart of Stormwind's aristocracy.",sp=1}},faq={{q="Who is Elling Trias?",a="Elling Trias is ostensibly a cheese vendor operating Trias' Cheese in Stormwind's Trade District alongside his family. Beneath that cover, he is a seasoned intelligence broker with ties to SI:7, the Church, and distant outposts across Azeroth.",al={"who is elling","elling trias identity","trias cheese guy"}},{q="Where is his cheese shop located?",a="You can find Trias' Cheese in the Trade District of Stormwind City, tucked into the shop row along the outer canal wall, near the border leading toward Old Town.",al={"trias cheese location","where is elling trias","trias shop stormwind"}},{q="What is his connection to the Defias Brotherhood?",a="Trias is not a member of the Defias Brotherhood; rather, he tracks their movements through his informant network. He helps Alliance adventurers trace Defias involvement in subversive plots, including the kidnapping of a royal diplomat.",al={"trias defias","is trias in the defias"},sp=1},{q="How does he know Mathias Shaw?",a="Elling collaborates closely with Master Mathias Shaw and the intelligence apparatus of SI:7. His shop provides an informal listening post where discreet inquiries can be launched outside official royal channels.",al={"trias and shaw","trias si7","is trias si7"}},{q="Who runs the shop with him?",a="Elling runs Trias' Cheese with his wife, Elaine Trias, and his son, Ben Trias. Together they maintain the appearance of a bustling, ordinary family-run trade shop.",al={"trias family","elling trias wife"}},{q="What is his involvement in the Missing Diplomat investigation?",a="Sent to Trias by Bishop DeLavey, investigators use Elling's expansive web of contacts—including his old associates Jorgen and Tyrion—to trace Defias movements and discover who seized the diplomat bound for Theramore.",al={"missing diplomat trias","why visit trias cheese"},sp=1}},ang={["class:Rogue"]="Any practitioner of subtlety recognizes that Elling's cheese shop is an ideal drop point. His proximity to Old Town and tight links to Mathias Shaw make him a fixture in Stormwind's underworld.",["faction:Alliance"]="Elling serves as an unsung pillar of Alliance intelligence, quietly filtering rumors from Theramore to Hearthglen to protect the realm from internal rot."},kw={"elaine trias","elling trias","mathias shaw","missing diplomat","si:7","stormwind","trade district","trias cheese","tyrion"},rel={"subzone:trade-district","zone:stormwind","npc:mathias-shaw","quest:1241","npc:tyrion","npc:bishop-delavey","topic:defias-brotherhood","quest:2300"},src={"Elling Trias"}}
E["npc:farthing"] = {t="npc",n="Farthing",z="stormwind",s="Bishop Farthing is a human clergyman residing within the Cathedral of Light in Stormwind City. To visitors and worshippers, he presents himself as a devout servant of the Holy Light who guides parishioners and directs aid toward beleaguered settlements across the kingdom.",h="Bishop Farthing is a human clergyman residing within the Cathedral of Light in Stormwind City.",sec={{t="A Bishop in Stormwind",b="Within the serene marble halls of the Cathedral of Light, Bishop Farthing stands as one of the prominent figures attending to the spiritual needs of Stormwind City. Alongside Archbishop Benedictus and the gathered clergy, he offers counsel to travelers, assists those pursuing the holy arts, and attends to the civic and pastoral obligations of the Church of the Holy Light.",sp=0},{t="Aid to the Plagued Lands",b="Despite remaining situated within the capital, Farthing directs earnest travelers toward darker corners of the kingdom that desperately require holy aid. When troubled reports filter in regarding the necromancer Morbent Fel and the creeping undead blight overtaking Duskwood, Farthing serves as an advisor in seeking out methods to overcome dark sorceries and cleanse the blighted frontier.",sp=0}},faq={{q="Where can Bishop Farthing be found?",a="Bishop Farthing resides inside the Cathedral of Light, located at the center of Cathedral Square within Stormwind City.",al={"farthing location","where is farthing","farthing map"}},{q="What role does Farthing play in the Cathedral?",a="He serves as an ordained bishop within the Church of the Holy Light, offering guidance to visiting faithful, priests in training, and adventurers seeking holy wisdom on behalf of distant settlements.",al={"what does farthing do","who is farthing"}},{q="How is Farthing involved with Duskwood?",a="Farthing is sought out by adventurers dealing with the undead menace in Duskwood, advising on the dark arts sustaining the necromancer Morbent Fel and directing souls toward purification.",al={"farthing duskwood","farthing morbent fel"}},{q="Is Farthing related to other citizens bearing the same name?",a="Several other individuals across human lands share the surname Farthing, including Coleman and Yvette Farthing, though he does not actively speak of any direct family ties.",al={"coleman farthing relative","farthing family"}}},ang={["class:Priest"]="For priests visiting the Cathedral of Light, Farthing represents the established hierarchy and scholarly wisdom of the human clergy in Stormwind.",["faction:Alliance"]="Adventurers battling the creeping corruption in southern Alliance territories such as Duskwood look to Farthing and his fellow clergy for divine insight and spiritual resolve."},kw={"benedictus","bishop farthing","cathedral of light","farthing","morbent fel","seeking wisdom","stormwind"},rel={"subzone:cathedral-of-light","npc:archbishop-benedictus","quest:269","quest:55","quest:270","zone:stormwind","zone:duskwood","topic:church-of-the-holy-light"},src={"Farthing"}}
E["npc:field-marshal-stonebridge"] = {t="npc",n="Field Marshal Stonebridge",z="stormwind",s="Field Marshal Stonebridge is a high-ranking Alliance officer stationed near the entrance of Stormwind City. Posted beside the Gates of Stormwind in the Valley of Heroes, she oversees city defenses alongside General Marcus Jonathan and serves as an authority for major martial triumphs.",h="Field Marshal Stonebridge is a high-ranking Alliance officer stationed near the entrance of Stormwind City.",sec={{t="A Bulwark at the Gates",b="Positioned just inside the towering entrance of the Valley of Heroes, Field Marshal Stonebridge stands watch beneath the eastern archway near the main gates. Her high rank within the Grand Alliance military places her among the highest echelons of Stormwind's strategic leadership, operating in close coordination with General Marcus Jonathan. From this prominent vantage, she observes the flow of defenders, travelers, and returning champions passing into the capital, standing ready to organize the garrison should threats breach the outer perimeter.",sp=0},{t="Bearer of Trophies",b="Beyond her ceremonial and defensive duties at the city gate, Field Marshal Stonebridge receives critical reports and spoils from campaigns against the greatest adversaries threatening the kingdom. High-ranking commanders rely on officers like Stonebridge to verify crucial intelligence and celebrate monumental victories won in the field, including the defeat of warlords and monsters nesting within the crags of Blackrock Mountain.",sp=0}},faq={{q="Where is Field Marshal Stonebridge located?",a="She stands under an archway in the northeastern portion of the Valley of Heroes in Stormwind City, just to the right of General Marcus Jonathan as you enter through the city gates.",al={"stonebridge location","where is field marshal stonebridge","find stonebridge"}},{q="What is Field Marshal Stonebridge's role in Stormwind?",a="She is a high-ranking Alliance military officer assisting General Marcus Jonathan with the defense of Stormwind's main gate and acts as a receiving officer for notable martial intelligence and grand victory trophies brought back by Alliance champions.",al={"what does stonebridge do","stonebridge purpose","who is field marshal stonebridge"}},{q="What rank is a Field Marshal in the Alliance?",a="Field Marshal is one of the highest officer ranks in the Grand Alliance military command structure, standing just below Grand Marshal. Officers of this rank oversee major tactical deployments, city defense sectors, and strategic garrisons.",al={"alliance field marshal rank","how high rank is stonebridge"}},{q="What major quests involve Field Marshal Stonebridge?",a="She is the officer who receives the report and trophy for 'The Lord of Blackrock', confirming the fall of Nefarian when Alliance adventurers drag the dragon's head back to the gates of Stormwind.",al={"stonebridge quests","the lord of blackrock quest ender"},sp=1}},ang={["class:Warrior"]="As one of the supreme military commanders stationed at the city gates, Field Marshal Stonebridge commands respect from frontline soldiers who strive to achieve high martial standing within the Alliance.",["faction:Alliance"]="Standing shoulder-to-shoulder with General Marcus Jonathan, Stonebridge represents the unwavering vigilance of the Alliance military guarding Stormwind against outside invasion."},kw={"field marshal","gates","lord of blackrock","marcus jonathan","nefarian","stonebridge","stormwind","valley of heroes"},rel={"subzone:valley-of-heroes","npc:general-marcus-jonathan","quest:7781","zone:stormwind","topic:stormwind-kingdom","topic:alliance"},src={"Field Marshal Stonebridge"}}
E["npc:furen-longbeard"] = {t="npc",n="Furen Longbeard",z="stormwind",s="Furen Longbeard is a master dwarven armorer stationed within Stormwind City's bustling Dwarven District. Apprenticed under the renowned smith Grimand Elmore, he specializes in crafting heavy protective gear and sturdy mail for seasoned defenders of the Alliance. Warriors across the kingdom seek out his metallurgical expertise to forge specialized, battle-ready armor.",h="Furen Longbeard is a master dwarven armorer stationed within Stormwind City's bustling Dwarven District.",sec={{t="A Dwarven Smith in the Human Capital",b="Furen Longbeard plies his craft far from the great forges of Ironforge, making his home instead among the cobblestones and soot of Stormwind's Dwarven District. Like many of his kin, Furen brought traditional dwarven metallurgy south to support the rebuilding and defense of the kingdom. Working amidst blazing hearths and clanging anvils, he maintains strong ties with other artisans throughout the city and beyond.",sp=0},{t="Mastery of Fire-Hardened Mail",b="Taught by the venerable craftsman Grimand Elmore, Furen has perfected techniques for treating heavy mail and plate to withstand extreme battlefield punishment. Promising young warriors seeking durable protection often turn to Furen, who requires rare ores, specialized components, and exotic reagents from distant corners of the world to fashion his signature fire-hardened armor.",sp=0}},faq={{q="Who is Furen Longbeard?",a="Furen Longbeard is a dwarven armorer operating out of the Dwarven District in Stormwind City. He serves as an essential contact and mentor for Alliance warriors looking to acquire mastercrafted mail armor.",al={"who is furen","furen longbeard lore","dwarf armorer stormwind"}},{q="Where can Furen Longbeard be found?",a="He is located in the Dwarven District of Stormwind City, standing near the bustling forges and smithing workshops that dominate the neighborhood.",al={"where is furen longbeard","furen longbeard location","furen stormwind"}},{q="Who taught Furen his smithing craft?",a="Furen was taught armorcraft and metallurgy by Grimand Elmore, a respected veteran craftsman also residing in the Dwarven District.",al={"furen teacher","furen mentor","who trained furen"}},{q="What armor is Furen famous for crafting?",a="He is renowned for fashioning Fire Hardened Mail, a resilient set of armor created through exacting metallurgical processes requiring rare components gathered across the continent.",al={"fire hardened mail","furen armor quest","warrior mail quest stormwind"}},{q="Is Furen Longbeard related to other Longbeards?",a="He shares his clan name with several other prominent dwarves across the Eastern Kingdoms, such as the seasoned mountaineer Pilot Longbeard, though he focuses strictly on smithing.",al={"furen family","longbeard clan","pilot longbeard relative"}},{q="Why do warriors seek out Furen Longbeard?",a="Warriors who have proven their basic martial prowess are directed to Furen to obtain heavy, durable armor capable of enduring front-line combat against deadlier threats.",al={"why do warriors visit furen","warrior quest dwarven district","furen warrior trainer"}}},ang={["class:Warrior"]="For Alliance warriors coming of age, Furen Longbeard is a pivotal contact who turns raw martial resolve and gathered reagents into vital, fire-hardened defensive armor.",["profession:Blacksmithing"]="Furen represents the high standards of dwarven smithing established in Stormwind, showcasing advanced techniques passed down by Grimand Elmore.",["race:Dwarf"]="Even far from Ironforge, Furen Longbeard keeps dwarven metallurgical traditions alive in the heart of the human capital."},kw={"armorer","blacksmith","dwarven district","fire hardened mail","furen longbeard","grimand elmore","stormwind","warrior"},rel={"quest:1701","quest:1782","quest:1700","subzone:dwarven-district","zone:stormwind","topic:dwarf","npc:pilot-longbeard","quest:1338"},src={"Furen Longbeard"}}
E["npc:gakin-the-darkbinder"] = {t="npc",n="Gakin the Darkbinder",z="stormwind",s="Gakin the Darkbinder is a master warlock operating covertly deep beneath The Slaughtered Lamb tavern in Stormwind's Mage Quarter. He instructs aspiring Alliance practitioners in the dark arts, testing their resolve before initiating rituals to summon and bind otherworldly demons to their service.",h="Gakin the Darkbinder is a master warlock operating covertly deep beneath The Slaughtered Lamb tavern in...",sec={{t="A Secret Gathering Place",b="While Stormwind's mages practice openly in their towering sanctuaries, practitioners of shadow and fel must dwell where prying eyes cannot reach. Hidden below the taproom of The Slaughtered Lamb is a damp crypt-like cellar equipped with summoning circles and grim tomes. Gakin serves as the anchor of this hidden conclave, ensuring that young warlocks learn discipline and restraint before unleashing horrors they cannot control.",sp=0},{t="Master of Demons",b="Gakin's expertise lies in demonology and binding rituals. Initiates who earn his notice are sent across the kingdom to acquire rare relics and ingredients—from stolen bloodstone talismans to corrupt wood from the dark forests. Once the reagents are assembled, Gakin oversees rituals in the crypt's summoning circle, forcing novitiates to subjugate voidwalkers and succubi in life-or-death trials of willpower.",sp=0},{t="Betrayals and Loose Ends",b="Not all of Gakin's students remain obedient. One former apprentice, Surena Caledon, absconded with a valuable Bloodstone Choker, fleeing into the wilds. Such internal treacheries threaten to expose the warlock circle to the city guards, prompting Gakin to dispatch loyal followers to recover lost artifacts and silence loose ends before the authorities take notice.",sp=1}},faq={{q="Where can I find Gakin the Darkbinder?",a="Gakin is located deep beneath The Slaughtered Lamb tavern in the Mage Quarter of Stormwind. Head inside the tavern, find the downward ramp at the back, and descend through the stone tunnels until you reach the summoning circle in the lowest crypt.",al={"where is gakin","gakin location","slaughtered lamb basement"}},{q="What does Gakin the Darkbinder do?",a="He serves as a prominent warlock quest-giver and mentor for Alliance characters. He tests novitiates by sending them on trials across Azeroth and teaching them how to summon and bind demons like the Voidwalker and Succubus.",al={"what does gakin do","gakin role","gakin quests"}},{q="Why are warlocks allowed under The Slaughtered Lamb?",a="Demonic magic is forbidden and deeply mistrusted in Stormwind. The practitioners under The Slaughtered Lamb operate in strict secrecy, tolerated only as a dangerous covert asset and hidden away from the city's guards and citizens.",al={"why are warlocks allowed","are warlocks legal in stormwind","slaughtered lamb lore"}},{q="Who is Surena Caledon?",a="Surena Caledon was a former student of Gakin who stole a powerful Bloodstone Choker from him. Her betrayal poses a danger to their hidden order, prompting Gakin to task warlocks with tracking her down.",al={"surena caledon","gakin student","who stole from gakin"}},{q="Which demons does Gakin help summon?",a="Gakin oversees the binding rituals for both Voidwalkers and Succubi, guiding warlocks to draw the creatures into the subterranean circle and subdue them.",al={"gakin demons","gakin voidwalker","gakin succubus"}},{q="Who is Strahad and why does Gakin mention him?",a="Strahad Farsan is an experienced warlock residing in the Ratchet hills of Kalimdor. Once a student advances past Gakin's fundamental binding rituals, Gakin directs them across the sea to continue their darker education with Strahad.",al={"strahad","seeking strahad","where does gakin send me next"}}},ang={["class:Warlock"]="Gakin is a vital mentor for human and gnome warlocks, offering pivotal class quests to master the voidwalker and succubus rituals in the crypts of Stormwind.",["faction:Alliance"]="Operating secretly under the capital city, Gakin's coven demonstrates the pragmatic, shadow-drenched compromises made in the heart of the Alliance."},kw={"darkbinder","gakin","mage quarter","slaughtered lamb","succubus","surena caledon","voidwalker","warlock"},rel={"subzone:slaughtered-lamb","subzone:mage-quarter","zone:stormwind","quest:1471","quest:1472","quest:1688","quest:1715","quest:1798"},src={"Gakin the Darkbinder"}}
E["npc:gazin-tenorm"] = {t="npc",n="Gazin Tenorm",z="stormwind",s="Gazin Tenorm is a dwarven paladin ally stationed near the altar in Stormwind's Cathedral of Light. Alongside his comrade Henze Faulk, he undertook a dangerous scouting mission to gather evidence of Defias Brotherhood activity for the king's advisors.",h="Gazin Tenorm is a dwarven paladin ally stationed near the altar in Stormwind's Cathedral of Light.",sec={{t="A Scout in the Cathedral",b="While Gazin Tenorm spends his days within the tranquil halls of the Cathedral of Light, his mind remains out in the wilds of Elwynn Forest. Gazin and his close friend Henze Faulk set out into the woods on an urgent errand: gathering hard proof of the Defias Brotherhood's movements to present before the royal court. The expedition went awry when they were ambushed by Defias forces. Gazin barely escaped with his life back to the safety of Stormwind, but Henze was left behind in mortal danger, prompting Gazin to seek a stalwart hero of the Light to come to his companion's aid.",sp=0}},faq={{q="Where can I find Gazin Tenorm?",a="Gazin Tenorm can be found inside the Cathedral of Light in Stormwind City, standing near the back altar alongside high-ranking clergy and paladin mentors.",al={"gazin location","where is gazin tenorm","where is gazin"}},{q="What happened to Gazin Tenorm in Elwynn Forest?",a="While investigating the Defias Brotherhood with his companion Henze Faulk, Gazin ran into an ambush of outlaw forces. He managed to fight his way free and flee back to Stormwind City, but the ordeal left his friend stranded out in the forest.",al={"gazin story","what happened to gazin","why is gazin hurt"}},{q="Why was Gazin investigating the Defias Brotherhood?",a="Gazin and Henze Faulk ventured into Elwynn Forest to gather undeniable evidence of the Defias Brotherhood's illicit activities, intending to bring undeniable proof directly before the king's advisors in Stormwind.",al={"why investigate defias","gazin mission","gazin henze defias"}},{q="How does Gazin connect to the Paladin trials?",a="High Paladin Duthorian Rall directs aspiring human paladins pursuing the Tome of Divinity to Gazin. Gazin then provides the means and direction to rescue his fallen partner Henze Faulk, testing the initiate's valor and mercy.",al={"gazin tome of divinity","paladin quest gazin","henze faulk quest"}}},ang={["class:Paladin"]="Initiates learning the paths of compassion and redemption meet Gazin in the Cathedral of Light to aid his fallen brother-in-arms, Henze Faulk.",["race:Dwarf"]="Gazin represents the enduring solidarity between Ironforge and Stormwind, serving as a dwarven champion willing to face Elwynn's brigands on behalf of the kingdom's advisors."},kw={"cathedral of light","defias","duthorian rall","gazin tenorm","henze faulk","paladin","tome of divinity"},rel={"npc:henze-faulk","npc:duthorian-rall","quest:1641","subzone:cathedral-of-light","zone:stormwind","topic:defias-brotherhood","zone:elwynn"},src={"Gazin Tenorm"}}
E["npc:harlan-bagley"] = {t="npc",n="Harlan Bagley",z="stormwind",s="Harlan Bagley is a human armorer and merchant operating out of the Lionheart Armory in Stormwind City's bustling Trade District. He tends his shop on the northern side of the district center, looking after arms and equipment for citizens and visiting adventurers alike.",h="Harlan Bagley is a human armorer and merchant operating out of the Lionheart Armory in Stormwind City's...",sec={{t="The Lionheart Armory",b="Situated along the northern side of the Trade District, the Lionheart Armory serves as a steady commercial fixture within the heart of Stormwind. From behind his counter, Harlan Bagley manages inventory and deals in defensive gear, relying on incoming trade and regional couriers to keep his shelves stocked while the capital contends with distant border conflicts and supply constraints.",sp=0}},faq={{q="Who is Harlan Bagley?",a="Harlan Bagley is a human shopkeeper and tradesman who runs the Lionheart Armory, an equipment shop located in the Trade District of Stormwind City.",al={"who is harlan","harlan bagley lore","lionheart armory vendor"}},{q="Where can I find Harlan Bagley?",a="He is located inside the Lionheart Armory on the northern side of the central square in Stormwind City's Trade District.",al={"harlan bagley location","where is harlan","lionheart armory location"}},{q="What role does he play in Stormwind's commerce?",a="As a local merchant in the kingdom's capital, Bagley supplies armor and gear, occasionally hiring adventurers to run delivery errands and secure supply shipments essential to keeping his armory open.",al={"what does harlan sell","harlan bagley business"}}},ang={["faction:Alliance"]="Merchants like Harlan Bagley keep the Alliance's primary capital supplied with gear and goods while regular supply lines are threatened across the surrounding territories."},kw={"armorer","harlan bagley","lionheart armory","merchant","stormwind","trade district"},rel={"subzone:trade-district","zone:stormwind","quest:333","topic:stormwind-kingdom"},src={"Harlan Bagley"}}
E["npc:high-priestess-laurena"] = {t="npc",n="High Priestess Laurena",z="stormwind",s="High Priestess Laurena is a respected human priest trainer stationed behind the grand altar within Stormwind City's Cathedral of Light. Having escaped the destruction of Lordaeron as a refugee during the Third War, she now instructs budding Alliance priests in spiritual devotion and arcane wards.",h="High Priestess Laurena is a respected human priest trainer stationed behind the grand altar within Stormwind...",sec={{t="A Refugee of Lordaeron",b="Before taking her post within the towering halls of the Cathedral of Light, Laurena dwelt in the northern kingdom of Lordaeron. When the Scourge swept across the land during the Third War, she and her entire family were fortunate enough to survive and flee southward, arriving in Stormwind City as displaced refugees. Despite the immense grief and chaos that shattered her homeland, Laurena remained steadfast in her devotion, eventually rising to become a High Priestess in service to the Church of the Holy Light.",sp=0},{t="Tending the Faithful",b="Positioned directly behind the central altar within the cathedral sanctuary, High Priestess Laurena dedicates herself to mentoring aspiring priests. When promising acolytes demonstrate sufficient dedication and piety, they are directed to her to deepen their studies. Laurena guides them in the invocation of sacred boons such as Desperate Prayer and instructs them in defensive arts, including spells designed to turn enemy arcane magic back against those who wield it. Once an initiate has learned all she can offer, she sends them onward to other master priests across the Alliance.",sp=0}},faq={{q="Where can I find High Priestess Laurena?",a="She stands behind the main altar inside the Cathedral of Light, which is located in Cathedral Square within Stormwind City.",al={"laurena location","where is priestess laurena","find laurena"}},{q="What does High Priestess Laurena teach?",a="Laurena is a priest trainer. She provides foundational instruction to human priests and teaches specialized racial prayers such as Desperate Prayer, as well as wards like Arcane Feedback to protect against hostile spellcasters.",al={"laurena spells","priest trainer laurena","what does laurena teach"}},{q="Where did Laurena come from before Stormwind?",a="Laurena originally lived in the kingdom of Lordaeron. During the Third War, her family managed to escape the horrors of the Scourge and fled to Stormwind City as refugees, where she continued her religious calling.",al={"laurena backstory","is laurena from stormwind","laurena lordaeron"}},{q="Does she serve under Archbishop Benedictus?",a="Yes. Archbishop Benedictus is the spiritual leader of the Church of the Holy Light and presides over the Cathedral of Light, where Laurena serves as a High Priestess.",al={"laurena and benedictus","who is laurena's boss","benedictus laurena"}},{q="Why does she direct me to other priest trainers?",a="Different cultures and races within the Alliance commune with the divine in unique ways. Once Laurena has taught her students the foundational prayers of the Holy Light, she sends them to master priests of other disciplines—such as dwarven masters in Ironforge or night elf priestesses in Darnassus—to expand their spiritual horizons.",al={"laurena sends me away","a lack of fear quest","elunes grace quest"}},{q="Did Laurena lose her family to the undead?",a="Remarkably, her immediate family survived the fall of Lordaeron. They were among the fortunate refugees who managed to escape the Scourge intact and make the long voyage south to the safety of Stormwind.",al={"laurena family dead","what happened to laurena family"}}},ang={["class:Priest"]="High Priestess Laurena acts as one of Stormwind's primary priest mentors, guiding human acolytes through sacred trials, blessing them with Desperate Prayer, and teaching methods to disrupt enemy spellcasters.",["race:Human"]="Like many humans in Stormwind, Laurena carries the sorrow of the fallen northern realm of Lordaeron, having rebuilt her life as a spiritual pillar for fellow survivors.",["faction:Alliance"]="From within the Cathedral of Light, Laurena helps strengthen the spiritual backbone of the Alliance, ensuring its champions can withstand dark magic and undead horrors."},kw={"arcane feedback","benedictus","cathedral of light","desperate prayer","high priestess","holy light","laurena","lordaeron","priest trainer","stormwind"},rel={"subzone:cathedral-of-light","npc:archbishop-benedictus","topic:church-of-the-holy-light","quest:5634","quest:5676","quest:5645","quest:5672","zone:stormwind"},src={"High Priestess Laurena"}}
E["npc:innkeeper-allison"] = {t="npc",n="Innkeeper Allison",z="stormwind",s="Innkeeper Allison manages the Gilded Rose, one of the busiest and most central inns in Stormwind City. Located in the heart of the Trade District right between the bank and auction house, she provides weary travelers and local merchants with hearthstone bindings, refreshing drinks, and shelter.",h="Innkeeper Allison manages the Gilded Rose, one of the busiest and most central inns in Stormwind City.",sec={{t="Hospitality in the Trade District",b="Positioned squarely between the bustling trade auction house and the main city vaults, the Gilded Rose serves as an epicenter for adventurers arriving in Stormwind. Innkeeper Allison stands behind the main counter on the ground floor, keeping order amidst a constant flow of peddlers, mercenaries, and visiting diplomats. Beyond offering lodging and hearthstone services, she frequently participates in local holiday festivities and coordinates small errands for traveling heroes seeking rest within the capital.",sp=0}},faq={{q="Where can I find Innkeeper Allison?",a="Innkeeper Allison stands behind the counter on the ground floor of the Gilded Rose. The inn is located directly in Stormwind City's Trade District, situated between the central bank and the auction house.",al={"allison location","where is innkeeper allison","gilded rose innkeeper"}},{q="What services does Innkeeper Allison offer?",a="She provides standard innkeeper services: players can set their hearthstone to the Gilded Rose, purchase food and drink for rest, and periodically interact with her during citywide seasonal events and holidays.",al={"what does allison do","allison services","can i bind hearthstone here"}},{q="Does Innkeeper Allison offer any quests?",a="Yes, Allison participates in various seasonal festivities throughout the year, such as holiday celebrations, and can occasionally be involved in city errands for travelers seeking aid across the realm.",al={"allison quests","innkeeper allison quest"}}},ang={["faction:Alliance"]="As the proprietor of the most accessible inn in Stormwind's commercial core, Allison is one of the most familiar faces for Alliance champions returning from frontline campaigns to rest and bank their spoils."},kw={"allison","gilded rose","hearthstone","innkeeper allison","stormwind","trade district"},rel={"subzone:trade-district","zone:stormwind","topic:alliance","topic:stormwind-kingdom","quest:8356"},src={"Innkeeper Allison"}}
E["npc:jennea-cannon"] = {t="npc",n="Jennea Cannon",z="stormwind",s="Jennea Cannon is a respected human mage trainer residing within the Wizard's Sanctum in Stormwind's Mage Quarter. She oversees the education of novice sorcerers, guiding them through foundational studies and investigating disturbances in the flow of local arcane energies. Through her tasks, she tests whether apprentices have the discipline needed to control magic without being consumed by it.",h="Jennea Cannon is a respected human mage trainer residing within the Wizard's Sanctum in Stormwind's Mage...",sec={{t="A Guide in the Sanctum",b="Positioned atop the spiral walkway of the Wizard's Sanctum, Jennea Cannon stands as one of the primary mentors for arcane practitioners entering Stormwind. Rather than merely drilling spells into pupils, she emphasizes caution and self-control. To non-mages passing through the tower, she offers a sharp warning: unchecked magic will burn the untrained, a truth novice spellcasters learn quickly under her tutelage.",sp=0},{t="Fieldwork and Foundation",b="Jennea believes magical theory must be tested by real-world observation. She frequently dispatches promising apprentices outside the city walls, sending them to examine sites such as Mirror Lake in Elwynn Forest to understand how natural water sources interact with arcane resonance. As students advance, she tests their resolve by directing them to investigate disruptions at the Blue Recluse or gathering volatile reagents for crafting their first true wizard's implements.",sp=0},{t="Ties to Greater Masters",b="While Jennea handles early instruction and local affairs, she knows when an apprentice has outgrown her syllabus. Once an initiate demonstrates true potential, she directs them up the hierarchy of the Sanctum to High Sorcerer Andromath or even beyond the kingdom's borders to reclusive practitioners like Tabetha deep in the Dustwallow Marsh.",sp=0}},faq={{q="Who is Jennea Cannon?",a="She is a human mage trainer stationed inside the Wizard's Sanctum within Stormwind's Mage Quarter, responsible for instructing new mages and directing early magical research.",al={"jennea cannon","who is jennea","stormwind mage trainer"}},{q="Where can I find Jennea Cannon?",a="She is located inside the Wizard's Sanctum, the spiraling arcane tower situated at the center of the Mage Quarter in Stormwind City.",al={"jennea cannon location","where is jennea","find jennea"}},{q="What quests does Jennea Cannon offer?",a="She provides class quests for Alliance mages, including investigating Mirror Lake in Elwynn Forest, looking into strange happenings at the Blue Recluse tavern, and gathering materials to craft novice mage gear.",al={"jennea quests","jennea cannon questline"}},{q="Why does she send mages to Mirror Lake?",a="She tasks apprentices with fetching a sample from Mirror Lake beneath the waterfalls of Elwynn to teach them how to perceive and interact with subtle ambient magical currents.",al={"why mirror lake","mirror lake quest jennea"}},{q="Does Jennea Cannon interact with non-mage classes?",a="Non-mages can speak with her, but she will simply offer a stern piece of advice to be cautious around magic, warning that it burns those who lack proper training.",al={"can non mages talk to jennea","jennea for other classes"}},{q="Who does Jennea Cannon report to?",a="She works within the hierarchy of the Wizard's Sanctum, guiding students until they are ready to study under senior figures such as High Sorcerer Andromath.",al={"jennea superior","wizards sanctum leaders"}}},ang={["class:Mage"]="Jennea is an essential early mentor for Alliance mages, guiding your first field investigations and directing you toward crafting your formal wizard robes and staff.",["faction:Alliance"]="Operating from the heart of Stormwind's Mage Quarter, Jennea ensures the kingdom's new sorcerers are disciplined and capable of serving the Alliance safely."},kw={"andromath","blue recluse","jennea cannon","mage quarter","mage trainer","mirror lake","stormwind","wizard's sanctum"},rel={"subzone:mage-quarter","zone:stormwind","quest:1860","quest:1861","quest:1939","quest:1961","npc:tabetha","topic:alliance"},src={"Jennea Cannon"}}
E["npc:jesper"] = {t="npc",n="Jesper",z="stormwind",s="Jesper is a human orphan residing in the orphanage of Cathedral Square in Stormwind City. During the annual festivities of Hallow's End, he steps out to celebrate and asks helpful adventurers to bring him special sweets.",h="Jesper is a human orphan residing in the orphanage of Cathedral Square in Stormwind City.",sec={{t="A Boy in Cathedral Square",b="Jesper lives in the Stormwind Orphanage under the watchful care of the Matron in Cathedral Square. Like many children left without family following the Second and Third Wars, he makes his home in the shadow of the Holy Light. When autumn arrives and the kingdom celebrates Hallow's End, Jesper leaves the quiet halls of the orphanage to join the festivities outside the city gates, eagerly seeking out anyone willing to bring him holiday treats from inns across the Alliance territories.",sp=0}},faq={{q="Where can I find Jesper?",a="Jesper normally resides within the orphanage located in Cathedral Square in Stormwind City. However, during the annual Hallow's End festivities, he joins the holiday celebrants gathered outside the city's main gates.",al={"jesper location","where is jesper","orphanage boy"}},{q="What does Jesper want during Hallow's End?",a="Jesper sends adventurers to collect various holiday candies from innkeepers across the Alliance lands, yearning for a taste of the festive season that an orphan in the city would otherwise miss.",al={"jesper treats","jesper quest","hallow's end jesper"}},{q="Why is Jesper in an orphanage?",a="Jesper is one of the many human children orphaned by the ongoing conflicts that have plagued Stormwind and the wider Eastern Kingdoms over recent years, finding refuge in Cathedral Square under the care of the Church of the Holy Light.",al={"jesper parents","who are jesper parents","why is jesper an orphan"}}},ang={["faction:Alliance"]="For Alliance heroes celebrating Hallow's End, running errands to satisfy Jesper's sweet tooth is a heartwarming tradition of bringing holiday cheer to Stormwind's most vulnerable youth."},kw={"cathedral square","hallow's end","jesper","orphan","orphanage","stormwind"},rel={"quest:8311","subzone:cathedral-square","zone:stormwind","topic:stormwind-kingdom"},src={"Jesper"}}
E["npc:jordan-stilwell"] = {t="npc",n="Jordan Stilwell",z="stormwind",s="Jordan Stilwell is a skilled human weaponsmith stationed outside the snowy Gates of Ironforge in Dun Morogh. Though originally called toward the priesthood of the Holy Light, he followed his father's craft to become an artisan whose work serves paladins across the Alliance. He is best known for forging Verigan's Fist in honor of his late friend, Bosch Verigan.",h="Jordan Stilwell is a skilled human weaponsmith stationed outside the snowy Gates of Ironforge in Dun Morogh.",sec={{t="A Calling at the Anvil",b="Though Jordan Stilwell was expected to take holy vows and become a paladin within the Church of the Holy Light, he ultimately chose the way of the forge. He followed in his father's footsteps, taking up his father's enchanted smithing hammer. Jordan refined his craft under the tutelage of the dwarven blacksmith Bailor Stonehand. Despite setting aside the mantle of an anointed holy warrior, Jordan remains deeply faithful to the Light, dedicating his extraordinary craftsmanship to outfitting champions who fight in its name.",sp=0},{t="Flight from Silverpine",b="Long before setting up shop in the biting cold of Dun Morogh, Jordan served as a smith at the keep of Baron Silverlaine in Silverpine Forest. When Archmage Arugal unleashed the feral worgen upon the fortress, turning it into the cursed bastion known as Shadowfang Keep, Jordan managed to escape the bloodshed. Forced to abandon his forge and his former home, he eventually found refuge among the dwarves of Dun Morogh.",sp=0},{t="Forging Verigan's Fist",b="Jordan keeps his forge outdoors near the gates of Ironforge, favoring the brisk alpine air over the stifling heat of the Great Forge inside the mountain. When the Church of the Holy Light sends worthy paladins to him, Jordan tasks them with recovering rare materials from across the world to craft a legendary two-handed warhammer. Named Verigan's Fist after his fallen friend Bosch Verigan, the weapon stands as a testament to the enduring bond between devoted faith and masterful steel.",sp=1}},faq={{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a master human blacksmith found working outside the Gates of Ironforge in Dun Morogh. He crafts sacred armaments for paladins of the Church of the Holy Light, most notably the legendary warhammer Verigan's Fist.",al={"who is jordan stilwell","jordan stilwell lore","who is this blacksmith outside ironforge"}},{q="Why does Jordan Stilwell work outside in the snow instead of inside Ironforge?",a="According to Duthorian Rall in Stormwind, Jordan prefers working in the crisp, cool mountain air of Dun Morogh rather than the stifling interior of the Great Forge within Ironforge.",al={"why is jordan outside ironforge","why work in dun morogh","why is he in the snow"}},{q="What is Jordan Stilwell's connection to Shadowfang Keep?",a="Jordan was once an armorer and blacksmith stationed at Baron Silverlaine's estate in Silverpine Forest. He managed to flee the keep before or during the disastrous uprising when Archmage Arugal and his feral worgen slaughtered the garrison and overtook the fortress.",al={"jordan stilwell shadowfang keep","jordan stilwell silverpine","did he live in pyrewood"}},{q="What is Verigan's Fist?",a="Verigan's Fist is a powerful two-handed holy hammer forged by Jordan Stilwell for Alliance paladins. It is named in memory of Jordan's close friend, Bosch Verigan, who perished in service to the Light.",al={"verigans fist","verigan hammer","who is verigan"}},{q="Who trained Jordan Stilwell in blacksmithing?",a="Jordan inherited his craft and an enchanted smithing hammer from his father, and went on to refine his expertise under the instruction of the dwarven blacksmith Bailor Stonehand.",al={"who trained jordan stilwell","jordan stilwell teacher","where did he learn smithing"}},{q="Who is Jordan Stilwell's wife?",a="Jordan is married to Daphne Stilwell. Together, the couple has provided immense aid to the Church of the Holy Light over the years, and both are revered as deeply devout servants of the faith.",al={"jordan stilwell wife","daphne stilwell husband","daphne stilwell"}}},ang={["class:Paladin"]="Jordan Stilwell is a crucial figure in a paladin's early trials, tasking them with scouring Azeroth for rare components to forge their signature warhammer, Verigan's Fist.",["profession:Blacksmithing"]="Trained by the dwarf Bailor Stonehand and wielding an enchanted hammer inherited from his father, Jordan represents the pinnacle of mortal holy metalworking.",["faction:Alliance"]="Having fled the horrors of Arugal's worgen in Silverpine Forest, Jordan found sanctuary with the dwarves of Dun Morogh and now lends his craft directly to Alliance champions."},kw={"bailor stonehand","bosch verigan","daphne stilwell","dun morogh","ironforge","jordan stilwell","shadowfang keep","tome of valor","verigan's fist","verigans fist"},rel={"quest:1653","quest:1649","npc:duthorian-rall","npc:daphne-stilwell","npc:bailor-stonehand","zone:shadowfang","subzone:gates-of-ironforge","topic:church-of-the-holy-light"},src={"Jordan Stilwell"}}
E["npc:jorgen"] = {t="npc",n="Jorgen",z="stormwind",s="Jorgen is a discreet human informant residing in Stormwind City, tucked away by the water just inside the Valley of Heroes. Despite his modest and out-of-the-way perch, he is entangled in sensitive matters involving prominent figures in the capital, including Elling Trias and Bishop DeLavey.",h="Jorgen is a discreet human informant residing in Stormwind City, tucked away by the water just inside the...",sec={{t="Eyes by the Water",b="Positioned down near the water immediately to the right of Stormwind's monumental entryway, Jorgen maintains a low profile away from the bustling thoroughfares of the city. While the towering statues of heroes overlook the bridge above, Jorgen monitors comings and goings from the shadows below, serving as a quiet contact for those who need information kept off the record.",sp=0},{t="A Tangled History",b="Jorgen's discreet presence is no accident. He shares an uneasy past with master cheese merchant and intelligence gatherer Elling Trias, as well as Bishop DeLavey of the Cathedral of Light. When delicate investigations arise—such as unraveling the circumstances behind King Varian Wrynn's vanished envoy—Jorgen is one of the few local contacts capable of pointing investigators in the right direction, provided they know how to approach him.",sp=1}},faq={{q="Where can I find Jorgen?",a="Jorgen is located in Stormwind City within the Valley of Heroes. As soon as you enter the city gates from Elwynn Forest, head down toward the water to the right of the main bridge.",al={"jorgen location","where is jorgen","find jorgen"}},{q="Who is Jorgen connected to in Stormwind?",a="Jorgen has a storied history with Elling Trias, the prominent cheesemonger in the Trade District with covert connections, as well as Bishop DeLavey of the Cathedral of Light.",al={"jorgen connections","jorgen ties","who does jorgen know"}},{q="What role does Jorgen play in the investigation of the missing diplomat?",a="During the search for the missing envoy, Jorgen serves as a key informant. Inquirers are directed to him to uncover who may have facilitated secret meetings and covert operations within the kingdom.",al={"jorgen missing diplomat","jorgen quest"}},{q="Is Jorgen affiliated with the Stormwind City Guard?",a="No. Jorgen operates independently, lurking away from the official guard patrols down near the canal banks where discreet conversations can happen out of earshot.",al={"is jorgen a guard","jorgen faction"}}},ang={["class:Rogue"]="Jorgen represents the street-level network of whispers that thrives beneath Stormwind's pristine marble, closely tied to the clandestine operations run through Trias' Cheese.",["faction:Alliance"]="When official channels in Stormwind run into bureaucratic walls, reliable street informants like Jorgen are critical for tracking down threats to the kingdom."},kw={"bishop delavey","elling trias","informant","jorgen","missing diplomat","stormwind","valley of heroes"},rel={"quest:1241","npc:elling-trias","npc:bishop-delavey","subzone:valley-of-heroes","zone:stormwind","topic:stormwind-kingdom"},src={"Jorgen"}}
E["npc:katrana-prestor"] = {t="npc",n="Lady Katrana Prestor",z="stormwind",s="Lady Katrana Prestor is a noblewoman of Stormwind and one of the most influential voices at court. With King Varian missing, she stands beside the boy-king Anduin and Highlord Bolvar Fordragon in Stormwind Keep as a trusted advisor.",h="Lady Katrana Prestor is a noblewoman of Stormwind and one of the most influential voices at court.",sec={{t="Voice of the Court",b="Lady Prestor arrived at court some years ago and quickly rose to become one of its most trusted figures. The nobles of Stormwind seek her favor, and her counsel shapes many of the decisions made in the young king's name while Highlord Bolvar Fordragon rules as regent. Petitioners who come to Stormwind Keep asking for soldiers or aid often find that her opinion carries as much weight as the regent's.",sp=0}},faq={{q="Who is Lady Katrana Prestor?",a="Lady Katrana Prestor is a Stormwind noblewoman and a trusted advisor at court. With King Varian missing, she stands beside the boy-king Anduin and Highlord Bolvar Fordragon in Stormwind Keep, and her voice carries great weight with the nobles.",al={"who is katrana prestor","who is lady prestor","katrana prestor lore"}},{q="Why is she advising the king?",a="King Varian's disappearance left his young son Anduin on the throne, with Highlord Bolvar Fordragon ruling as regent. Lady Prestor sits at their side as an advisor. Many of the court's decisions, including how Stormwind answers requests for help from its outlying lands, pass through her counsel.",al={"why is prestor at court","what does katrana do"}},{q="Where can I find Lady Prestor?",a="She is usually found in the throne room of Stormwind Keep, standing near Highlord Bolvar Fordragon and the young King Anduin.",al={"where is katrana prestor","katrana prestor location"}}},kw={"katrana","prestor","katrana prestor","lady prestor","advisor","stormwind keep","court"},rel={"zone:stormwind","npc:bolvar-fordragon","npc:anduin-wrynn"},src={"Katrana Prestor"}}
E["npc:keryn-sylvius"] = {t="npc",n="Keryn Sylvius",z="stormwind",s="Keryn Sylvius is a human rogue trainer stationed on the second floor of Goldshire's Lion's Pride Inn. Tucked away in the inn's reading room, she teaches fledgling scoundrels the basics of stealth and bladecraft while acting as a quiet conduit to Stormwind's intelligence service.",h="Keryn Sylvius is a human rogue trainer stationed on the second floor of Goldshire's Lion's Pride Inn.",sec={{t="A Quiet Presence in Goldshire",b="While the ground floor of the Lion's Pride Inn bustles with boisterous travelers and weary town guards, Keryn Sylvius keeps to the quiet reading room upstairs. Outwardly unassuming, she observes the constant flow of road gossip and serves as the local mentor for rogues cutting their teeth in Elwynn Forest. When promising operatives outgrow local petty thievery and roadside skulduggery, Sylvius discretely sends them onward to Stormwind City to make contact with SI:7.",sp=0}},faq={{q="Where can I find Keryn Sylvius?",a="She is located on the second floor of the Lion's Pride Inn in Goldshire, secluded in the small reading room.",al={"keryn sylvius location","where is keryn","goldshire rogue trainer location"}},{q="What services does she offer?",a="Keryn Sylvius is a rogue trainer who teaches new abilities, resets talent specializations, and provides direction to developing rogues.",al={"what does keryn do","can she train me","keryn sylvius role"}},{q="What connection does she have to SI:7?",a="Sylvius serves as an early contact point for Stormwind's covert intelligence network, sending skilled operatives to seek out Master Mathias Shaw and SI:7 in Old Town once they prove their capabilities.",al={"keryn si7","is she si:7","does she work for stormwind"}}},ang={["class:Rogue"]="Sylvius is the primary mentor for budding rogues roaming Elwynn Forest, eventually pointing them toward SI:7 headquarters in Stormwind City.",["faction:Alliance"]="Positioned above Goldshire's crossroads, she helps keep the Alliance's covert eyes open along the major thoroughfares of Elwynn."},kw={"elwynn forest","goldshire","keryn sylvius","lion's pride inn","rogue trainer","si:7"},rel={"subzone:lion-s-pride-inn","subzone:goldshire","zone:elwynn","quest:2205","quest:2300"},src={"Keryn Sylvius"}}
E["npc:lieutenant-orrin"] = {t="npc",n="Lieutenant Orrin",z="stormwind",s="Lieutenant Orrin is an officer of the Argent Dawn stationed at the gates of Stormwind City. Positioned in the Valley of Heroes, he coordinates local defense against incursions by the Scourge and directs fresh recruits to investigate undead threats outside the capital's walls.",h="Lieutenant Orrin is an officer of the Argent Dawn stationed at the gates of Stormwind City.",sec={{t="A Sentinel at the Gates",b="While the Argent Dawn is primarily known for holding the front lines in the ruined north, their presence extends south to safeguard vital strongholds like Stormwind City. Lieutenant Orrin stands near the towering statues of the Valley of Heroes, watching the road for signs of corruption. When necromantic magic stirs outside the capital, he is tasked with sounding the alarm and rallying adventurers before foul forces can threaten the populace.",sp=0},{t="Eyes on the Unliving",b="Orrin acts as a primary liaison between the independent order and volunteers within the southern kingdom. When signs of the Scourge surface beyond the city gates, he marshals able-bodied scouts and sends them out to gather intelligence and secure hazardous artifacts, such as cracked necrotic crystals, to better understand and repel the undead threat.",sp=0}},faq={{q="Who is Lieutenant Orrin?",a="Lieutenant Orrin is a human officer serving the Argent Dawn. He is stationed in the Valley of Heroes at the entrance of Stormwind City, tasked with coordinating defenses and enlisting scouts whenever the Scourge threatens the surrounding lands.",al={"who is orrin","lieutenant orrin lore","who is the argent dawn officer"}},{q="Why is the Argent Dawn in Stormwind City?",a="Although the Argent Dawn primarily wages war against the Scourge in the Plaguelands, they maintain outposts and liaisons across major Alliance and Horde hubs. Stationed at the capital's gates, officers like Orrin keep watch for necromantic incursions and recruit capable fighters to stem the spread of the undead.",al={"why is argent dawn in stormwind","argent dawn stormwind","what is argent dawn doing here"}},{q="What does Lieutenant Orrin ask adventurers to do?",a="Orrin directs recruits to scout the perimeter outside Stormwind City, investigate signs of Scourge activity, and recover artifacts like cracked necrotic crystals to study the unholy magic behind the incursions.",al={"orrin quests","investigate the scourge of stormwind","what does orrin want"}}},ang={["faction:Alliance"]="For Alliance champions returning to the capital, Orrin serves as a stark reminder that even the southern heartlands are not entirely safe from the reach of the Lich King.",["class:Paladin"]="Paladins who uphold the Light often find natural common cause with the Argent Dawn's efforts to purge necromancy wherever it festers."},kw={"argent dawn","lieutenant orrin","necrotic crystal","orrin","scourge","stormwind","undead","valley of heroes"},rel={"topic:argent-dawn","topic:scourge","subzone:valley-of-heroes","zone:stormwind","quest:9260","topic:stormwind-kingdom"},src={"Lieutenant Orrin"}}
E["npc:lord-baurles-k-wishock"] = {t="npc",n="Lord Baurles K. Wishock",z="stormwind",s="Lord Baurles K. Wishock is a nobleman residing in Stormwind Keep's Petitioner's Chamber. Known among barkeeps for his unpaid tabs and fondness for strong drink, he stumbled upon darker dealings than mere drunkenness in the city's underbelly.",h="Lord Baurles K.",sec={{t="A Nobleman's Dangerous Curiosity",b="Holding court among the petitioners and dignitaries within Stormwind Keep, Lord Baurles K. Wishock is a member of the influential House of Nobles. Despite his elevated station, Wishock developed a habit of frequenting the dive bars of the Mage Quarter, especially the Slaughtered Lamb, leaving behind substantial unpaid bills. While drinking there, however, he caught wind of the warlock coven practicing dark arts in the cellars beneath the floorboards. Determined to shut the tavern down, Wishock began petitioning fellow nobles for a formal investigation—unaware that uncovering demonic cabals in Stormwind rarely goes unpunished.",sp=0},{t="A Poisoned Cup",b="Wishock's lobbying placed him squarely in the crosshairs of the city's hidden warlocks. Rather than risk royal scrutiny or an inquisition into their underground sanctum, the warlock Zardeth of the Black Claw orchestrated the nobleman's quiet elimination. Exploiting Wishock's notorious thirst for luxury vintages, the coven prepared a lethal concoction disguised as fine ale, arranging for an unsuspecting courier to deliver the fatal drink right under the noses of the Keep's guards.",sp=1}},faq={{q="Who is Lord Baurles K. Wishock?",a="Lord Baurles K. Wishock is an aristocrat affiliated with the House of Nobles. He spends his days in the Petitioner's Chamber inside Stormwind Keep, though he is infamous in the Mage Quarter for running up large, unpaid drinking tabs.",al={"baurles wishock","who is wishock","noble petitioner"}},{q="Where can Lord Wishock be found?",a="He can be found standing inside the Petitioner's Chamber on the eastern side of Stormwind Keep, surrounded by other courtiers, diplomats, and supplicants awaiting royal attention.",al={"wishock location","where is wishock","find lord wishock"}},{q="Why do the warlocks beneath the Slaughtered Lamb want him dead?",a="During his late nights drinking at the Slaughtered Lamb, Wishock learned that a coven of warlocks was operating beneath the tavern. He began lobbying the House of Nobles to launch a formal inquiry and shut the establishment down, threatening to expose their secret operations.",al={"why kill wishock","zardeth wishock","why poison wishock"},sp=1},{q="How is he assassinated?",a="Zardeth of the Black Claw brews a deadly poison and disguises it as an exquisite beverage. Knowing Wishock's weakness for fine alcohol and free drinks, an agent delivers the poisoned cask directly to him in Stormwind Keep.",al={"how does wishock die","wishock poison","a noble brew"},sp=1}},ang={["class:Warlock"]="Wishock's nosy investigation into the Slaughtered Lamb poses an immediate threat to Stormwind's shadow coven, making his quiet demise a top priority for practicing warlocks.",["race:Human"]="His presence in the Petitioner's Chamber reflects the decadent, self-serving reputation of the House of Nobles during the boy-king Anduin's early reign."},kw={"baurles","house of nobles","petitioner's chamber","slaughtered lamb","stormwind keep","wishock","zardeth"},rel={"quest:335","quest:397","npc:zardeth-of-the-black-claw","subzone:slaughtered-lamb","subzone:petitioner-s-chamber","subzone:stormwind-keep","topic:house-of-nobles"},src={"Lord Baurles K. Wishock"}}
E["npc:lucius"] = {t="npc",n="Lucius",z="stormwind",s="Lucius is a dwarf operative found near the docks of Lakeshire in the Redridge Mountains. Operating as an undercover field contact for Stormwind's SI:7 intelligence service, he assists operatives with specialized reconnaissance and trade skills.",h="Lucius is a dwarf operative found near the docks of Lakeshire in the Redridge Mountains.",sec={{t="Eyes in the Mountains",b="While Lucius presents himself casually on the Lakeshire waterfront, he is in fact a clandestine operative tied directly to Stormwind's intelligence apparatus, SI:7. From his post on the docks, he monitors trade, unusual traffic, and regional threats encroaching on Redridge. Operatives dispatched eastward from Stormwind are directed to him to coordinate covert tasks and hone practical fieldwork arts such as lockpicking, ensuring the Crown maintains hidden reach far beyond Elwynn Forest.",sp=0}},faq={{q="Who is Lucius?",a="Lucius is a dwarven agent stationed in Lakeshire who works on behalf of SI:7, the intelligence arm of the Kingdom of Stormwind.",al={"lucius identity","who is the dwarf on the docks","lucius npc"}},{q="What does Lucius do in Lakeshire?",a="He serves as a field contact for covert operatives, providing local instruction in thievery and lockpicking while keeping watch over regional movements in the Redridge Mountains.",al={"what is lucius doing here","lucius purpose","why is lucius on the docks"}},{q="Which quests involve Lucius?",a="Lucius is the contact for the SI:7 mission 'Redridge Rendezvous' and directs operatives toward surveillance at Alther's Mill.",al={"lucius quests","redridge rendezvous quest","alther's mill"}}},ang={["class:Rogue"]="For rogues sent afield from Stormwind, Lucius serves as an essential contact and instructor for fine-tuning lockpicking and reconnaissance skills.",["race:Dwarf"]="Lucius is a reminder that dwarven talents extend well beyond the forge and front line, finding a home within Stormwind's covert operations."},kw={"docks","dwarf","lakeshire","lockpick","lucius","redridge","rogue","si:7"},rel={"quest:2281","quest:2282","quest:2300","subzone:lakeshire","zone:redridge","topic:dwarf"},src={"Lucius"}}
E["npc:lyria-du-lac"] = {t="npc",n="Lyria Du Lac",z="stormwind",s="Lyria Du Lac is a human warrior trainer stationed in Goldshire within Elwynn Forest. Tucked away just behind the village smithy, she drills novice combatants and guides young warriors as they begin mastering their stances and arms.",h="Lyria Du Lac is a human warrior trainer stationed in Goldshire within Elwynn Forest.",sec={{t="Warrior Trainer of Goldshire",b="While Goldshire's Lion's Pride Inn bustles with travellers and its blacksmith hammers away at local trade goods, Lyria Du Lac keeps to the yard behind the forge. Experienced in martial discipline, she serves the Alliance by instructing fledgeling warriors fresh from Northshire Abbey. She evaluates their readiness and introduces them to specialized combat techniques, ensuring that those who take up shield and blade for Stormwind can hold their own against the encroaching threats of Elwynn Forest.",sp=0}},faq={{q="Where can I find Lyria Du Lac?",a="Lyria Du Lac stands outside directly behind the blacksmith shop in Goldshire, just west of the Lion's Pride Inn in Elwynn Forest.",al={"lyria du lac location","where is lyria","warrior trainer goldshire"}},{q="What service does Lyria Du Lac provide?",a="She is a warrior trainer. She teaches fledgling warriors essential combat maneuvers, stance fundamentals, and battle disciplines as they advance in skill.",al={"what does lyria do","lyria du lac role","what does lyria teach"}},{q="What quests involve Lyria Du Lac?",a="Young Alliance warriors completing their earliest training in Northshire are directed to her through the quest 'A Warrior's Training' to continue honing their martial abilities.",al={"lyria du lac quests","warrior quest goldshire"}}},ang={["class:Warrior"]="For warriors fresh from Northshire Abbey, Lyria Du Lac is the first major trainer you meet in Elwynn Forest, helping you sharpen your stance mastery and melee tactics.",["faction:Alliance"]="Positioned behind Goldshire's forge, Lyria ensures local recruits are capable of defending the heartland of Stormwind from Defias brigands and gnoll raiders."},kw={"a warrior's training","blacksmith","elwynn forest","goldshire","lyria du lac","warrior trainer"},rel={"subzone:goldshire","zone:elwynn","quest:1638"},src={"Lyria Du Lac"}}
E["npc:major-mattingly"] = {t="npc",n="Major Mattingly",z="stormwind",s="Major Mattingly is a seasoned officer of the Stormwind Army stationed at the grand gates in the Valley of Heroes. Serving under General Hammond Clay, he assists in safeguarding the capital's main entrance and advising capable crafters on protecting heroes against draconic threats.",h="Major Mattingly is a seasoned officer of the Stormwind Army stationed at the grand gates in the Valley of...",sec={{t="Sentinel of the Capital Gates",b="Standing watch in the Valley of Heroes, Major Mattingly is one of the high-ranking officers directly responsible for Stormwind City's primary landward defense. A grizzled veteran soldier whose face bears the lines of hard-won experience, he serves under General Hammond Clay alongside the city's standing garrison. Beyond his daily duties overseeing gate patrols and incoming travelers, Mattingly possesses specialized tactical knowledge regarding the lethal nature of dragons. He is recognized by seasoned adventurers as a vital contact when learning to craft protective dragonscale gear necessary for braving the realm's deadliest lairs.",sp=0}},faq={{q="Where can Major Mattingly be found?",a="Major Mattingly is stationed near the entrance of Stormwind City in the Valley of Heroes, standing watch alongside fellow garrison troops just inside the main gates.",al={"mattingly location","where is major mattingly","find major mattingly"}},{q="What is Major Mattingly's rank and role in Stormwind?",a="He is an officer in the Stormwind Army serving under General Hammond Clay. He helps oversee the defense of the city's gates and provides military guidance to adventurers.",al={"who is mattingly","mattingly job","what does mattingly do"}},{q="Why do leatherworkers seek out Major Mattingly?",a="Mattingly possesses instructions on how to treat and craft scale cloaks from black dragonhide, guiding skilled crafters who wish to protect their allies from draconic flame.",al={"onyxia scale cloak mattingly","mattingly quest","the journey has just begun mattingly"}},{q="Is Major Mattingly involved in any broader conflicts?",a="He is a battle-hardened veteran of the Kingdom of Stormwind, dedicated to the defense of the realm while King Varian Wrynn remains missing and the kingdom contends with lingering threats.",al={"mattingly background","mattingly lore"}}},ang={["faction:Alliance"]="For Alliance champions seeking to challenge great dragons like Onyxia, Major Mattingly provides the crucial guidance needed to craft defensive cloaks out of dragon scales.",["class:Warrior"]="As a disciplined veteran wielding his longsword at the city gates, Mattingly represents the steadfast resolve of the Stormwind Army's infantry officers."},kw={"dragonscale cloak","hammond clay","major mattingly","mattingly","stormwind army","valley of heroes"},rel={"subzone:valley-of-heroes","zone:stormwind","topic:stormwind-army","quest:7493","topic:stormwind-kingdom","topic:alliance"},src={"Major Mattingly"}}
E["npc:milton-sheaf"] = {t="npc",n="Milton Sheaf",z="stormwind",s="Milton Sheaf is the head librarian of the Royal Library inside Stormwind Keep. Dedicated to preserving the kingdom's history, he oversees the realm's collection of ancient tomes and historical chronicles. He frequently enlists Alliance travelers to recover lost volumes, track down scattered records, and restore neglected manuscripts.",h="Milton Sheaf is the head librarian of the Royal Library inside Stormwind Keep.",sec={{t="The Caretaker of Stormwind's History",b="Tucked away in the quiet halls of the Royal Library in Stormwind Keep, Milton Sheaf tends to the collective memory of the kingdom. While the court upstairs bustles with politics, squabbling nobles, and military concerns, Sheaf focuses on the preservation of the written word. He considers maintaining accurate histories of the Alliance and the Eastern Kingdoms a sacred duty, especially in an era fraught with war, loss, and instability.",sp=0},{t="Recovering Lost Tomes",b="Preserving the library's collection requires constant effort. Books suffer wear and tear, and valuable records are often scattered across the realm in monastic archives, distant outposts, or forgotten ruins. Milton regularly dispatches adventurers across the land—from Northshire Abbey to the distant northern settlement of Southshore—to retrieve misplaced volumes, investigate ancient texts, and ensure rare manuscripts return safely to the keep's shelves.",sp=0}},faq={{q="Who is Milton Sheaf?",a="Milton Sheaf is a human scholar and the chief caretaker of the Royal Library, located within Stormwind Keep in Stormwind City. He manages the kingdom's book collections and chronicles.",al={"who is milton sheaf","milton sheaf role","stormwind librarian"}},{q="Where can I find Milton Sheaf?",a="You can find Milton Sheaf inside the Royal Library wing of Stormwind Keep, situated just off the main palace corridors.",al={"milton sheaf location","where is milton sheaf","stormwind library location"}},{q="Why does Milton Sheaf need adventurers?",a="Milton often relies on traveling Alliance adventurers to track down historical manuscripts, replace damaged books, and coordinate with scholars and priests across the kingdom to expand the Royal Library's archives.",al={"milton sheaf quests","what does milton want","why give quests"}},{q="Does Milton Sheaf interact with other scholars in the kingdom?",a="Yes. He maintains ties with monastic archivists and religious scholars, including Brother Paxton in Northshire Valley, to preserve sacred teachings and historical records.",al={"milton northshire","milton brother paxton","milton connections"}}},ang={["faction:Alliance"]="As the kingdom's premier librarian, Milton Sheaf helps preserve the recorded heritage of the human kingdoms and the wider Alliance.",["race:Human"]="Milton safeguards centuries of human history, protecting chronicles that survived the fall and reconstruction of Stormwind."},kw={"books","history","librarian","milton sheaf","royal library","stormwind keep","tomes"},rel={"subzone:royal-library","subzone:stormwind-keep","zone:stormwind","quest:337","quest:343","quest:344","subzone:southshore","topic:stormwind-kingdom"},src={"Milton Sheaf"}}
E["npc:onyxia"] = {t="npc",n="Onyxia",z="stormwind",s="Onyxia is the broodmother of the black dragonflight and the devious daughter of Deathwing. Lurking in her wyrm lair within Dustwallow Marsh, she tends to her burgeoning brood while coordinating with her sinister dragonflight to exert dominance over the mortal realms.",h="Onyxia is the broodmother of the black dragonflight and the devious daughter of Deathwing.",sec={{t="The Broodmother in the Court",b="While her brother Nefarian consolidates his armies within Blackrock Spire, Onyxia pursues power through guile. Taking the guise of Lady Katrana Prestor, she has wormed her way into the highest echelons of Stormwind's nobility. By posing as a trusted adviser to the House of Nobles, she systematically undercuts the kingdom's military efforts, intentionally withholding soldiers and resources from outposts in Westfall, Redridge, and the Burning Steppes to leave mortal realms defenseless.",sp=1},{t="Architect of Ruin",b="Behind the painted smiles of Lady Prestor lies a predatory mastermind responsible for Stormwind's most agonizing tragedies. It was Onyxia who stoked the bitter dispute between the Stonemasons' Guild and the House of Nobles, sparking the deadly riot that claimed the life of Queen Tiffin Wrynn. With King Varian now abducted en route to a peace summit at Theramore, Prestor exerts deep influence over the young boy-king Anduin and ensnares Highlord Bolvar Fordragon, bringing the throne teetering on the edge of her talons.",sp=2}},faq={{q="Who is Lady Katrana Prestor?",a="Lady Katrana Prestor is the mortal persona assumed by the black dragon Onyxia. Using this noble guise, she whispers counsel to Stormwind's House of Nobles and manipulates the kingdom's politics without arousing suspicion.",al={"prestor identity","who is prestor","katrana prestor real identity"},sp=2},{q="Why does Onyxia target Stormwind?",a="Onyxia considers humanity the mortal race best positioned to challenge dragonkind. By infiltrating Stormwind's government, she aims to subjugate the kingdom from the shadows, neutralize its military power, and aid her brother Nefarian's dominion over the region.",al={"onyxia goal","why attack stormwind","prestor motive"},sp=2},{q="Where does Onyxia live?",a="Onyxia's home is a subterranean lair nestled in the swamps of Dustwallow Marsh, where she tends to the clutches of her black dragonflight.",al={"where is onyxia","onyxia location","onyxia lair location"},sp=2},{q="What is her connection to Nefarian and Deathwing?",a="Onyxia is the daughter of the Aspect Deathwing and his consort Sintharia. She is also the younger twin sister of Nefarian, working closely with him to restore the black dragonflight's supremacy across Azeroth.",al={"onyxia brother","onyxia father","onyxia family"}}},kw={"anduin wrynn","black dragonflight","bolvar fordragon","deathwing","nefarian","onyxia","stormwind"},rel={"subzone:onyxia-s-lair","topic:black-dragonflight","zone:stormwind","npc:deathwing","topic:house-of-nobles","topic:varian-wrynn","topic:defias-brotherhood"},src={"Onyxia"}}
E["npc:orphan-matron-nightingale"] = {t="npc",n="Orphan Matron Nightingale",z="stormwind",s="Orphan Matron Nightingale oversees the Stormwind Orphanage located in Cathedral Square. Alongside Matron Shellene, she cares for children who have lost their families to the relentless conflicts troubling the kingdom. She also enlists trusted Alliance adventurers to mentor and inspire her young wards during Children's Week.",h="Orphan Matron Nightingale oversees the Stormwind Orphanage located in Cathedral Square.",sec={{t="Guardian of the Displaced",b="Standing watch just outside the orphanage south-east of the Cathedral of Light, Orphan Matron Nightingale tends to Stormwind's most vulnerable survivors. Recent wars, gnoll rampages, and the rise of the Defias Brotherhood have left many children without homes or parents. Nightingale and her fellow caretaker, Matron Shellene, provide these youngsters shelter, basic care, and guidance beneath the watchful eye of the Church of the Holy Light.",sp=0},{t="Children's Week Patron",b="Believing that hope is as vital as food and shelter, Matron Nightingale organizes Stormwind's Children's Week celebrations. During this time, she appeals directly to Alliance heroes to chaperone an orphan on travels across Azeroth. By pairing these children with celebrated champions, she hopes to instill confidence, grant them a broader view of the world outside the city walls, and remind them that they are never truly forgotten.",sp=0}},faq={{q="Where can Orphan Matron Nightingale be found?",a="She stands directly outside the entrance to the Stormwind Orphanage, situated in Cathedral Square to the south-east of the Cathedral of Light.",al={"matron nightingale location","stormwind orphanage location","where is nightingale"}},{q="Why are there so many orphans in Stormwind?",a="The kingdom has endured devastating wars, including the Third War and ongoing skirmishes with the Defias Brotherhood, orc remnants, and hostile beasts in nearby territories. Many city residents and frontier farmers have perished, leaving behind children with nowhere else to turn.",al={"why are there orphans","stormwind orphans origin","who are these kids"}},{q="What is Children's Week?",a="Children's Week is an annual event in Stormwind organized by Matron Nightingale. Alliance adventurers are invited to act as guardians and chaperones for an orphan, taking them on journeys to witness the wonders and heroes of the wider world.",al={"childrens week stormwind","what is children's week","orphan event"}},{q="Who helps Matron Nightingale run the orphanage?",a="Matron Shellene works alongside Nightingale inside and around the orphanage, helping to raise, feed, and shelter the children under their care.",al={"other orphan matron","who runs the orphanage","matron shellene"}}},ang={["faction:Alliance"]="For Alliance champions, Nightingale serves as a reminder of the quiet, everyday costs of war and the duty to protect the realm's future generations.",["class:Priest"]="Stationed right outside the Cathedral of Light, Nightingale's mission embodies the virtues of compassion and service that priests of the Holy Light strive to uphold."},kw={"cathedral square","children's week","matron shellene","nightingale","orphan matron nightingale","stormwind","stormwind orphanage"},rel={"subzone:cathedral-square","subzone:cathedral-of-light","zone:stormwind","quest:171","topic:stormwind-kingdom","topic:light","topic:alliance"},src={"Orphan Matron Nightingale"}}
E["npc:osric-strang"] = {t="npc",n="Osric Strang",z="stormwind",s="Osric Strang is a veteran armor merchant who operates Limited Immunity, a shop situated in Stormwind's Old Town. Specializing in heavy mail and plate, he supplies sturdy gear and shields to Alliance defenders and weary travelers passing through the capital.",h="Osric Strang is a veteran armor merchant who operates Limited Immunity, a shop situated in Stormwind's Old...",sec={{t="Shopkeeper of Limited Immunity",b="Tucked away in the weathered streets of Old Town, Osric Strang manages Limited Immunity, a shop catering to frontline fighters in need of heavy armor and shields. Osric has a history of guard service in Stormwind, giving him a practical eye for the protective value of mail and plate. While his wares are suited for standard soldiers and traveling adventurers, he often assists incoming couriers who need a point of contact when arriving in the capital from nearby settlements like Redridge.",sp=0}},faq={{q="What does Osric Strang sell?",a="Osric sells various pieces of heavy protective armor, ranging from augmented chain and polished scale to solid platemail suits, bucklers, and heater shields.",al={"osric items","what does osric strang have","limited immunity goods"}},{q="Where can I find Osric Strang?",a="He can be found inside Limited Immunity, an armor shop in Old Town near the southern district of Stormwind.",al={"osric location","where is osric strang","limited immunity location"}},{q="Why am I sent to Osric Strang on a quest?",a="Couriers delivering goods across the kingdom, such as shipments arriving via gryphon master from Redridge, are often directed to Osric's shop in Old Town to complete deliveries and receive return messages.",al={"why talk to osric","osric strang quest","delivery to osric"}}},ang={["class:Warrior"]="Osric Strang offers reliable sets of chain, scale, plate, and shields, serving as an early source of dependable bulk protection for warriors visiting Old Town.",["faction:Alliance"]="A loyal resident and former city guard, Osric equips the kingdom's defenders and aids couriers maintaining supply links between Stormwind and outlying settlements."},kw={"dungar longdrink","heavy armor","limited immunity","old town","osric strang","shields","stormwind vendor"},rel={"subzone:old-town","quest:6281","quest:6261","topic:stormwind-kingdom"},src={"Osric Strang"}}
E["npc:randis"] = {t="npc",n="Randis",z="stormwind",s="Randis is a spirited young human orphan under the care of Orphan Matron Nightingale at the orphanage in Cathedral Square. During Children's Week, he eagerly accompanies willing adventurers across the Alliance's territories to take in sights far beyond the city walls.",h="Randis is a spirited young human orphan under the care of Orphan Matron Nightingale at the orphanage in...",sec={{t="A Ward of Stormwind",b="Residing in the orphanage near Stormwind's Cathedral of Light, Randis is one of many children left without family in the wake of the realm's persistent conflicts. When the annual Children's Week arrives, Orphan Matron Nightingale entrusts sympathetic heroes with a whistle to take him under their wing. Full of youthful curiosity and nonstop questions, Randis dreams of adventuring, asks endless riddles, and boldly declares that when he grows up, he wants to be the king of Stormwind.",sp=0},{t="Eyes on the World",b="For a boy who spends most of his days penned up in Cathedral Square, leaving the capital is a grand adventure. Randis marvels at distant wonders like the grand Stonewrought Dam in Loch Modan and dreams of meeting famous figures across Azeroth. Though he is quick to note that places like Ironforge smell rather odd, his boundless wonder reflects the innocent future that heroes of the Alliance fight to protect.",sp=0}},faq={{q="Who is Randis?",a="Randis is a human child staying at the Stormwind Orphanage in Cathedral Square. During the festivities of Children's Week, adventurers can volunteer to look after him and take him on travels across the world.",al={"randis npc","who is the human orphan","human orphan stormwind"}},{q="How do you meet Randis?",a="During Children's Week, Orphan Matron Nightingale in Cathedral Square provides adventurers with an orphan whistle. Blowing the whistle summons Randis so he can tag along on your adventures.",al={"how to get randis","summon randis","orphan whistle stormwind"}},{q="What places does Randis want to visit?",a="Randis longs to see legendary landmarks across the Alliance, including the immense Stonewrought Dam in Loch Modan and prominent figures of the realm, giving him a glimpse of life outside Stormwind.",al={"randis places","randis sights","childrens week human orphan locations"}},{q="Why is Randis living in an orphanage?",a="Like many children under Matron Nightingale's roof, Randis lost his parents to the constant wars, invasions, and hardships that have struck the kingdom of Stormwind and the wider lands of Azeroth.",al={"randis parents","why is randis an orphan","stormwind orphanage lore"}}},ang={["faction:Alliance"]="Mentoring Randis during Children's Week reminds Alliance champions what their battles are truly for: protecting the next generation of civilians and dreamers."},kw={"cathedral square","children's week","human orphan","matron nightingale","randis","stonewrought dam","stormwind"},rel={"npc:orphan-matron-nightingale","subzone:cathedral-square","zone:stormwind","subzone:stonewrought-dam","zone:ironforge","topic:stormwind-kingdom"},src={"Randis"}}
E["npc:rema-schneider"] = {t="npc",n="Rema Schneider",z="stormwind",s="Rema Schneider is a human citizen who works out of the Canal Tailor and Fit Shop in Stormwind City. Situated along the quiet waterways between the major districts, she frequently assists local shopkeepers and artisans with trade deliveries.",h="Rema Schneider is a human citizen who works out of the Canal Tailor and Fit Shop in Stormwind City.",sec={{t="Shopkeeper of the Canals",b="Tucked away in the Canal Tailor and Fit Shop, positioned just west of the stone bridge leading across to Cathedral Square, Rema Schneider manages the daily needs of urban trade. Like many skilled artisans and assistants across the city, her work keeps cloth and finished garments moving between local craftsmen, relying on helpful couriers to carry supplies between workshops.",sp=0}},faq={{q="Where is Rema Schneider located?",a="Rema Schneider works inside the Canal Tailor and Fit Shop in Stormwind City. The shop sits along the northern waterways, just west of the bridge that crosses into Cathedral Square.",al={"rema schneider location","where is rema","find rema schneider"}},{q="What role does Rema play in Stormwind?",a="She acts as a contact and quest giver for local trade errands, helping coordinate supply packages and resupply orders between merchants and craftspeople across the city.",al={"who is rema schneider","what does rema do","rema schneider purpose"}},{q="Does Rema teach tailoring?",a="No, while she works out of the Canal Tailor and Fit Shop and handles shipments of tailor goods, she is not a profession trainer or primary vendor.",al={"is rema a tailor trainer","rema tailoring training"}}},ang={["profession:Tailoring"]="Rema works inside the Canal Tailor and Fit Shop, serving as an everyday fixture in Stormwind's clothworking trade.",["faction:Alliance"]="Travelers and new recruits in Stormwind often run simple courier tasks for Rema while getting their bearings in the capital."},kw={"canal tailor","harlan needs a resupply","package for thurman","rema schneider","stormwind canals"},rel={"quest:333","quest:334","zone:stormwind","subzone:canals-stormwind-city","subzone:cathedral-square","topic:stormwind-kingdom"},src={"Rema Schneider"}}
E["npc:renato-gallina"] = {t="npc",n="Renato Gallina",z="stormwind",s="Renato Gallina is an energetic barker found promoting business in Stormwind City's bustling Trade District. A member of the Gallina winemaking family, his job is to drum up patrons and direct thirsty travelers to the family winery nestled along the city canals.",h="Renato Gallina is an energetic barker found promoting business in Stormwind City's bustling Trade District.",sec={{t="Voice of the Gallina Winery",b="Standing amidst the busy stalls of the Trade District, Renato Gallina spends his days calling out to passers-by, boldly proclaiming that his family sells the finest vintages in all of Stormwind. His family operates the Gallina Winery located nearby along the Canals, and Renato serves as their public promoter, handing out advertisements to anyone willing to help spread word of their cellar to thirsty travelers across the kingdom.",sp=0}},faq={{q="Who is Renato Gallina?",a="Renato is a human barker working in Stormwind City's Trade District. He belongs to the Gallina family and spends his time promoting their family-owned winery to locals and visiting adventurers.",al={"renato gallina","who is renato","wine barker stormwind"}},{q="Where is the Gallina Winery located?",a="The Gallina Winery is situated along the Canals of Stormwind City, tucked just off the bustling streets of the main commercial quarters.",al={"where is gallina winery","stormwind wine shop location","gallina winery"}},{q="What does Renato ask adventurers to do?",a="Renato provides an advertisement for his family's wine shop, hoping willing couriers will help distribute the word and bring fresh business to their canal cellar.",al={"renato gallina quest","wine shop advert quest","what does renato want"}}},ang={["faction:Alliance"]="For Alliance travelers arriving in the capital, Renato offers a quick introduction to Stormwind's local commerce and domestic trades."},kw={"canals","gallina winery","renato gallina","stormwind wine","trade district","wine shop advert"},rel={"subzone:trade-district","subzone:canals-stormwind-city","quest:332","zone:stormwind","topic:stormwind-kingdom"},src={"Renato Gallina"}}
E["npc:skuerto"] = {t="npc",n="Skuerto",z="stormwind",s="Skuerto is a dwarven scout stationed at Refuge Pointe in the Arathi Highlands. Displaced from his home in Ironforge during the refugee crisis, he now aids the Alliance in the field, helping secure ancient magical relics on behalf of Archmage Malin.",h="Skuerto is a dwarven scout stationed at Refuge Pointe in the Arathi Highlands.",sec={{t="A Displaced Scout in the Highlands",b="Skuerto previously lived in Ironforge, but was displaced when city authorities made room to house thousands of gnome refugees escaping the radioactive fall of Gnomeregan. Relocating to the field, Skuerto took up work as a scout in the dangerous Arathi Highlands. Stationed alongside Apprentice Kryten at Refuge Pointe, he works under the direction of Archmage Malin to recover arcane reagents and potent magical artifacts that once belonged to Malin's old master, Archmage Trelane.",sp=0},{t="Pride and Peril",b="Despite the harsh conditions of the Highlands, Skuerto takes considerable pride in his wilderness scouting and reacts poorly to anyone questioning his competence. His work regularly brushes up against regional perils, from the hostile Syndicate and Boulderfist ogres to dangerous ancient entities tied to the land. Through his extensive travels and network of acquaintances, he maintains ties with diverse figures across the region, including Shakes O'Breen down at Faldir's Cove and Gerrig Bonegrip in the Ironforge forges.",sp=0}},faq={{q="Why is Skuerto stationed in Arathi instead of Ironforge?",a="Skuerto used to live in Ironforge, but lost his living space when the city cleared quarters to take in gnome refugees fleeing the disaster at Gnomeregan. Left without a home in the mountain capital, he took employment out in the field as an Alliance scout.",al={"why is skuerto here","skuerto backstory","ironforge refugee"}},{q="What is Skuerto's mission at Refuge Pointe?",a="Archmage Malin sent Skuerto and Apprentice Kryten to the Arathi Highlands to collect arcane reagents and recover powerful magical artifacts once owned by Malin's former master, Archmage Trelane.",al={"skuerto purpose","what does skuerto do","skuerto malin"}},{q="Who are Skuerto's allies in the region?",a="Beyond working directly with Apprentice Kryten and the Alliance garrison at Refuge Pointe, Skuerto is friends with Shakes O'Breen hiding out at Faldir's Cove, as well as Gerrig Bonegrip in Ironforge.",al={"skuerto friends","shakes obreen friend"}},{q="Does Skuerto hold a grudge against gnomes?",a="He harbors noticeable bitterness about losing his home in Ironforge to make room for displaced gnomes, though he remains dutifully in service to the Alliance cause out in Arathi.",al={"skuerto hates gnomes","skuerto gnomeregan"}}},ang={["race:Dwarf"]="Skuerto exemplifies the grit of dwarves forced out of the Great Forge into wild frontiers, though his pride as a scout is easily bruised.",["race:Gnome"]="Gnomes may find a chilly reception from Skuerto, who was ousted from his Ironforge lodging when the capital opened its doors to refugees after Gnomeregan fell."},kw={"arathi highlands","archmage malin","ironforge","refuge pointe","scout","skuerto","trelane"},rel={"subzone:refuge-pointe","zone:arathi","npc:archmage-malin","subzone:faldir-s-cove","npc:gerrig-bonegrip","zone:ironforge","zone:gnomeregan","topic:alliance"},src={"Skuerto"}}
E["npc:suzetta-gallina"] = {t="npc",n="Suzetta Gallina",z="stormwind",s="Suzetta Gallina is a member of the Gallina family, purveyors of fine vintages in Stormwind City. She can be found inside the family's wine shop tucked along the Canals, helping manage the business and spread word of their stock to thirsty patrons across the city.",h="Suzetta Gallina is a member of the Gallina family, purveyors of fine vintages in Stormwind City.",sec={{t="A Taste of the Canals",b="Situated along the scenic waterways of Stormwind's Canal District, the Gallina Winery caters to citizens seeking quality vintages imported or crafted across the kingdom. Suzetta Gallina helps oversee daily life in the establishment, maintaining the family legacy of supplying taverns, nobles, and common folk with wine. While not a public figure of high politics, her presence represents the everyday commercial heartbeat that keeps the capital thriving amidst broader troubles.",sp=0}},faq={{q="Who is Suzetta Gallina?",a="Suzetta Gallina is a resident of Stormwind City and a member of the Gallina family, who run the Gallina Winery located along the city's Canals.",al={"suzetta gallina","who is suzetta","gallina winery woman"}},{q="Where can I find Suzetta Gallina?",a="She is located inside the Gallina Winery, situated along the canals between the Trade District and Cathedral Square in Stormwind City.",al={"suzetta gallina location","where is suzetta","gallina winery location"}},{q="Does Suzetta offer any work for travelers?",a="Yes, Suzetta needs help drumming up business and sends couriers out with promotional advertisements to spread word of the winery's selection across town.",al={"suzetta quests","gallina wine quest","wine shop advert"}}},ang={["faction:Alliance"]="For Alliance travelers returning from the perils of Elwynn or Westfall, stopping by Suzetta's shop offers a warm reminder of peaceful, civilized life in the capital."},kw={"gallina winery","stormwind canals","stormwind wine","suzetta gallina","wine shop advert"},rel={"quest:332","zone:stormwind","subzone:canals-stormwind-city","topic:stormwind-kingdom"},src={"Suzetta Gallina"}}
E["npc:tyrion"] = {t="npc",n="Tyrion",z="stormwind",s="Tyrion is a covert gnome operative stationed inside Stormwind Keep. Operating in the shadows alongside close associates like Elling Trias, he aids adventurers in unearthing sensitive intelligence and combating treacherous plots against the kingdom.",h="Tyrion is a covert gnome operative stationed inside Stormwind Keep.",sec={{t="A Quiet Presence in the Keep",b="Amid the grandeur of Stormwind Keep, Tyrion keeps a low profile. While noble courtiers and royal guards bustle through the halls, this clever gnome operates under the radar, watching palace movements and liaising with outside contacts who operate far from official oversight.",sp=0},{t="Shadows and Espionage",b="Tyrion is a trusted confidant of Elling Trias, the renowned cheese merchant of the Trade District who operates a discreet information network. When sensitive matters arise that require bypassing the official bureaucracy of the House of Nobles, Trias directs reliable operatives straight to Tyrion inside the castle walls.",sp=0},{t="Uncovering the Threat",b="Tyrion assists investigators with critical infiltration tasks and securing sensitive goods within the city. His efforts culminate in identifying imminent danger within the royal heart of the kingdom, warning allies before an orchestrated strike can compromise Stormwind's leadership.",sp=1}},faq={{q="Who is Tyrion?",a="Tyrion is a resourceful gnome operative stationed within Stormwind Keep. Working alongside clandestine allies, he manages covert tasks and intelligence gathering that bypass standard royal channels.",al={"who is this gnome","tyrion identity","what does tyrion do"}},{q="Where can I find Tyrion?",a="Tyrion is located inside Stormwind Keep in Stormwind City, keeping watch and assisting agents who arrive with word from his trusted contacts.",al={"tyrion location","where is tyrion","find tyrion"}},{q="What is his connection to Elling Trias?",a="Tyrion and Elling Trias are longtime friends and collaborators. Trias uses his trade connections to gather whispers throughout the kingdom, sending reliable adventurers to Tyrion when covert action inside the Keep is required.",al={"tyrion and elling trias","does tyrion know trias","trias connection"}},{q="What quests does Tyrion offer?",a="Tyrion is involved in covert operations including 'Infiltrating the Castle', 'Items of Some Consequence', and warning allies during 'The Attack!'.",al={"tyrion quests","what quests does he give"}},{q="Why is a gnome handling secret operations in the human court?",a="Gnomes are key allies of the Alliance, and individuals like Tyrion provide sharp intellect, stealth, and technical resourcefulness that human authorities often overlook.",al={"why is a gnome in stormwind keep","gnome operative keep"}},{q="What is the nature of the plot Tyrion is investigating?",a="Tyrion assists in tracking stolen intelligence and hidden plots operating right under the nose of the royal court, leading up to an armed ambush within the city itself.",al={"tyrion conspiracy","what is tyrion investigating"},sp=1}},ang={["race:Gnome"]="Tyrion exemplifies the subtlety and intellect gnomes bring to high-stakes Alliance espionage, operating right beneath the noses of pompous human nobility.",["class:Rogue"]="For rogues dealing with Elling Trias's covert operations, Tyrion serves as the vital inside man within Stormwind Keep.",["faction:Alliance"]="Tyrion's intelligence work is instrumental in protecting the crown from covert threats brewing within the kingdom's capital."},kw={"elling trias","gnome","infiltrating the castle","items of some consequence","spy","stormwind keep","the attack","tyrion"},rel={"npc:elling-trias","subzone:stormwind-keep","zone:stormwind","quest:2745","quest:2746","quest:434","topic:stormwind-kingdom","topic:gnome"},src={"Tyrion"}}
E["npc:watcher-backus"] = {t="npc",n="Watcher Backus",z="stormwind",s="Watcher Backus is a member of the Night Watch tasked with patrolling the shadowy roads of Duskwood. Stationed along the thoroughfare between Darkshire and Manor Mistmantle, he keeps a weary eye out for lurking undead and strange travelers. His post also makes him a vital contact for those investigating suspicious movements tied to Stormwind's political intrigues.",h="Watcher Backus is a member of the Night Watch tasked with patrolling the shadowy roads of Duskwood.",sec={{t="A Patrol in the Shadows",b="Like the rest of the Night Watch, Watcher Backus faces an uphill struggle against the cursed woodland. Duskwood receives little support from the Stormwind garrison, leaving local volunteers to guard the misty paths on their own. Backus walks a solitary beat along the road leading north out of Darkshire, passing near the eerie Manor Mistmantle while keeping beast and ghoul at bay.",sp=0},{t="Eyes on the Road",b="Because of his isolated patrol route, Backus sees much of the traffic skirting the edges of Darkshire. When royal investigators trace the disappearance of a high-ranking diplomat down south, Backus serves as a crucial witness, recalling odd Defias activity around Addle's Stead.",sp=1}},faq={{q="Who is Watcher Backus?",a="Watcher Backus is a human guard belonging to the Night Watch, the beleaguered town militia responsible for defending Darkshire and the roads of Duskwood.",al={"who is backus","watcher backus role","backus duskwood"}},{q="Where can Watcher Backus be found?",a="He patrols the main road running north from Darkshire toward Manor Mistmantle in Duskwood.",al={"where is backus","backus location","backus patrol route"}},{q="What is the Night Watch?",a="The Night Watch is a local volunteer militia formed by the citizens of Duskwood to defend against undead, worgen, and feral beasts after Stormwind withdrew its official military presence.",al={"what is the night watch","night watch duskwood","darkshire guards"}},{q="How is Backus involved with The Missing Diplomat?",a="During the investigation into a missing Stormwind diplomat, clues lead adventurers to Duskwood. Backus recalls recent Defias activity around Addle's Stead and helps look over the documents recovered from their hideout there.",al={"backus missing diplomat","missing diplomat quest backus"},sp=1},{q="Does Watcher Backus have any town gossip surrounding him?",a="Within Darkshire, fellow guard Watcher Brownell is known to harbor an unspoken crush on Backus, offering a rare moment of lighthearted town gossip amid the gloom.",al={"backus brownell","watcher brownell crush"}},{q="Why does Backus patrol alone near Manor Mistmantle?",a="The Night Watch is stretched thin across the entire territory. With few able-bodied defenders to spare, watchers are forced to handle long, dangerous patrol routes by themselves.",al={"why alone","backus danger"}}},ang={["faction:Alliance"]="For Alliance agents tracking a missing diplomat, Backus represents a vital contact providing ground-level intelligence on the frontier.",["race:Human"]="Backus exemplifies the grit of Duskwood's human defenders, abandoned by the capital yet determined to hold the roads."},kw={"backus","darkshire","duskwood","manor mistmantle","night watch","the missing diplomat","watcher backus"},rel={"quest:1241","zone:duskwood","subzone:darkshire","subzone:manor-mistmantle"},src={"Watcher Backus"}}
E["npc:wynne-larson"] = {t="npc",n="Wynne Larson",z="stormwind",s="Wynne Larson is a human clothier and robe merchant operating in Stormwind City's Mage Quarter. With the historic arcane textile centers of Dalaran and Quel'Thalas ruined in the Third War, she relies on local craftsmen to supply mages across the kingdom. She regularly directs adventuring spellcasters toward the rare materials required to craft powerful enchanted garments.",h="Wynne Larson is a human clothier and robe merchant operating in Stormwind City's Mage Quarter.",sec={{t="A New Arcane Market",b="Before the Third War, the finest woven fabrics and enchanted vestments came from the magical workshops of Dalaran and the high elven kingdom of Quel'Thalas. The destruction of both northern realms crippled traditional trade routes and devastated arcane textile production. Vendors like Wynne Larson in Stormwind's Mage Quarter have had to adapt, coordinating directly with local tailors and enchanters like Lucan Cordell to meet the city's growing demand for robes and spellwoven gear.",sp=0},{t="Crafting Sorcerous Robes",b="Novice and journeyman mages seeking garments imbued with arcane potency often find their way to Wynne's shop. She knows precisely what materials are required to tailor vestments like Manaweave Robes or Astral Knot Garments, often sending practitioners of the arcane into dangerous territories to recover exotic reagents such as pristine spider silk. Her efforts ensure that Stormwind's practitioners remain properly outfitted despite northern shortages.",sp=0}},faq={{q="Where can I find Wynne Larson?",a="Wynne Larson is located in the Mage Quarter of Stormwind City, selling arcane cloth chestpieces and garments to aspiring spellcasters.",al={"wynne larson location","where is wynne larson","mage robe vendor stormwind"}},{q="Why does Wynne mention Dalaran and Quel'Thalas?",a="Historically, Dalaran and Quel'Thalas were the primary producers of enchanted fabrics across the Eastern Kingdoms. Their destruction during the Third War cut off imports, forcing merchants in Stormwind to rely on homegrown talent and rare imported materials.",al={"wynne dalaran dialogue","quelthalas robes","why are robes hard to find"}},{q="What quests involve Wynne Larson?",a="Wynne assists mages in acquiring tailored arcane garments, participating in questlines such as Gathering Materials, Manaweave Robe, Pristine Spider Silk, and the Astral Knot Garment.",al={"wynne larson quests","robe quests stormwind","manaweave robe quest"}},{q="What does Wynne Larson sell?",a="She sells a selection of basic and intermediate cloth robes, including Burning Robes, Chromatic Robes, Double-Stitched Robes, and Silver Dress Robes.",al={"wynne larson goods","what robes does wynne sell"}},{q="Who does Wynne rely on for crafting supplies in Stormwind?",a="Wynne mentions that local artisans, particularly enchanter Lucan Cordell and other city tradesmen, step in to weave and enchant the merchandise she sells.",al={"who makes wynnes robes","lucan cordell connection"}},{q="Is Wynne Larson related to other Larsons in Stormwind?",a="She shares a surname with Evan Larson, a clothier in Stormwind, and Jenny Larson, suggesting a family of tradesfolk working within the city's garment industry.",al={"larson family stormwind","evan larson","jenny larson"}}},ang={["class:Mage"]="Wynne is an essential contact during your early magical career, helping tailor your iconic Manaweave and Astral Knot garments.",["profession:Tailoring"]="Wynne represents the vital role clothiers and tailors play in Stormwind following the collapse of northern textile hubs.",["faction:Alliance"]="Her shop showcases how Stormwind has stepped forward to provide self-sufficient arcane craftsmanship for the surviving Alliance races."},kw={"astral knot garment","dalaran","mage quarter","manaweave robe","quel'thalas","robe vendor","stormwind","wynne larson"},rel={"subzone:mage-quarter","zone:stormwind","quest:1941","quest:1942","quest:1961","quest:1940","subzone:dalaran","topic:stormwind-kingdom"},src={"Wynne Larson"}}
E["npc:zaldimar-wefhellt"] = {t="npc",n="Zaldimar Wefhellt",z="stormwind",s="Zaldimar Wefhellt is a human mage trainer stationed on the upper floor of the Lion's Pride Inn in Goldshire. He serves as an instructor for fledgling spellcasters passing through Elwynn Forest before sending them along to higher practitioners in Stormwind City.",h="Zaldimar Wefhellt is a human mage trainer stationed on the upper floor of the Lion's Pride Inn in Goldshire.",sec={{t="The Mage in Goldshire",b="While Goldshire's Lion's Pride Inn is best known for weary travelers, rowdy adventurers, and local gossip, its upper rooms house instructors of various trades. Tucked into one of the second-floor chambers, Zaldimar Wefhellt instructs novice mages in the foundational arts of the arcane, fire, and frost. Once an apprentice outgrows his early tutelage, he directs them north to the Mage Quarter in Stormwind to study under Jennea Cannon.",sp=0}},faq={{q="Who is Zaldimar Wefhellt?",a="Zaldimar Wefhellt is an arcane instructor stationed in the Lion's Pride Inn in Goldshire. He helps novice Alliance mages learn their initial spells and guides them toward advanced training in Stormwind City.",al={"who is zaldimar","zaldimar wefhellt role","goldshire mage trainer"}},{q="Where can I find Zaldimar Wefhellt?",a="He is located on the second floor of the Lion's Pride Inn in Goldshire, inside the leftmost room at the top of the stairs.",al={"zaldimar location","where is zaldimar","how to find zaldimar"}},{q="Where does Zaldimar send novice mages?",a="Once a mage has gained basic proficiency, Zaldimar directs them to Stormwind's Mage Quarter to speak with Jennea Cannon in the Wizard's Sanctum for continued training.",al={"zaldimar quest","who does zaldimar send you to","speak with jennea quest"}},{q="Is Zaldimar related to any other mages?",a="He shares his rare surname with Zalna Wefhellt, another human mage trainer who instructs students within Stormwind City.",al={"wefhellt family","zalna wefhellt","zaldimar relatives"}}},ang={["class:Mage"]="For young human mages leaving Northshire Abbey, Zaldimar is the first trainer you encounter in the wider world, teaching early spells before directing you to the Wizard's Sanctum in Stormwind.",["faction:Alliance"]="Stationed inside the bustling Lion's Pride Inn, Zaldimar ensures Alliance spellcasters patrolling Elwynn Forest have access to magical instruction without needing to immediately trek into Stormwind."},kw={"elwynn forest","goldshire","lion's pride inn","mage trainer","wefhellt","zaldimar"},rel={"subzone:lion-s-pride-inn","subzone:goldshire","quest:1860","zone:elwynn","npc:marshal-dughan"},src={"Zaldimar Wefhellt"}}
E["npc:zardeth-of-the-black-claw"] = {t="npc",n="Zardeth of the Black Claw",z="stormwind",s="Zardeth of the Black Claw is a warlock dwelling in the dim subterranean chambers beneath the Slaughtered Lamb in Stormwind's Mage Quarter. Operating under the guise of an unassuming patron, he coordinates covert measures to protect the city's hidden warlock cabal from outside scrutiny. When inquisitive nobles begin looking too closely into their activities, Zardeth ensures those inquiries end permanently.",h="Zardeth of the Black Claw is a warlock dwelling in the dim subterranean chambers beneath the Slaughtered Lamb...",sec={{t="A Shadow Beneath the Lamb",b="While the Mage Quarter's towering spires study arcane discipline in the open, the underground tunnels beneath the Slaughtered Lamb house those who traffic in darker arts. Zardeth of the Black Claw operates from these crypts, functioning as a watchful guardian for the practitioners hiding right beneath the city guard's nose. Because the Alliance officially condemns fel magic, survival requires an ironclad secret and a willingness to eliminate any threat before royal investigators come knocking.",sp=0},{t="Silencing the Nobility",b="When Lord Baurles K. Wishock discovered whispers of the hidden warlock coven, the nobleman began lobbying the House of Nobles for an immediate, full-scale investigation. Aware that such scrutiny would destroy their underground haven, Zardeth arranged a clandestine countermeasure. Capitalizing on the lord's known indulgence in fine liquor, Zardeth dispatched an operative across the eastern kingdoms to gather rare, lethal flora—the Tear of Tilloa from Duskwood and Musquash Root from beneath the Stonewrought Dam.",sp=1},{t="A Noble Brew",b="Blending the gathered reagents with stout ale, Zardeth concocted the Black Claw Stout, a lethal vintage engineered to look like an ordinary luxury gift. Once delivered to Wishock's estate, the poisoned brew did its work swiftly and quietly. With Wishock dead and his campaign extinguished before the crown could intervene, Zardeth and his fellow warlocks successfully safeguarded the subterranean enclave beneath the Slaughtered Lamb.",sp=2}},faq={{q="Who is Zardeth of the Black Claw?",a="Zardeth is a human warlock stationed in the underground crypts beneath the Slaughtered Lamb tavern in Stormwind's Mage Quarter. He acts on behalf of the hidden warlock brotherhood to deflect suspicion and handle threats to their secret presence in the city.",al={"zardeth","who is zardeth","zardeth stormwind"}},{q="Where can I find Zardeth?",a="He can be found beneath the Slaughtered Lamb, an inn situated in the southern half of the Mage Quarter in Stormwind City. Enter the tavern, find the descending passageway in the back, and follow the winding catacombs down to the warlock enclave.",al={"zardeth location","where is zardeth","zardeth slaughter lamb"}},{q="Why does Zardeth want Lord Wishock dead?",a="Lord Baurles K. Wishock discovered evidence that warlocks were operating beneath the city and began lobbying Stormwind's nobility for a formal investigation. If an official inquiry took place, the Slaughtered Lamb coven would have been rooted out and executed by city authorities.",al={"why kill wishock","lord wishock target","noble brew reason"}},{q="What is Black Claw Stout?",a="Black Claw Stout is a lethal concoction brewed by Zardeth. It combines regular stout with two rare, poisonous plants: the Tear of Tilloa from Darkshire and Musquash Root from the Wetlands. It was designed to mimic an expensive drink while quietly assassinating Lord Wishock.",al={"black claw stout","what is the brew","wishock poison"}},{q="What is the Black Claw?",a="The Black Claw refers to the shadowy affiliation or title held by Zardeth within the covert network of warlocks practicing in Stormwind. They operate beneath the radar of the Stormwind guard and the Kirin Tor, using lethal discretion to protect their members.",al={"black claw meaning","who are the black claw","black claw warlock"}},{q="Why are warlocks allowed in Stormwind at all?",a="They are not openly tolerated. While dark spellcasters lurk in the city, they are forced to hide deep in the cellars beneath the Slaughtered Lamb. The authorities either turn a blind eye due to pragmatic utility or remain oblivious because agents like Zardeth eliminate anyone who prepares to expose them.",al={"are warlocks legal","stormwind warlock lore","why warlock in city"}}},ang={["class:Warlock"]="Zardeth embodies the cold pragmatism required of human warlocks surviving in the heart of the Alliance, proving that survival often depends on pre-emptive assassinations.",["faction:Alliance"]="For Alliance loyalists, Zardeth is a stark reminder of the corruptive underbelly festering right beneath Stormwind's gleaming streets.",["profession:Herbalism"]="Zardeth's plot relies on toxic botanical specimens like the Tear of Tilloa and Musquash Root, demonstrating the lethal potential of rare wild flora."},kw={"a noble brew","baurles wishock","black claw","mage quarter","musquash root","slaughtered lamb","tear of tilloa","warlock","zardeth"},rel={"subzone:slaughtered-lamb","npc:lord-baurles-k-wishock","quest:335","quest:397","subzone:mage-quarter","zone:stormwind","subzone:darkshire","subzone:stonewrought-dam"},src={"Zardeth of the Black Claw"}}
E["quest:1075"] = {t="quest",n="A Scroll from Mauren",z="stormwind",s="\"A Scroll from Mauren\" is an Alliance errand carrying word between gnome ingenuity and human arcane craft. The inventive Gaxim Rustfizzle requires a specialized spell to remotely trigger his volatile NG-5 explosives, dispatching couriers to consult with mage Collin Mauren in the heart of Stormwind.",h="\"A Scroll from Mauren\" is an Alliance errand carrying word between gnome ingenuity and human arcane craft.",sec={{t="A Spark Across Distances",b="Gnomish engineering is legendary for ambitious concepts, but safe execution often requires clever solutions. When Gaxim Rustfizzle set out to design an explosive payload capable of remote activation, mechanical fuses proved insufficient. Rather than relying purely on mechanical timers or trailing cords, Gaxim envisioned a device that would detonate the NG-5 explosives at the push of a single button from a safe vantage point. To bridge the gap between volatile powder and instantaneous trigger, he turned his sights toward arcane magic.",sp=0},{t="The Mage Quarter Connection",b="To acquire the necessary spellwork, Gaxim directs travelers across the kingdom to Stormwind's bustling Mage Quarter. There resides Collin Mauren, a human spellcaster whose practical understanding of the arcane makes him an ideal partner for ambitious tinkers. Mauren ponders the delicate problem of binding explosive ignition to a distant command, marking the first step in assembling the arcane incantation required to arm Gaxim's hazardous project.",sp=0}},faq={{q="Who sends me to Collin Mauren?",a="Gaxim Rustfizzle sends you on this task. He needs an arcane formula from his human acquaintance to finish building a remote detonator.",al={"quest giver","who gives a scroll from mauren","gaxim quest"}},{q="Where can Collin Mauren be found?",a="Collin Mauren resides within the Mage Quarter of Stormwind City. Look for him among the instructors, apprentices, and arcane researchers stationed around the district's towers and shops.",al={"collin mauren location","where is collin mauren","find mauren"}},{q="Why does Gaxim need a spell for an explosive device?",a="Gaxim wants to detonate his NG-5 explosive charges from a safe distance with the press of a single button. Pure mechanics can be cumbersome or unreliable over long ranges, so he seeks Mauren's arcane expertise to create an instantaneous remote trigger.",al={"why magic for bombs","remote detonation lore","why see a mage"}},{q="What is the NG-5?",a="NG-5, or Nitromirglyceronium, is a volatile explosive brewed by Gaxim's old colleague Lomac Gearstrip in Ironforge. To make it both effective and safe for field deployment, Gaxim requires a remote detonation system so the operator is well out of the blast radius when it ignites.",al={"ng-5","what is ng5","gaxim explosive"}},{q="What comes next after speaking with Collin Mauren?",a="Once Collin Mauren assesses the request for a distant detonation spell, he tasks you with aiding him in Westfall in the quest 'Devils in Westfall'.",al={"next quest","what follows a scroll from mauren","collin mauren follow up"}},{q="Is Collin Mauren a gnome or a human?",a="Collin Mauren is a human mage. Gaxim humorously notes in his instructions that because Mauren is human, he should be easy enough to spot amidst the crowds in Stormwind.",al={"collin mauren race","what race is mauren","is mauren a human"}}},ang={["class:Mage"]="This task demonstrates how the Kirin Tor and Stormwind's practitioners of the arcane frequently collaborate with engineers, applying evocation and transmutation to mechanical challenges.",["race:Gnome"]="Gnomes are never shy about combining technology with sorcery if it yields a more efficient, catastrophic explosion from a comfortable distance.",["profession:Engineering"]="Tinkers often find that pairing volatile black powder with arcane catalysts solves complex problems like remote ignition.",["faction:Alliance"]="The errand highlights practical cooperation between gnomish tinkerers and the human wizards who study in Stormwind's Mage Quarter."},kw={"collin mauren","devils in westfall","explosives","gaxim rustfizzle","mage quarter","ng-5","remote detonator","stormwind"},rel={"npc:collin-mauren","npc:gaxim-rustfizzle","subzone:mage-quarter","quest:1076","topic:stormwind-kingdom"},m={start="Gaxim Rustfizzle",["end"]="Collin Mauren",level="21",faction="Alliance",id=1075},src={"A Scroll from Mauren"}}
E["quest:1076"] = {t="quest",n="Devils in Westfall",z="stormwind",s="\"Devils in Westfall\" is an Alliance errand undertaken for Collin Mauren in the Mage Quarter of Stormwind. Tasked with aiding an eccentric experiment by the gnome inventor Gaxim Rustfizzle, adventurers are sent into the desolate plains of Westfall to gather volatile debris from living dust devils. The collected dust provides the raw magical component needed to enchant a specialized messaging scroll.",h="\"Devils in Westfall\" is an Alliance errand undertaken for Collin Mauren in the Mage Quarter of Stormwind.",sec={{t="A Messenger's Components",b="The wizard Collin Mauren is assisting the tinkerer Gaxim Rustfizzle with an unusual venture, but arcane work requires specialized reagents. To enchant a scroll capable of carrying Gaxim's desired messaging spell, Mauren cannot rely on simple ink and vellum alone. The swirling elemental magic trapped within Westfall's native dust devils provides the exact volatile medium needed to bind the spell into parchment form.",sp=0},{t="The Elemental Wastes",b="Westfall was once the fertile breadbasket of Stormwind, but drought, banditry, and neglect have left the land arid and wild. Swirling dust devils now roam the untamed fields, posing a hazard to travelers and lone homesteaders alike. By defeating one of these living whirlwinds and gathering its residue, adventurers retrieve the focused elemental essence required to bring the mage's enchantment to life.",sp=0}},faq={{q="Who is Collin Mauren?",a="Collin Mauren is a human mage residing in the Mage Quarter of Stormwind. He works alongside other spellcasters in the city and occasionally assists outside researchers, such as the gnome engineer Gaxim Rustfizzle, by preparing enchanted scrolls and arcane components.",al={"collin mauren","who is the quest giver","mage in stormwind"}},{q="Why does Collin Mauren need dust devil debris?",a="Mauren needs the debris to enchant a specialized messaging scroll for Gaxim Rustfizzle. The residual elemental energy contained within the dust devil's remains provides the necessary arcane affinity to impress the messaging spell onto parchment.",al={"why dust devil debris","what is dust devil debris for","why go to westfall"}},{q="Where are dust devils found?",a="Dust devils roam throughout the dry plains and barren fields of Westfall, particularly across the dusty stretches between neglected farmsteads south of the Sentinel Hill road.",al={"dust devil location","where are dust devils","westfall dust devils"}},{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is an ambitious gnome inventor involved in esoteric engineering projects. Collin Mauren assists him by drafting enchanted scrolls to facilitate his experiments.",al={"gaxim","gaxim rustfizzle","who is gaxim"}},{q="What happens after bringing the debris to Mauren?",a="Once supplied with the debris, Mauren weaves the messaging enchantment into a completed scroll and instructs you to return it to Gaxim so the gnome can continue his experiments.",al={"quest reward","what comes next","after devils in westfall"}},{q="Are dust devils magical or natural creatures?",a="Dust devils are minor air and earth elementals that manifest as living whirlwinds of sand and grit, thriving in the parched, unsettled landscape of modern Westfall.",al={"are dust devils elementals","dust devil lore"}}},ang={["class:Mage"]="For practitioners of the arcane, gathering dust devil remains illustrates the practical craft of enchanting: capturing wild elemental resonance to bind complex communication spells into physical scrolls.",["profession:Engineering"]="The entire errand stems from Gaxim Rustfizzle's tinkerings, underscoring how often advanced engineering projects must integrate arcane scrollcraft to solve communication hurdles.",["faction:Alliance"]="Venturing between the civilized towers of Stormwind and the ruined, neglected soils of Westfall highlights the stark divide between the capital's comfort and the kingdom's crumbling frontier."},kw={"collin mauren","dust devil","dust devil debris","gaxim rustfizzle","mage quarter","messaging spell","scroll","stormwind","westfall"},rel={"npc:collin-mauren","quest:1075","zone:westfall","topic:stormwind-kingdom"},m={start="Collin Mauren",level="21",faction="Alliance",id=1076},src={"Devils in Westfall"}}
E["quest:1097"] = {t="quest",n="Elmore's Task",z="stormwind",s="Elmore's Task is an Alliance courier assignment offered by Smith Argus in Goldshire. Recognizing a reliable traveler, Argus sends you into the Dwarven District of Stormwind to assist master weaponsmith Grimand Elmore. The errand highlights the cooperative ties and trade routes running between the humans of Elwynn and their dwarven allies.",h="Elmore's Task is an Alliance courier assignment offered by Smith Argus in Goldshire.",sec={{t="A Word from the Forge",b="While resting in Goldshire, local blacksmith Smith Argus keeps an eye out for dependable adventurers capable of handling more than clearing wolves and kobolds. Grimand Elmore, a skilled dwarven weaponsmith stationed in Stormwind, has put out word requesting help with an impending delivery bound for his kin in the northern mountains of Khaz Modan. Seeing someone with the grit for travel, Argus directs you toward the city gates to answer the call.",sp=0},{t="The Ties That Bind",b="Maintaining open trade and goodwill between the kingdom of Stormwind and the mountain stronghold of Ironforge is essential for the Alliance. Argus emphasizes that while local defenders are always needed in Elwynn Forest, honoring commitments to their dwarven counterparts keeps both realms supplied and unified. Stepping into the bustling, soot-stained Dwarven District in northeastern Stormwind brings you directly to Elmore's shop, setting up a journey far beyond the forest borders.",sp=0}},faq={{q="Who starts the quest Elmore's Task?",a="The quest is offered by Smith Argus, the resident blacksmith working the forge in the village of Goldshire, located just south of Stormwind City in Elwynn Forest.",al={"where do i get elmore's task","who gives elmore's task","elmore task quest giver"}},{q="Where can Grimand Elmore be found?",a="Grimand Elmore operates out of a weapon shop in the Dwarven District, located in the northeastern quarter of Stormwind City.",al={"grimand elmore location","where is grimand elmore","find elmore stormwind"}},{q="What is the purpose of this task?",a="Smith Argus sends you to Grimand Elmore because the dwarven smith needs a trustworthy courier to transport a delivery to his homeland in the north. It serves as an introduction to broader travel across the Alliance territories.",al={"why send me to elmore","elmore's task purpose","what does elmore want"}},{q="What quest follows Elmore's Task?",a="Speaking with Grimand Elmore completes this brief errand and immediately unlocks the follow-up quest, Stormpike's Delivery, which tasks you with bringing his crafted shipment northward to Loch Modan.",al={"elmore's task next quest","followup to elmore's task","what comes after elmore's task"}},{q="Why does Smith Argus care about dwarven deliveries?",a="Smith Argus notes that while the local militia could use every able body in Elwynn Forest, preserving strong relations and trade connections with their dwarven allies in Khaz Modan is vital for Stormwind's security and supply lines.",al={"why does argus help dwarves","smith argus dwarven ties"}},{q="Do you need to be a blacksmith to take this quest?",a="No. Despite being initiated by one blacksmith and turned in to another, the task is a general courier quest available to any Alliance adventurer ready to journey into Stormwind City.",al={"is elmore's task blacksmith only","blacksmithing required elmore task"}}},ang={["faction:Alliance"]="The task represents the vital daily cooperation between the human realm of Stormwind and the dwarven clans of Khaz Modan, maintaining common trade and trust across the Alliance.",["race:Dwarf"]="Dwarven travelers will find it familiar to see their human peers recognizing the craftsmanship of Ironforge smiths and helping route supplies back to the northern mountains.",["profession:Blacksmithing"]="Though open to all adventurers, the errand connects two prominent crafters—Smith Argus of Goldshire and Grimand Elmore of Stormwind—who share the craft of the anvil."},kw={"blacksmith","delivery","dwarven district","elmore","goldshire","grimand elmore","smith argus","stormwind"},rel={"npc:smith-argus","quest:1700","subzone:dwarven-district","topic:stormwind-kingdom"},m={start="Smith Argus",["end"]="Grimand Elmore",faction="Alliance",id=1097},src={"Elmore's Task"}}
E["quest:121"] = {t="quest",n="Messenger to Stormwind",z="stormwind",s="Messenger to Stormwind sees you carrying General Marcus Jonathan's initial reply back to Magistrate Solomon in Lakeshire. The town is reeling from Blackrock orc raids and gnoll incursions, but the capital's response brings cold comfort rather than troops. It highlights the growing political paralysis at the heart of the kingdom.",h="Messenger to Stormwind sees you carrying General Marcus Jonathan's initial reply back to Magistrate Solomon...",sec={{t="A Dispatch to Lakeshire",b="Having delivered Magistrate Solomon's desperate plea for reinforcements directly to General Marcus Jonathan in Stormwind, you are immediately sent back down the road to Redridge. The General cannot commit the army without royal approval, so he sends you back with a preliminary missive while he awaits word from the throne room. For Lakeshire's beleaguered citizens, every day without city guards brings their settlement closer to falling under the heel of the Blackrock clan.",sp=0},{t="Unease in the Kingdom",b="When Magistrate Solomon reads Jonathan's reply, the relief he hoped for does not materialize. Instead of promised battalions marching eastward along the Elwynn border, the letter yields evasive bureaucracy. Solomon immediately senses that something is deeply wrong within the royal court. With King Varian Wrynn mysteriously missing and the regency deadlocked, outlying towns like Lakeshire are increasingly left to fend for themselves.",sp=1}},faq={{q="What is in General Marcus Jonathan's response?",a="General Marcus Jonathan's letter explains that he cannot deploy the Stormwind army without formal authorization from the King or the royal court. Rather than offering troops, he sends assurances that the matter has been elevated to the crown while Lakeshire is forced to wait.",al={"what does the letter say","general response","marcus jonathan letter"}},{q="Why can't Stormwind just send soldiers to Redridge?",a="With King Varian Wrynn vanished, governing decisions rest with young Prince Anduin, Regent Lord Bolvar Fordragon, and the House of Nobles. Political division and stalling within the capital have tied the military's hands, leaving commander General Jonathan unable to march without royal sanction.",al={"why no stormwind help","why won't stormwind help lakeshire","stormwind army redridge"}},{q="Who is Magistrate Solomon?",a="Magistrate Solomon is the civic leader of Lakeshire and the Redridge Mountains. He is responsible for governing the settlement and coordinating its meager defense against Blackrock orcs, gnolls, and local brigands.",al={"magistrate solomon","who is solomon","lakeshire magistrate"}},{q="Who is General Marcus Jonathan?",a="General Marcus Jonathan is the High Commander of the Stormwind City Guard and the standing armed forces of the capital. He is stationed at the Valley of Heroes just inside the main gates of Stormwind City.",al={"who is marcus jonathan","general jonathan","stormwind general"}},{q="What does Solomon do next after reading the letter?",a="Realizing that Stormwind is unable or unwilling to send immediate help, Solomon attempts to seek assistance from neighboring regions, dispatching you to investigate the status of Westfall.",al={"what happens next","quest after messenger to stormwind","where to go next"},sp=1},{q="Why does Solomon say 'something is amiss in our Kingdom'?",a="Solomon recognizes that a complete refusal or delay in sending aid to a critical border town under active siege makes no military sense. It alerts him that Stormwind's political administration is being manipulated or paralyzed from within.",al={"something is amiss","why is solomon worried","stormwind conspiracy"}}},ang={["race:Human"]="For humans of the kingdom, carrying this correspondence exposes the painful disconnect between the guarded comfort of Stormwind City and the crumbling borders of Elwynn's neighbors.",["faction:Alliance"]="The stall in communication illustrates the vulnerability of the Alliance's core kingdom, where internal political gridlock leaves human territories undefended against regional threats."},kw={"blackrock orcs","bolvar","lakeshire","magistrate solomon","marcus jonathan","messenger to stormwind","redridge mountains","stormwind"},rel={"quest:120","quest:143","npc:magistrate-solomon","npc:general-marcus-jonathan","subzone:lakeshire","topic:stormwind-kingdom"},m={start="General Marcus Jonathan",["end"]="Magistrate Solomon",level="14",faction="Alliance",id=121},src={"Messenger to Stormwind (2)"}}
E["quest:1241"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="An urgent discreet investigation begins within Stormwind City after an Alliance diplomat fails to arrive at Theramore Isle. Bishop DeLavey suspects Defias foul play and dispatches trusted operatives to consult Jorgen, a quiet contact stationed in the Valley of Heroes.",h="An urgent discreet investigation begins within Stormwind City after an Alliance diplomat fails to arrive at...",sec={{t="A Vanishing in the Shadows",b="A high-ranking diplomat departed the Eastern Kingdoms bound for Theramore Isle to conduct sensitive talks with Lady Jaina Proudmoore. The envoy vanished before ever making landfall. While royal investigators comb Stormwind for leads, the disappearance has been kept strictly under wraps to avoid widespread panic or tipping off conspirators who might be watching the crown's every move.",sp=0},{t="Private Inquiries",b="Believing the Defias Brotherhood is involved in the diplomat's abduction, Bishop DeLavey opts not to rely solely on the king's formal guard. Instead, the bishop reaches out to unofficial and discreet channels, turning to Jorgen, an old acquaintance who keeps a low profile fishing in the Valley of Heroes just inside the city gates.",sp=0},{t="A Reluctant Informant",b="Jorgen maintains a gruff demeanor and an unassuming cover by the city waters, but he honors past obligations to DeLavey. Recognizing the perilous nature of the mystery, Jorgen makes it clear that discovering the diplomat's trail carries deadly risks, demanding absolute silence from anyone drawn into the inquiry.",sp=1}},faq={{q="Who is the missing diplomat?",a="The Church of the Light and the Stormwind throne keep the envoy's identity closely guarded, officially referring to them only as a key diplomat sent across the Great Sea to Theramore.",al={"missing diplomat identity","who disappeared","who vanished","diplomat identity"}},{q="Why was the diplomat traveling to Theramore?",a="The diplomat was tasked with meeting Lady Jaina Proudmoore for critical talks concerning the security and state of the Alliance between the Eastern Kingdoms and Kalimdor.",al={"why theramore","diplomat purpose","what was diplomat doing"}},{q="Who does Bishop DeLavey suspect?",a="Bishop DeLavey suspects the Defias Brotherhood orchestrated the kidnapping, though their exact methods and accomplices in the city remain unknown.",al={"who took the diplomat","delavey suspect","who kidnapped the diplomat"}},{q="Who is Jorgen?",a="Jorgen is an operative and longtime personal contact of Bishop DeLavey who keeps an unassuming post fishing by the waters in Stormwind's Valley of Heroes.",al={"where is jorgen","jorgen identity","who is the fisherman"}},{q="Why is the matter kept secret from the public?",a="Revealing that a vital envoy has been abducted under the throne's nose would incite chaos and alert the conspirators that royal agents are actively hunting them.",al={"why secrecy","why keep it secret","why not tell the city"}},{q="Where does this investigation lead?",a="Jorgen provides further instructions to dig into the underworld and hidden networks surrounding Stormwind to uncover where the diplomat was intercepted.",al={"what happens next","where to go after jorgen"}}},ang={["faction:Alliance"]="The disappearance of a royal diplomat threatens delicate negotiations between the kingdom of Stormwind and Lady Jaina Proudmoore's outpost in Theramore.",["class:Priest"]="Bishop DeLavey leverages church connections to quietly investigate state crimes when traditional royal channels might be compromised.",["class:Rogue"]="Tracing missing envoys through low-profile informants like Jorgen highlights the underground espionage running beneath Stormwind's spotless streets.",["race:Human"]="The ongoing threat of the Defias Brotherhood strikes directly at the stability of the human kingdom, reaching far beyond Westfall into the capital itself."},kw={"defias","delavey","jaina","jorgen","missing diplomat","stormwind","theramore","valley of heroes"},rel={"npc:bishop-delavey","npc:jorgen","npc:jaina-proudmoore","subzone:valley-of-heroes","zone:stormwind","topic:stormwind-kingdom"},m={start="Bishop DeLavey",["end"]="Jorgen",level="28",faction="Alliance",id=1241},src={"The Missing Diplomat (2)"}}
E["quest:1242"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This errand directs investigators from Jorgen in the Valley of Heroes to Elling Trias, the proprietor of Trias' Cheese in Stormwind's Trade District. Carrying a discreet sealed note, it bridges palace concerns about the missing diplomat into the underworld network quietly operated behind the counter of a modest cheese shop.",h="This errand directs investigators from Jorgen in the Valley of Heroes to Elling Trias, the proprietor of...",sec={{t="A Discreet Delivery",b="Following initial inquiries into the disappearance of an unnamed diplomat, Jorgen directs trusted operatives to keep their mouths firmly shut and carry a sealed note across the city. The destination is not an official barracks or a magistrate's office, but Trias' Cheese, nestled in the busy Trade District. The secretive nature of the handover hints at how delicate the matter has become, bypassing ordinary guard channels in favor of informal intelligence.",sp=0},{t="Behind the Shopfront",b="To the casual shopper browsing wheels of Darnassian bleu or sharp cheddar, Master Cheesemonger Elling Trias appears to be nothing more than a jovial, hardworking merchant. In reality, Trias operates as one of the kingdom's most connected information brokers, intimately linked to the city's rogue network. Delivering Jorgen's note places the search for the missing royal directly into the hands of the capital's shadow trade.",sp=1}},faq={{q="Who is Elling Trias?",a="On the surface, Elling Trias is a respected merchant running Trias' Cheese in the Trade District of Stormwind. Beneath his culinary trade, he is deeply connected to Stormwind's rogue syndicate and acts as a key information gatherer and fixer for delicate kingdom matters.",al={"who is trias","cheese vendor","elling trias identity"}},{q="Why does Jorgen tell me to keep quiet?",a="The disappearance of the diplomat is a state secret that could incite panic or alert whoever orchestrated the abduction. Jorgen insists on utter discretion so as not to betray that an active investigation is underway.",al={"why silence","jorgens warning","keep your yapper shut"}},{q="Where can I find Trias' Cheese?",a="The shop is located in the Trade District of Stormwind City, tucked along the main avenues among the general merchants and craftsmen.",al={"trias location","cheese shop location","where is elling trias"}},{q="What is in the sealed note to Elling?",a="The letter contains Jorgen's discreet briefing regarding the missing diplomat, calling upon Trias to utilize his specialized contacts and underground ears to locate tracks that conventional authorities cannot trace.",al={"note contents","what does note say","sealed note to elling"}},{q="Who is the missing diplomat mentioned in the quest?",a="The royal court keeps the exact identity guarded at this stage of the investigation, though the extreme secrecy and high-level concern point toward someone of immense political significance to the Kingdom of Stormwind.",al={"who is missing","who is the diplomat","missing person identity"}},{q="Why would the investigation use a cheesemonger instead of the city guard?",a="The official city guard is bound by protocol, jurisdiction, and potential political entanglements. Elling Trias has access to street-level whispers, rogue operatives, and underground leads that formal soldiers simply cannot reach.",al={"why a cheesemonger","why trias not guards","guards vs trias"}}},ang={["class:Rogue"]="Rogues know that Trias' Cheese is far more than a dairy storefront; it serves as a central clearinghouse for clandestine contacts and underworld contracts within Stormwind.",["faction:Alliance"]="The quiet pursuit of the missing envoy reveals subtle vulnerabilities in Stormwind's leadership during a period when King Varian Wrynn remains absent."},kw={"elling trias","jorgen","missing diplomat","sealed note","stormwind","trade district","trias cheese"},rel={"npc:elling-trias","npc:jorgen","subzone:trade-district","zone:stormwind","topic:stormwind-kingdom"},m={start="Jorgen",["end"]="Elling Trias",level="28",faction="Alliance",id=1242},src={"The Missing Diplomat (3)"}}
E["quest:1243"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This errand within the investigation of Stormwind's vanished emissary sends you south into the gloomy realm of Duskwood. Acting on leads secured in the capital, master of cheese Elling Trias dispatches you to contact Watcher Backus near Darkshire to uncover traces of Defias activity.",h="This errand within the investigation of Stormwind's vanished emissary sends you south into the gloomy realm...",sec={{t="Footwork in the Gloom",b="Following a frustrating exchange involving Jorgen, master rogue and cheesemonger Elling Trias decides to leverage his broader network of informants. Rather than squander his own coin sending out professional agents, he directs you to undertake the legwork yourself. You are charged with carrying a sealed missive across the border into Duskwood, a shadowed land beleaguered by beasts, the undead, and worse.",sp=0},{t="A Friendly Ear in the Night Watch",b="Your target is Watcher Backus, a member of the Night Watch patrolling the northern approach to Darkshire. Despite the perils that make Duskwood treacherous for ordinary travelers, Trias relies on Backus as a dependable source of intelligence regarding illicit movements. Presenting the sealed dispatch opens the door to municipal guard records and local gossip concerning Defias Brotherhood operations in the south.",sp=0}},faq={{q="Why is Elling Trias sending me to Duskwood?",a="Elling Trias is pursuing every potential lead regarding the missing diplomat and suspicious Defias Brotherhood operations. To stretch his coin while mobilizing his contacts, he sends you to interview Watcher Backus in Duskwood for news on the ground.",al={"why go to duskwood","trias duskwood errand","why darkshire"}},{q="Where can I find Watcher Backus?",a="Watcher Backus patrols the northern dirt road just outside Darkshire in Duskwood, guarding the thoroughfare leading toward Redridge and Elwynn Forest.",al={"watcher backus location","where is backus","find backus"}},{q="Who is Watcher Backus?",a="Watcher Backus is a soldier in Darkshire's civic militia, the Night Watch. He is also a personal associate of Elling Trias, willing to share observations on suspicious travelers and criminal movements in the region.",al={"backus lore","who is backus"}},{q="What is in the sealed note given to Backus?",a="The note contains confidential inquiries from Elling Trias requesting intelligence on any local sightings or movements of the Defias Brotherhood passing through Duskwood.",al={"contents of sealed note","what does the note say","sealed note to watcher backus"}},{q="What does Duskwood have to do with the Defias Brotherhood?",a="Although centered in Westfall and hiding out beneath the Deadmines, the Defias maintain cells, couriers, and hideouts stretching throughout the southern human provinces, including the shadowed fringes of Duskwood.",al={"defias in duskwood","are defias in duskwood"}},{q="Why does Trias complain about Jorgen?",a="Jorgen previously stonewalled or drove a hard bargain during the investigation, irritating Trias enough that he curses Jorgen to the Twisting Nether before resorting to other field contacts.",al={"who is jorgen","trias and jorgen"}}},ang={["faction:Alliance"]="The disappearance of the diplomat strikes at the heart of Stormwind's royal interests, forcing heroes to coordinate between royal spymasters, independent crooks, and regional militias.",["class:Rogue"]="Elling Trias demonstrates how veteran operatives run networks, leaning on independent foot soldiers to gather reconnaissance while keeping their own hands clean."},kw={"darkshire","defias","duskwood","elling trias","jorgen","missing diplomat","night watch","watcher backus"},rel={"quest:1241","npc:elling-trias","npc:watcher-backus","npc:jorgen","subzone:darkshire","zone:duskwood"},m={start="Elling Trias",["end"]="Watcher Backus",level="28",faction="Alliance",id=1243},src={"The Missing Diplomat (4)"}}
E["quest:1244"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This leg of the investigation directs Alliance agents into the shadows of Duskwood following the trail of Stormwind's vanished emissary. Acting on information from Watcher Backus, investigators must search the derelict farmstead of Addle's Stead to uncover Defias paperwork.",h="This leg of the investigation directs Alliance agents into the shadows of Duskwood following the trail of...",sec={{t="A Lead in the Gloom",b="After following whisperings of conspiracy outside Stormwind's walls, the search for the missing diplomat reaches the Night Watch in Duskwood. Watcher Backus notes that while Defias bandits usually keep to themselves across the border, an unusually large gathering converged at Addle's Stead several weeks prior. For an organization operating largely out of Westfall, such concentrated activity in the dark woods suggests something critical transpired on that abandoned farmland.",sp=0},{t="The Defias Docket",b="Searching the overrun farmstead yields a locked footbox containing a Defias Docket. While the papers confirm the brotherhood's involvement, Backus warns that dealing with such conspirators is treacherous—the documents could easily be forged misdirection designed to send meddling investigators down a blind alley.",sp=1}},faq={{q="Where is Addle's Stead located?",a="Addle's Stead lies in western Duskwood, just south of the main road that enters the zone from Westfall. It is a run-down farmhouse currently occupied by hostile Defias agents.",al={"addle's stead location","where is addles stead","find addle's stead"}},{q="What is the Defias Docket?",a="The Defias Docket is a collection of official-looking papers kept in a footbox inside the farmhouse at Addle's Stead. It details aspects of the Brotherhood's recent clandestine operations in the region.",al={"defias docket","what is the docket","addle stead document"}},{q="Who is Watcher Backus?",a="Watcher Backus is a member of the Night Watch stationed in Duskwood. Having contacts in town and keeping an eye on border threats, he assists in tracking down unusual Defias movements along the Westfall border.",al={"watcher backus","who is backus","backus duskwood"}},{q="Why are Defias operating inside Duskwood?",a="Although their stronghold lies across the border in Westfall, Defias operatives frequently make quiet incursions into western Duskwood. Addle's Stead serves as an isolated, secluded waypoint away from Stormwind patrols.",al={"why are defias in duskwood","defias at addle's stead"}},{q="Can the contents of the Defias Docket be trusted?",a="Watcher Backus himself expresses caution upon inspecting it. While the document appears authentic, the Defias are cunning conspirators capable of planting fake leads to throw investigators off their trail.",al={"is the docket real","docket forgery","is it a dupe"}},{q="Who originally pointed investigators toward Watcher Backus?",a="Watcher Backus notes that Elling Trias, the cheese merchant and covert information broker in Stormwind, was the one who directed the investigation toward the Night Watch in Duskwood.",al={"who sent me to backus","trias connection"}}},ang={["faction:Alliance"]="The disappearance of King Varian's emissary strikes at the heart of Stormwind's security, proving that Defias intrigue extends far beyond petty highway robbery in Westfall.",["class:Rogue"]="Navigating criminal networks and deciphering planted paper trails requires discerning genuine intelligence from clever Defias misdirection."},kw={"addle's stead","defias docket","duskwood","footbox","night watch","the missing diplomat","watcher backus"},rel={"npc:watcher-backus","subzone:addle-s-stead","zone:duskwood","zone:westfall"},m={start="Watcher Backus",level="30",faction="Alliance",id=1244},src={"The Missing Diplomat (5)"}}
E["quest:1245"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This errand within the sprawling investigation sends you racing back to Stormwind with the recovered Defias Docket. What began as a quiet inquiry into a missing diplomat is steadily uncovering a conspiracy far broader and more perilous than local night watchmen dare touch.",h="This errand within the sprawling investigation sends you racing back to Stormwind with the recovered Defias...",sec={{t="Too Heavy for the Night Watch",b="Upon recovering the Defias Docket in the shadowed forests of Duskwood, Watcher Backus wants nothing more to do with it. The papers detail schemes far too intricate to be mere banditry or diversionary tactics. Terrified of royal retribution and wary of his own superiors in the Night Watch, Backus urges you to keep his involvement entirely quiet. The documents speak of machinations dangerous enough to end careers or cost lives, leaving the investigator no choice but to carry the dangerous prize directly back to the capital.",sp=0},{t="A Cheesemonger's True Trade",b="Back in Stormwind's Trade District, Master Cheesemonger Elling Trias drops all pretense of selling dairy the moment you return. As a pivotal handler for the kingdom's covert intelligence network, Trias pores over the docket's contents. Far from simple brigand communications, the documents reveal careful planning, coordinated efforts by the Defias Brotherhood, and an ominous codename: 'Fist.' The missing diplomat was clearly targeted by a meticulous, well-connected network with reach deep inside the kingdom.",sp=1}},faq={{q="What is the Defias Docket?",a="The Defias Docket is a collection of complex, sensitive papers retrieved in Duskwood outlining Defias Brotherhood plans. Its contents are sophisticated enough to terrify local watchmen and provide Master Trias with fresh leads in the search for the missing royal diplomat.",al={"defias docket","what are the papers","docket contents"}},{q="Why is Watcher Backus so afraid to keep the docket?",a="Backus realizes the information in the docket is way beyond the pay grade or jurisdiction of a Duskwood Night Watchman. He fears that if his commanders or Stormwind superiors discover he withheld or handled state-level conspiratorial intelligence, he could be hanged for treason.",al={"why backus scared","watcher backus fear"}},{q="Why take the papers to a cheese shop owner in Stormwind?",a="Elling Trias poses as a simple cheesemonger, but he is in truth one of Stormwind's most capable spymasters and a key figure in the kingdom's underworld intelligence. He possesses the cipher skills, contacts, and political awareness required to decipher the Defias plans.",al={"why elling trias","why trias cheese"}},{q="Who is 'Fist' mentioned in the docket?",a="Upon reading through the docket, Elling Trias notes the name 'Fist' with immediate familiarity. It serves as an operative alias or codename for an individual tied directly to the coordination between the Defias Brotherhood and the abduction plot.",al={"who is fist","the fist defias","fist codename"}},{q="Where does this investigation lead next?",a="Trias uses the newly revealed details from the docket to trace the conspirators further, sending you to question contacts and pursue the mysterious 'Fist' to find where the kidnapped diplomat was taken.",al={"next step","what after docket","where do i go next"}},{q="What does this have to do with King Varian Wrynn?",a="Officially, you are searching for a missing diplomat whose carriage was intercepted. However, whispers throughout the kingdom hint that the crown itself is shrouded in secrecy, and uncovering the Defias plot is part of a much graver royal crisis.",al={"is varian the diplomat","king varian connection"},sp=1}},ang={["class:Rogue"]="Elling Trias represents the side of roguecraft that trades daggers for information networks. Watching a spymaster decode raw Defias cipher-work shows how the crown's shadow wars are truly fought.",["faction:Alliance"]="The discovery of high-level Defias planning underscores how deeply the kingdom of Stormwind's security has eroded since the Third War, threatening stability from within."},kw={"defias docket","duskwood","elling trias","fist","missing diplomat","stormwind","watcher backus"},rel={"npc:elling-trias","npc:watcher-backus","zone:duskwood","npc:jorgen","topic:stormwind-kingdom"},m={start="Watcher Backus",["end"]="Elling Trias",level="30",faction="Alliance",id=1245},src={"The Missing Diplomat (6)"}}
E["quest:1246"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This errand leads investigators deep into Old Town to confront a known street brawler tied to suspicious papers. Guided by the cheese merchant Elling Trias, you must seek out Dashel Stonefist and pry answers from him by any means necessary. The trail surrounding the missing diplomat is rapidly shifting from court intrigue to Stormwind's rough underbelly.",h="This errand leads investigators deep into Old Town to confront a known street brawler tied to suspicious...",sec={{t="A Lead in Old Town",b="After examining the coded notes and leads tied to the missing diplomat, Master Trias recalls a key figure connected to the operation: a rough street fighter named Dashel Stonefist, colloquially known as 'Fist'. Rather than rubbing shoulders with nobility in the Cathedral Square, Stonefist frequents the cramped alleys of Old Town. Tracking him down represents the first physical thread pulling the investigation away from the grand halls of Stormwind Keep and into the city's criminal circles.",sp=0},{t="Persuasion by the Fist",b="Elling Trias knows well that men like Dashel do not speak freely with inquisitive strangers, especially when treason and kidnappings are involved. His instructions are blunt: if polite questioning fails, blunt force will have to do the talking. Stonefist considers the alleyways his domain and does not take kindly to outsiders poking their noses into matters that could cost him his livelihood or his neck.",sp=1}},faq={{q="Who is Dashel Stonefist?",a="Dashel Stonefist is a notorious brawler who hangs around the central alleys of Old Town in Stormwind. Trias identifies him as an intermediary connected to incriminating papers unearthed during the search for the missing diplomat.",al={"dashel stonefist","who is fist","dashel"}},{q="Where can I find Dashel Stonefist?",a="Dashel Stonefist lingers in Old Town, situated outdoors near the center of the district, often loitering in the alleys away from the main streets.",al={"dashel stonefist location","where is dashel","where is stonefist"}},{q="Why is Elling Trias sending me after him?",a="Trias linked Dashel's name directly to documents related to the disappearance of the King's envoy. Dashel is in deep enough that he must have names, locations, or orders regarding who organized the abduction.",al={"why fight dashel","trias reason"}},{q="Will Dashel cooperate willingly?",a="No. Stonefist is immediately hostile to strangers meddling in his personal business. Trias anticipates this stubbornness, advising you to use a weapon or heavy fist to force him to speak.",al={"does dashel talk","stonefist friendly"}},{q="What happens after finding Dashel?",a="Confronting Dashel inevitably leads to a brawl. Once subdued, he reveals further leads regarding the network operating behind the diplomat's abduction, directing you toward other conspirators within the kingdom.",al={"missing diplomat next step","what after dashel"},sp=1},{q="Who is the missing diplomat mentioned in the quest?",a="Officially, Stormwind authorities speak only of an unnamed diplomat who vanished en route to Theramore to meet with Jaina Proudmoore. The envoy's true identity remains a closely guarded secret at this stage of the investigation.",al={"who is missing diplomat","which diplomat"},sp=2}},ang={["class:Rogue"]="Operating in Old Town and navigating informants like Trias and thuggish enforcers like Stonefist puts a rogue right at home in Stormwind's shadowy underbelly.",["race:Human"]="For humans of Stormwind, this lead is troubling proof that local street scum are actively cooperating in high treason against the kingdom's leadership.",["faction:Alliance"]="Unraveling the conspiracy behind the missing diplomat is vital to stabilizing the Alliance, which sits vulnerable while King Varian remains absent."},kw={"dashel stonefist","elling trias","fist","missing diplomat","old town","stormwind"},rel={"npc:dashel-stonefist","npc:elling-trias","subzone:old-town","topic:stormwind-kingdom"},m={start="Elling Trias",["end"]="Dashel Stonefist",level="31",faction="Alliance",id=1246},src={"The Missing Diplomat (7)"}}
E["quest:1247"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This step in the investigation of Stormwind's missing envoy follows the interrogation of Dashel Stonefist in Old Town. Having beaten a confession out of the thug, you carry word of a backup abduction plot back to the spymaster disguised as a master of cheese, Elling Trias.",h="This step in the investigation of Stormwind's missing envoy follows the interrogation of Dashel Stonefist in...",sec={{t="A Crack in the Wall",b="Dashel Stonefist is not the kind of operative who takes secrets to the grave, especially once convinced his health is on the line. Cornered behind the five-and-dime in Old Town, Dashel folds and admits that his role in the kidnapping crumbled when the conspirators' initial plan fell apart. Desperate to deflect blame, he points to a clandestine meeting held weeks earlier at Addle's Stead in Duskwood and offers a single lead for their backup operation: an insider operating out of Menethil Harbor known only as Slim.",sp=0},{t="Reporting to the Fromager",b="Elling Trias maintains an unassuming presence behind the counter of Trias' Cheese in the Trade District, but his true profession is the gathering of secrets for the Crown. While you wrung details out of Dashel, Trias examined captured communications regarding the plot. Dashel's confession matches the written intelligence: an unnamed diplomat was targeted, the primary ambush went awry, and a contingency was set in motion via the Wetlands. With the name 'Slim' in hand, the search moves from Stormwind's shadowed alleys north toward the marshes.",sp=1}},faq={{q="Who is Dashel Stonefist?",a="Dashel Stonefist is a local muscle and fixer operating out of Stormwind's Old Town. Entangled in the Defias-linked underworld, he served as a ground-level henchman in the initial scheme to capture Stormwind's envoy before turning informant when confronted.",al={"dashel stonefist","who is dashel","stonefist stormwind"}},{q="Why is Elling Trias involved in this investigation?",a="While known publicly as a master of fine cheeses, Elling Trias is one of Stormwind's veteran intelligence operatives. He uses his shop in the Trade District as a cover to coordinate covert inquiries that require discretion beyond the official city guard.",al={"why elling trias","cheese vendor spy","trias intelligence"}},{q="What happened at Addle's Stead?",a="Addle's Stead is an abandoned farmstead in western Duskwood where the conspirators convened weeks prior to coordinate their kidnapping schemes after their opening gambit was disrupted.",al={"addle's stead meeting","addles stead","westfall meeting"}},{q="Who is the diplomat they were trying to abduct?",a="The official documents and street thugs only refer to the target as an unnamed diplomat bound for Theramore. The envoy's true identity remains a closely guarded secret at this stage of the investigation.",al={"who is missing diplomat","who got kidnapped","the diplomat identity"},sp=2},{q="Who is Slim?",a="Slim is the contact identified by Dashel Stonefist as the operative handling 'Plan B' out of Menethil Harbor in the Wetlands, representing the conspirators' secondary logistics route.",al={"who is slim","slim menethil","menethil contact"}},{q="Where does the trail lead after this?",a="Armed with the name Slim and confirmation from Elling Trias, the investigation shifts northward to the port town of Menethil Harbor in the Wetlands to hunt down the contact.",al={"next step missing diplomat","where to go after dashel","what next"}}},ang={["class:Rogue"]="For an operative of the shadows, coordinating between back-alley muscle like Dashel and spymasters like Trias highlights the thin divide between common street crime and high-stakes statecraft.",["race:Human"]="The conspiracy unfolds directly within the capital's borders, proving that treason has festered inside the kingdom of Stormwind while the boy-king sits upon the throne.",["faction:Alliance"]="Unraveling the envoy's disappearance is vital to the stability of the entire Alliance, as high-level sabotage threatens the leadership in Stormwind."},kw={"addle's stead","dashel stonefist","elling trias","menethil","missing diplomat","slim","stormwind"},rel={"npc:dashel-stonefist","npc:elling-trias","subzone:addle-s-stead","topic:stormwind-kingdom"},m={start="Dashel Stonefist",["end"]="Elling Trias",level="31",faction="Alliance",id=1247},src={"The Missing Diplomat (9)"}}
E["quest:1274"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="The Missing Diplomat is the introductory step in one of Stormwind's most critical and sensitive investigations. Brought to your attention discreetly on the city streets, the matter leads directly to Bishop DeLavey in Stormwind Keep. The Church and the crown require capable hands for an issue too perilous to trust to public channels.",h="The Missing Diplomat is the introductory step in one of Stormwind's most critical and sensitive...",sec={{t="A Quiet Summons",b="While traveling through Stormwind, an unassuming courier named Thomas approaches trustworthy adventurers with a quiet request. Bishop DeLavey, a respected figure within the Church of the Holy Light stationed at Stormwind Keep, needs an outsider's assistance. The matter is described strictly as delicate and urgent, requiring complete discretion to avoid inciting panic among the populace.",sp=0},{t="Whispers in the Keep",b="Upon answering the summons within Stormwind Keep, Bishop DeLavey reveals the reason for such secrecy. A high-ranking dignitary from the kingdom has vanished under mysterious circumstances. In an era marked by brewing domestic unrest and the mysterious absence of King Varian Wrynn, any hint of high-level foul play threatens to destabilize the realm's fragile peace.",sp=1}},faq={{q="Who is Thomas?",a="Thomas is an errand runner in Stormwind employed by Bishop DeLavey. He keeps a watchful eye out for competent adventurers on the city streets, quietly directing them to Stormwind Keep whenever delicate Church or state affairs require capable intermediaries.",al={"who is thomas","thomas stormwind","thomas quest giver"}},{q="Who is Bishop DeLavey?",a="Bishop DeLavey is a senior cleric of the Church of the Holy Light stationed within Stormwind Keep. Working alongside the royal court, he handles discreet Kingdom security concerns and sensitive investigations that regular city guards cannot openly pursue.",al={"who is bishop delavey","delavey","bishop delavey"}},{q="Why is this matter handled in secret?",a="Stormwind is already on edge with King Varian Wrynn missing and the Defias Brotherhood stirring rebellion across Westfall. If news spreads that another prominent diplomat or official has vanished, it could provoke widespread panic or expose court vulnerabilities to enemies.",al={"why discreet","why secrecy","why secret"}},{q="Where does this investigation lead?",a="Meeting Bishop DeLavey in Stormwind Keep kicks off an extensive investigation that takes you deep into the heart of Kingdom politics, sprawling through the streets of Stormwind, outward into the surrounding human territories, and beyond into treacherous lands across the sea.",al={"where does missing diplomat go","missing diplomat next"}},{q="Who is the missing diplomat?",a="At the start of the inquiry, the exact identity of the diplomat is closely guarded by Bishop DeLavey. Public disclosure would threaten ongoing investigations and jeopardize the safety of both the missing official and the kingdom.",al={"who is the diplomat","identity of missing diplomat"}}},ang={["faction:Alliance"]="Unraveling the mystery of the missing diplomat is vital for the integrity and defense of the Alliance, exposing deep threats rooted within Stormwind's own court.",["race:Human"]="For humans of Stormwind, this assignment touches upon the very stability of your homeland during a fragile regency."},kw={"bishop delavey","diplomat","investigation","stormwind keep","the missing diplomat","thomas"},rel={"quest:1241","subzone:stormwind-keep","npc:bishop-delavey","topic:stormwind-kingdom"},m={start="Thomas",["end"]="Bishop DeLavey",level="28",faction="Alliance",id=1274},src={"The Missing Diplomat"}}
E["quest:1338"] = {t="quest",n="Stormpike's Order",z="stormwind",s="Mountaineer Stormpike, stationed up in the snowy crags of Loch Modan, desires a shield crafted by the renowned armorsmith Furen Longbeard. Because Furen has set up shop far to the south in Stormwind City, the mountaineer enlists a traveling adventurer to deliver the commissioned order.",h="Mountaineer Stormpike, stationed up in the snowy crags of Loch Modan, desires a shield crafted by the...",sec={{t="A Shield Worth the Journey",b="Even in remote outposts like Loch Modan, dwarf mountaineers hold strong opinions about craftsmanship. Mountaineer Stormpike insists that only one smith can forge his next shield: Furen Longbeard. Convinced that Longbeard's talent is second to none, Stormpike is willing to pay handsomely to get a commission into the master smith's hands, despite the immense distance between them.",sp=0},{t="From Ironforge to the Dwarven District",b="What baffles Stormpike most is Furen's location. Rather than staying near the Great Forge of Ironforge alongside his kin, Longbeard makes his living far south in Stormwind City's Dwarven District. Stormpike surmises the humans must be paying him a king's ransom to lure such an artisan away from his ancestral home. When the missive finally reaches Furen over his anvil, the smith takes pride in hearing from the prestigious Stormpike clan and eagerly prepares to hammer out the shield.",sp=0}},faq={{q="Who is Mountaineer Stormpike?",a="He is an Alliance sentry stationed in Loch Modan, part of the dwarven mountaineer force protecting the mountain passes and valleys. He belongs to the proud and influential Stormpike clan.",al={"mountaineer stormpike","who gives the quest","quest giver"}},{q="Who is Furen Longbeard?",a="Furen Longbeard is an accomplished dwarven armorsmith who resides in the Dwarven District of Stormwind City. His reputation for forging superior shields and armor extends all the way north to Khaz Modan.",al={"furen longbeard","who is furen","the armorsmith"}},{q="Why does Furen live in Stormwind instead of Ironforge?",a="While traditionalists like Mountaineer Stormpike wonder why any master dwarf would abandon Ironforge, Furen plies his trade in Stormwind's Dwarven District to cater to human nobility, city guards, and traveling adventurers, likely earning a lucrative income in human coin.",al={"why is furen in stormwind","why dwarven district","furen leaving ironforge"}},{q="What is the Deeprun Tram's role in delivering this order?",a="Travelers carrying Stormpike's missive generally journey south from Loch Modan through Ironforge, then take the subterranean Deeprun Tram directly into Stormwind City's Dwarven District where Furen's forge is located.",al={"travel to stormwind","how to get to stormwind","deeprun tram"}},{q="What comes before this quest?",a="Before entrusting you with this courier mission to Stormwind, Mountaineer Stormpike tests your mettle and reliability in Loch Modan with 'Mountaineer Stormpike's Task'.",al={"prerequisites","previous quest","mountaineer stormpike's task"}},{q="Does Furen Longbeard forge the shield immediately?",a="Upon receiving the letter and recognizing the prestige of the Stormpike name, Furen happily accepts the commission and promises to begin hammering out the shield before the end of the day.",al={"what happens next","followup quest","furen reaction"}}},ang={["race:Dwarf"]="For dwarves, this delivery highlights the reach of clan reputations like the Stormpikes, while playfully questioning why a master armorsmith would ever choose human stone over Ironforge.",["profession:Blacksmithing"]="Furen Longbeard is recognized even across kingdoms as an exceptional armorsmith, making this a noteworthy stop for aspiring smiths traveling through Stormwind.",["faction:Alliance"]="The delivery demonstrates the close trade and cultural ties connecting the dwarven holds of Khaz Modan to the human capital of Stormwind via the Deeprun Tram."},kw={"armorsmith","dwarven district","furen longbeard","ironforge","loch modan","shield","stormpike","stormwind"},rel={"npc:furen-longbeard","npc:mountaineer-stormpike","quest:1339","subzone:dwarven-district","zone:ironforge","topic:stormwind-kingdom"},m={start="Mountaineer Stormpike",["end"]="Furen Longbeard",level="14",faction="Alliance",id=1338},src={"Stormpike's Order"}}
E["quest:1447"] = {t="quest",n="The Missing Diplomat",z="stormwind",s="This tense confrontation is a pivotal step in unraveling the mystery of the missing diplomat. Following a trail through Stormwind's underbelly, an investigator corners Dashel Stonefist in Old Town to force answers out of the stubborn ruffian.",h="This tense confrontation is a pivotal step in unraveling the mystery of the missing diplomat.",sec={{t="A Friendly Chat in Old Town",b="Tracking the fate of the missing diplomat leads deep into the shadows of Old Town, where cutpurses and shady brokers mingle away from the watchful eyes of the Cathedral. Dashel Stonefist is known to harbor ties to the city's unsavory factions and holds valuable information regarding the abduction, but he isn't keen on sharing it willingly with agents asking sensitive questions.",sp=0},{t="Brawl in the Alley",b="When approached, Dashel quickly drops any pretense of cooperation. Backed by his loyal Old Town thugs, he attempts to beat down inquisitive travelers and silence the investigation permanently. Subduing Dashel and cutting down his backup proves to be the only language he respects, quickly changing his tune and opening the door to the next lead in the conspiracy.",sp=1}},faq={{q="Who is Dashel Stonefist?",a="Dashel Stonefist is a shady character lurking in Old Town with ties to Stormwind's criminal underworld. He acts as a local contact who knows far more than he lets on about illicit movements throughout the city.",al={"dashel stonefist","who is stonefist","dashel"}},{q="Why do I have to fight Dashel instead of just talking to him?",a="Dashel has no interest in cooperating with investigators. The moment you ask about the missing diplomat, he assumes you can be easily intimidated and calls in his thugs to silence you. Only a sound thrashing convinces him to talk.",al={"why fight dashel","can i talk to stonefist","why beat up dashel"}},{q="Do I have to kill Dashel Stonefist?",a="No. The goal is to beat him into submission rather than execute him. Once his health drops sufficiently low, he yields, calls off his cronies, and agrees to answer your questions.",al={"do i kill dashel","stonefist alive","is dashel dead"}},{q="Where does this fight take place?",a="The confrontation takes place out in the open in Old Town, near the alleys behind the pig and whistle tavern and local training halls where Stonefist typically hangs around.",al={"stonefist location","where is dashel","old town brawl"}},{q="What happens after beating Dashel?",a="Once bested, a humbled Dashel apologizes and becomes willing to spill what he knows about the conspiracy, directing the investigation to the next link in the chain outside the capital.",al={"what next after dashel","stonefist next quest","diplomat chain next"},sp=1},{q="What is 'The Missing Diplomat' chain really about?",a="While officially presented as a search for a lost ambassador, the quest chain uncovers a web of deceit surrounding the diplomat's abduction and the shadowy figures orchestrating it.",al={"missing diplomat lore","who is the diplomat","missing king"},sp=2}},ang={["class:Rogue"]="Old Town is your natural habitat, and dealing with brutes like Dashel Stonefist is routine business when shaking down contacts for street-level intelligence.",["race:Human"]="Discovering that local thugs in Stormwind's own capital are actively hindering the search for the missing king strikes at the very heart of the kingdom's security.",["faction:Alliance"]="Every lead on the diplomat's disappearance is critical to uncovering the internal treachery threatening the stability of the Alliance leadership."},kw={"brawl","conspiracy","dashel","missing diplomat","old town","stonefist","stormwind","thugs"},rel={"npc:dashel-stonefist","subzone:old-town","topic:stormwind-kingdom"},m={start="Dashel Stonefist",level="31",faction="Alliance",id=1447},src={"The Missing Diplomat (8)"}}
E["quest:1638"] = {t="quest",n="A Warrior's Training",z="stormwind",s="A Warrior's Training is an introductory class quest that directs promising young warriors from Goldshire to Stormwind City. Dispatched by the trainer Lyria Du Lac, soldiers travel to the Pig and Whistle Tavern in Old Town to seek out the veteran Harry Burlguard for seasoned instruction in battlefield endurance.",h="A Warrior's Training is an introductory class quest that directs promising young warriors from Goldshire to...",sec={{t="From Elwynn to Old Town",b="Once an aspiring fighter demonstrates reliable fundamentals handling threats across Elwynn Forest, their trainers recognize that drillmasters in Goldshire can offer little more. Lyria Du Lac sends recruits into the heart of Stormwind, specifically toward the gritty district of Old Town. There, veteran fighters gather to exchange combat experience far away from the rigid formalities of the royal garrison.",sp=0},{t="Lessons of the Veteran",b="The contact in Old Town is Harry Burlguard, an aged battle veteran who makes his quarters at the Pig and Whistle Tavern. Rather than drilling in parade grounds, Harry tests a warrior's mettle through tavern grit and practical stamina. Before teaching defensive maneuvers that keep soldiers alive on dangerous campaigns, Harry expects new arrivals to match his appetite for drink and face down local brawlers.",sp=0}},faq={{q="Who gives this quest?",a="The quest is offered by Lyria Du Lac, the warrior trainer stationed outside the Lion's Pride Inn in Goldshire, once a fighter has proven their early combat proficiency.",al={"quest giver","who starts a warriors training","lyria du lac quest"}},{q="Where can Harry Burlguard be found?",a="Harry Burlguard is located inside the Pig and Whistle Tavern, nestled in the Old Town district of Stormwind City.",al={"where is harry burlguard","harry burlguard location","pig and whistle tavern"}},{q="What does Harry Burlguard teach?",a="Harry is an old veteran who instructs warriors in practical moves and stances designed to keep them breathing longer in the field, beginning with a few colorful tests of endurance.",al={"what do you learn","warrior quest reward level 10","harry burlguard lesson"}},{q="Why is training held in a tavern instead of the barracks?",a="Old Town is the traditional, rougher heart of Stormwind where retired soldiers and hardened veterans congregate. Harry prefers conducting his instruction over ale and bare-knuckle discipline rather than stuffy military protocol.",al={"why pig and whistle","why train in tavern","stormwind barracks"}},{q="What comes after speaking to Harry?",a="Harry immediately ropes the recruit into a challenge involving local brawler Bartleby the Drunk, testing their physical resilience before completing their training.",al={"what is next quest","after a warriors training","next step"},sp=1},{q="Can non-warriors receive this quest?",a="No. This quest is part of the dedicated warrior training line and is offered exclusively to characters of the warrior class.",al={"is this warrior only","can paladins do this","warrior class quest"}}},ang={["class:Warrior"]="This rite of passage marks your transition from local militia recruit to an officially recognized soldier of the Alliance, unlocking advanced stances and defensive techniques.",["race:Human"]="The path leads human fighters from the pastoral defenses of Elwynn right into Old Town, the ancestral, working-class cradle of Stormwind's martial heritage.",["faction:Alliance"]="Seasoned veterans like Harry Burlguard ensure that recruits heading into contested borders carry practical brawling wisdom, not just book-learned tactics."},kw={"bartleby","goldshire","harry burlguard","lyria du lac","old town","pig and whistle","stormwind","training","warrior"},rel={"npc:lyria-du-lac","subzone:pig-and-whistle-tavern","subzone:old-town","quest:1639","npc:bartleby","quest:1640","quest:1665","topic:stormwind-kingdom"},m={start="Lyria Du Lac",["end"]="Harry Burlguard",level="10",faction="Alliance",id=1638},src={"A Warrior's Training"}}
E["quest:1639"] = {t="quest",n="Bartleby the Drunk",z="stormwind",s="Bartleby the Drunk is an early rite of passage for Alliance warriors training in Stormwind City. Directed by Harry Burlguard inside the Pig and Whistle Tavern, an aspiring fighter must confront a stubborn barfly and take his prized drinking mug. It serves as a simple test of grit, proving a warrior can handle a brawl before advancing to true martial techniques.",h="Bartleby the Drunk is an early rite of passage for Alliance warriors training in Stormwind City.",sec={{t="A Tavernhouse Test",b="Before Harry Burlguard will impart deeper combat training in the Old Town tavern, he demands proof that a novice has real backbone. Rather than assigning an orderly sparring match, Harry gestures across the room to Bartleby, a belligerent patron nursing drinks at the far end of the counter. The task is straightforward: take the man's mug. Burlguard knows full well that Bartleby would rather fight than surrender his ale, making the confrontation an immediate trial of a warrior's resolve.",sp=0},{t="Old Town Etiquette",b="The Pig and Whistle caters to soldiers, laborers, and rough-and-tumble locals, leaving little patience for polished manners. Approaching Bartleby yields mockery rather than conversation, as the drunk immediately derides any newcomer as too prissy for a tavern scuffle. This friction sets the stage for a brawl right on the floorboards, showing that advancement in Stormwind's martial circles often begins with basic barroom brawling.",sp=0}},faq={{q="Who is Bartleby?",a="Bartleby is an obstinate, heavy-drinking patron found loitering at the bar in the Pig and Whistle Tavern within Stormwind's Old Town district.",al={"who is bartleby","bartleby npc","bartleby the drunk"}},{q="Why does Harry Burlguard send me to Bartleby?",a="Harry Burlguard wants to see what moves you have before committing to teach you advanced warrior techniques. Demanding Bartleby's mug guarantees a fight, testing your willingness to take a punch and hold your ground.",al={"why fight bartleby","harry burlguard test","why get the mug"}},{q="Where does this encounter take place?",a="The encounter occurs inside the Pig and Whistle Tavern, located in Old Town on the eastern side of Stormwind City.",al={"where is bartleby","pig and whistle location"}},{q="What happens when you speak to Bartleby?",a="Bartleby insults you, calling you fancy and prissy and warning you not to break a nail in a rough establishment like the Pig and Whistle, which quickly sparks a fight.",al={"what does bartleby say","bartleby dialogue"}},{q="What comes after talking to Bartleby?",a="Confronting Bartleby leads directly into a tavern brawl where you must physically defeat him to claim his mug and return it to Harry Burlguard.",al={"next quest after bartleby","what follows bartleby the drunk"}},{q="Is this quest available to any class?",a="No, this quest is part of the class training storyline exclusive to Alliance warriors reaching level 10.",al={"can anyone do bartleby","warrior only"}}},ang={["class:Warrior"]="This confrontation marks the practical test required by Stormwind's trainers before they will instruct you in defensive tactics and stance mastery.",["faction:Alliance"]="The tavern scuffle illustrates the gritty, unglamorous side of Stormwind's Old Town, far removed from the royal court of the Keep."},kw={"bartleby","drunk","harry burlguard","mug","old town","pig and whistle","stormwind","training","warrior"},rel={"quest:1638","quest:1640","quest:1665","npc:bartleby"},m={start="Harry Burlguard",["end"]="Bartleby",level="10",faction="Alliance",id=1639},src={"Bartleby the Drunk"}}
E["quest:1640"] = {t="quest",n="Beat Bartleby",z="stormwind",s="Beat Bartleby is a straightforward test of martial mettle for aspiring Alliance warriors in Stormwind City. To fulfill an initiation task, the trainee must physically brawl with a stubborn town drunk who refuses to hand over his prized mug without a fight. Proving one's strength against him earns both his begrudging respect and the vessel required by the warrior trainers.",h="Beat Bartleby is a straightforward test of martial mettle for aspiring Alliance warriors in Stormwind City.",sec={{t="A Brawler's Challenge",b="Warrior instructors in Stormwind do not accept excuses, nor do they teach their students that combat will always be noble and grand. As part of a recruit's formal training, young warriors are tasked with retrieving a particular mug from Bartleby, a notorious drunkard found lounging in the city. When approached, Bartleby scoffs at any polite requests, swearing that the only way anyone will claim his prized drinkware is by prying it from his cold, dead fingers. For a fledgling warrior, words quickly give way to bare-knuckle violence.",sp=0},{t="A Drunken Lesson",b="Though Bartleby makes grand declarations about fighting to the death, a thorough thrashing is all that is truly required to sober him up. Once beaten into submission, his bravado collapses into bruised admiration. Recognizing that his opponent is far tougher than they appear, he yields peacefully, allowing the victor to finally claim the mug and complete the trial for the training hall.",sp=0}},faq={{q="Who is Bartleby?",a="Bartleby is a belligerent drunkard who frequents Stormwind City. Known for clutching a beloved drinking vessel, he serves as an unwitting obstacle and sparring test for novice warriors sent to prove their physical resolve.",al={"bartleby","who is bartleby","bartleby npc"}},{q="Why do I have to fight Bartleby?",a="Alliance warrior trainers send recruits to recover a specific mug in Bartleby's possession. Because he stubbornly refuses to give it up without a brawl, the trainee must defeat him in hand-to-hand combat to loosen his grip.",al={"why fight bartleby","beat bartleby reason","why beat him"}},{q="Do I actually kill Bartleby in this quest?",a="No. Despite his boasting that you must pry the mug from his cold, dead fingers, Bartleby surrenders once his health is depleted, readily admitting that you are far tougher than he assumed.",al={"does bartleby die","kill bartleby","is bartleby dead"}},{q="Where does this quest take place?",a="The confrontation takes place within the city of Stormwind, where Bartleby can be found drinking and loitering.",al={"beat bartleby location","where is bartleby","bartleby spot"}},{q="What happens after I defeat him?",a="Once beaten, Bartleby yields and speaks to you amicably. You are then able to take his mug and deliver it back to the warrior trainers to complete your initiation.",al={"after beat bartleby","what next bartleby"}},{q="What level of training does this trial represent?",a="This brawl represents an early milestone for fledgling warriors around their tenth season of experience, serving as a practical test of basic melee endurance.",al={"bartleby quest level","when do i fight bartleby"}}},ang={["class:Warrior"]="This tavern brawl forms an iconic early trial for Alliance warriors, instilling the hard lesson that force of will and a heavy fist often resolve disputes where diplomacy fails.",["faction:Alliance"]="Set within the capital streets of Stormwind, this skirmish offers a colorful glimpse into the city's rough-and-tumble underbelly alongside its stately stone walls."},kw={"bartleby","brawl","drunk","mug","stormwind","training","trial","warrior"},rel={"npc:bartleby","quest:1639","quest:1665","quest:1638"},m={start="Bartleby",level="10",faction="Alliance",id=1640},src={"Beat Bartleby"}}
E["quest:1641"] = {t="quest",n="The Tome of Divinity",z="stormwind",s="The Tome of Divinity is an essential rite of passage for young paladins in the Kingdom of Stormwind. Under the guidance of Duthorian Rall in the Cathedral of Light, initiates are tested on their understanding of virtue, devotion, and the solemn responsibilities of wielding the Holy Light.",h="The Tome of Divinity is an essential rite of passage for young paladins in the Kingdom of Stormwind.",sec={{t="A Paladin's Calling",b="Within the serene marble halls of the Cathedral of Light, Duthorian Rall oversees the instruction of those who take up the mantle of the paladin. While early training focuses on martial discipline and martial rites, advancing within the order demands a deeper spiritual commitment. The trials associated with the Tome of Divinity challenge initiates to look beyond combat and understand the weight of moral duty in a kingdom besieged by internal and external perils.",sp=0},{t="The Path of Virtue",b="To receive the Book of Divinity is to enter into a contract of service and self-sacrifice. Duthorian tasks aspiring champions with studying the holy text to grasp what the Light demands of its defenders. The lessons contained within prepare paladins to counter the creeping horrors of the Scourge and safeguard the common folk, proving that righteous power must always be governed by genuine virtue and compassion.",sp=0}},faq={{q="What is the purpose of the Tome of Divinity?",a="The Tome of Divinity is a foundational holy text and trial given to developing paladins. It serves to test an initiate's grasp of sacred principles before they are entrusted with greater divine abilities, ensuring their strength is rooted in devotion and virtue rather than mere martial force.",al={"why tome of divinity","what is tome of divinity","paladin book quest"}},{q="Who is Duthorian Rall?",a="Duthorian Rall is a high-ranking paladin trainer stationed in the Cathedral of Light in Stormwind. He is responsible for guiding newly minted paladins, presenting them with the Book of Divinity, and directing their trials across the kingdom.",al={"duthorian rall","paladin trainer stormwind","who is duthorian"}},{q="Where does this trial take place?",a="The quest begins in the Cathedral Square of Stormwind City, inside the grand Cathedral of Light. Initiates report directly to Duthorian Rall after completing preliminary duties in the outer townships like Goldshire.",al={"where is duthorian","cathedral of light quest","where start tome of divinity"}},{q="Why is the Scourge mentioned in Stormwind's teachings?",a="Although the Scourge devastated Lordaeron to the north, the undead remain an existential threat to all living mortals. The paladins of Stormwind are trained from the outset to recognize and combat the unholy corruption of the Scourge wherever it may arise across Azeroth.",al={"scourge threat stormwind","why scourge here","paladins vs scourge"}},{q="What comes after reading the Book of Divinity?",a="Studying the text is only the opening step. Duthorian Rall tests whether the initiate truly internalizes its lessons by sending them out to aid those in dire need, proving their compassion and resilience through deeds rather than words.",al={"next step tome of divinity","after reading book","what does duthorian want next"}},{q="Who normally directs candidates to Duthorian Rall?",a="Local instructors and clergy serving in the outlying settlements of Elwynn, such as Brother Wilhelm in Goldshire, recognize when an initiate is ready for formal trials and dispatch them directly to Duthorian in the capital.",al={"who sent me to duthorian","previous quest tome of divinity","brother wilhelm"}}},ang={["class:Paladin"]="This rite marks the transition from a simple apprentice of arms into a true servant of the Holy Light, establishing the core tenets of sacrifice and mercy that define the order.",["race:Human"]="For humans of Stormwind, this ceremony honors the legacy of Lordaeron's fallen knights, continuing the proud tradition of the Silver Hand in the southern kingdom.",["faction:Alliance"]="Training stalwart paladins strengthens the heart of Stormwind, ensuring righteous protectors stand ready to shield the Alliance from rising darkness."},kw={"book of divinity","brother wilhelm","cathedral of light","duthorian rall","holy light","paladin","stormwind","tome of divinity","virtue"},rel={"npc:duthorian-rall","topic:light","topic:stormwind-kingdom","topic:scourge"},m={start="Duthorian Rall",level="12",faction="Alliance",id=1641},src={"The Tome of Divinity (human 1)"}}
E["quest:1649"] = {t="quest",n="The Tome of Valor",z="stormwind",s="The Tome of Valor represents a sacred transitional trial for rising paladins within the Cathedral of Light. Guided by holy texts and seasoned instructors, aspirants seek out Duthorian Rall in Stormwind to prove their unyielding faith, courage, and dedication to the Church's virtues.",h="The Tome of Valor represents a sacred transitional trial for rising paladins within the Cathedral of Light.",sec={{t="Tempering the Spirit",b="Within the traditions of the Holy Light, valor is not considered an innate trait that remains pure on its own. The sacred text of the Tome compares virtues to precious, unrefined ores: valuable upon discovery, yet requiring careful smelting and refinement to endure hardship. Only through strenuous trials and true commitment can a paladin fuse faith, compassion, and courage into an alloy capable of resisting the darkest evils threatening Azeroth.",sp=0},{t="Petitioning the Church",b="Having absorbed the wisdom laid down within the Tome of Valor, the paladin is directed to Duthorian Rall, a respected leader among the paladins gathered in Stormwind's Cathedral of Light. Duthorian serves as the arbiter for those petitioning to face the trials of valor. He warns aspirants that the tests ahead are no mere ritual: defending the innocent and upholding the Church demands readiness to sacrifice one's life, ensuring only the truly steadfast earn recognition in the order.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest bridges an initiate's foundational studies of holy doctrine with active, perilous trials. After consulting the Tome of Valor, aspiring paladins present themselves to Duthorian Rall in the Cathedral of Light to petition for their true tests of faith and courage.",al={"what is the tome of valor quest","why do i need this quest","tome of valor purpose"}},{q="Who is Duthorian Rall?",a="Duthorian Rall is a high-ranking paladin and teacher stationed within the Cathedral of Light in Stormwind. He oversees the development of promising defenders, administering the rigorous trials required to prove an initiate's worthiness before the Church.",al={"who is duthorian rall","duthorian rall lore","cathedral paladin trainer"}},{q="Why does the Church test its paladins so severely?",a="The Church of the Holy Light expects its paladins to serve as unshakeable bulwarks against despair and violence. Weak resolve or fragile faith could cost lives on the battlefield, so instructors ensure an initiate's spirit is tested and tempered before sending them on critical holy missions.",al={"why are paladin trials dangerous","why test valor"}},{q="Where does this trial take place?",a="The initiate delivers their petition directly to Duthorian Rall within the Cathedral of Light, situated prominently at the heart of the Cathedral Square in Stormwind City.",al={"where to turn in tome of valor","duthorian rall location"}}},ang={["class:Paladin"]="This trial marks a defining step in a paladin's growth, proving that righteous martial prowess must be anchored by disciplined faith and selfless service.",["faction:Alliance"]="The trials administered in Stormwind help maintain the core of the Alliance's defensive and spiritual strength amidst turbulent times."},kw={"cathedral of light","church of the holy light","duthorian rall","faith","paladin","stormwind","tome of valor","valor"},rel={"npc:duthorian-rall","topic:light","topic:stormwind-kingdom"},m={start="Tome of Valor (Classic)",["end"]="Duthorian Rall",level="25",faction="Alliance",id=1649},src={"The Tome of Valor (2)"}}
E["quest:1650"] = {t="quest",n="The Tome of Valor",z="stormwind",s="This quest represents the second trial in the paladin's pursuit of the Tome of Valor. Duthorian Rall dispatches knights to the distant shores of Westfall to shield Daphne Stilwell, a secluded homesteader left vulnerable to surrounding Defias bandits.",h="This quest represents the second trial in the paladin's pursuit of the Tome of Valor.",sec={{t="A Call to Arms",b="Within the Cathedral of Light, Duthorian Rall tests aspiring paladins not merely through scripture or solitary devotion, but through the direct defense of the realm's people. Having embraced the mantle of valor, paladins are immediately tasked with putting their ideals into practice where authority and law have broken down.",sp=0},{t="Peril on the Longshore",b="The destination is the isolated Longshore of Westfall, where Daphne Stilwell and her husband Jordan maintain an outpost against the ocean. With Jordan away in Ironforge consulting dwarven blacksmiths, Daphne has been left on her own amid rampant Defias Brotherhood activity. Duthorian orders the paladin to ride westward and stand as her shield before the thieves overwhelm her solitary homestead.",sp=0}},faq={{q="Why is Daphne Stilwell alone in Westfall?",a="Her husband, Jordan Stilwell, is a renowned blacksmith who traveled to the dwarven kingdom of Ironforge to consult with fellow smiths. His absence left Daphne to defend their coastal property unassisted amid growing Defias attacks.",al={"where is daphnes husband","why is jordan stilwell gone","daphne stilwell alone"}},{q="Who assigns this task to the paladin?",a="Duthorian Rall, a leading paladin trainer and preceptor within Stormwind's Cathedral of Light, gives the order once you prove ready to undertake the trials of valor.",al={"who gives tome of valor 1650","quest giver tome of valor","duthorian rall quest"}},{q="Where can Daphne Stilwell be found?",a="She resides in a small cottage on the far southern reaches of the Longshore, perched along the coastline of southwestern Westfall.",al={"where is daphne stilwell","daphne stilwell location","find daphne stilwell"}},{q="Is Daphne completely helpless when you arrive?",a="Not in the slightest. By the time a paladin reaches her porch, Daphne has already personally dispatched half a dozen Defias bandits with her own weapon while holding down the homestead.",al={"can daphne fight","is daphne defenseless","daphne stilwell fighting"}},{q="What threat is menacing the Stilwell home?",a="The Defias Brotherhood has overrun much of Westfall and continually harasses the isolated coastal homestead, attempting to claim the land and plunder what remains.",al={"who is attacking daphne","defias in westfall","enemies at stilwell farm"}},{q="How does this task fit into the Tome of Valor chain?",a="Valor in the paladin tradition is measured by proactive sacrifice and the defense of the defenseless. Standing between Daphne and marauding bandits provides a practical demonstration of righteousness in action.",al={"why do i have to help daphne","tome of valor trial purpose","meaning of this quest"}}},ang={["class:Paladin"]="This mission forms a core right of passage for young paladins, requiring them to leave the safety of Stormwind's Cathedral and prove their valor by guarding the defenseless.",["faction:Alliance"]="The Stilwell homestead's plight underscores how far Westfall has fallen from Stormwind's direct protection, leaving rural citizens to fend off the Defias alone."},kw={"daphne stilwell","defias brotherhood","duthorian rall","jordan stilwell","longshore","stormwind","tome of valor","westfall"},rel={"npc:duthorian-rall","npc:daphne-stilwell","subzone:longshore","zone:westfall","zone:ironforge","quest:1649"},m={start="Duthorian Rall",["end"]="Daphne Stilwell",level="25",faction="Alliance",id=1650},src={"The Tome of Valor (3)"}}
E["quest:1652"] = {t="quest",n="The Tome of Valor",z="stormwind",s="This quest marks the conclusion of the trials of valor set forth by the Church of the Holy Light in Stormwind. After defending the isolated Stilwell homestead from bandits in Westfall, an aspiring paladin returns to Duthorian Rall to report Daphne's safety. It cements the sacred duty of the paladin to serve as a selfless shield for the innocent.",h="This quest marks the conclusion of the trials of valor set forth by the Church of the Holy Light in Stormwind.",sec={{t="A Sacred Shield",b="The path of a paladin is not merely defined by combat prowess, but by the will to stand between danger and the defenseless. When Daphne Stilwell found herself besieged on her farm in Westfall, the Church of the Holy Light dispatched an initiate to hold the line. Returning to the Cathedral of Light in Stormwind, the initiate delivers the news that the homestead holds firm, proving that their courage matches their conviction.",sp=0},{t="Ties Between Kingdoms",b="Daphne's husband, Jordan Stilwell, is away in Ironforge assisting the efforts of the Alliance with his renowned craftsmanship. With the homestead guarded and Daphne secure, Duthorian Rall prepares word to travel north to the dwarven mountain city. Reassuring Jordan that his family remains protected allows the artisan to focus on his work, highlighting how mutual aid and paladin devotion bind the Alliance together across distant lands.",sp=0}},faq={{q="Who is Duthorian Rall?",a="Duthorian Rall is a senior paladin trainer within the Cathedral of Light in Stormwind. He oversees the spiritual and martial trials of young paladins, guiding them through the lessons recorded in the holy texts to ensure they embody the virtues of valor, righteousness, and humility.",al={"duthorian rall","who is duthorian","paladin trainer stormwind"}},{q="Why was Daphne Stilwell in danger?",a="Daphne Stilwell lives on an isolated farmstead in Westfall. Surrounded by Defias bandits and lawlessness, the farm became an easy target while her husband Jordan was away working in Ironforge.",al={"daphne stilwell","stilwell farm","who attacked daphne"}},{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a skilled blacksmith and craftsman devoted to the Church of the Holy Light and the Alliance. He is currently working in Ironforge, lending his expertise to their cause while relying on the Church to protect his wife back home.",al={"jordan stilwell","daphne husband","jordan ironforge"}},{q="What is the Tome of Valor?",a="The Tome of Valor represents both a holy book of lessons and a series of practical trials administered by the Cathedral of Light. Through these trials, paladins prove they possess the courage to confront darkness and protect the vulnerable at great personal risk.",al={"tome of valor meaning","what is tome of valor"}},{q="What comes after completing this trial?",a="Once Duthorian Rall acknowledges your valor in defending Daphne Stilwell, he guides you toward the next step in your spiritual and martial progression, the Test of Righteousness, continuing your advancement within the order.",al={"next quest after tome of valor","what is next"}},{q="Why does the Church care about the Stilwell homestead?",a="Daphne and Jordan Stilwell have long aided the Church of the Holy Light through faithful service and craftsmanship. Protecting Daphne during Jordan's absence is an act of reciprocal honor and charity, fulfilling the Church's promise to look after its own.",al={"why church help daphne","church and stilwells"}}},ang={["class:Paladin"]="Reporting back to Duthorian Rall concludes your lesson in valor, proving you possess the selflessness required to serve as a holy protector of the Alliance.",["faction:Alliance"]="The Stilwell family's plight links human farmlands in Westfall directly to dwarven workshops in Ironforge, showing the practical interdependence of the Alliance."},kw={"cathedral of light","daphne stilwell","duthorian rall","ironforge","jordan stilwell","stormwind","tome of valor","westfall"},rel={"npc:duthorian-rall","npc:daphne-stilwell","quest:1653","topic:stormwind-kingdom","zone:ironforge"},m={start="Daphne Stilwell",["end"]="Duthorian Rall",level="25",faction="Alliance",id=1652},src={"The Tome of Valor (5)"}}
E["quest:1653"] = {t="quest",n="The Test of Righteousness",z="stormwind",s="The Test of Righteousness marks the transition from defending the innocent in Westfall to embarking on the construction of a paladin's sacred weapon. Entrusted by Duthorian Rall, the initiate travels to Ironforge to bring glad tidings to the devout smith Jordan Stilwell.",h="The Test of Righteousness marks the transition from defending the innocent in Westfall to embarking on the...",sec={{t="A Messenger of Good News",b="Having stood guard over Daphne Stilwell during a harrowing Defias ambush on her Westfall homestead, a paladin initiate returns to Cathedral Square to report. Lord Duthorian Rall recognizes that word must reach her husband, Jordan Stilwell, who left for Ironforge believing his family in jeopardy. Rall sends the young knight to deliver the relief in person, serving both as an act of fellowship and the prelude to a deeper undertaking.",sp=0},{t="The Smith of Dun Morogh",b="Jordan Stilwell was originally destined for the holy order of paladins, yet chose to honor his father's craft as a master weapon-smith without ever forsaking his faith. Setting up his anvil outside the gates of Ironforge to work in the bracing mountain air, Jordan relies on his spiritual devotion to guide his hammer. Upon hearing that his wife survived the Defias assault, his profound gratitude moves him to aid the paladin in forging a blessed weapon of righteousness.",sp=0}},faq={{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a devout weaponsmith stationed outside the massive front gates of Ironforge. Though he originally studied alongside the paladins in the ways of the Light, he ultimately chose to dedicate his life to continuing his late father's smithing craft.",al={"jordan stilwell","who is jordan","the smith in ironforge"}},{q="Why was Jordan's wife in danger?",a="Daphne Stilwell lives on a farmstead in Westfall, an untamed territory swarming with Defias Brotherhood outlaws. Her husband had feared an impending attack when he departed for the dwarf capital, a fear realized when bandits stormed the farm before being driven off by paladin initiates.",al={"daphne stilwell danger","what happened to jordan's wife","why defias attacked"}},{q="Where can Jordan Stilwell be found?",a="Jordan Stilwell works outside the main gates of Ironforge in the frigid snow of Dun Morogh. He prefers the crisp mountain air to the stifling heat of the Great Forge within the mountain city.",al={"where is jordan stilwell","stilwell location","jordan ironforge location"}},{q="Why does Duthorian Rall send the player to Ironforge?",a="Lord Duthorian Rall wishes for Jordan to hear directly from his wife's rescuer that she survived the Defias attack. The journey also connects the initiate with a master smith capable of guiding them through the creation of a sacred paladin armament.",al={"why go to ironforge","duthorian rall errand","reason for message"}},{q="What comes after speaking with Jordan?",a="Relieved by the news, Jordan offers his expertise to forge a magnificent holy warhammer for the initiate, requiring the gathering of rare materials and sanctified relics scattered across distant lands.",al={"test of righteousness next","what does jordan want","after talking to jordan"},sp=1},{q="How does Jordan feel about the Defias threat?",a="Jordan is incensed by the council of Stormwind's blind negligence. He notes that the Defias Brotherhood has plagued Westfall for a long time, but hopes that attacks reaching deep into honest homesteads will force the boy-king's regents to finally acknowledge the crisis.",al={"jordan defias opinion","stilwell king advisors","defias in westfall"}}},ang={["class:Paladin"]="This leg of your trials represents the shift from protecting the weak to crafting the sacred tools necessary to purge evil across the lands of the Alliance.",["faction:Alliance"]="The Stilwell family's plight reflects the growing instability in Westfall, where common folk struggle against the Defias while royal advisors in Stormwind dither.",["profession:Blacksmithing"]="Jordan Stilwell proves that true dedication to the anvil can be just as holy an expression of devotion as wielding a consecrated blade on the battlefield."},kw={"daphne stilwell","defias brotherhood","dun morogh","duthorian rall","ironforge","jordan stilwell","stormwind","test of righteousness"},rel={"npc:jordan-stilwell","npc:duthorian-rall","zone:ironforge","topic:light"},m={start="Duthorian Rall",["end"]="Jordan Stilwell",level="21",faction="Alliance",id=1653},src={"The Test of Righteousness"}}
E["quest:1665"] = {t="quest",n="Bartleby's Mug",z="stormwind",s="Bartleby's Mug is the concluding task in a young Stormwind warrior's initial test of grit. Having bested the belligerent brawler Bartleby in the Pig and Whistle Tavern, the adventurer claims his drinking mug as proof of victory for their trainer, Harry Burlguard.",h="Bartleby's Mug is the concluding task in a young Stormwind warrior's initial test of grit.",sec={{t="Trophy of a Tavern Brawl",b="Warrior trainers in Stormwind care little for dainty theory; they want to see raw determination and the ability to hold one's ground. Harry Burlguard tasks budding warriors with taking down Bartleby, a stubborn drunk at the bar of the Pig and Whistle in Old Town. Once subdued, Bartleby reluctantly surrenders his prized drinking mug—only after taking one final swig to drain whatever dregs remained.",sp=0},{t="A Step Toward Mastery",b="Delivering the mug back to Harry Burlguard marks the completion of the novice trial. Recognizing the fighter's knack for persuasion through sheer force, Burlguard acknowledges the warrior's readiness for defensive mastery, directing them onward to further battlefield instruction and the seasoned veteran Marshal Haggard in Elwynn Forest.",sp=0}},faq={{q="Why does Harry Burlguard want Bartleby's mug?",a="The mug serves as undeniable proof that the novice warrior actually fought and bested Bartleby. Bartleby is fiercely attached to his drink, so surrendering his personal mug proves he was soundly beaten into submission.",al={"why bartleby mug","burlguard mug purpose","proof of beating bartleby"}},{q="Who is Bartleby?",a="Bartleby is an unruly tavern patron lingering at the bar of the Pig and Whistle in Stormwind's Old Town. Known for his drunkenness and foul temper, local warrior trainers use him as an informal rite of passage for up-and-coming fighters.",al={"bartleby lore","who is bartleby the drunk","bartleby old town"}},{q="Where does this fight take place?",a="The brawl occurs inside the Pig and Whistle Tavern, situated in Old Town in Stormwind City.",al={"where is bartleby","bartleby location","pig and whistle fight"}},{q="What comes after returning the mug to Burlguard?",a="Once Burlguard inspects the mug and confirms your victory, he imparts advanced training in defensive combat stances before sending you outside the city gates to seek out Marshal Haggard in Elwynn Forest.",al={"what next after bartleby mug","quest after bartleby mug","haggard quest"}},{q="Does Bartleby get hurt permanently in the brawl?",a="No. The brawl is merely a non-lethal tavern scuffle. Once beaten, Bartleby yields, finishes off his drink, hands over his mug, and remains in the tavern to nurse his bruises and pride.",al={"is bartleby dead","did bartleby die","bartleby survived"}},{q="Can any Alliance class do this quest?",a="This task is strictly reserved for Alliance warriors as part of their level 10 class training progression to master the art of combat stances and defensive maneuvers.",al={"is bartlebys mug warrior only","who can do bartleby quest","mug quest classes"}}},ang={["class:Warrior"]="Stormwind's trainers believe practical brawling teaches lessons no manual can match; taking Bartleby's mug proves your ability to stand toe-to-toe and overpower unruly foes.",["faction:Alliance"]="Keeping the peace in Old Town often means handling disorderly patrons, making Bartleby a familiar local headache for Stormwind's martial instructors."},kw={"bartleby","burlguard","mug","old town","pig and whistle","stormwind","warrior"},rel={"quest:1640","quest:1639","quest:1638","npc:bartleby"},m={start="Bartleby",["end"]="Harry Burlguard",level="10",faction="Alliance",id=1665},src={"Bartleby's Mug (quest)"}}
E["quest:1666"] = {t="quest",n="Marshal Haggard",z="stormwind",s="Marshal Haggard is an Alliance quest given by Harry Burlguard in Stormwind City to novice warriors seeking better arms. The young fighter is dispatched out of the capital to the Eastvale Logging Camp in eastern Elwynn Forest to meet a retired military marshal who keeps a storied collection of veteran weaponry. It marks an early step in a warrior's martial journey beyond the safety of the city walls.",h="Marshal Haggard is an Alliance quest given by Harry Burlguard in Stormwind City to novice warriors seeking...",sec={{t="A Veteran's Armory",b="Novice warriors training in Stormwind are quickly reminded that raw technique only goes so far without reliable steel. Harry Burlguard directs promising fighters to track down Marshal Haggard, a retired officer of the realm living in the quiet reaches of eastern Elwynn Forest. Over a lifetime in the field, Haggard amassed a respectable personal armory, making his homestead a natural destination for fledgling warriors in need of real equipment.",sp=0},{t="Retirement at Eastvale",b="Marshal Haggard resides in a secluded manor near the Eastvale Logging Camp. Years of grueling service have taken their toll on the aging commander: his vision is failing, and he is prone to mistaking approaching travelers for prowling riverpaw gnolls. Despite his age and isolation, the old marshal remains a respected figure among Stormwind's guards and trainers.",sp=0}},faq={{q="Who starts this quest?",a="Harry Burlguard, a warrior trainer stationed in Stormwind City, offers this quest once an aspiring warrior has proven their foundational skills.",al={"where do i get marshal haggard quest","who gives marshal haggard","quest giver marshal haggard"}},{q="Where is Marshal Haggard located?",a="Marshal Haggard lives in a manor house just east of the Eastvale Logging Camp, situated in the far eastern edge of Elwynn Forest near the border of Redridge Mountains.",al={"marshal haggard location","where is haggard","eastvale lumber camp manor"}},{q="Why does Harry Burlguard send you to Haggard?",a="Burlguard recognizes that a developing warrior needs quality equipment beyond standard issue trainees' blades. Haggard gathered substantial arms and armor throughout his long career and is known to part with gear for those who prove their worth.",al={"why marshal haggard","why go to eastvale warrior","purpose of marshal haggard quest"}},{q="Why does Haggard mistake visitors for gnolls?",a="Haggard's eyesight has deteriorated significantly in his old age. Because gnolls frequently harass the eastern timber operations and outskirts of Elwynn Forest, the cautious old veteran remains on edge against sudden visitors.",al={"haggard eyesight","is haggard blind","haggard gnoll dialogue"}},{q="What comes after completing this quest?",a="Upon greeting Haggard, the retired marshal will test your mettle by sending you on the quest Dead-tooth Jack before considering parting with any weapons from his personal stores.",al={"marshal haggard next quest","follow up to marshal haggard"},sp=1},{q="Is this quest available to classes other than warriors?",a="No. This quest line forms part of the level 10 warrior class progression designed to equip young fighters for challenges beyond Elwynn Forest.",al={"can paladins do marshal haggard","warrior only quest haggard"}}},ang={["class:Warrior"]="This task serves as an early milestone for Alliance warriors, transitioning them from formal urban training into the wider wilderness in search of martial gear.",["faction:Alliance"]="The quest reflects how Stormwind relies on the lingering expertise and private supplies of retired veterans to foster the next generation of defenders."},kw={"eastvale","eastvale logging camp","elwynn forest","harry burlguard","marshal haggard","stormwind","warrior"},rel={"quest:1667","zone:elwynn","topic:gnoll"},m={start="Harry Burlguard",["end"]="Marshal Haggard",level="10",faction="Alliance",id=1666},src={"Marshal Haggard (quest)"}}
E["quest:1685"] = {t="quest",n="Gakin's Summons",z="stormwind",s="A summons delivered to promising Alliance warlocks by Remen Marcot on behalf of Gakin the Darkbinder. It directs fledgling practitioners down into the crypts beneath the Slaughtered Lamb in Stormwind's Mage Quarter to begin their next stage of dark occult training.",h="A summons delivered to promising Alliance warlocks by Remen Marcot on behalf of Gakin the Darkbinder.",sec={{t="A Discrete Message",b="Demonology is strictly outlawed across the civilized districts of Stormwind, yet dark arts persist right under the noses of the city guard. When a warlock displays sufficient proficiency with their introductory imps, word quietly travels to senior practitioners. Remen Marcot delivers the message with deliberate discretion, urging initiates to keep the meeting place quiet and head into the shadowy recesses beneath the Mage Quarter.",sp=0},{t="The Crypts of the Slaughtered Lamb",b="Behind the modest facade of the Slaughtered Lamb tavern lies a network of damp cellars and hidden catacombs. Here, shielded from prying Kirin Tor mages and the Cathedral's inquisitors, Gakin the Darkbinder oversees the instruction of Stormwind's warlocks. The summons serves as the gateway to commanding a voidwalker, a rite requiring dangerous stolen reagents and perilous summoning circles.",sp=0}},faq={{q="Why does Gakin the Darkbinder summon warlocks?",a="Gakin summons budding warlocks once they reach a suitable level of experience. He considers untrained warlocks a liability prone to losing their heads, and aims to instruct them in the complex ritual of binding a voidwalker to their service.",al={"why gakin summons","what is gakin summons for","voidwalker quest start"}},{q="Where is Gakin the Darkbinder located?",a="Gakin is hidden in the deep underground crypts beneath the Slaughtered Lamb, a tavern situated in the Mage Quarter of Stormwind.",al={"where is gakin","gakin location","slaughtered lamb basement"}},{q="Who is Remen Marcot?",a="Remen Marcot is an associate of Stormwind's warlock coven who spends his time tracking down promising candidates in the city to quietly direct them to Gakin's hidden enclave.",al={"remen marcot","who starts gakin summons"}},{q="Why must the location be kept secret?",a="Fel magic and demon summoning are forbidden in the Kingdom of Stormwind. Discovery by the Silver Hand, the Cathedral of Light, or the city guards would result in imprisonment or execution.",al={"why secret","warlock secrecy stormwind"}},{q="What comes after answering Gakin's summons?",a="After reporting to Gakin, he tasks the warlock with venturing to the Brackwell Pumpkin Patch in Elwynn Forest to recover a bloodstone choker from Surena Caledon, an essential component for the voidwalker binding ritual.",al={"next quest after gakins summons","what happens next"},sp=1},{q="Can non-warlocks receive this summons?",a="No. The summons is strictly restricted to warlocks who have mastered their basic imp companion and require advanced occult instruction.",al={"can mages get this","who can do gakins summons"}}},ang={["class:Warlock"]="This summons marks your progression beyond parlor tricks and minor imps, initiating the trials necessary to enslave a voidwalker to shield you in battle.",["faction:Alliance"]="Even within the heart of Stormwind, the Alliance tolerates a subterranean cabal of shadow-weavers whose fel expertise provides a shadowy edge against their enemies."},kw={"demonology","gakin the darkbinder","mage quarter","remen marcot","slaughtered lamb","stormwind","voidwalker","warlock"},rel={"npc:gakin-the-darkbinder","subzone:slaughtered-lamb","quest:1688","quest:1471","subzone:mage-quarter","quest:1715","topic:stormwind-kingdom"},m={start="Remen Marcot",["end"]="Gakin the Darkbinder",level="10",faction="Alliance",id=1685},src={"Gakin's Summons (Voidwalker)"}}
E["quest:1698"] = {t="quest",n="Yorus Barleybrew",z="stormwind",s="Yorus Barleybrew is an Alliance warrior summons directing seasoned fighters out of Stormwind toward the borderlands of Redridge. Issued by martial trainers across the Alliance capitals, it sends ambitious combatants to meet an eccentric dwarf laying down a deadly challenge at the Lakeshire Inn.",h="Yorus Barleybrew is an Alliance warrior summons directing seasoned fighters out of Stormwind toward the...",sec={{t="A Call to the Strong",b="Warrior trainers across the Alliance capitals, including Kelv Sternhammer, Wu Shen, and Darnath Bladesinger, keep a close eye on fighters who have outgrown basic drills. When an apprentice proves their mettle around their twentieth season, these masters pass along word of a dwarf named Yorus Barleybrew. Rather than issuing a standard military directive, Barleybrew has put out an open wager and a test of arms to any Alliance warrior bold enough to answer.",sp=0},{t="Waiting in Lakeshire",b="Barleybrew has stationed himself at the tavern in Lakeshire, right on the front lines of Redridge's struggle against encroaching gnolls and Blackrock orcs. Those who track him down find a boastful dwarf with a hearty drink in hand, ready to size up any challenger who claims to possess real fighting spirit. For warriors seeking to prove themselves beyond the safe cobbled streets of the capital, his trial marks an initiation into harsher frontier battles.",sp=0}},faq={{q="Who is Yorus Barleybrew?",a="Yorus Barleybrew is a dwarf associated with the famous Barleybrew brewing clan who has issued an open martial challenge to Alliance warriors. Stationed in the Lakeshire Inn, he tests fighters who think they are ready for the brutal frontier of Redridge Mountains.",al={"yorus barleybrew","who is barleybrew","dwarf in lakeshire inn"}},{q="Why do the trainers send warriors to Redridge?",a="Once a warrior reaches sufficient skill in Stormwind, local weapon masters push them toward practical, high-stakes combat. Yorus Barleybrew offers a trial that forces trainees to venture beyond city walls and prove their endurance against real wilderness threats.",al={"why lakeshire","warrior trainer quest redridge","why go to yorus"}},{q="Where can I find Yorus Barleybrew?",a="He can be found sitting inside the Lakeshire Inn, situated in the town of Lakeshire within the Redridge Mountains, just east of Elwynn Forest.",al={"yorus barleybrew location","where is yorus","find barleybrew"}},{q="What happens after speaking with Yorus?",a="Speaking with Yorus initiates his martial trial, challenging you to take on the Rethban Gauntlet, a perilous test against the vicious beasts and gnolls inhabiting the surrounding hills.",al={"after yorus","barleybrew trial","next quest"}},{q="Who offers the quest to find him?",a="The quest is provided by various warrior trainers in the Alliance capitals, including Kelv Sternhammer, Wu Shen, and Darnath Bladesinger, once a warrior has proven basic competence.",al={"who gives quest","quest starter","trainers for yorus"}},{q="Is this trial open to classes other than warriors?",a="No. The challenge is specifically tailored for warriors. Yorus Barleybrew issues his trial exclusively to martial combatants who rely purely on physical endurance and arms.",al={"can paladins do this","is this warrior only","class restrictions"}}},ang={["class:Warrior"]="This quest marks an important rite of passage for Alliance warriors, moving them from introductory drills into dangerous trials out on the Redridge frontier.",["faction:Alliance"]="Barleybrew's challenge brings capable martial recruits directly into Lakeshire, a vulnerable settlement currently beset by gnolls and Blackrock orcs."},kw={"kelv sternhammer","lakeshire","lakeshire inn","redridge","rethban","stormwind","warrior","wu shen","yorus barleybrew"},rel={"quest:1699","subzone:lakeshire-inn","subzone:lakeshire","topic:alliance"},m={start="Kelv Sternhammer,Wu Shen, orDarnath Bladesinger",["end"]="Yorus Barleybrew",level="20",faction="Alliance",id=1698},src={"Yorus Barleybrew (quest)"}}
E["quest:1700"] = {t="quest",n="Grimand Elmore",z="stormwind",s="Following the creation of specialized armor, the dwarven smith Furen Longbeard sends a copy of his findings across the district to Grimand Elmore. The brief errand carries technical notes between two headstrong weaponsmiths sharing space in Stormwind City.",h="Following the creation of specialized armor, the dwarven smith Furen Longbeard sends a copy of his findings...",sec={{t="A Message Across the District",b="Having forged the specialized Fire Hardened Mail, Furen Longbeard documents the intricate heat-treating techniques and elemental principles he uncovered during the process. Rather than keeping the knowledge entirely to himself, he commits the notes to parchment and tasks an adventurer with delivering them straight to Grimand Elmore, a seasoned crafter operating out of a nearby weapon shop.",sp=0},{t="Professional Pride and Curiosity",b="Grimand Elmore's immediate reaction upon receiving the manuscript is wounded pride. Adamant that he taught Furen everything the younger dwarf knows, Grimand bristles at the notion that his former pupil could offer him instruction. Despite his outward indignation, the craftsman cannot resist perusing the text, quickly finding an intriguing idea hidden within the notes that he is eager to test for himself.",sp=0}},faq={{q="Who is Grimand Elmore?",a="Grimand Elmore is a respected weaponsmith who maintains a shop in Stormwind City's Dwarven District. He is known for his immense professional pride and his past role in teaching craft skills to other local smiths, including Furen Longbeard.",al={"grimand elmore","who is grimand","elmore stormwind"}},{q="Why does Furen send notes to Grimand?",a="While crafting the Fire Hardened Mail, Furen discovered new techniques and recorded his methods. He wanted to share the breakthroughs with Grimand, even while knowing Grimand's fiery temper and stubborn ego would make him react defensively to being taught something new.",al={"why send notes","furen notes","furen to grimand"}},{q="Where can Grimand Elmore be found?",a="He can be found working inside the weapon shop located within the Dwarven District of Stormwind City, only a short walk from Furen Longbeard's forge.",al={"where is grimand","grimand location","grimand elmore shop"}},{q="How does Grimand react to the notes?",a="Grimand is initially outraged, declaring that he taught Furen everything the dwarf knows. However, his curiosity as a master smith quickly takes over when he spots an intriguing technique in the text that he wants to experiment with.",al={"grimand reaction","is grimand mad"}},{q="What happens after Grimand reads the notes?",a="Intrigued by Furen's work on fire-tempering metal, Grimand decides to pursue his own ambitious craft project, which leads into further tasks to gather rare components with elemental heat.",al={"what next grimand","after grimand elmore quest"},sp=1},{q="Why does Furen warn to duck when handing over the notes?",a="Furen knows Grimand's fiery temper and excessive pride firsthand. He anticipates that Grimand might throw a tantrum—or an object—at the mere implication that an apprentice could teach the master a new technique.",al={"why duck","furen duck warning"}}},ang={["class:Warrior"]="This delivery bridges the gap between armoring yourself and seeking out martial weapons forged through the very same elemental experiments.",["profession:Blacksmithing"]="The exchange between Furen and Grimand illustrates the intense professional rivalry and sharing of trade secrets common among master metalworkers.",["race:Dwarf"]="The hot-headed, prideful banter between Grimand and Furen reflects the deeply competitive yet cooperative traditions of Khaz Modan's smithing culture."},kw={"blacksmithing","dwarven district","fire hardened mail","furen longbeard","furen's notes","grimand elmore","stormwind"},rel={"npc:furen-longbeard","quest:1701","subzone:dwarven-district"},m={start="Furen Longbeard",["end"]="Grimand Elmore",level="28",faction="Alliance",id=1700},src={"Grimand Elmore (quest)"}}
E["quest:1701"] = {t="quest",n="Fire Hardened Mail",z="stormwind",s="\"Fire Hardened Mail\" is an Alliance warrior quest offered by the dwarf armorer Furen Longbeard in Stormwind City. Building upon his previous smithing work, Furen promises to fashion a suit of exceptionally durable mail armor if the warrior can retrieve rare alchemical and beast-harvested components scattered across both continents.",h="\"Fire Hardened Mail\" is an Alliance warrior quest offered by the dwarf armorer Furen Longbeard in Stormwind...",sec={{t="A Master Armorer's Ambition",b="After forging an exceptional buckler for the aspiring warrior, Furen Longbeard proposes an even greater project: a suit of mail hardened against the fiercest blows. Such dwarf craftsmanship requires more than mere iron or steel; it demands exotic materials imbued with elemental heat and natural resilience. Because the smith cannot abandon his forge in Stormwind, the burden of collecting these hazardous reagents falls entirely upon the warrior seeking the armor.",sp=0},{t="A Cross-Continental Expedition",b="Furen's detailed instructions send the warrior to distant wildernesses and treacherous depths. The recipe requires fangs harvested from the venomous arachnids crawling through the damp crevices of the Wetlands, as well as scorched and galvanized horns stripped from the fierce chimaeras nesting in the Stonetalon Mountains. To bind and temper these beast parts into wearable mail, the armor also calls for a vial of volatile phlogiston seized from Roogug, a geomancer deep inside the bristling thorn-labyrinths of Razorfen Kraul in the Barrens.",sp=0}},faq={{q="Who is Furen Longbeard?",a="Furen Longbeard is a veteran dwarven armorer and shieldsmith stationed in the Dwarven District of Stormwind City. He specializes in crafting tailored defensive equipment for promising warriors willing to aid him.",al={"furen","who gives fire hardened mail","who is the smith"}},{q="Why does Furen require such strange ingredients?",a="Traditional smelting produces ordinary steel, but Furen's secret techniques require organic materials conditioned by natural venom, mountain winds, and breath weapons, compounded by the volatile catalytic substance phlogiston to temper the metal beyond typical dwarven methods.",al={"why spider fangs","why horns","what is phlogiston"}},{q="Where do the chimaera horns come from?",a="The charred horns and the prized galvanized horn come from chimaeras dwelling in Kalimdor's Stonetalon Mountains, particularly the younger beasts and the formidable Chimaera Matriarch who leads them.",al={"where to find chimaera horns","charred horn location","galvanized horn"}},{q="Where can phlogiston be found?",a="A vial of phlogiston is carried by the quilboar geomancer Roogug, who makes his lair within Razorfen Kraul, located at the southern tip of the Barrens in Kalimdor.",al={"vial of phlogiston","who drops phlogiston","roogug"}},{q="Which spiders carry scorched spider fangs?",a="The fangs are obtained from the giant arachnids of the Wetlands in the Eastern Kingdoms, specifically Leech Stalkers and Cave Stalkers lurking along the region's marshes and caverns.",al={"scorched spider fangs","where are the spiders","wetlands spiders"}},{q="What happens after all the materials are gathered?",a="Upon receiving the fangs, horns, and phlogiston, Furen immediately begins working his forge to hammer the raw elements into a custom breastplate for the warrior in the quest 'Furen's Armor'.",al={"what comes next","fire hardened mail follow up","reward"}}},ang={["class:Warrior"]="This undertaking represents a major rite of passage for Alliance warriors, forcing them to brave Kalimdor's wilds and deep dungeons to earn a piece of masterwork armor.",["race:Dwarf"]="Furen's craft reflects the enduring dwarven belief that true armor requires unyielding materials drawn straight from the harshest natural predators.",["faction:Alliance"]="Fulfilling Furen's list requires an Alliance soldier to venture deep into the Barrens and Stonetalon Mountains, regions heavily contested by the Horde."},kw={"charred horn","fire hardened mail","furen longbeard","galvanized horn","phlogiston","razorfen kraul","roogug","scorched spider fang","stonetalon","wetlands"},rel={"npc:furen-longbeard","quest:1782","quest:1702","zone:razorfenkraul","zone:stonetalon","zone:wetlands","topic:stormwind-kingdom","topic:razorfen"},m={start="Furen Longbeard",level="28",faction="Alliance",id=1701},src={"Fire Hardened Mail"}}
E["quest:1702"] = {t="quest",n="The Shieldsmith",z="stormwind",s="Following a harrowing trial in the Redridge Mountains, Yorus Barleybrew sends warriors to Stormwind's Dwarven District to collect their true reward. Bearing a potent cask of Barleybrew Scalder, martial travelers seek out master armorer Furen Longbeard to fashion a stout shield.",h="Following a harrowing trial in the Redridge Mountains, Yorus Barleybrew sends warriors to Stormwind's Dwarven...",sec={{t="A Promise Kept",b="After proving their mettle against the gnolls and perils of the Rethban Gauntlet, warriors expect compensation from Yorus Barleybrew. While Yorus honors his bargain, the true prize cannot be hammered out in Lakeshire. Instead, he directs promising fighters back to Stormwind City, where a dwarven armorer stands ready to repay a personal debt.",sp=0},{t="Barleybrew's Finest",b="Rather than a parchment letter of credit, Yorus provides currency far more persuasive to a thirsty Ironforge artisan: a heavy cask of Barleybrew Scalder. Delivered to Furen Longbeard amidst the clatter and soot of the Dwarven District, the brew serves as both introduction and payment, prompting the seasoned smith to lend his craft to an aspiring protector.",sp=0}},faq={{q="Who is Furen Longbeard?",a="Furen Longbeard is a master dwarven armorer and shieldsmith stationed in the Dwarven District of Stormwind City. Renowned among Alliance warriors, he crafts specialized defensive gear and works closely with martial veterans who earn his respect.",al={"furen longbeard","who is furen","who is the shieldsmith"}},{q="Why does Yorus send you to Stormwind?",a="While Yorus Barleybrew offered a reward for clearing the Rethban Gauntlet, he lacks the specialized smithing skills to forge the promised martial shield himself. He sends you to his friend Furen Longbeard, who owes him a significant favor.",al={"why go to stormwind","why stormwind","yorus reward location"}},{q="What is Barleybrew Scalder?",a="Barleybrew Scalder is an exceptionally potent dwarven beverage crafted by the Barleybrew family. Yorus sends a fresh cask to Furen Longbeard to quench the smith's thirst and grease the wheels of their arrangement.",al={"cask of scalder","barleybrew scalder","what is the scalder"}},{q="Where can Furen Longbeard be found?",a="Furen Longbeard can be found tending his forge in the heart of the Dwarven District in Stormwind City, surrounded by the soot, anvils, and workshops of dwarven crafters.",al={"furen location","where is furen longbeard","find furen"}},{q="What happens after giving Furen the cask?",a="Receiving the Scalder confirms that Yorus sent you. Furen acknowledges his debt and immediately offers to construct defensive armor suited for seasoned battle, beginning a path toward crafting fire-hardened gear.",al={"what comes next","furen follow up quest"}},{q="Why is this errand important for Alliance warriors?",a="This errand introduces an Alliance warrior to one of the most capable armorers in the kingdom, opening the door to tailored martial gear and further instruction in the art of defensive warfare.",al={"warrior quest importance","why warriors care"}}},ang={["class:Warrior"]="This delivery bridges the grit of Redridge with the mastercraft of Stormwind, proving your right to carry a shield forged by a legendary dwarven armorer.",["race:Dwarf"]="Trading a cask of fine Barleybrew ale for forged iron in the heart of Stormwind's Dwarven District is about as quintessentially dwarven as business gets.",["profession:Blacksmithing"]="Meeting Furen Longbeard connects you with a master of the anvil whose specialized work on defensive armor is celebrated throughout the Alliance."},kw={"barleybrew scalder","cask","dwarven district","furen longbeard","rethban","shieldsmith","stormwind","warrior","yorus barleybrew"},rel={"npc:furen-longbeard","quest:1699","quest:1701","quest:1698","subzone:dwarven-district","topic:stormwind-kingdom","quest:116"},m={start="Yorus Barleybrew",["end"]="Furen Longbeard",level="22",faction="Alliance",id=1702},src={"The Shieldsmith"}}
E["quest:1705"] = {t="quest",n="Burning Blood",z="stormwind",s="Master smith Grimand Elmore in Stormwind tasks an adventurer with venturing into the shadowy forests of Duskwood to recover exotic forge reagents. Intrigued by innovative armorcrafting techniques pioneered by Furen Longbeard, Grimand requires burning blood and a blazing ember stone held by feral worgen to test the process himself.",h="Master smith Grimand Elmore in Stormwind tasks an adventurer with venturing into the shadowy forests of...",sec={{t="A Reluctant Experiment",b="Grimand Elmore, one of the Alliance's most accomplished armorers, rarely concedes that another craftsman might outshine his own methods. Yet, after hearing of Furen Longbeard's unconventional smithing discoveries, professional curiosity overtakes his stubborn pride. Grimand agrees to put Furen's methods to the test by hammering out a bespoke piece of armor. To quench and temper the metal to exact specifications, ordinary water or common coals will not suffice; he demands strange, volatile components found only in the darkened reaches of the south.",sp=0},{t="The Horrors of Roland's Doom",b="The quest directs brave smith-aspirants and warriors into Duskwood, specifically toward the forsaken mine of Roland's Doom. The cavern has been overrun by savage Nightbane worgen—lupine beasts whose cursed veins pulse with unnatural, searing ichor. Grimand requires vials of this burning blood, alongside a rare flaming geological core known as a burning rock, held by the pack's ferocious leader, Gutspill. Slaying these beasts and securing their scorching remains allows Grimand to fire his forge with dark, fiery power.",sp=0}},faq={{q="Who is Grimand Elmore?",a="Grimand Elmore is a respected master armorer operating in the Dwarven District of Stormwind. He works alongside fellow craftsmen to equip the city's defenders and trains aspiring warriors in the durability and weight of proper battle plate.",al={"grimand","grimand elmore","stormwind armorer"}},{q="Why does Grimand want burning blood and a burning rock?",a="Grimand wants to test an unconventional armorcrafting technique developed by Furen Longbeard. The burning blood and burning rock possess intense, supernatural heat necessary to temper and forge specialized armor plates.",al={"why burning blood","what is burning rock for","quest purpose"}},{q="Where do I find the Nightbane worgen carrying these materials?",a="The materials are found in Duskwood at Roland's Doom, an abandoned mine in southeastern Duskwood, southwest of Darkshire. The mine tunnels are packed with hostile Nightbane worgen that carry the searing blood.",al={"where are the worgen","roland's doom location","where is burning blood"}},{q="Who holds the burning rock?",a="The burning rock is carried by Gutspill, a powerful leader among the Nightbane worgen dwelling within the depths of Roland's Doom.",al={"who has burning rock","gutspill","gutspill location"}},{q="What is the relationship between Grimand Elmore and Furen Longbeard?",a="Furen Longbeard and Grimand Elmore are rival dwarven master smiths. Grimand is usually skeptical of outside ideas, but Furen's latest innovations in armorcrafting proved compelling enough for Grimand to test them firsthand.",al={"grimand and furen","who is furen longbeard"}},{q="What happens after returning the blood and rock?",a="After receiving the fiery reagents, Grimand immediately begins forging the armor to verify Furen's techniques, promising the finished crafted piece to the adventurer who gathered the materials.",al={"next quest","reward","what does grimand make"}}},ang={["class:Warrior"]="For warriors traversing the kingdom, braving the cursed beasts of Duskwood for Grimand's experiment yields uniquely tempered armor tailored for the front lines.",["profession:Blacksmithing"]="Blacksmiths will appreciate the professional rivalry between Grimand and Furen, highlighting the lengths master smiths will go to test rare metallurgy and quenching agents.",["faction:Alliance"]="Reclaiming reagents from Roland's Doom helps keep the encroaching worgen menace in Duskwood checked while supplying Stormwind's armories with potent new defensive techniques."},kw={"burning blood","burning rock","duskwood","furen longbeard","grimand elmore","gutspill","nightbane worgen","roland's doom"},rel={"quest:1700","quest:1706","subzone:roland-s-doom","zone:duskwood","topic:worgen","topic:stormwind-kingdom"},m={start="Grimand Elmore",level="28",faction="Alliance",id=1705},src={"Burning Blood (quest)"}}
E["quest:1706"] = {t="quest",n="Grimand's Armor",z="stormwind",s="\"Grimand's Armor\" is the culmination of a warrior's training questline under the supervision of Grimand Elmore in the Dwarven District of Stormwind. After proving the viability of Furen Longbeard's metallurgic techniques, the smith crafts a formidable piece of armor capable of absorbing punishing blows in battle. It marks an essential milestone in an Alliance warrior's journey toward mastery.",h="\"Grimand's Armor\" is the culmination of a warrior's training questline under the supervision of Grimand...",sec={{t="A Master's Innovation Proven",b="Grimand Elmore, working from his forge in Stormwind's Dwarven District, originally held deep skepticism regarding the bizarre and daring techniques developed by the dwarven master armorer Furen Longbeard. Testing Furen's methods required perilous expeditions into hostile territory to gather rare elemental and beast components. By delivering these vital materials, a warrior allows Grimand to put the dwarf's theories to the fire, turning raw ingredients into a reinforced suit of armor engineered to endure catastrophic impacts.",sp=0},{t="Forging the Aegis",b="The final product demonstrates that Furen's metallurgic insights were entirely sound. Grimand successfully treats the metal to withstand intense pressure and physical trauma that would warp ordinary steel. Presenting the crafted breastplate to the warrior who aided him, Grimand acknowledges both Furen's craft and the adventurer's determination, equipping them to hold the frontline against the greatest threats in Azeroth.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest is the final turn-in for a major warrior class questline. Grimand Elmore completes crafting a specially treated breastplate using the rare materials you secured, validating the experimental smithing methods of Furen Longbeard.",al={"grimand armor purpose","why do grimands armor","what does grimand give me"}},{q="Who is Grimand Elmore?",a="Grimand Elmore is a skilled dwarven weaponsmith residing in the Dwarven District of Stormwind. He works in tandem with colleagues in Ironforge to assist rising warriors in obtaining specialized armor.",al={"who is grimand","grimand elmore role","where is grimand"}},{q="Who is Furen Longbeard and why is he mentioned?",a="Furen Longbeard is a dwarven master armorer stationed in the Dwarven District of Stormwind who devised an experimental technique to fortify armor against immense stress. Grimand was originally doubtful of Furen's claims until you brought the materials needed to test the method.",al={"who is furen","furen technique","furen longbeard"}},{q="What quest leads directly into this one?",a="This quest follows 'Burning Blood', where the warrior brings the final rare reagent—Burning Blood from the Nightbane worgen of Roland's Doom in Duskwood—to Grimand so he can quench and temper the metal.",al={"prereq for grimands armor","burning blood quest","what quest comes before this"}},{q="Can any class complete this quest?",a="No. This quest chain is strictly tailored for Alliance warriors around their thirtieth season, representing a rite of passage in obtaining durable heavy plate armor.",al={"is grimand's armor warrior only","who can do grimand armor"}},{q="Where does this turn-in take place?",a="The quest is turned in directly to Grimand Elmore at his anvil in the Dwarven District of Stormwind City.",al={"where turn in grimand armor","grimand location stormwind"}}},ang={["class:Warrior"]="This quest represents a defining moment in an Alliance warrior's career, rewarding them with an iconic, resilient breastplate forged to withstand the brutal impacts of frontline combat.",["profession:Blacksmithing"]="The exchange showcases the collaboration between Ironforge innovations and Stormwind craftsmanship, utilizing unusual reagents to dramatically temper metal.",["faction:Alliance"]="Grimand Elmore's reliance on Furen Longbeard's designs highlights the tight technical and martial cooperation binding the humans of Stormwind and the dwarves of Ironforge."},kw={"armor","breastplate","burning blood","dwarven district","furen longbeard","grimand elmore","stormwind","warrior quest"},rel={"quest:1700"},m={start="Grimand Elmore",level="30",faction="Alliance",id=1706},src={"Grimand's Armor"}}
E["quest:171"] = {t="quest",n="A Warden of the Alliance",z="stormwind",s="A Warden of the Alliance is the heartfelt conclusion to Children's Week for Alliance adventurers guiding a young orphan through Stormwind. After showing Randis the wonders of the kingdom, the hero buys a rack of toy foam swords so the rest of the orphanage can join the fun before returning the boy to Matron Nightingale.",h="A Warden of the Alliance is the heartfelt conclusion to Children's Week for Alliance adventurers guiding a...",sec={{t="A Farewell Gift",b="Throughout Children's Week, adventurers volunteer to take an orphan out into the world, offering a brief escape from the quiet walls of the Stormwind Orphanage. As his journey comes to an end, the young human orphan Randis realizes how lucky he has been compared to the friends he left behind. Rather than asking for one last treat for himself, his final wish is to bring something back for everyone: a foam sword rack purchased from Craggle Wobbletop, the traveling toy vendor patrolling the Canals outside the Trade District.",sp=0},{t="Joy in the Cathedral Square",b="Returning to the Cathedral District, the adventurer delivers Randis back to Orphan Matron Nightingale along with the toys. The gift transforms the quiet steps of the orphanage into a lively playground as children pour outside to grab foam blades and stage mock battles across the courtyard. Grateful for the kindness shown to Randis, Matron Nightingale honors the adventurer as a true warden of the Alliance and presents a small pet chosen by the boy to remember his week in the wider world.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest marks the finale of Children's Week for Alliance players. You purchase a Foam Sword Rack from the toy vendor Craggle Wobbletop in Stormwind's Canals and return Randis to Orphan Matron Nightingale at the Cathedral District orphanage.",al={"what do you do in a warden of the alliance","warden of the alliance quest goal"}},{q="Who is Randis?",a="Randis is a young human boy residing in the Stormwind Orphanage who accompanies Alliance adventurers during Children's Week. Having lost his parents, he spends the holiday seeing sights across the Alliance before returning home.",al={"who is the human orphan","stormwind orphan name"}},{q="Where can Craggle Wobbletop be found?",a="Craggle Wobbletop is a gnome toy merchant who walks along the paved paths of the Canals bordering the Trade District in Stormwind City, pushing a cart stocked with novelties.",al={"where is craggle wobbletop","find craggle wobbletop","foam sword rack vendor"}},{q="What happens when the quest is turned in?",a="When you deliver the Foam Sword Rack to Orphan Matron Nightingale, the rack is set down and the children rush out from the orphanage, grabbing foam swords and play-fighting across the courtyard.",al={"what happens at turn in","children foam swords event"}},{q="Who is Orphan Matron Nightingale?",a="Orphan Matron Nightingale is the caretaker of the Stormwind Orphanage in the Cathedral District. She oversees the welfare of children left parentless by the Third War and other ongoing conflicts threatening the kingdom.",al={"matron nightingale","who runs the stormwind orphanage"}},{q="Why does Randis ask for foam swords?",a="Randis is grateful for the adventures he experienced and feels sympathy for the children who had to stay behind. He wants all of his fellow orphans to share in the fun of Children's Week with toys of their own.",al={"why foam swords","reason for sword rack"}}},ang={["faction:Alliance"]="The quest embodies the spirit of the Alliance's defenders, reminding champions that protecting the kingdom means looking after its most vulnerable survivors.",["race:Human"]="For humans of Stormwind, caring for the city's war orphans hits close to home after years of fighting the Scourge, gnolls, and the Defias Brotherhood.",["class:Paladin"]="Guiding an orphan and bringing joy to the children outside the Cathedral of Light reflects the holy duty of compassion central to the Silver Hand."},kw={"children's week","craggle wobbletop","foam sword rack","matron nightingale","randis","stormwind orphanage","warden of the alliance"},rel={"npc:orphan-matron-nightingale","npc:randis","subzone:canals-stormwind-city","subzone:trade-district","topic:stormwind-kingdom","topic:alliance"},m={start="Human Orphan",["end"]="Orphan Matron Nightingale",faction="Alliance",id=171},src={"A Warden of the Alliance"}}
E["quest:1782"] = {t="quest",n="Furen's Armor",z="stormwind",s="Furen's Armor marks the culmination of an aspiring warrior's quest to assist the master smith Furen Longbeard in Stormwind. By gathering rare metals and elemental components, the adventurer helps Longbeard forge a resilient suit of fire-hardened mail. In return for their aid, Longbeard rewards the warrior with the finished mail and pledges to share his newfound metallurgical techniques across the Alliance.",h="Furen's Armor marks the culmination of an aspiring warrior's quest to assist the master smith Furen Longbeard...",sec={{t="A Master's Breakthrough",b="Furen Longbeard, an esteemed dwarven armorer stationed in Stormwind, has dedicated his craft to pushing the limits of Alliance defensive metallurgy. By commissioning a stalwart adventurer to track down scarce ores and elemental reagents, Longbeard sought to test advanced techniques in tempering mail against searing heat and crushing impacts. The resulting craftwork proves to be a tremendous success, solidifying Longbeard's standing as one of the Alliance's foremost armor crafters.",sp=0},{t="Sharing the Craft",b="Upon presenting the newly finished fire-hardened mail to the adventurer who gathered the materials, Furen expresses deep gratitude for the partnership. The experiments did more than produce a single durable suit; they expanded his understanding of protective smithing. In the communal spirit of Ironforge and Stormwind artisans, Longbeard resolves to dispatch his notes and discoveries to fellow Alliance smiths, ensuring that his breakthrough strengthens frontline fighters across the faction.",sp=0}},faq={{q="Who is Furen Longbeard?",a="Furen Longbeard is a master dwarven armorer operating within the city of Stormwind. He works extensively with the Alliance's martial orders, particularly warriors seeking specialized, high-grade armor.",al={"who is furen","furen longbeard","stormwind smith furen"}},{q="What kind of armor did Furen create?",a="Through extensive experimentation with rare ores and reagents, Furen forged a suit of Fire Hardened Mail. He designed it to withstand ferocious assaults and extreme heat on the battlefield.",al={"what armor does furen make","fire hardened mail","furen's reward"}},{q="Where does Furen Longbeard send his smithing discoveries?",a="Furen promises to send his technical findings and notes to fellow blacksmiths across the Alliance, spreading the benefits of the newly tested tempering methods to armories and forges throughout the realm.",al={"furen's notes","who gets furen's designs","alliance blacksmiths"}},{q="Why was the warrior asked to gather reagents for Furen?",a="Furen needed rare and volatile components to test untried smithing techniques. Lacking the ability to leave his forge to hunt down elemental agents and exotic minerals, he relied on an ambitious warrior to acquire them.",al={"why gather reagents for furen","fire hardened mail quest materials"}},{q="Where is this armor forged and delivered?",a="The exchange takes place directly at Furen Longbeard's forge in the city of Stormwind, where he completes the final hammering and cooling of the mail suit.",al={"where is furen longbeard","turn in location","furen location"}},{q="Does this work benefit other Alliance fighters?",a="Yes. Furen notes that the lessons learned from working with these materials will be shared with other Alliance armorers, which he hopes will encourage other smiths to craft and provide elite equipment for Alliance soldiers.",al={"alliance benefit","furen's breakthrough"}}},ang={["class:Warrior"]="For Alliance warriors coming of age, earning Furen's custom-tempered armor represents a rite of passage and provides indispensable protection for early frontline campaigns.",["profession:Blacksmithing"]="Furen's successful experiment highlights the collaborative tradition of Alliance smiths, who share specialized metallurgical discoveries to elevate craft standards across Stormwind and Ironforge.",["faction:Alliance"]="Strong armaments are crucial to keeping the Alliance's standing forces alive against persistent threats from the Defias, gnolls, and hostile elemental forces."},kw={"alliance warrior","blacksmithing","fire hardened mail","furen longbeard","furen's armor","mail armor","stormwind"},rel={"npc:furen-longbeard","quest:1701","topic:alliance"},m={start="Furen Longbeard",level="28",faction="Alliance",id=1782},src={"Furen's Armor"}}
E["quest:1860"] = {t="quest",n="Speak with Jennea",z="stormwind",s="Speak with Jennea is an introductory summoning summons directed at novice Alliance mages who have advanced beyond basic training in Elwynn Forest. Dispatched by the trainer Zaldimar Wefhellt in Goldshire, initiates are directed to report directly to Jennea Cannon in the Wizard's Sanctum within Stormwind City.",h="Speak with Jennea is an introductory summoning summons directed at novice Alliance mages who have advanced...",sec={{t="A Call to the Wizard's Sanctum",b="Once an apprentice mage shows sufficient mastery of elementary spells in Goldshire, Zaldimar Wefhellt recognizes that field training under local tutors has run its course. Rather than lingering indefinitely in Elwynn's hamlets, promising spellcasters are directed into Stormwind City itself. At the heart of the Mage Quarter looms the Wizard's Sanctum, a sprawling sanctuary of arcane research and instruction where the realm's senior practitioners coordinate broader magical matters across the kingdom.",sp=0},{t="Matters of Kingdom Security",b="Zaldimar emphasizes that reporting to Stormwind is far more than a routine scholastic promotion; a specific task has arisen that directly impacts the security of Elwynn Forest and Stormwind alike. Upon arrival, the apprentice reports to Jennea Cannon, an established mage who oversees vital local assignments. While Jennea remains measured and cautious about divulging grand secrets to a freshly arrived apprentice, reporting to her marks the start of direct service to the wizarding order.",sp=0}},faq={{q="Who sends me on this quest?",a="Zaldimar Wefhellt, the human mage trainer stationed inside the Lion's Pride Inn at Goldshire, initiates the quest once you reach sufficient arcane proficiency.",al={"quest giver","who gives quest","zaldimar"}},{q="Where can I find Jennea Cannon?",a="Jennea Cannon resides inside the Wizard's Sanctum, located in the center of the Mage Quarter in Stormwind City. She is found studying within the sanctum's mystical halls.",al={"jennea cannon location","where is jennea","find jennea"}},{q="What is the Wizard's Sanctum?",a="The Wizard's Sanctum is the prominent magical spire in Stormwind's Mage Quarter. It serves as the primary academy, library, and operational base for the kingdom's mages and arcane scholars.",al={"what is wizards sanctum","mage tower stormwind"}},{q="Why does Zaldimar send me to Jennea instead of handling it himself?",a="Zaldimar trains young mages in the fundamentals at Goldshire, but larger regional threats and specialized tasks affecting the realm are overseen by higher-ranking scholars like Jennea Cannon from the capital.",al={"why go to stormwind","why jennea"}},{q="What happens after reporting to Jennea Cannon?",a="Once you report to Jennea, she tasks you with investigating mysterious magical anomalies surrounding Mirror Lake back in Elwynn Forest.",al={"what next","follow up quest","next step"},sp=1},{q="Is this quest available to any class?",a="No. This quest is exclusive to mages, serving as a class rite of passage that transitions an apprentice out of local village training and into the formal ranks of Stormwind's arcane society.",al={"can non mages do this","mage only","class requirement"}}},ang={["class:Mage"]="This assignment marks your graduation from rural spellcasting in Goldshire to formal involvement with the high mages operating out of Stormwind's Wizard's Sanctum.",["faction:Alliance"]="The safety of Elwynn Forest and Stormwind relies not just on foot soldiers, but on arcane vigilance monitored directly from the capital's magical academy."},kw={"elwynn forest","goldshire","jennea cannon","mage quarter","speak with jennea","stormwind","wizard's sanctum","zaldimar wefhellt"},rel={"npc:jennea-cannon","npc:zaldimar-wefhellt","quest:1861","zone:elwynn","topic:stormwind-kingdom"},m={start="Zaldimar Wefhellt",["end"]="Jennea Cannon",level="10",faction="Alliance",id=1860},src={"Speak with Jennea"}}
E["quest:1938"] = {t="quest",n="Ur's Treatise on Shadow Magic",z="stormwind",s="Ur's Treatise on Shadow Magic is a quest given by High Sorcerer Andromath in the Mage Quarter of Stormwind. He charges adventurers with recovering a forbidden, magically sealed tome from the renegade mage Morganth, who fled with it to the Tower of Ilgalar in the Redridge Mountains.",h="Ur's Treatise on Shadow Magic is a quest given by High Sorcerer Andromath in the Mage Quarter of Stormwind.",sec={{t="A Schism in the Tower",b="Long ago, three promising mages studied together within the Wizard's Sanctum of Stormwind. Over time, one of them, Morganth, succumbed to the temptations of dark arts and shadow magic. Despite desperate warnings from his peers urging him to turn away from such corrupting power, he refused to abandon his obsession. He was formally banished from the city's magical order, but he did not leave empty-handed—he stole a dangerous work penned by Ur, an infamous archmage whose studies ventured beyond orthodox arcana.",sp=0},{t="The Fallen Mage's Lair",b="Morganth established a new redoubt far from Stormwind's scrutiny, seizing the Tower of Ilgalar in the heights of the Redridge Mountains. High Sorcerer Andromath cannot allow such hazardous knowledge to remain in the hands of an outcast practicing forbidden sorcery. Tasking Alliance adventurers with breaching the tower's defenses, Andromath seeks the recovery of the tome before its wards fall.",sp=0},{t="Intact Wards",b="Upon recovering the treatise from Ilgalar's library and returning it to the Wizard's Sanctum, Andromath is greatly relieved. He feared Morganth had already unraveled its protective enchantments or hidden it beyond reach. Fortunately, the magical seals placed upon Ur's treatise held firm, preventing the rogue sorcerer from unleashing the catastrophic secrets bound within its pages.",sp=1}},faq={{q="Who wrote the treatise?",a="The treatise was penned by Ur, a legendary Dalaran mage renowned for his esoteric research into extra-planar entities and shadow magic.",al={"who is ur","author of the treatise","urs treatise author"}},{q="Who stole Ur's Treatise on Shadow Magic?",a="Morganth, a former mage of Stormwind, stole the book when he fell to dark magic and was banished from the Wizard's Sanctum.",al={"who stole the book","who took the treatise","morganth book"}},{q="Where is the book kept?",a="The book is kept in the library within the Tower of Ilgalar, perched high in the Redridge Mountains where Morganth established his new sanctuary.",al={"where is the treatise","tower of ilgalar book location","where is urs treatise found"}},{q="Did Morganth manage to read the book?",a="No. When the treatise is returned to High Sorcerer Andromath, he confirms that the protective seals placed upon the book held firm, meaning Morganth never managed to open it.",al={"did morganth open the book","was the treatise opened","are the seals broken"},sp=1},{q="Why do the mages of Stormwind want the book back?",a="The tome contains profound secrets of shadow magic that can bring ruin to the untrained. Stormwind's mages consider it far too perilous to leave in the hands of a renegade like Morganth.",al={"why recover the book","why is the treatise dangerous","andromath goal"}},{q="Who gives this quest?",a="The quest is offered by High Sorcerer Andromath, located inside the Wizard's Sanctum in the Mage Quarter of Stormwind.",al={"quest giver","where to get urs treatise quest","andromath quest"}}},ang={["class:Mage"]="Stormwind's mages take internal disciplinary matters seriously, tasking trusted practitioners with cleaning up the dangerous fallout of a peer turned to forbidden shadow magic.",["class:Warlock"]="While the Kirin Tor and Stormwind's mages fear Ur's treatises on the shadows, warlocks frequently covet the very powers of extra-planar summoning and dark casting sealed within.",["faction:Alliance"]="Recovering the stolen tome secures the borders of Redridge from Morganth's growing magical menace while protecting the kingdom of Stormwind from rogue arcana."},kw={"andromath","ilgalar","morganth","shadow magic","stormwind","treatise","ur","wizards sanctum"},rel={"quest:1939","quest:249","subzone:tower-of-ilgalar","quest:115","topic:stormwind-kingdom","topic:alliance"},m={start="High Sorcerer Andromath",level="28",faction="Alliance",id=1938},src={"Ur's Treatise on Shadow Magic (quest)"}}
E["quest:1939"] = {t="quest",n="High Sorcerer Andromath",z="stormwind",s="High Sorcerer Andromath is a short summons directing Alliance mages to report to the summit of the Wizard's Sanctum in Stormwind. High Sorcerer Andromath stands as one of the kingdom's preeminent archmages remaining outside the secluded remnants of Dalaran.",h="High Sorcerer Andromath is a short summons directing Alliance mages to report to the summit of the Wizard's...",sec={{t="Summons to the Tower",b="Within the Mage Quarter of Stormwind, apprentice coordinator Jennea Cannon directs promising casters upward to the peak of the Wizard's Sanctum. High Sorcerer Andromath, one of the most senior practitioners of the arcane operating actively in the southern kingdoms, specifically requests an audience with emerging magi ready for weightier responsibilities.",sp=0},{t="A Master Outside Dalaran",b="With the northern magocracy of Dalaran ruined in the Third War and its surviving wizards sealed away beneath an opaque, shimmering violet dome, practitioners like Andromath hold vital strategic importance. Without easy access to the libraries of the Violet Citadel, the Alliance relies directly on senior archmages stationed within Stormwind to study ancient threats and direct research into shadowy, forbidden arts.",sp=0}},faq={{q="Who is High Sorcerer Andromath?",a="High Sorcerer Andromath is an esteemed senior mage residing at the very top of the Wizard's Sanctum in Stormwind. He is recognized by his peers as one of the most powerful and knowledgeable spellcasters active in the world who is not enclosed within Dalaran.",al={"who is andromath","andromath lore","stormwind high sorcerer"}},{q="Where can I find High Sorcerer Andromath?",a="He can be found at the apex of the Wizard's Sanctum, the spiraling tower located in the Mage Quarter of Stormwind.",al={"andromath location","where is andromath","find high sorcerer andromath"}},{q="Why does Jennea Cannon send me to see him?",a="Jennea Cannon identifies promising casters who have outgrown basic instruction and sends them to Andromath for higher council and specialized, hazardous research tasks.",al={"why speak to andromath","jennea cannon referral"}},{q="What does Andromath need help with?",a="Andromath enlists capable mages to investigate dark arcane secrets, specifically sending them to retrieve a dangerous historical volume: Ur's Treatise on Shadow Magic.",al={"andromath questline","what does andromath want"},sp=1},{q="Why is Dalaran described as 'locked away'?",a="Following its devastation by the Burning Legion during the Third War, the surviving wizards of the Kirin Tor erected an impenetrable protective magical shield over the city while they reconstruct it, cutting themselves off from most outward affairs.",al={"why is dalaran locked away","dalaran status","what happened to dalaran"}},{q="Is this quest exclusive to mages?",a="Yes. This summons is part of the dedicated training and quest path for Alliance mages advancing their craft.",al={"can non mages do this","mage only quest"}}},ang={["class:Mage"]="This summons marks a transition from routine spellcraft exercises under Jennea Cannon to direct research into dangerous, specialized lore alongside one of Stormwind's premier archmages.",["faction:Alliance"]="With northern allies cut off behind Dalaran's protective bubble, the Alliance depends heavily on Stormwind's own Sanctum to train mages and counter supernatural threats."},kw={"andromath","arcane","dalaran","jennea cannon","mage quarter","stormwind","wizard's sanctum"},rel={"npc:jennea-cannon","subzone:dalaran","topic:stormwind-kingdom","topic:alliance"},m={start="Jennea Cannon",["end"]="High Sorcerer Andromath",level="26",faction="Alliance",id=1939},src={"High Sorcerer Andromath (quest)"}}
E["quest:1940"] = {t="quest",n="Pristine Spider Silk",z="stormwind",s="Pristine Spider Silk is an initiation task for rising Alliance mages entrusted by High Sorcerer Andromath in Stormwind. To earn a garment fitting an adept's station, the spellcaster is dispatched into the darkened woods of Duskwood to harvest prime silk from carrion recluses. The gathered spools are delivered to tailor Wynne Larson in the Mage Quarter to prepare enchanted robes.",h="Pristine Spider Silk is an initiation task for rising Alliance mages entrusted by High Sorcerer Andromath in...",sec={{t="Vestments of the Adept",b="Within the Wizard's Sanctum, recognition is measured not only by mastery over the arcane but in the regalia worn by its practitioners. High Sorcerer Andromath recognizes when a student has graduated from mere apprentice work and directs them to commission vestments proper to an adept. Rather than simply purchasing finished goods, the mage must prove both field competence and discernment by gathering pristine, unblemished silk directly from perilous beasts.",sp=0},{t="The Loom of Duskwood",b="The required material cannot be found in conventional merchant stalls. It must be carefully extracted from the venomous carrion recluse spiders stalking the haunted gloom of Duskwood. Once eight prime samples are gathered, they are brought across the city to Larson Clothiers in the Mage Quarter, where tailor Wynne Larson stands ready to spin the delicate threads into a robe of arcane significance.",sp=0}},faq={{q="Who sends mages on this assignment?",a="High Sorcerer Andromath, presiding over the Wizard's Sanctum in Stormwind City, offers this task to spellcasters who have proved their dedication.",al={"who gives pristine spider silk","quest giver pristine spider silk","andromath quest"}},{q="Where is the silk harvested?",a="The silk is gathered from carrion recluse spiders found roaming the haunted forests and webbed clearings of Duskwood.",al={"where do i get pristine silk","spider location","carrion recluse location"}},{q="Who crafts the robe from the silk?",a="Wynne Larson, a professional tailor working out of Larson Clothiers in Stormwind's Mage Quarter, handles the weaving and tailoring.",al={"who weaves the silk","wynne larson","larson clothiers"}},{q="Why do mages use spider silk for garments?",a="Pristine spider silk offers natural resilience and an exceptionally fine weave, creating lightweight fabric capable of holding subtle enchantments without weighing down the spellcaster.",al={"why spider silk","spider silk magic robes"}},{q="What comes after delivering the silk?",a="After Wynne inspects the silk and works at her loom, she asks the mage to obtain additional arcane components to complete the garment.",al={"next quest after pristine spider silk","what happens next"}},{q="Is any spider silk from Duskwood acceptable?",a="No. The delicate enchantments woven by Larson Clothiers require specifically pristine samples extracted carefully from carrion recluses, rejecting coarser webbing.",al={"can i use regular spider silk","pristine vs normal silk"}}},ang={["class:Mage"]="This rite of passage bridges apprenticeship and true adepts, ensuring every Stormwind mage wears robes woven from hazards they personally surmounted.",["profession:Tailoring"]="Wynne Larson's methods show how high-grade wild monster fibers can be turned into magically receptive fabrics far superior to common sheep's wool or linen.",["faction:Alliance"]="Duskwood remains a dangerous frontier for Stormwind subjects, requiring mages to step out of the sanctuary of the capital to retrieve rare regional resources."},kw={"andromath","carrion recluse","duskwood","larson clothiers","mage robes","pristine spider silk","wizard's sanctum","wynne larson"},rel={"npc:wynne-larson","quest:1942","zone:duskwood","topic:stormwind-kingdom","topic:alliance"},m={start="High Sorcerer Andromath",["end"]="Wynne Larson",level="26",faction="Alliance",id=1940},src={"Pristine Spider Silk (quest)"}}
E["quest:1941"] = {t="quest",n="Manaweave Robe",z="stormwind",s="Manaweave Robe marks the conclusion of a tailor's ambitious crafting commission in the heart of Stormwind. Wynne Larson presents a finished enchanted vestment woven from fine materials, standing as a proud showcase for her family's shop. For emerging spellcasters, it represents an early badge of arcane dedication and quality human craftsmanship.",h="Manaweave Robe marks the conclusion of a tailor's ambitious crafting commission in the heart of Stormwind.",sec={{t="Larson Clothiers",b="In the bustling Mage Quarter of Stormwind, Larson Clothiers caters to practitioners of the arcane arts who require garments suited to channeling volatile energies. Crafting fine magical vestments demands rare materials, meticulous needlework, and a keen eye for threadwork that will not unravel under mystic resonance. Wynne Larson takes personal pride in the garments leaving her shop, viewing every robe worn into the field as a walking testament to the Larson name.",sp=0},{t="Woven Sorcery",b="The manaweave robe is designed to assist apprentice mages, providing comfort, mobility, and the practical resilience required when roaming contested lands. Upon the delivery of the necessary components, Wynne weaves the final stitch herself, presenting the finished garment not merely as a transaction, but as a masterpiece intended to turn heads and advertise the quality of Larson tailoring across the kingdom.",sp=0}},faq={{q="Who crafts the Manaweave Robe?",a="Wynne Larson crafts the garment at Larson Clothiers, situated in Stormwind City's Mage Quarter.",al={"who makes manaweave robe","wynne larson robe","larson clothiers"}},{q="Why does Wynne Larson want you to wear the robe with pride?",a="Wynne considers the robe one of her finest creations yet. She asks adventurers to spread the word about Larson Clothiers whenever others admire the craftsmanship, treating it as living promotion for her shop.",al={"why tell people larson","larson advertising","wynne dialogue"}},{q="Where is Larson Clothiers located?",a="The shop is located in the Mage Quarter of Stormwind City, close to the academies and sanctums where Alliance spellcasters congregate.",al={"larson shop location","where is wynne larson","mage quarter tailoring shop"}},{q="What kind of garment is a Manaweave Robe?",a="It is an enchanted cloth robe designed for practitioners of magic, tailored to channel mystic energies while offering practical wear during dangerous journeys.",al={"manaweave robe lore","what is manaweave robe","what does the robe do"}},{q="Is this part of a longer questline?",a="Yes, completing this commission serves as the final step of a tailoring quest chain assisting Wynne Larson with materials for her work.",al={"manaweave chain","robe quest chain","questline end"}},{q="What faction can undertake this quest?",a="This quest is strictly for members of the Alliance, as Wynne Larson operates entirely within the capital city of Stormwind.",al={"alliance or horde robe","can horde get manaweave robe","faction requirement"}}},ang={["class:Mage"]="For an apprentice mage studying in the towers of Stormwind, donning a tailored manaweave robe signals graduation into serious field research and independent spellcraft.",["profession:Tailoring"]="Wynne Larson's work illustrates the high standard of human tailoring, demonstrating how worldly materials can be woven to harness and temper volatile arcane power.",["faction:Alliance"]="Outfitting promising champions from local shops in the capital helps project Stormwind's prestige and self-sufficiency across troubled territories."},kw={"apprentice robe","clothier","larson clothiers","mage quarter","manaweave robe","stormwind","tailor","wynne larson"},rel={"npc:wynne-larson","npc:lars"},m={start="Wynne Larson",["end"]="Wynne Larson",level="15",faction="Alliance",id=1941},src={"Manaweave Robe (quest)"}}
E["quest:1942"] = {t="quest",n="Astral Knot Garment",z="stormwind",s="Astral Knot Garment is the culmination of a dedicated crafting endeavor in Stormwind City. After braving the wilds to gather rare spider silk, an adventurer presents the materials to the skilled tailor Wynne Larson. The result is a fine, magical weave suited for both treacherous journeys and high-society gatherings.",h="Astral Knot Garment is the culmination of a dedicated crafting endeavor in Stormwind City.",sec={{t="A Weaver's Wit",b="In the bustling Mage Quarter of Stormwind, tailors and seamstresses cater to the arcane elite and visiting nobility alike. Wynne Larson is one such artisan, renowned for her ability to weave pristine spider silk into durable, enchanted vestments. Known for a playful sense of humor, she jokes about keeping extra scraps of precious silk for her own wardrobe before delivering her expertly tailored creations.",sp=0},{t="Versatile Elegance",b="The Astral Knot Garment is prized by cloth-wearing spellcasters who demand both resilience and refinement. Woven from delicate yet hardy silk gathered from dangerous arachnids, the garment is designed to withstand the rigors of combat while maintaining the polished appearance expected at formal banquets within Stormwind Keep.",sp=0}},faq={{q="What is the Astral Knot Garment?",a="It is a finely tailored garment crafted by Wynne Larson in Stormwind City. Built from pristine spider silk, it is specifically made to serve cloth-wearing practitioners in both adventurous combat and formal high-society affairs.",al={"what is astral knot garment","astral knot robe","astral knot vestments"}},{q="Who crafts the Astral Knot Garment?",a="Wynne Larson, a resident tailor working in Stormwind's Mage Quarter, crafts the piece once provided with the necessary exotic materials.",al={"who makes astral knot","wynne larson quest","astral knot tailor"}},{q="What materials are required to complete this garment?",a="The garment requires pristine spider silk harvested from deadly spiders across the wild regions of the world, woven together with tailoring techniques that preserve the silk's natural strength and enchantability.",al={"materials for astral knot","spider silk needed","how is it made"}},{q="Why does Wynne Larson tease about keeping leftover silk?",a="Pristine spider silk is exceptionally rare and prized among tailors. Wynne jokes about tailoring the garment short so she could hoard a few scraps for herself, though she delivers the completed work in full.",al={"did she steal my silk","wynne larson joke","short robe"}},{q="Where in Stormwind does this tailoring take place?",a="Wynne Larson is located in the Mage Quarter of Stormwind, a district home to scholars, arcanists, and specialized clothiers who understand enchanted textiles.",al={"where is wynne larson","astral knot location","where to turn in astral knot"}},{q="Who typically wears the Astral Knot Garment?",a="Alliance spellcasters, especially mages, priests, and warlocks, favor the garment for its light, protective weave and dignified appearance.",al={"who uses astral knot","what class is this for","who wears it"}}},ang={["class:Mage"]="The Astral Knot Garment blends the arcane dignity of Stormwind's Mage Quarter with practical enchantments needed when traveling beyond the kingdom's fortified walls.",["profession:Tailoring"]="Wynne Larson's work represents the pinnacle of working with pristine spider silk, showing how raw monstrous materials can be refined into grand fashion.",["faction:Alliance"]="Stormwind's artisans pride themselves on providing Alliance champions with equipment suitable for royal halls and dangerous frontlines alike."},kw={"astral knot garment","cloth armor","mage quarter","pristine spider silk","silk robe","stormwind","tailoring","wynne larson"},rel={"npc:wynne-larson","quest:1940","topic:alliance"},m={start="Wynne Larson",level="26",faction="Alliance",id=1942},src={"Astral Knot Garment"}}
E["quest:2205"] = {t="quest",n="Seek out SI: 7",z="stormwind",s="Seek out SI: 7 is an introductory task handed to fledgling rogues in Elwynn Forest by Keryn Sylvius. Carrying a small package from Goldshire to Stormwind City, novice agents are introduced to Master Mathias Shaw, the leader of the crown's covert intelligence network.",h="Seek out SI: 7 is an introductory task handed to fledgling rogues in Elwynn Forest by Keryn Sylvius.",sec={{t="A Courier's Test",b="In the Lion's Pride Inn at Goldshire, rogue trainer Keryn Sylvius wastes little time flattering newcomers. Believing fresh initiates look more like cheese delivery hands than capable covert operatives, Sylvius nonetheless passes along an errand: carry a sealed delivery into the capital. The task acts as both a reliable courier run and a quiet vetting process for scouts entering the broader service of the realm.",sp=0},{t="Behind Closed Doors in Old Town",b="The destination lies deep within Old Town, the bustling and worn quarter of Stormwind City. Tucked into the southeastern corner of the district stands the command center of SI:7—Stormwind Intelligence, Section 7. Here, Master Mathias Shaw oversees the kingdom's covert operations. Receiving the package with his characteristic dry skepticism, Shaw evaluates whether the traveler possesses the grit needed for real espionage.",sp=0}},faq={{q="What is SI:7?",a="SI:7 stands for Stormwind Intelligence, Section 7. It is the clandestine intelligence and covert operations branch of the Kingdom of Stormwind, led by Master Mathias Shaw from their headquarters in Old Town.",al={"what does si 7 mean","what is si7","si:7 lore"}},{q="Who is Keryn Sylvius?",a="Keryn Sylvius is a rogue trainer stationed in Goldshire at the Lion's Pride Inn. Operating in liaison with SI:7, she evaluates local recruits and directs promising scouts toward Master Mathias Shaw in Stormwind City.",al={"keryn sylvius","goldshire rogue trainer"}},{q="Where is Mathias Shaw located in Stormwind?",a="Master Mathias Shaw can be found on the upper floor of the SI:7 headquarters, located in the southeastern corner of Old Town in Stormwind City, past the city's rogue trainers.",al={"where is shaw","find mathias shaw","mathias shaw location"}},{q="What happens after delivering the package to Shaw?",a="Once you report to Mathias Shaw, he immediately tests your practical rogue skills by sending you on a covert operation to Jerod's Landing to lift a shipping schedule from a Defias dockmaster.",al={"next quest after seek out si 7","what does shaw want"},sp=1},{q="Why does Keryn mock the player before handing over the delivery?",a="SI:7 operatives pride themselves on high competence and sharp instincts. Sylvius treats green recruits harshly to gauge their temperament and ensure only those with thick skin and real resolve bother Master Shaw.",al={"why does keryn insult me","cheese delivery insult"}}},ang={["class:Rogue"]="This mission marks a rogue's formal entry into the service of Stormwind's premier espionage agency, transitioning from petty back-alley tricks to royal reconnaissance.",["faction:Alliance"]="SI:7 serves as the crown's eyes and ears against internal and external threats, quietly protecting the realm while King Varian Wrynn remains missing."},kw={"goldshire","keryn sylvius","mathias shaw","old town","rogue","seek out si: 7","si:7","stormwind"},rel={"quest:2206","npc:mathias-shaw","npc:keryn-sylvius","subzone:old-town","zone:stormwind","subzone:goldshire","quest:2300"},m={start="Keryn Sylvius",["end"]="Mathias Shaw",level="10",faction="Alliance",id=2205},src={"Seek out SI: 7"}}
E["quest:2206"] = {t="quest",n="Snatch and Grab",z="stormwind",s="Snatch and Grab is an undercover assignment given to promising rogues by Master Mathias Shaw, leader of SI:7. It tasks operatives with infiltrating Jerod's Landing to steal shipping intelligence from the Defias Brotherhood.",h="Snatch and Grab is an undercover assignment given to promising rogues by Master Mathias Shaw, leader of SI:7.",sec={{t="A Test of Tradecraft",b="For an aspiring operative in Stormwind, standing before Master Mathias Shaw is the true test of entry into the kingdom's covert intelligence wing. Rather than relying on simple brute force, Shaw demands proof of finesse and stealth. Taking down key figures quietly and retrieving vital papers without drawing the realm into open scandal is the core mandate of SI:7, and this mission serves as an initiate's proving ground.",sp=0},{t="Smugglers on the River",b="Jerod's Landing sits on the river in southern Elwynn, south of Goldshire and just east of the Maclure Vineyards. Though once a quiet local dock, the Defias Brotherhood seized control of the site to establish an illicit transit corridor. By ferrying smuggled arms, supplies, and contraband across the waters from Redridge down toward Westfall, the thieves bypass royal road patrols entirely.",sp=0},{t="Plausible Deniability",b="Shaw makes SI:7's standing doctrine abundantly clear before dispatching agents into the field: should the operative be captured, compromised, or slain, the Crown and its spymasters will disavow all knowledge of their existence. Recovering the Defias Dockmaster's schedule secures crucial proof of the Brotherhood's supply lines while keeping Stormwind's official involvement in the shadows.",sp=0}},faq={{q="Who assigns the quest Snatch and Grab?",a="Master Mathias Shaw, leader of Stormwind's intelligence service SI:7, gives the quest from inside the SI:7 headquarters located in the Command Center of Old Town.",al={"who gives snatch and grab","quest giver snatch grab"}},{q="Where is Jerod's Landing?",a="Jerod's Landing is a dock on the river in southern Elwynn Forest, south of Goldshire and just east of the Maclure Vineyards. The Defias Brotherhood has commandeered the docks and the dock house there.",al={"jerods landing location","where is jerod's landing","dockmaster location"}},{q="What are the Defias smuggling through Jerod's Landing?",a="The Defias use Jerod's Landing to move large shipments of contraband and supplies across the water between Redridge and Westfall, circumventing kingdom watchposts and road checkpoints.",al={"what are they smuggling","defias contraband"}},{q="Who carries the Defias Shipping Schedule?",a="The shipping schedule is carried by the Defias Dockmaster, who can be found guarding the dock house at Jerod's Landing.",al={"where is shipping schedule","who drops schedule","defias dockmaster"}},{q="What happens if an operative is captured during this mission?",a="As Master Mathias Shaw warns, SI:7 operates with strict plausible deniability. If an operative is exposed or captured, SI:7 will disavow all connection to them.",al={"what happens if i fail","disavowed by si7"}},{q="Why does SI:7 care about this shipping schedule?",a="The document details how the Defias Brotherhood moves contraband between Redridge and Westfall. Securing it allows Stormwind's intelligence network to map out enemy logistics without alerting the syndicate.",al={"why need schedule","si7 shipping schedule"}}},ang={["class:Rogue"]="This mission marks a rogue's formal introduction to SI:7, testing stealth and cutpurse instincts to earn recognition and a signature blade from Mathias Shaw.",["faction:Alliance"]="Intercepting Defias supply chains at Jerod's Landing protects Elwynn Forest and chips away at the criminal syndicate threatening Stormwind's surrounding territories."},kw={"crystal lake","defias","dockmaster","goldshire","jerod's landing","mathias shaw","shipping schedule","si:7","snatch and grab"},rel={"quest:2205","npc:mathias-shaw","subzone:jerod-s-landing","subzone:goldshire","zone:westfall","quest:2300"},m={start="Master Mathias Shaw",level="10",faction="Alliance",id=2206},src={"Snatch and Grab"}}
E["quest:2281"] = {t="quest",n="Redridge Rendezvous",z="stormwind",s="Redridge Rendezvous is an Alliance rogue assignment dispatched from Stormwind's intelligence headquarters. Recognizing that raw recruits lack the finesse needed for dangerous field operations, SI:7 routes promising agents to Lakeshire to refine their tradecraft under seasoned operatives.",h="Redridge Rendezvous is an Alliance rogue assignment dispatched from Stormwind's intelligence headquarters.",sec={{t="A Measure of Survival",b="Within the clandestine halls of SI:7 in Stormwind, second-in-command Renzik 'The Shiv' is blunt about the life expectancy of novices. Pushing unrefined operatives directly into hostile operations breeds casualties rather than intelligence. To prevent needless loss, recruits showing potential are dispatched eastward into the Redridge Mountains to train under Lucius, an operative stationed among the lakeside docks.",sp=0},{t="Eyes in Lakeshire",b="Lakeshire serves as an ideal staging ground for clandestine training. Hemmed in by gnolls and Blackrock orcs, the frontier town provides plenty of real-world peril, while the bustling piers give an operative like Lucius ample cover to evaluate a rogue's stealth, reflexes, and lockpicking capabilities without drawing the attention of local townspeople or town guards.",sp=0}},faq={{q="Who gives the quest Redridge Rendezvous?",a="Renzik 'The Shiv', the goblin spymaster operating within the SI:7 headquarters in Stormwind's Old Town, issues the assignment to rogues who have reported to intelligence command.",al={"who starts redridge rendezvous","redridge rendezvous questgiver","who gives quest"}},{q="Where is Lucius located?",a="Lucius is positioned along the wooden docks of Lakeshire in the Redridge Mountains, blending in with the local loafers and fishermen by the water.",al={"where is lucius","lucius location","find lucius"}},{q="Why does SI:7 send rogues to Redridge?",a="Renzik considers green rogues unfit for high-stakes intelligence field assignments. Lucius is tasked with honing their rough edges, testing their practical skills such as pickpocketing and lockpicking under frontier conditions.",al={"why lakeshire","purpose of redridge rendezvous","why redridge"}},{q="What comes after completing Redridge Rendezvous?",a="Reporting to Lucius leads directly into training exercises starting with Alther's Mill, where the agent is instructed to put their stealth and manual dexterity to the test.",al={"next quest","redridge rendezvous followup","after redridge rendezvous"}},{q="Is this quest available to classes other than rogues?",a="No. Redridge Rendezvous is exclusively an Alliance rogue class quest tailored to SI:7 field training.",al={"can warriors do redridge rendezvous","is this rogue only","class requirement"}},{q="Why does Renzik work for Stormwind intelligence?",a="Despite being a goblin, Renzik 'The Shiv' is a highly trusted lieutenant of Spymaster Mathias Shaw, running operative intake and training from deep inside the SI:7 stronghold.",al={"why is a goblin in si7","renzik lore","goblin in stormwind"}}},ang={["class:Rogue"]="This mission marks a rogue's entry into formal SI:7 field work, shifting their training from backstreet thievery to calculated state espionage.",["faction:Alliance"]="The assignment reveals the reach of Stormwind's clandestine arm, which maintains quiet operatives stationed across outer settlements like Lakeshire."},kw={"lakeshire","lucius","redridge rendezvous","renzik the shiv","rogue quest","si:7","stormwind"},rel={"npc:lucius","npc:renzik-the-shiv","quest:2300","quest:2282","subzone:lakeshire","zone:redridge"},m={start="Renzik \"The Shiv\"",["end"]="Lucius",level="16",faction="Alliance",id=2281},src={"Redridge Rendezvous"}}
E["quest:2300"] = {t="quest",n="SI:7",z="stormwind",s="This directive summons promising young rogues from Elwynn Forest directly into the heart of Stormwind's covert intelligence network. Directed by Keryn Sylvius in Goldshire, agents are ordered to report immediately to Renzik \"The Shiv\" in Old Town. Answering this summons brings an operative directly into service under Master Mathias Shaw.",h="This directive summons promising young rogues from Elwynn Forest directly into the heart of Stormwind's...",sec={{t="A Summons to Old Town",b="Operating out of the Lion's Pride Inn in Goldshire, rogue trainer Keryn Sylvius keeps tabs on local recruits. When a rogue shows enough cunning and competence against the gathering Defias threat, Sylvius passes along word from headquarters. The summons is brief and unceremonious: report to Renzik \"The Shiv\" without delay. Leaving the fields of Elwynn behind, the agent is directed straight into the covert heart of the capital.",sp=0},{t="Stormwind's Hidden Eyes",b="Tucked away behind the facade of an unassuming barracks in Old Town sits the headquarters of SI:7, Stormwind's premier intelligence agency. Commanded by Master Mathias Shaw, SI:7 manages covert operations, reconnaissance, and assassination throughout the kingdom and beyond. Renzik \"The Shiv,\" Shaw's sharp-tongued second-in-command, personally vets promising field agents before dispatching them into high-stakes operations that the kingdom's formal military cannot touch.",sp=0}},faq={{q="Who sends me to report to SI:7?",a="Keryn Sylvius, the rogue trainer at the Lion's Pride Inn in Goldshire, gives you the directive. Once you prove your competence in the field, Sylvius passes down orders instructing you to report to headquarters in Stormwind.",al={"who gives quest","quest giver","keryn sylvius"}},{q="Who is Renzik \"The Shiv\"?",a="Renzik \"The Shiv\" is a goblin operative who serves as the second-in-command of SI:7, working directly under Master Mathias Shaw. He evaluates field agents and coordinates covert intelligence assignments from SI:7's headquarters in Old Town.",al={"renzik the shiv","who is renzik","renzik"}},{q="What is SI:7?",a="SI:7—short for Stormwind Intelligence, Section 7—is the covert espionage, reconnaissance, and assassination branch of the Kingdom of Stormwind. Led by Mathias Shaw, its operatives gather intelligence on threats to the crown that conventional guards and soldiers cannot address.",al={"what is si7","what does si7 do","stormwind intelligence"}},{q="Where is the SI:7 headquarters located?",a="The SI:7 headquarters is located in the eastern portion of Old Town in Stormwind City. It operates out of a fortified guildhall and training barracks tucked away from the main streets.",al={"where is si7","si7 location","where is renzik"}},{q="What happens after reporting to Renzik?",a="Once you report to Renzik, he tests your readiness before assigning you a field mission beyond the city walls, dispatching you to meet an operative stationed in Redridge.",al={"next quest","what comes after","redridge rendezvous"},sp=1},{q="Why does Keryn Sylvius call me 'fish'?",a="It is slang for an untested novice or new recruit. Operatives within the agency use colorful, abrasive nicknames to keep rookies grounded until they have proven themselves on real assignments.",al={"why called fish","fish meaning"}}},ang={["class:Rogue"]="This summons marks your transition from a scoundrel working local jobs into a recognized operative for Stormwind's official intelligence branch.",["faction:Alliance"]="SI:7 serves as the covert shield of the Alliance, handling dangerous espionage operations that regular marshals and infantry cannot publicly undertake."},kw={"keryn sylvius","mathias shaw","old town","renzik the shiv","rogue","sentinel hill","si:7","stormwind"},rel={"npc:renzik-the-shiv","npc:keryn-sylvius","quest:2281","quest:2282","topic:stormwind-kingdom"},m={start="Keryn Sylvius",["end"]="Renzik \"The Shiv\"",level="16",faction="Alliance",id=2300},src={"SI:7 (quest)"}}
E["quest:2359"] = {t="quest",n="Klaven's Tower",z="stormwind",s="Klaven's Tower is a covert SI:7 infiltration mission assigned to Alliance rogues in Westfall. Operating on intelligence from Agent Kearnen, agents must pickpocket a key, break into a heavily guarded Defias outpost, and retrieve sinister documents linked to unnatural experiments.",h="Klaven's Tower is a covert SI:7 infiltration mission assigned to Alliance rogues in Westfall.",sec={{t="A Stakeout in Westfall",b="Perched on the bluffs overlooking the ocean in northern Westfall stands a lonely stone spire claimed by the Defias Brotherhood. While the Brotherhood's human thieves and brigands are common across the plains, Agent Kearnen noticed strange developments after weeks of solitary surveillance. A bizarre shipment recently arrived directly from the shadowed woods of Duskwood, escorted by monstrous, deformed sentries unlike any ordinary highwaymen.",sp=0},{t="The Spire and the Spiked Guard",b="The tower is commanded by Klaven Mortwake and guarded by bizarrely altered sentries whose breathing is harsh and labored. Among these shambling guards is a hulking zombie driven with iron spikes, who carries the Defias Tower Key. Stealing the key requires silence and finesse, enabling an operative to bypass the ground defenses, slip into the upper levels of the stronghold, and crack open the padlocked Duskwood Chest.",sp=1},{t="Zanzil's Concoction",b="Recovered from the chest, Klaven Mortwake's personal journal details a grim partnership linking the Defias, the Venture Company, and the jungle trolls of Stranglethorn. The writings reveal that the witch doctor Zanzil discovered an alchemical poison potent enough to raise unthinking, obedient undead drones. For Master Mathias Shaw and SI:7, this discovery exposes the Defias's expanding ambitions and cements the vital necessity of counter-poisons in the kingdom's covert arsenal.",sp=2}},faq={{q="Where is Klaven's Tower located?",a="Klaven's Tower is situated along the northwestern cliffs of Westfall, overlooking the sea. It serves as a secure, fortified redoubt for the Defias Brotherhood.",al={"klavens tower location","where is klavens tower","defias tower location westfall"}},{q="Who is Agent Kearnen?",a="Agent Kearnen is an operative for Stormwind's intelligence service, SI:7. She has spent weeks secretly watching Klaven's Tower from a nearby camp, tracking strange shipments and plotting an infiltration.",al={"agent kearnen","who gives klaven's tower quest","who is the rogue in westfall"}},{q="What makes the guards at Klaven's Tower unusual?",a="Unlike the standard human bandits of the Defias, the sentries guarding the tower are mutated undead drones. They are mindless laborers created through an exotic alchemical concoction shipped into Westfall.",al={"why are guards zombies","klaven tower guards","what are the tower guards"},sp=1},{q="How does the Defias have undead servants?",a="The Defias procured a specialized toxic brew concocted by the jungle troll witch doctor Zanzil in Stranglethorn Vale. Through deals involving the Venture Company, this poison was imported to turn living subjects into obedient drones.",al={"how did defias get zombies","why defias have undead","zanzil defias connection"},sp=1},{q="Who is Klaven Mortwake?",a="Klaven Mortwake is a high-ranking Defias overseer stationed at the tower. He oversaw the receipt of dark shipments from Duskwood and kept a private journal detailing their sinister alchemy.",al={"klaven mortwake lore","who is klaven mortwake","klaven"}},{q="Why does Mathias Shaw care about the recovered journal?",a="Master Mathias Shaw requires actionable intelligence on Defias alliances and dangerous foreign agents. Learning that Zanzil's trolls can manufacture undeath via poison alerts SI:7 to a grave new threat facing Stormwind, compelling the agency to train its operatives thoroughly in venomcraft.",al={"why mathias shaw wants journal","si7 zanzil poison","mathias shaw klaven"},sp=1}},ang={["class:Rogue"]="This covert infiltration is a defining rite of passage for Alliance rogues, demanding mastery of stealth, pickpocketing, lockpicking, and exploitation of enemy physical vulnerabilities.",["faction:Alliance"]="Uncovering the Defias plot at the tower reveals that the rebels are not mere aggrieved masons, but dangerous conspirators willing to traffic with jungle trolls and dark alchemy to threaten the kingdom.",["race:Human"]="Human defenders of Stormwind are horrified to see their former countrymen twisted into mindless undead drones along the peaceful bluffs of Westfall."},kw={"agent kearnen","defias brotherhood","duskwood chest","klaven mortwake","klaven's tower","mathias shaw","poisons","si:7","westfall","zanzil"},rel={"npc:mathias-shaw","quest:2300","topic:stormwind-kingdom","zone:duskwood","topic:troll","topic:venture-company"},m={start="Agent Kearnen",["end"]="Master Mathias Shaw",level="24",faction="Alliance",id=2359},src={"Klaven's Tower (quest)"}}
E["quest:269"] = {t="quest",n="Seeking Wisdom",z="stormwind",s="Seeking Wisdom is an Alliance errand carrying Jitters' Completed Journal from the embattled camps of Duskwood into the safety of Stormwind City. Sven Yorgen sends adventurers to consult Bishop Farthing at the Cathedral of Light, hoping holy counsel will reveal how to destroy the shielded necromancer Morbent Fel.",h="Seeking Wisdom is an Alliance errand carrying Jitters' Completed Journal from the embattled camps of Duskwood...",sec={{t="A Plea from the Shadows",b="Duskwood suffers under lingering curses, ravenous undead, and the growing indifference of Stormwind's royal court. Sven Yorgen, a broken-hearted survivor camping near the borders, knows ordinary strength cannot pierce the dark wards of the necromancer Morbent Fel. Armed with the assembled diary of the vagrant Jitters, Sven urges traveling heroes to petition the church rather than the crown, sending them north along the road to the Cathedral of Light.",sp=0},{t="Counsel in the Cathedral",b="In the grand halls of Stormwind's Cathedral, Bishop Farthing represents one of the few authorities still willing to listen to Duskwood's cries for aid. Reviewing Jitters' harrowing account, the bishop confirms the dread power of Morbent Fel. The necromancer shields himself with vile sorcery that deflects standard blows, meaning unguided courage alone will only lead to slaughter. To vanquish the fiend, an enchanted holy instrument must be recovered.",sp=1}},faq={{q="Why does Sven send you to Bishop Farthing instead of King Anduin?",a="Stormwind's nobility and army have largely abandoned Darkshire and the surrounding lands to fend for themselves amid political paralysis. Sven knows official channels will produce no soldiers, but he trusts Bishop Farthing as a compassionate, learned man of the Holy Light who understands foul magics.",al={"why farthing","why not stormwind nobles","stormwind ignored duskwood"}},{q="What is Jitters' journal and why does the Bishop need it?",a="Jitters recorded his unwitting role in unleashing dark forces across Duskwood, including the Scythe of Elune and the rise of local horrors. His journal provides vital intelligence on the necromancer Morbent Fel and the exact nature of the sorceries haunting the region.",al={"what is jitters journal","why jitters journal","jitters completed journal"}},{q="Who is Morbent Fel?",a="Morbent Fel is a powerful necromancer haunting the graves of Raven Hill in western Duskwood. He commands hordes of skeletal minions and shields his physical form with potent warding enchantments, making him impervious to normal weapons.",al={"who is morbent fel","morbent fel lore"}},{q="Where is Bishop Farthing located?",a="Bishop Farthing resides inside the Cathedral of Light, the grand human cathedral dominating the Cathedral Square district within Stormwind City.",al={"where is farthing","farthing location","bishop farthing map"}},{q="What happens after Bishop Farthing reads the journal?",a="Bishop Farthing explains that Morbent Fel cannot be harmed by conventional strikes. He points adventurers toward uncovering a sanctified relic capable of dispelling the necromancer's magical wards, leading into the search for the Doomed Fleet.",al={"what next seeking wisdom","seeking wisdom followup","after seeking wisdom"},sp=1},{q="Where does Sven Yorgen stay in Duskwood?",a="Sven Yorgen shelters in a small camp in northwestern Duskwood, tucked near the river border south of Elwynn Forest and east of the haunted Raven Hill Cemetery.",al={"where is sven","sven yorgen location","sven's camp"}}},ang={["class:Paladin"]="Carrying pleas for holy intervention from the abandoned borderlands to the heart of the Cathedral of Light directly tests the Silver Hand's duty to protect the forgotten and purge necromancy.",["class:Priest"]="Bishop Farthing offers clerical guidance on how dark wards corrupt the soul and body, showing that shadow sorcery cannot simply be fought with blade, but with focused sanctification.",["faction:Alliance"]="The journey underscores the bitter political divide between the guarded marble halls of Stormwind City and the forsaken towns of Duskwood that receive no garrison support."},kw={"bishop farthing","cathedral of light","darkshire","duskwood","jitters","morbent fel","seeking wisdom","stormwind","sven yorgen"},rel={"npc:farthing","npc:sven-yorgen","npc:jitters","quest:55","quest:270","subzone:cathedral-of-light","zone:duskwood","topic:stormwind-kingdom"},m={start="Sven Yorgen",["end"]="Bishop Farthing",level="29",faction="Alliance",id=269},src={"Seeking Wisdom"}}
E["quest:2745"] = {t="quest",n="Infiltrating the Castle",z="stormwind",s="Master cheese monger and intelligence broker Elling Trias directs you into the royal seat of Stormwind Keep. Your objective is to rendezvous with his fellow operative Tyrion, who has spent weeks watching the corrupt nobleman Lord Gregor Lescovar from the keep's gardens.",h="Master cheese monger and intelligence broker Elling Trias directs you into the royal seat of Stormwind Keep.",sec={{t="A Matter Outside the Law",b="When you bring your findings to Elling Trias in his Old Town cheese shop, he quickly grasps the gravity of the Defias threat nestled deep inside the kingdom's governance. Legal channels will not suffice to expose or punish someone as deeply entrenched and protected as Lord Gregor Lescovar. Trias offers a dangerous route forward: delivering extrajudicial justice within the very walls of Stormwind Keep to permanently sever the conspiracy.",sp=0},{t="Eyes in the Shrubbery",b="Trias does not work alone in the high halls. For weeks, an operative named Tyrion—a clever gnome adept at concealment—has staked out the keep's courtyards and manicured royal gardens. Tyrion has watched Lescovar's movements, noting who enters his chambers and when the traitor confers with his covert Defias contacts. Reaching Tyrion without arousing the suspicion of the Royal Guard is the vital next link in the chain.",sp=0},{t="Treason in the Court",b="The presence of a high nobleman like Lescovar colluding directly with Defias assassins like Marzon the Silent Blade underscores how rotten Stormwind's political core has become in the absence of King Varian Wrynn. With court nobles manipulating affairs from within and outlaws pressing the borders from Westfall and the Redridge Mountains, striking at Lescovar represents an attempt to cut out a festering cancer before the kingdom crumbles completely.",sp=1}},faq={{q="Why does Elling Trias want this handled outside the law?",a="Lord Lescovar holds immense influence and wealth within the House of Nobles. Pursuing ordinary legal accusations against a high-ranking lord without indisputable, politically disastrous proof would likely see the evidence suppressed and the whistleblowers executed. Trias recognizes that direct, clandestine action is the only reliable way to neutralize the threat.",al={"why outside law","trias illegal justice","why vigilante"}},{q="Where is Tyrion hiding?",a="Tyrion conceals himself in the royal gardens of Stormwind Keep, just off the courtyard to the left after walking through the main gates. He lurks in the bushes to observe Lord Lescovar's quarters without alerting the guards.",al={"where is tyrion","find tyrion","tyrion location"}},{q="Who is Tyrion?",a="Tyrion is a covert operative and a trusted associate of Elling Trias. He has spent several weeks staking out Stormwind Keep to monitor Lord Gregor Lescovar and map out his clandestine Defias connections.",al={"who is tyrion","tyrion gnome","trias friend"}},{q="Who is Lord Lescovar?",a="Lord Gregor Lescovar is a prominent Stormwind nobleman secretly collaborating with the Defias Brotherhood, acting as their highly placed insider to sabotage the kingdom from within its royal court.",al={"lord lescovar","who is lescovar","lescovar defias"}},{q="Who is Marzon?",a="Marzon, known as the Silent Blade, is an elite Defias assassin who liaises directly with Lord Lescovar to coordinate attacks and assassinations on behalf of the Brotherhood.",al={"marzon","marzon the silent blade","silent blade"},sp=1},{q="Why is Tyrion worried about his reputation?",a="Beyond blowing his cover while conducting clandestine surveillance, Tyrion snarkily complains about how suspicious and unseemly it appears to have heavily armed adventurers loitering alongside him in the royal shrubbery under the noses of the castle guards.",al={"tyrion hiding bushes","reputation in bushes"}}},ang={["class:Rogue"]="Infiltrating the seat of human nobility to aid two seasoned underground operatives highlights the quiet, lethal tradecraft required to protect Stormwind from shadows inside its own court.",["race:Gnome"]="Seeing Tyrion run an intensive, long-term covert surveillance operation inside Stormwind Keep proves that gnomish ingenuity extends well beyond machinery into high-stakes espionage.",["faction:Alliance"]="With King Varian missing, the kingdom cannot afford betrayal in its highest legislative chamber; routing out conspirators in the Keep is critical to keeping the realm stable."},kw={"cheese shop","defias","elling trias","infiltrating the castle","lescovar","stormwind keep","tyrion"},rel={"npc:elling-trias","npc:tyrion","quest:350","quest:2746","subzone:stormwind-keep","topic:stormwind-kingdom","topic:gnome","subzone:dark-portal"},m={start="Elling Trias",["end"]="Tyrion",level="31",faction="Alliance",id=2745},src={"Infiltrating the Castle"}}
E["quest:2746"] = {t="quest",n="Items of Some Consequence",z="stormwind",s="To sneak his mechanical spy into Stormwind Keep and eavesdrop on Lord Lescovar, the covert operative Tyrion demands a very specific assortment of disguise materials. You must supply fine silk and crisp orchard apples to assemble an eccentric cover identity that can bypass the royal guards undetected.",h="To sneak his mechanical spy into Stormwind Keep and eavesdrop on Lord Lescovar, the covert operative Tyrion...",sec={{t="A Tightening Schedule",b="Word from the cheese merchant Elling Trias has accelerated operations against Lord Gregor Lescovar. Suspecting that the noble's machinations within Stormwind Keep pose an immediate danger to the realm, Trias insisted the timetable be moved forward. Hidden in the gardens of Stormwind Keep, Tyrion agrees to advance the operation, though he insists that gathering the proper infiltration supplies requires careful preparation.",sp=0},{t="The Art of the Disguise",b="Tyrion's plan hinges on an unconventional asset: Spybot, a small mechanical contraption intended to slip past the vigilant castle guards to reach Lescovar inside the keep. Rather than relying on simple stealth, Tyrion constructs a bizarre feminine disguise to deflect suspicion. To complete this masquerade, he sends operatives out to Clara's orchard just outside the city walls for appropriately sized apples, while demanding bolts of silk cloth to tailor the puppet's garments.",sp=0},{t="Uncovering Treason",b="Tyrion reveals that his initial surveillance of Lord Lescovar was not tied to the Defias Brotherhood at all, but rather suspicious leads connecting the noble to the Twilight's Hammer cult. The discovery that Lescovar is actively colluding with Defias conspirators makes his continued presence in the royal court untenable, turning a routine surveillance mission into a high-stakes sting in the heart of the kingdom.",sp=1}},faq={{q="Why does Tyrion need apples and silk cloth?",a="Tyrion is crafting a peculiar feminine disguise for his mechanical scout, Spybot, to slip past the royal guards in Stormwind Keep without raising an alarm. The silk is tailored into makeshift garments, while the apples from Clara's farm provide the exact shape needed to complete the illusion.",al={"why apples","what are the apples for","tyrion disguise materials","spybot disguise"}},{q="Who is Tyrion working for?",a="Tyrion works in coordination with Elling Trias, the Old Town cheese merchant who runs his own network of friends in Stormwind; Trias admits the operation only indirectly does a favor for Mathias Shaw and SI:7.",al={"who does tyrion report to","tyrion allegiance","elling trias tyrion"}},{q="Where do I find Clara's apples?",a="Clara's farm sits just outside the city gates of Stormwind in northern Elwynn Forest. Fresh apples can be gathered directly around her modest orchard.",al={"clara farm location","where are claras apples","fresh apples stormwind"}},{q="What did Tyrion originally suspect Lord Lescovar of doing?",a="Tyrion and Trias initially tracked leads suggesting Lord Lescovar had ties to the sinister Twilight's Hammer cult. Uncovering his collaboration with the Defias Brotherhood proved that his treason ran far deeper and posed an imminent threat to the crown.",al={"lescovar twilight hammer","why was lescovar investigated","tyrion lescovar history"},sp=1},{q="What is the next step after delivering these items?",a="Once Spybot is fully outfitted and sent into the keep's library wing, you will be tasked with directly confronting and eliminating the conspirators in the follow-up mission, 'The Attack!'.",al={"what happens next","after items of some consequence","next quest after items of some consequence"},sp=1},{q="Why use a mechanical spybot instead of sneaking in personally?",a="Stormwind Keep is heavily guarded by royal sentries who scrutinize everyone entering the throne room and private courtyards. Disguised as a priestess, Spybot can walk past the guards and speak with Lescovar directly, drawing him out to the garden to meet Marzon where no known agent could get close.",al={"why use spybot","why not sneak in yourself","stormwind keep security"}}},ang={["class:Rogue"]="Working alongside operatives like Tyrion and Elling Trias highlights SI:7's unorthodox surveillance methods and shows how domestic intelligence operates right under the nobles' noses.",["profession:Tailoring"]="Tyrion's improvised scheme requires genuine silk cloth, reminding tailors that fine textiles are as vital for undercover intrigue as they are for formal gowns.",["faction:Alliance"]="Safeguarding the young King Anduin and Highlord Bolvar Fordragon requires rooting out corrupt aristocrats who conspire with outlaws within Stormwind Keep itself."},kw={"clara","elling trias","infiltrating the castle","lord lescovar","silk cloth","spybot","stormwind keep","the attack","tyrion"},rel={"quest:2745","quest:434","npc:tyrion","topic:defias-brotherhood","topic:twilight-s-hammer","topic:stormwind-kingdom","quest:65"},m={start="Tyrion",level="31",faction="Alliance",id=2746},src={"Items of Some Consequence"}}
E["quest:2998"] = {t="quest",n="Tome of Divinity",z="stormwind",s="Tome of Divinity marks a vital summons for budding human paladins serving the Alliance. Dispatched by local mentors like Brother Wilhelm in Goldshire, initiates travel to Stormwind's Cathedral of Light to meet Duthorian Rall. Answering this call begins the sacred trial necessary to master the holy gift of resurrection.",h="Tome of Divinity marks a vital summons for budding human paladins serving the Alliance.",sec={{t="A Summons to the Capital",b="Novice paladins beginning their journey through Elwynn Forest spend their early days helping the locals and testing their combat prowess against wolves, Defias bandits, and kobolds. Once an initiate demonstrates both martial discipline and dedication to the Holy Light, mentors such as Brother Wilhelm deliver a personal summons. Influential paladin leaders take note of promising students, directing them to leave local chapel outposts behind and report straight to the spiritual heart of the kingdom.",sp=0},{t="The Cathedral of Light",b="In the Cathedral Square of Stormwind, the Cathedral of Light serves as the supreme sanctuary for the kingdom's priesthood and the Knights of the Silver Hand. It is here that Duthorian Rall resides, overseeing the growth of those sworn to the Order. Stepping beneath the soaring vaulted ceilings, the initiate stands before high-ranking paladins to receive the formal trials of the Tome of Divinity—challenges structured to test unyielding compassion, fortitude, and sacrificial duty.",sp=0}},faq={{q="Who sends me to Stormwind for this quest?",a="Brother Wilhelm, the paladin trainer stationed near the Lion's Pride Inn in Goldshire, offers this summons once you have shown sufficient promise and strength in the field.",al={"quest giver","who gives quest","brother wilhelm"}},{q="Where can I find Duthorian Rall?",a="Duthorian Rall resides inside the Cathedral of Light, located within Cathedral Square in northwestern Stormwind City. He spends most of his days training paladins beneath the cathedral's grand halls.",al={"duthorian rall location","where is duthorian rall","paladin master location"}},{q="Why is this summons so important for paladins?",a="Reporting to Duthorian Rall marks the transition from basic martial training to deep holy communion. It initiates the trials of the Tome of Divinity, which ultimately bestow the sacred power to call fallen allies back from death through the Light.",al={"why do this quest","quest importance","paladin trial"}},{q="Do non-human paladins receive this exact quest?",a="This particular version of the summons originates in Elwynn Forest from Brother Wilhelm and is intended for human paladins. Dwarven paladins receive a parallel calling in Dun Morogh from their own trainers to visit Ironforge.",al={"dwarf paladin","can dwarves do this","is this quest human only"}},{q="What happens after reporting to Duthorian Rall?",a="Upon greeting Duthorian Rall, he welcomes you to Stormwind and immediately presents the trials of the Tome of Divinity, challenging your compassion and dedication to defending the weak.",al={"next quest","what happens next","tome of divinity next step"}},{q="Who is Duthorian Rall?",a="Duthorian Rall is one of the most influential paladins within the kingdom of Stormwind and the Knights of the Silver Hand, responsible for instructing new generations of holy warriors in the capital.",al={"who is duthorian","duthorian rall lore"}}},ang={["class:Paladin"]="This quest represents a rite of passage for human paladins, marking the moment your mentors formally recognize your deeds and send you before the high commanders of the Silver Hand.",["race:Human"]="Travelling from rural Elwynn Forest into the grandiose Cathedral of Light anchors human defenders to the kingdom's deepest spiritual and martial institutions.",["faction:Alliance"]="Recruiting and testing holy warriors in Stormwind ensures the Alliance maintains dedicated frontline healers and combatants during troubled times."},kw={"brother wilhelm","cathedral of light","duthorian rall","goldshire","paladin","redemption","stormwind","tome of divinity"},rel={"npc:duthorian-rall","npc:brother-wilhelm","subzone:cathedral-of-light","topic:stormwind-kingdom","topic:light"},m={start="Brother Wilhelm",["end"]="Duthorian Rall",level="12",faction="Alliance",id=2998},src={"Tome of Divinity (Brother Wilhelm)"}}
E["quest:322"] = {t="quest",n="Blessed Arm",z="stormwind",s="Having salvaged lightforge ingots from the wreck of the Flying Osprey in the Wetlands, an adventurer is directed to carry the precious metal to Stormwind City. There, the master dwarven smith Grimand Elmore awaits to fashion the raw metal into a tool capable of confronting the necromancer Morbent Fel.",h="Having salvaged lightforge ingots from the wreck of the Flying Osprey in the Wetlands, an adventurer is...",sec={{t="A Rare Metal Returns",b="Lightforge iron is not an everyday trade metal found in standard market stalls. Renowned for its resonance against foul and unholy entities, it demands a smith who understands its temper and quirks. After the shipment was recovered from the wreck of the Flying Osprey off the Wetlands coast, Glorin Steelbrow packed the reclaimed ingots into a sturdy crate, knowing of only one artisan in the southern kingdoms suited to work such extraordinary material: master weaponsmith Grimand Elmore.",sp=0},{t="The Dwarven District's Forge",b="Situated amidst the soot and clatter of Stormwind's Dwarven District, Grimand Elmore maintains one of the city's finest anvils. When presented with the recovered shipment, Elmore notes that years have passed since he last hammered lightforge iron. Intrigued by the heroic errand and eager to strike a blow against the necromancer Morbent Fel, the veteran artisan readily agrees to lend his hammer to the cause.",sp=0}},faq={{q="What is the purpose of this delivery?",a="The crate holds recovered lightforge iron salvaged from the Flying Osprey wreck in the Wetlands. Glorin Steelbrow sends it to Grimand Elmore so the skilled smith can shape the consecrated metal into a weapon capable of combating the necromancer Morbent Fel.",al={"why bring ingots to stormwind","blessed arm purpose","what is crate of lightforge ingots for"}},{q="Who is Grimand Elmore?",a="Grimand Elmore is a respected dwarven weaponsmith who operates in the Dwarven District of Stormwind. He is among the rare craftsmen with the training and skill necessary to forge specialized metals like lightforge iron.",al={"grimand elmore lore","who is the smith in dwarven district"}},{q="Why is lightforge iron so important against Morbent Fel?",a="Morbent Fel is an elusive and powerful necromancer shielded by dark magic. Normal arms struggle to pierce his unholy defenses, making weapons forged from sanctified lightforge iron necessary to strip away his protection and make him vulnerable.",al={"why lightforge iron","how does lightforge iron hurt morbent fel"}},{q="Where does Glorin Steelbrow send you?",a="Glorin Steelbrow sends you from Menethil Harbor in the Wetlands to the Dwarven District of Stormwind City, where Grimand Elmore keeps his forge.",al={"where do i go for blessed arm","where is grimand elmore located"}},{q="Has Grimand Elmore worked with lightforge iron before?",a="Yes. Upon inspecting the metal, Grimand remarks that it has been years since he last worked with lightforge iron, welcoming the chance to practice his craft on such a storied material once more.",al={"did grimand forge lightforge before","elmore smithing experience"}},{q="What must happen before the weapon can be finished?",a="While Grimand agrees to forge the weapon, shaping raw lightforge ingots into an enchanted arm requires time, additional labor, and specific components before it is ready to face the necromancer in Duskwood.",al={"what comes after blessed arm","is weapon forged immediately"}}},ang={["profession:Blacksmithing"]="Lightforge iron is a rare and finicky metal; observing an experienced dwarven smith like Grimand Elmore take on the task of working it highlights the exceptional craft required to forge holy arms.",["class:Paladin"]="Carrying consecrated iron to fashion an arm against a Duskwood necromancer mirrors the core calling of the Silver Hand: purifying dark sorcery with holy vigilance.",["faction:Alliance"]="The delivery demonstrates the close cooperation between the kingdoms, bridging a dwarven priest in Menethil Harbor with the forges of Stormwind's Dwarven District to aid the beleaguered people of Duskwood."},kw={"blessed arm","dwarven district","glorin steelbrow","grimand elmore","lightforge iron","loch modan","morbent fel","stormwind"},rel={"quest:324","quest:1700","npc:glorin-steelbrow","subzone:dwarven-district","quest:55","quest:321","topic:stormwind-kingdom","topic:light"},m={start="Glorin Steelbrow",["end"]="Grimand Elmore",level="29",faction="Alliance",id=322},src={"Blessed Arm"}}
E["quest:325"] = {t="quest",n="Armed and Ready",z="stormwind",s="Armed and Ready marks the culmination of forging a weapon specifically designed to strip away the unholy defenses of the necromancer Morbent Fel. Having secured Grimand Elmore's craft and a holy blessing, the adventurer carries Morbent's Bane back across the river to the vengeful Sven Yorgen in Duskwood.",h="Armed and Ready marks the culmination of forging a weapon specifically designed to strip away the unholy...",sec={{t="A Weapon Forged",b="Morbent Fel's grasp on the Raven Hill cemetery seemed unbreakable. Conventional steel shattered or deflected harmlessly off the dark wards shrouding the necromancer. Overcoming such vile magic required a specialized artifact: Morbent's Bane. With the metal shaped by Grimand Elmore in the Dwarven District of Stormwind and properly consecrated with sacred power, the blade is finally complete and ready to sever Fel's connection to unlife.",sp=0},{t="Return to the Hermit",b="Carrying Morbent's Bane back into Duskwood brings hope to Sven Yorgen, who has watched his family and farm fall victim to the encroaching darkness. Stationed at his lonely camp near the western border of the woods, Sven immediately recognizes the fire in the traveler's eyes and the divine craftsmanship of the weapon. With the ward-breaking relic delivered, the stage is set for a direct strike against the master of Raven Hill.",sp=1}},faq={{q="What is Morbent's Bane?",a="Morbent's Bane is a specially forged and consecrated weapon crafted to pierce the invulnerable magical wards surrounding the necromancer Morbent Fel in Raven Hill.",al={"morbents bane","what is the weapon","morbent bane sword"}},{q="Who crafted the weapon?",a="Grimand Elmore, a skilled blacksmith residing in the Dwarven District of Stormwind City, fashioned the physical blade before it received a sacred blessing.",al={"who made morbents bane","grimand elmore role"}},{q="Where do I deliver Morbent's Bane?",a="You must deliver the weapon to Sven Yorgen, who is hiding at an encampment in western Duskwood, not far from the border with Westfall.",al={"where is sven","sven yorgen location","turn in location"}},{q="Why can't Sven Yorgen fight Morbent Fel himself?",a="Sven Yorgen was driven from his home and lost his family and companions to the dark forces infesting the woods. Isolated and hunted, he relies on capable champions of the Alliance to avenge the fallen.",al={"why doesnt sven fight","sven yorgen backstory"}},{q="What happens after completing Armed and Ready?",a="Upon receiving the blessed weapon, Sven Yorgen tasks you with venturing directly into Raven Hill Cemetery to face Morbent Fel and strike him down.",al={"what comes next","next quest after armed and ready"},sp=1},{q="What is the quickest route back to Sven's camp?",a="Traveling east from Sentinel Hill in Westfall across the river often provides a much shorter and safer journey to Sven's camp than trekking westward through the terrors of Darkshire.",al={"fastest way to sven","how to get to sven quickly"}}},ang={["class:Paladin"]="The combination of fine dwarven steel and holy consecration echoes the paladin tradition of infusing martial armaments with divine light to shatter undead wards.",["profession:Blacksmithing"]="Grimand Elmore's handiwork demonstrates how elite smithing can be combined with divine rites to craft specialized banes against supernatural threats.",["faction:Alliance"]="Coordinating between artisans in Stormwind and front-line survivors in Duskwood highlights how the Alliance must draw upon its capital's expertise to purge creeping blights."},kw={"armed and ready","duskwood","grimand elmore","morbent fel","morbent's bane","raven hill","stormwind","sven yorgen"},rel={"npc:sven-yorgen","quest:55","quest:322","quest:1700","zone:duskwood","subzone:sentinel-hill","zone:westfall","subzone:darkshire"},m={start="Grimand Elmore",["end"]="Sven Yorgen",level="29",faction="Alliance",id=325},src={"Armed and Ready (Classic)"}}
E["quest:332"] = {t="quest",n="Wine Shop Advert",z="stormwind",s="Wine Shop Advert is a brief promotional errand handed out by Renato Gallina in the Trade District of Stormwind. He entices passersby with a voucher for a complimentary bottle of vintage wine from his family's storefront along the canals. It serves as an everyday glimpse into the domestic trade and small businesses flourishing within the reconstructed capital.",h="Wine Shop Advert is a brief promotional errand handed out by Renato Gallina in the Trade District of...",sec={{t="A Taste of the Canals",b="While adventurers often occupy themselves with martial threats and political intrigue, daily life in Stormwind revolves around brisk commerce. Renato Gallina walks the cobbled ways of the Trade District promoting Gallina Winery, the small shop he runs alongside his sister, Suzetta. To draw in thirsty travelers and locals alike, he hands out promotional flyers entitling the bearer to a complimentary tasting.",sp=0},{t="The Dalaran Noir Vintage",b="The prize offered by the Gallina family is a sample of Dalaran Noir, a famous northern red vintage prized across human settlements. Following the ticket to the winery entrance near the canal waterways, patrons find Suzetta Gallina ready to hand over the bottle, confident that one sip of their signature stock will turn any newcomer into a loyal regular.",sp=0}},faq={{q="Where is the Gallina Winery located?",a="The Gallina Winery sits in Stormwind City's Trade District, tucked right along the edge of the scenic canals not far from Renato Gallina's promotional route.",al={"where is gallina winery","suzetta gallina location","where is wine shop advert turned in"}},{q="Who are Renato and Suzetta Gallina?",a="Renato and Suzetta Gallina are siblings running an independent vintner shop in Stormwind. Renato wanders the streets promoting their trade with flyers, while Suzetta tends the shop counter and pours the wine.",al={"who are the gallinas","renato gallina","suzetta gallina lore"}},{q="What is Dalaran Noir?",a="Dalaran Noir is a celebrated vintage of red wine styled after the traditional spirits of Dalaran. Even with the northern magocracy shielded behind an impenetrable dome, their cultural vintages remain legendary across the southern kingdoms.",al={"dalaran noir wine","what wine do you get","pinot noir stormwind"}},{q="Why does Renato give out free wine tickets?",a="It is classic street-level marketing. Renato uses free samples of their prized stock to draw foot traffic into their canal-side shop and build a returning customer base among Stormwind's citizens.",al={"why free wine","wine shop ticket purpose"}},{q="Does this errand involve any danger or combat?",a="No. The errand simply involves taking a promotional ticket from Renato and strolling a short distance through the safe streets of the Trade District to Suzetta at the storefront.",al={"is wine shop advert dangerous","wine quest fights"}},{q="Does the Gallina Winery sell other goods?",a="Suzetta stocks a selection of standard wines and alcoholic beverages for thirsty travelers, guards on break, and local tavern suppliers in need of a refill.",al={"what else does suzetta sell","gallina winery drinks"}}},ang={["profession:Cooking"]="Fine wines like the Dalaran Noir distributed by the Gallinas are prized companions for hearty meals prepared across the taverns of the Eastern Kingdoms.",["race:Human"]="For humans rebuilding their lives in Stormwind, the presence of family-run wineries along the canal banks is a comforting sign of urban revival.",["faction:Alliance"]="Even during turbulent times of war and missing kings, Stormwind's bustling Trade District maintains an active market for domestic luxuries and imported tastes."},kw={"canals","dalaran noir","gallina winery","renato gallina","suzetta gallina","trade district","wine shop advert","wine ticket"},rel={"npc:renato-gallina","npc:suzetta-gallina","subzone:trade-district","subzone:canals-stormwind-city","subzone:dalaran","topic:stormwind-kingdom"},m={start="Renato Gallina",["end"]="Suzetta Gallina",faction="Alliance",id=332},src={"Wine Shop Advert"}}
E["quest:333"] = {t="quest",n="Harlan Needs a Resupply",z="stormwind",s="Harlan Bagley, a merchant in Stormwind, finds his racks emptied by an unprecedented surge in demand for sturdy garments and armor. Unaware of the brewing conflicts beyond the city walls, he dispatches a courier with an urgent cloth order to Rema Schneider at the Canal Tailor and Fit Shop.",h="Harlan Bagley, a merchant in Stormwind, finds his racks emptied by an unprecedented surge in demand for...",sec={{t="A Run on Sturdy Clothes",b="In the bustling commercial districts of Stormwind City, shopkeepers like Harlan Bagley have seen their inventory dwindle at an alarming rate. Ordinary citizens and wandering adventurers alike have been snatching up reinforced tunics, traveling wear, and battle-ready armor. To Harlan, it feels as though the kingdom's populace is bracing for a harsh season or an impending winter, but the sheer volume of sales leaves his shop depleted and desperate for finished cloth.",sp=0},{t="Questions on the Canals",b="To replenish his shelves, Bagley sends a runner across the city's waterways to Rema Schneider, the seamstress operating the Canal Tailor and Fit Shop. While Rema is grateful for the continued trade, the sudden run on protective outfitting strikes her as unsettling. Rumors of tension linger throughout the kingdom, and the seamstress cannot help but wonder if Stormwind's ruling House of Nobles is hiding rumors of an open war from the common folk.",sp=0}},faq={{q="Who is Harlan Bagley?",a="Harlan Bagley is a clothier and shopkeeper operating in Stormwind City. His business relies on local tailors to keep his inventory stocked with knitted goods and travel-ready garments.",al={"harlan bagley","who is harlan","bagley stormwind"}},{q="Who is Rema Schneider?",a="Rema Schneider is a professional tailor and seamstress who works at the Canal Tailor and Fit Shop in Stormwind. Along with her husband Corbett, she supplies merchants across the city with freshly sewn fabric and garments.",al={"rema schneider","tailor rema","canal tailor"}},{q="Why is Harlan running out of clothing?",a="Citizens and travelers have been buying up armor and rugged garments in unusually high numbers. Harlan jokes that people act as if a bitter winter is coming, though the true cause is the rising unrest and danger across the kingdom's borders.",al={"why out of cloth","why buying armor","harlan business booming"}},{q="Why does Rema Schneider suspect the nobles?",a="Rema finds it unnatural that common folk are suddenly equipping themselves for battle without any official declaration of conflict. Since the House of Nobles controls royal affairs while King Varian Wrynn remains absent, she fears the aristocracy is concealing impending war from the public.",al={"rema nobles","stormwind nobles hiding war","why nobles suspect"}},{q="Where is the Canal Tailor and Fit Shop located?",a="The Canal Tailor and Fit Shop sits along the waterways that wind through Stormwind City, tucked conveniently between the major urban districts for easy merchant delivery.",al={"canal tailor location","where is rema schneider","where is canal tailor"}},{q="What happens after the cloth request is delivered?",a="Upon receiving the order, Rema prepares the supply request, prompting her husband Corbett Schneider to set out through the city streets—passing local storefronts like the Lionheart Armory and Trias' Cheese—to handle trade errands.",al={"corbett schneider walk","what does corbett do","rema husband"}}},ang={["profession:Tailoring"]="The errand offers a glimpse into the everyday logistics of Stormwind's textile industry, where small canal workshops supply larger mercantile storefronts.",["faction:Alliance"]="The quiet panic among Stormwind's shoppers hints at the growing unease gripping the Alliance heartland in the absence of King Varian Wrynn.",["race:Human"]="Stormwind's working-class artisans remain wary of their rulers, suspecting the nobility of keeping ordinary citizens in the dark about looming dangers."},kw={"bagley","canal","cloth","harlan","rema","resupply","schneider","stormwind","tailor"},rel={"npc:harlan-bagley","npc:rema-schneider"},m={start="Harlan Bagley",["end"]="Rema Schneider",faction="Alliance",id=333},src={"Harlan Needs a Resupply"}}
E["quest:334"] = {t="quest",n="Package for Thurman",z="stormwind",s="Package for Thurman is a brief errand through the streets of Stormwind City. A worried mother, Rema Schneider, asks passing travelers to bring forgotten tailoring supplies to her slacking apprentice son at Larson Clothiers in the Mage Quarter.",h="Package for Thurman is a brief errand through the streets of Stormwind City.",sec={{t="A Mother's Errand",b="In the daily hustle of Stormwind, not every task involves fighting gnolls or uncovering Defias conspiracies. Rema Schneider, concerned for her son Thurman's livelihood, notices he left home in a rush without his shears and needles. Fearing he will fall behind in his trade duties, she entreats an adventurer to deliver the kit across the canals to his workshop.",sp=0},{t="A Reluctant Apprentice",b="Larson Clothiers sits nestled deep within the Mage Quarter, not far from the soaring spires of the Mage Tower. Upon receiving his tools, Thurman reveals that leaving his shears behind was entirely deliberate—a scheme to escape his daily chores and spend the day having fun. With his mother's intervention, however, his afternoon of freedom evaporates, and he is forced back to his stitching.",sp=0}},faq={{q="Who starts the quest Package for Thurman?",a="Rema Schneider starts the quest. She is looking for someone to deliver a sewing kit to her son, who works across town in the Mage Quarter.",al={"who gives quest","rema schneider quest","quest giver"}},{q="Where can Thurman Schneider be found?",a="Thurman Schneider is located inside Larson Clothiers in the Mage Quarter of Stormwind. The shop is positioned deeper into the quarter, close to the path leading up to the Mage Tower.",al={"thurman location","where is thurman","find thurman"}},{q="Did Thurman actually forget his tools by accident?",a="No. Thurman deliberately left his needles and shears behind at home, hoping the missing tools would excuse him from his tailoring chores so he could shirk his apprentice duties for the day.",al={"did thurman forget","why did thurman leave tools","thurman slacking"},sp=1},{q="What shop does Thurman apprentice for?",a="Thurman works as an apprentice tailor for Larson Clothiers, a garment shop in Stormwind's Mage Quarter run by the Larson family.",al={"where does thurman work","larson clothiers","who does thurman work for"}},{q="Why does Rema Schneider ask an adventurer for help?",a="Rema believes her son's apprenticeship is in jeopardy without his kit. Unable to leave her own obligations, she appeals to passing adventurers who might be headed toward the Mage Quarter.",al={"why ask player","rema help"}},{q="What happens after you deliver the sewing kit?",a="Thurman begrudgingly accepts the kit with a groan, admitting his plan to skip work was ruined and that he must now get back to sewing for the Larsons.",al={"quest reward","after package for thurman","thurman reaction"},sp=1}},ang={["profession:Tailoring"]="Every grand tailor started at the bottom: running seams, holding pins, and trying to slip away from apprentice chores at Larson Clothiers.",["faction:Alliance"]="Beneath the high politics of Stormwind Keep, ordinary citizens and artisans keep the capital clothed, fed, and running one errand at a time."},kw={"apprentice","clothiers","larson","mage quarter","rema","schneider","sewing kit","stormwind","thurman"},rel={"npc:rema-schneider","subzone:mage-quarter","npc:lars","topic:stormwind-kingdom"},m={start="Rema Schneider",["end"]="Thurman Schneider",faction="Alliance",id=334},src={"Package for Thurman"}}
E["quest:335"] = {t="quest",n="A Noble Brew",z="stormwind",s="Deep within the shadowed recesses of the Slaughtered Lamb in Stormwind, Zardeth of the Black Claw schemes against the city's nobility. An inquisitive peer, Lord Wishock, threatens to uncover the warlock enclave beneath the tavern, prompting a quiet gathering of rare and potent reagents to neutralize the threat.",h="Deep within the shadowed recesses of the Slaughtered Lamb in Stormwind, Zardeth of the Black Claw schemes...",sec={{t="Threat from the Nobility",b="Beneath the streets of the Mage Quarter, the warlock coven operating out of the Slaughtered Lamb enjoys a precarious secrecy. That secrecy is jeopardized by Lord Wishock, a member of the House of Nobles who has caught wind of the dark magic simmering below the city. Wishock has begun lobbying his peers for a full investigation, which would bring the city guard and royal scrutiny down upon the coven.",sp=0},{t="A Concoction in the Shadows",b="Rather than risk open confrontation with Stormwind's ruling class, Zardeth of the Black Claw devises a discreet remedy to ensure Lord Wishock becomes permanently preoccupied. The preparation requires obscure botanical ingredients gathered from distant corners of the Eastern Kingdoms: a pale bloom known as the Tear of Tilloa from Duskwood, and a submerged Musquash Root plucked from beneath the Stonewrought Dam.",sp=1}},faq={{q="Who is Lord Wishock?",a="Lord Wishock is a nobleman within the Stormwind House of Nobles. After discovering hints of warlock activities hidden beneath the Mage Quarter, he began pressing the council for a formal investigation.",al={"wishock","lord wishock","who is wishock"}},{q="Who is Zardeth of the Black Claw?",a="Zardeth is a senior warlock operating from the crypts beneath the Slaughtered Lamb tavern in Stormwind. He works to shield the city's warlock cabal from being discovered and purged by authorities.",al={"zardeth","zardeth black claw","who is zardeth"}},{q="Where does the Tear of Tilloa come from?",a="The Tear of Tilloa is a delicate white flower found growing in the overgrown Garden of Stalvan on the outskirts of Darkshire in Duskwood.",al={"tear of tilloa location","tear of tilloa","where is tear of tilloa"}},{q="Where is the Musquash Root found?",a="The Musquash Root grows only in the wetlands at the very base of the massive waterfalls tumbling beneath the Stonewrought Dam in the Wetlands.",al={"musquash root location","musquash root","where to get musquash root"}},{q="Why doesn't Stormwind's government already know about the warlocks?",a="Fel magic is strictly forbidden and reviled within the Alliance. The warlocks under the Slaughtered Lamb must practice their craft entirely underground to avoid imprisonment or execution by the paladins and city guards.",al={"stormwind warlocks secret","why are warlocks hiding","are warlocks illegal"}},{q="What does Zardeth intend to brew with these reagents?",a="Zardeth claims the brew will keep Lord Wishock 'preoccupied' so the investigation stalls. What exactly he has in mind for the nobleman only becomes clear once the brew is ready.",al={"what is the brew","noble brew purpose","why make the brew"},sp=1}},ang={["class:Warlock"]="The crypts beneath the Slaughtered Lamb are your safe haven in Stormwind. Assisting Zardeth protects your brothers and sisters of the dark arts from the prying eyes of the kingdom's righteous nobility.",["faction:Alliance"]="While King Varian Wrynn remains missing, political maneuvering among the House of Nobles is at an all-time high, making internal scandals especially dangerous for the city's stability.",["profession:Herbalism"]="The Tear of Tilloa and Musquash Root represent rare and specialized flora that thrive only in regions shaped by grim history or torrents of pristine water."},kw={"darkshire","house of nobles","musquash","slaughtered lamb","stonewrought dam","tilloa","wishock","zardeth"},rel={"npc:zardeth-of-the-black-claw","quest:397","topic:house-of-nobles","subzone:darkshire","zone:duskwood","subzone:stonewrought-dam","zone:wetlands"},m={start="Zardeth of the Black Claw",level="30",faction="Alliance",id=335},src={"A Noble Brew"}}
E["quest:336"] = {t="quest",n="A Noble Brew",z="stormwind",s="A Noble Brew is the culmination of a covert scheme orchestrated from the shady cellar beneath the Slaughtered Lamb in Stormwind. Operating at the behest of Zardeth of the Black Claw, an unwitting or uncaring courier delivers a potent concoction known as Black Claw Stout to Lord Baurles K. Wishock inside the Royal Keep.",h="A Noble Brew is the culmination of a covert scheme orchestrated from the shady cellar beneath the Slaughtered...",sec={{t="A Noble Hypocrite",b="Lord Baurles K. Wishock is a nobleman who frequents the Hall of Petitioners in Stormwind Keep, preaching self-importance and the future of the kingdom. Yet beneath his aristocratic posturing lies an open secret known to the patrons of the Slaughtered Lamb: by night, Wishock frequents the tavern's upper rooms, drinking heavily and running up massive tabs he never settles. Worse still in the eyes of the establishment, he spends his days petitioning to shut the tavern down entirely.",sp=0},{t="A Lethal Toast",b="Zardeth of the Black Claw, a warlock lurking in the dark recesses below the tavern, decides to settle Wishock's debt in a permanent fashion. He brews a specialized draught—Black Claw Stout—promising it carries 'quite a kick.' When presented with the foaming tankard in the Hall of Petitioners, the pompous noble mistakes the courier for a simple servant, flings a copper coin as a dismissal, and drinks greedily, collapsing dead moments later right within the halls of the keep.",sp=1}},faq={{q="Who is Zardeth of the Black Claw?",a="Zardeth of the Black Claw is a warlock affiliated with the shadowy cabal operating hidden catacombs beneath The Slaughtered Lamb in Stormwind's Mage Quarter. He conducts dangerous and clandestine operations out of sight of the city guard.",al={"who is zardeth","zardeth of the black claw","who gives the quest"}},{q="Why does Zardeth want Lord Wishock dead?",a="Wishock is a drunken hypocrite who spends his nights carousing in the upper floors of the Slaughtered Lamb without paying his bills, while spending his days in the Hall of Petitioners demanding the authorities shut the tavern down.",al={"why kill wishock","wishock motivation","why poisoned"},sp=1},{q="Where is Lord Wishock found?",a="Lord Baurles K. Wishock loiters in the Hall of Petitioners, an antechamber within Stormwind Keep where nobles and citizens gather to lobby the realm's regency.",al={"lord wishock location","where is wishock","hall of petitioners wishock"}},{q="What happens when Lord Wishock drinks the brew?",a="Upon receiving the Black Claw Stout, Wishock arrogantly dismisses the player with a single copper coin, drinks the brew, and drops dead on the floor from the lethal poison.",al={"does wishock die","wishock death","what does the stout do"},sp=1},{q="Is the player arrested for assassinating a noble in Stormwind Keep?",a="Remarkably, no. Because you simply delivered a drink that the arrogant noble eagerly accepted and drank of his own accord, the chaotic scene in the Hall of Petitioners lets you slip away clean to report back to the catacombs.",al={"do guards attack","am i wanted in stormwind","consequences of poisoning"},sp=1},{q="What is the follow-up quest after Wishock dies?",a="After poisoning Lord Wishock, you return to Zardeth beneath the Slaughtered Lamb to turn in the deed, leading directly into the quest 'You Have Served Us Well.'",al={"what comes next","after a noble brew","next quest"},sp=1}},kw={"baurles wishock","black claw stout","hall of petitioners","noble brew","slaughtered lamb","stormwind keep","zardeth"},rel={"quest:335","quest:397","npc:lord-baurles-k-wishock","npc:zardeth-of-the-black-claw"},m={start="Zardeth of the Black Claw",["end"]="Lord Baurles K. Wishock",level="30",faction="Alliance",id=336},src={"A Noble Brew (2)"}}
E["quest:337"] = {t="quest",n="An Old History Book",z="stormwind",s="Recovered from the blighted soil and monstrous dens of Duskwood, this battered tome bears the official stamp of the Royal Library of Stormwind. Titled 'The History of Stormwind,' it vanished prior to the kingdom's reconstruction following the First War. Returning it restores a lost chronicle to Head Librarian Milton Sheaf and begins an effort to preserve Southern human history.",h="Recovered from the blighted soil and monstrous dens of Duskwood, this battered tome bears the official stamp...",sec={{t="A Relic of the First War",b="Discovered among the hostile undead and brutish ogres roaming Duskwood, this mud-caked volume is a rare surviving artifact from the era before Stormwind's destruction. Bearing the kingdom's formal library seal on its opening page, it was checked out decades ago—before the Horde razed the capital—and was presumed lost forever amid the fall of the south.",sp=0},{t="Restoring Forgotten Annals",b="When brought back to Milton Sheaf in the Royal Library of Stormwind Keep, the book is recognized as an invaluable treasure destined for the rare books archive. Years of exposure in the haunted wilderness have left its pages badly degraded, and the find spurs Sheaf to recover more lost knowledge, looking north to Southshore, the town closest to the ruined kingdom of Alterac and its abandoned libraries.",sp=0}},faq={{q="Where is this book found?",a="The book drops from various hostile creatures roaming Duskwood, most commonly the undead haunting the cemeteries and fields or the ogres occupying the southern hills.",al={"where to find old history book","book drop location","duskwood history book"}},{q="Who do I bring the book to?",a="You return the volume to Milton Sheaf, the head librarian situated in the Royal Library inside Stormwind Keep.",al={"turn in location","where do i turn this in","milton sheaf location"}},{q="Why is the book in such poor condition?",a="The book was checked out prior to the First War and the sack of Stormwind. It survived decades in the wilderness of Duskwood, weathered by dirt, rot, and the hands of wandering scavengers and monsters.",al={"why is it muddy","why damaged"}},{q="Does returning this book lead to other tasks?",a="Yes. Milton Sheaf will send you north to Southshore in the Hillsbrad Foothills to speak with Loremaster Dibbs, who can direct you to books still lying in the Ruins of Alterac.",al={"what comes next","followup quest","book quest chain"}},{q="Why does Milton Sheaf care so much about this specific tome?",a="Because the original kingdom was leveled during the First War, few original historical records survived the burning of the city. Recovering genuine pre-war texts helps scholars reconstruct the kingdom's past.",al={"why is the book important","importance of history of stormwind"}},{q="Can Horde players complete this quest?",a="No. The book belongs to the Royal Library of Stormwind and can only be turned in to Alliance librarians within Stormwind Keep.",al={"horde version","is this alliance only"}}},ang={["faction:Alliance"]="Recovering pre-war texts restores fragments of Stormwind's lost heritage that survived the devastation of the First War.",["race:Human"]="For humans of the south, reclaiming written records from the wilderness is a vital step in rebuilding the culture shattered by the Old Horde.",["class:Mage"]="Scholars of the arcane understand that ancient libraries hold knowledge vulnerable to decay and neglect when left in the wild."},kw={"an old history book","duskwood","milton sheaf","preserving knowledge","southshore","stormwind keep","stormwind library","the history of stormwind"},rel={"npc:milton-sheaf","subzone:southshore","zone:duskwood","topic:stormwind-kingdom","quest:579","quest:366","subzone:library-ironforge"},m={start="An Old History Book",["end"]="Milton Sheaf",level="25",faction="Alliance",id=337},src={"An Old History Book (quest)"}}
E["quest:343"] = {t="quest",n="Speaking of Fortitude",z="stormwind",s="\"Speaking of Fortitude\" is an Alliance errand within Stormwind City begun by Brother Kristoff in Cathedral Square. Preparing a sermon titled \"Fortitude of the Spirit,\" Kristoff enlists an adventurer to visit the Royal Library within Stormwind Keep and ask Head Librarian Milton Sheaf for a specific technical text.",h="\"Speaking of Fortitude\" is an Alliance errand within Stormwind City begun by Brother Kristoff in Cathedral...",sec={{t="A Metaphor in Metal",b="Brother Kristoff, one of the priests stationed in Stormwind's Cathedral of Light, seeks to deliver a sermon on the Fortitude of the Spirit. Rather than drawing solely from clerical scripture, Kristoff looks to the craft of metalworking to illustrate the temper and resilience of faith. Specifically, he requires a treatise known as \"The Stresses of Iron\" to quote during his address, hoping its lessons on enduring pressure will resonate with his congregation.",sp=0},{t="The Royal Stacks",b="Stormwind Keep houses the Royal Library, the central repository of knowledge, history, and civic treatises for the kingdom of Stormwind. Because the collection spans countless shelves and centuries of work, Kristoff directs messengers to Milton Sheaf, the head librarian. Sheaf prides himself on knowing the archive by heart, making him the only practical guide for tracking down obscure craft manuscripts among the keep's sprawling vaults.",sp=0}},faq={{q="Who is Brother Kristoff?",a="Brother Kristoff is a priest serving the Church of the Holy Light in Cathedral Square within Stormwind City. He often engages visitors to assist with procuring materials and references for his teachings and sermons.",al={"kristoff","who gives speaking of fortitude","brother kristoff"}},{q="What book is Brother Kristoff looking for?",a="He is searching for a technical text titled \"The Stresses of Iron,\" an instructional work on metallurgy that he intends to cite as a metaphor for spiritual endurance.",al={"which book","the stresses of iron","kristoff book"}},{q="Who is Milton Sheaf?",a="Milton Sheaf is the head librarian of the Royal Library inside Stormwind Keep. He oversees the realm's vast compilation of books, scrolls, and municipal records, knowing the collection thoroughly.",al={"milton sheaf","librarian stormwind","head librarian"}},{q="Where is the Royal Library located?",a="The Royal Library sits within the northeastern wing of Stormwind Keep, accessible directly through the main hall of the royal palace.",al={"library location stormwind","where is royal library","stormwind keep library"}},{q="Why does a priest need a metallurgy book?",a="Brother Kristoff is writing a sermon titled \"Fortitude of the Spirit.\" He intends to use the physical stresses that iron endures during forging as an allegory for how the human spirit is strengthened under trial.",al={"why metallurgy","why iron book","fortitude sermon"}},{q="Does Milton Sheaf have the book ready right away?",a="Milton Sheaf confirms that the library houses works on metallurgy, but he must check the exact title and coordinate the search when approached, starting the process to track down Kristoff's text.",al={"does sheaf have book","hand in speaking of fortitude"}}},ang={["class:Priest"]="Brother Kristoff's sermon draws on themes of spiritual fortitude, offering insight into how Stormwind's clergy craft sermons by blending mundane craft lessons with devotion to the Light.",["profession:Blacksmithing"]="The sermon relies on \"The Stresses of Iron,\" reflecting how even scholarly theologians look to the harsh realities of the forge to explain endurance under pressure.",["faction:Alliance"]="The errand ties Cathedral Square's priesthood directly to Stormwind Keep's Royal Library, displaying the civic and scholarly infrastructure maintained in the capital."},kw={"brother kristoff","cathedral of light","metallurgy","milton sheaf","royal library","speaking of fortitude","stormwind keep","the stresses of iron"},rel={"npc:brother-kristoff","npc:milton-sheaf","subzone:royal-library","subzone:stormwind-keep","topic:light","topic:stormwind-kingdom"},m={start="Brother Kristoff",["end"]="Milton Sheaf",level="24",faction="Alliance",id=343},src={"Speaking of Fortitude"}}
E["quest:344"] = {t="quest",n="Brother Paxton",z="stormwind",s="Brother Paxton is an errand that sends adventurers from Stormwind's royal archives out to Northshire Abbey. Librarian Milton Sheaf directs searchers there to track down a borrowed dwarven mining treatise that never found its way back to the city shelves.",h="Brother Paxton is an errand that sends adventurers from Stormwind's royal archives out to Northshire Abbey.",sec={{t="A Borrowed Volume",b="When researchers come looking for rare technical lore within Stormwind City, the head librarian Milton Sheaf often finds his collection scattered. A notable treatise on metallurgical techniques, 'The Stresses of Iron' by dwarven prospector Margulf Blaggon, is missing from the capital's shelves. Rather than being misplaced in the capital, it was loaned out months ago to the clerics of Northshire Abbey for transcription.",sp=0},{t="Northshire's Scribe",b="The task of transcribing and preserving literature falls to Brother Paxton, the caretaker of the abbey's library. While the Holy Order of Northshire Clerics values knowledge, manual hand-copying of lengthy technical manuscripts is painstaking and slow. Caught red-handed with the overdue tome, Paxton admits he has yet to finish duplicating Blaggon's work, stalling the recovery of the original manuscript.",sp=0}},faq={{q="Why does Milton Sheaf send you to Northshire Abbey?",a="Milton Sheaf loaned the library's copy of 'The Stresses of Iron' to Brother Paxton months ago so the abbey could produce its own duplicate. With no word or return of the manuscript, Sheaf sends you to check on Paxton's progress.",al={"why brother paxton","where is the book","milton sheaf errand"}},{q="Who is Brother Paxton?",a="Brother Paxton is a cleric and the caretaker of the library at Northshire Abbey. He spends his days cataloging and manually copying valuable books to build up the abbey's local collection.",al={"who is paxton","brother paxton lore","paxton northshire"}},{q="What is 'The Stresses of Iron'?",a="It is a respected technical manual written decades ago by the dwarven miner Margulf Blaggon, detailing his insights into digging ore and metallurgical stress deep within the mountains of Khaz Modan.",al={"what is stresses of iron","stresses of iron book","margulf blaggon book"}},{q="Why hasn't Paxton returned the book yet?",a="Brother Paxton is still hand-copying the manuscript for his own library's shelves. Because copying an extensive technical work by hand takes considerable time and materials, he is reluctant to part with the original before finishing.",al={"why overdue","why is paxton taking so long","paxton delay"}},{q="Where can Brother Paxton be found?",a="Brother Paxton resides inside Northshire Abbey, the seat of the Holy Order of Northshire Clerics located in the Northshire Valley in northern Elwynn Forest.",al={"paxton location","where is brother paxton"}},{q="What happens after you confront Brother Paxton?",a="Paxton admits to holding the book and explains that he cannot finish duplicating it without replenishing his writing materials, sending you out to gather ink supplies.",al={"next quest after paxton","what does paxton need"},sp=1}},ang={["profession:Mining"]="The object of your search, Margulf Blaggon's 'The Stresses of Iron', represents decades of hard-won dwarven mining knowledge carved directly out of the mountains of Khaz Modan.",["race:Dwarf"]="The tome being sought after is dwarven craft at its finest, penned by fellow miner Margulf Blaggon and revered enough for Stormwind's scribes to covet copies.",["class:Priest"]="Visiting Brother Paxton offers a glimpse into the scholarly duties of the Northshire clerics, who laboriously copy tomes by hand to preserve knowledge for the order.",["faction:Alliance"]="This task highlights the cultural exchange binding Stormwind and Ironforge, as human libraries actively preserve and study foundational dwarven texts."},kw={"brother paxton","margulf blaggon","milton sheaf","northshire abbey","stormwind library","the stresses of iron","transcription"},rel={"npc:milton-sheaf","subzone:northshire-abbey","quest:343","quest:345","subzone:library-ironforge"},m={start="Milton Sheaf",["end"]="Brother Paxton",level="24",faction="Alliance",id=344},src={"Brother Paxton (quest)"}}
E["quest:345"] = {t="quest",n="Ink Supplies",z="stormwind",s="Ink Supplies is an Alliance errand on behalf of Brother Paxton, a monastic scribe residing in Northshire Abbey. Needing a specialized mineral component to brew his fast-drying ink, Paxton sends an adventurer east into the embattled township of Lakeshire to secure Rethban ore from Foreman Oslow.",h="Ink Supplies is an Alliance errand on behalf of Brother Paxton, a monastic scribe residing in Northshire...",sec={{t="A Scribe's Formula",b="Brother Paxton takes immense pride in his literary craft, refusing to rely on standard inks for vital transcriptions like The Stresses of Iron. Instead, he brews a custom recipe noted for its resistance to smearing and its rapid drying time. The formula's chief flaw is that it dries out even in the pot if left unattended too long. Replenishing his stock requires raw Rethban iron ore, a distinctive mineral mined in the rocky reaches of the Redridge Mountains.",sp=0},{t="A Town Under Siege",b="When travelers arrive in Lakeshire carrying Paxton's humble requisition, they find the settlement in no condition to indulge a distant monk. Foreman Oslow oversees the strained town laborers, who are wholly occupied with shoring up barricades, rebuilding ruined structures, and bracing against ongoing raids from the Blackrock orcs. Oslow has neither the men nor the patience to dig ore for Stormwind's scribes, leaving outsiders to brave the perilous Rethban Caverns on their own.",sp=0}},faq={{q="Why does Brother Paxton need iron ore for ink?",a="Brother Paxton utilizes a proprietary recipe designed to produce permanent, smear-proof script that dries almost immediately. Ground Rethban iron ore provides the crucial mineral pigment and setting qualities necessary for his distinct ink.",al={"why iron for ink","paxton ore ink","brother paxton ink recipe"}},{q="Who is Foreman Oslow?",a="Foreman Oslow is the head overseer in charge of civic construction and repairs in Lakeshire. With the town under constant pressure from Blackrock orcs, he directs the fortification and rebuilding efforts along the lake.",al={"foreman oslow","oslow lakeshire","who is oslow"}},{q="Where does Brother Paxton send you?",a="Paxton sends you east from Elwynn Forest to Lakeshire, the central township of the Redridge Mountains, to track down Foreman Oslow.",al={"ink supplies destination","where is oslow","where do i go for ink supplies"}},{q="Why won't Foreman Oslow just give you the ore?",a="Lakeshire is facing relentless attacks from Blackrock clan orcs. Oslow's crew is completely committed to repairing damaged buildings and fortifying the town's perimeter, leaving no hands to spare for mining errands.",al={"why no ore","oslow refuses ore","why oslow mad"}},{q="What book is Brother Paxton attempting to copy?",a="He is in the middle of transcribing a volume titled The Stresses of Iron, a task brought to a halt when his previous batch of quick-drying ink solidified in its container.",al={"paxton book","what is paxton copying","the stresses of iron"}},{q="What happens after speaking with Foreman Oslow?",a="Oslow tells you that if you want Rethban iron ore, you will have to harvest it yourself from the dangerous Rethban Caverns north of Lake Everstill.",al={"next quest after ink supplies","what next after oslow","follow up ink supplies"}}},ang={["class:Priest"]="Brother Paxton's quest chain is part of the early trials tied to the virtues of Fortitude, guiding acolytes of the Holy Light to aid the clergy's scholarly duties.",["profession:Mining"]="The quest highlights Rethban iron ore, a localized mineral deposit nestled high in the crags of Redridge.",["faction:Alliance"]="The journey shows the stark contrast between the tranquil seclusion of Northshire Abbey and the violent frontier crisis consuming Lakeshire."},kw={"brother paxton","foreman oslow","ink supplies","lakeshire","northshire abbey","redridge mountains","rethban ore","the stresses of iron"},rel={"npc:foreman-oslow","quest:344","quest:343","subzone:lakeshire","zone:redridge"},m={start="Brother Paxton",["end"]="Foreman Oslow",level="24",faction="Alliance",id=345},src={"Ink Supplies"}}
E["quest:346"] = {t="quest",n="Return to Kristoff",z="stormwind",s="Return to Kristoff concludes Brother Kristoff's search for the elusive tome, The Stresses of Iron. After journeying through Redridge to fetch ore for special ink and waiting on Northshire's scribes, the adventurer finally brings the borrowed volume back to the Cathedral of Light in Stormwind.",h="Return to Kristoff concludes Brother Kristoff's search for the elusive tome, The Stresses of Iron.",sec={{t="A Long-Delayed Return",b="Brother Kristoff, stationed in Stormwind's Cathedral Square, needed access to a specialized metallurgical volume known as The Stresses of Iron. The pursuit of the work sent couriers across human lands, leading first to the Royal Library in Stormwind Keep and then deep into Northshire Abbey. At the abbey, Brother Paxton was busily copying the text by hand, delayed by a shortage of Rethban ore needed to craft scribe's ink. With the ore retrieved and the copy complete, Paxton finally surrenders the original volume for its return to the city.",sp=0},{t="The Labor of Scribes",b="In a kingdom constantly pressed by outside threats, the quiet work of Northshire's copyists remains vital to preserving civic and spiritual lore. Brother Paxton's request to apologize to Librarian Milton Sheaf highlights how thin the abbey's resources have worn. Valuable books must be meticulously duplicated stroke by stroke using mineral-rich inks before they can be released back into Stormwind's care, turning a simple book request into an arduous logistical errand.",sp=0}},faq={{q="What is the book The Stresses of Iron about?",a="The Stresses of Iron is a treatise on metallurgy and metalworking. Brother Kristoff sought it out for study in Cathedral Square, while the scribes at Northshire Abbey required an exact copy to preserve its knowledge.",al={"what is stresses of iron","stresses of iron book","what book is kristoff looking for"}},{q="Why was the book at Northshire Abbey?",a="The Royal Library lent the book to Brother Paxton so he could produce an illuminated copy for Northshire Abbey's archives. Scribes there preserve important texts by hand, but Paxton's progress stalled when he ran short of Rethban ore for specialized ink.",al={"why was paxton holding the book","why was it in northshire"}},{q="Who is Brother Kristoff?",a="Brother Kristoff is a member of the Clergy of the Holy Light stationed in Cathedral Square outside the Cathedral of Light in Stormwind. He requested the book and offers spiritual blessings in gratitude.",al={"who is kristoff","kristoff stormwind"}},{q="Who is Milton?",a="Milton Sheaf is the head librarian residing in Stormwind Keep's Royal Library. He originally permitted the loan of The Stresses of Iron and grew impatient over the lengthy delay in its return.",al={"who is librarian milton","milton sheaf"}},{q="Where does this quest chain begin?",a="The chain begins in Stormwind's Cathedral Square with Brother Kristoff in the quest Speaking of Fortitude, which leads to Librarian Milton Sheaf, then Northshire Abbey, and into Redridge Mountains before concluding back with Kristoff.",al={"how to start speaking of fortitude","quest chain start"}},{q="Does this quest have any follow-ups?",a="Return to Kristoff marks the end of the Speaking of Fortitude questline. Once you deliver The Stresses of Iron, Brother Kristoff offers his thanks and a blessing of the Light, resolving the matter.",al={"what comes after return to kristoff","is there a next quest"}}},ang={["class:Priest"]="A simple errand for the clergy showcases how the Church of the Holy Light maintains, preserves, and distributes crucial scholarship throughout the kingdom.",["faction:Alliance"]="Even seemingly trivial academic exchanges rely on safe roadways between Stormwind Keep, Northshire, and the embattled Redridge Mountains."},kw={"brother kristoff","brother paxton","cathedral square","milton sheaf","northshire abbey","return to kristoff","stormwind","the stresses of iron"},rel={"npc:brother-kristoff","quest:344","quest:343","subzone:cathedral-square","topic:light"},m={start="Brother Paxton",["end"]="Brother Kristoff",level="24",faction="Alliance",id=346},src={"Return to Kristoff"}}
E["quest:347"] = {t="quest",n="Rethban Ore",z="stormwind",s="Foreman Oslow directs adventurers into the Rethban Caverns of Redridge to retrieve a peculiar dark mineral. While too soft to forge reliable armor or weapons, its unique pigmentation makes it indispensable to the scribes of Northshire Abbey for crafting specialized ink.",h="Foreman Oslow directs adventurers into the Rethban Caverns of Redridge to retrieve a peculiar dark mineral.",sec={{t="A Curious Mineral",b="Rethban Ore is named after its discoverer, Bart Rethban. Unlike common iron or copper, this ore holds little value at an armorer's anvil—when smelted down, the resulting metal lacks the tensile strength required for sturdy weapons or plate. Its true value lies in its raw, dark, flat coloration, which monks and scribes prize as a pigment base for rich manuscript dyes.",sp=0},{t="Contested Caverns",b="The primary deposits of the mineral lie within the Rethban Caverns, nestled in the northern mountains of Redridge. Unfortunately for the stoneworkers of Lakeshire, the local miners have abandoned the cavern. A fierce band of Redridge gnolls has seized the tunnels, putting gnoll drudgers to work chipping away at the rocky veins for their own crude purposes.",sp=0},{t="Preserving the Word",b="Brother Paxton, a monk residing within the quiet walls of Northshire Abbey, depends on this pigment to reproduce historic texts. His current undertaking—a transcribed copy of the treatise 'The Stresses of Iron'—has ground to an abrupt halt without the proper dye, sending messengers and adventurers deep into gnoll-infested territory to secure the raw stone.",sp=0}},faq={{q="What is Rethban Ore used for?",a="While it is too weak when smelted to forge durable weapons or armor, its dark, flat color makes it an excellent base pigment for inks and dyes. Scribes such as Brother Paxton in Northshire Abbey rely on it to illuminate and transcribe historic manuscripts.",al={"why do we need rethban ore","rethban ore purpose","what is rethban ore for"}},{q="Who was Bart Rethban?",a="Bart Rethban was the explorer and prospector who originally discovered the dark ore veins in the northern mountains of Redridge, giving both the mineral and the Rethban Caverns their name.",al={"who discovered rethban ore","bart rethban lore"}},{q="Why hasn't Lakeshire mined the ore recently?",a="Foreman Oslow and the town's workers are completely consumed by defending Lakeshire against Blackrock orc incursions. To make matters worse, Redridge gnolls moved into the Rethban Caverns, forcing civilian miners out.",al={"why isn't oslow mining it","why are the mines abandoned"}},{q="What book is Brother Paxton copying?",a="Brother Paxton is diligently copying an informational work titled 'The Stresses of Iron'. He requires the dark dye produced from Rethban Ore to finish transcribing the text for the abbey's library.",al={"what book is paxton writing","paxton manuscript"}},{q="Why do gnolls want the ore?",a="The Redridge gnolls have set their drudgers to dig throughout the caverns. While gnolls rarely keep extensive written records, they covet metal deposits for crude implements, trading, or simply fortifying their mountain warrens against intruders.",al={"why are gnolls mining","gnoll drudgers rethban"}},{q="Where does this quest chain lead next?",a="Once Brother Paxton receives the ore and finishes preparing his inks, he directs you back to Stormwind to report your success to Kristoff, concluding the errand for Northshire's scribes.",al={"what quest comes after rethban ore","return to kristoff next"},sp=1}},ang={["profession:Mining"]="Miners can extract Rethban Ore directly from cavern veins with a pick, bypassing the need to scavenge raw chunks from gnoll drudgers.",["faction:Alliance"]="The errand highlights how stretched the Kingdom of Stormwind's supply lines are, requiring monastery scribes to rely on traveling adventurers to fetch basic writing supplies from war zones.",["race:Human"]="Preserving historical manuscripts at Northshire Abbey is a sacred duty for Stormwind's scholars, who work to restore knowledge lost during the First and Second Wars."},kw={"bart rethban","brother paxton","foreman oslow","northshire abbey","redridge drudgers","rethban caverns","rethban ore","stresses of iron"},rel={"subzone:rethban-caverns","npc:foreman-oslow","quest:344","subzone:northshire-abbey","quest:345","quest:346","topic:gnoll"},m={start="Foreman Oslow",["end"]="Brother Paxton",level="24",faction="Alliance",id=347},src={"Rethban Ore (quest)"}}
E["quest:350"] = {t="quest",n="Look to an Old Friend",z="stormwind",s="Master Mathias Shaw directs an investigator to seek out an unconventional contact in Stormwind's Trade District. Because noble corruption shields powerful traitors from standard legal justice, the spymaster reluctantly relies on the intelligence network of the city's finest cheesemonger.",h="Master Mathias Shaw directs an investigator to seek out an unconventional contact in Stormwind's Trade...",sec={{t="Above the Law",b="Following the discovery that Lord Gregor Lescovar and the assassin Marzon the Silent Blade maintain direct ties to the Defias Brotherhood, Master Mathias Shaw faces an intelligence dead end. With Edwin VanCleef dead in the Deadmines and Bazil Thredd eliminated in the Stockade, no living bandit leaders remain to testify. Furthermore, Lescovar's aristocratic status and extensive political ties place him effectively beyond the reach of standard Royal Guard justice and formal SI:7 warrants.",sp=0},{t="The Cheesemonger's Ear",b="To pierce the defenses of a Stormwind noble, Shaw directs his agent to Elling Trias, the proprietor of Trias' Cheese in the Trade District. While outwardly a temperamental merchant known across the city for imported wedges and wheels, Trias runs an independent network of eyes and ears that rivals SI:7 itself. Shaw loathes calling upon his former colleague, but unmasking treason inside Stormwind Keep demands methods beyond official royal channels.",sp=1}},faq={{q="Why does Mathias Shaw send you to a cheese merchant?",a="Elling Trias is far more than a simple cheesemonger. While he runs Trias' Cheese near the Trade District entrance, he maintains an independent, far-reaching underground intelligence web. Shaw loathes asking him for assistance, but SI:7 requires unconventional means to move against a nobleman who sits out of reach of standard law enforcement.",al={"why elling trias","why talk to trias","why cheese shop"}},{q="Why can't Mathias Shaw simply arrest Lord Lescovar?",a="Lord Lescovar is a high-ranking Stormwind nobleman with deep connections across the House of Nobles. With Edwin VanCleef slain in the Deadmines and Bazil Thredd eliminated in the Stockade, SI:7 has no surviving high-ranking Defias witnesses whose confessions would legally stick to an aristocrat.",al={"why not arrest lescovar","why cant shaw arrest lescovar","why lescovar untouchable"}},{q="Who is Marzon the Silent Blade?",a="Marzon the Silent Blade is a lethal operative working closely with the Defias conspiracy and maintaining secret communications with Lord Lescovar inside Stormwind's court.",al={"who is marzon","marzon silent blade role"}},{q="Why does Trias mention Deathwing when you speak to him?",a="When informed of the conspiracy involving the Defias Brotherhood, Trias responds with bitter sarcasm, scoffing that next you will be telling him that the long-lost Black Dragon Aspect Deathwing is still alive and assailing the kingdom.",al={"why does trias say deathwing","trias deathwing line","deathwing attacking stormwind"}},{q="What happens after meeting with Elling Trias?",a="After listening to the full account of the conspiracy, Trias begins planning a quiet infiltration of Stormwind Keep to corner Lord Lescovar without alerting the rest of the noble court.",al={"next quest after trias","where to after look to an old friend"},sp=1},{q="Where is Elling Trias located?",a="Elling Trias can be found inside his shop, Trias' Cheese, located in Stormwind's Trade District just off the main road entering from the city gates.",al={"trias location","where is trias cheese"}}},ang={["class:Rogue"]="The quiet rivalry between Mathias Shaw and Elling Trias illustrates the fractured nature of Stormwind's covert operatives, where street-level informants often possess better leverage than the crown's official intelligence division.",["faction:Alliance"]="This task demonstrates how the corruption of the House of Nobles paralyzes Stormwind's internal security while King Varian Wrynn remains missing."},kw={"defias","elling trias","lescovar","marzon","mathias shaw","stormwind","trade district","trias cheese"},rel={"npc:elling-trias","quest:2745","quest:65","topic:defias-brotherhood","subzone:trade-district","topic:stormwind-kingdom","npc:deathwing"},m={start="Master Mathias Shaw",["end"]="Elling Trias",level="31",faction="Alliance",id=350},src={"Look to an Old Friend"}}
E["quest:373"] = {t="quest",n="The Unsent Letter",z="stormwind",s="Found upon the corpse of Edwin VanCleef deep within the Deadmines, this sealed missive is addressed to Baros Alexston, the City Architect of Stormwind. Its delivery pulls back the curtain on the personal grievances and history binding the Defias leader to the city's master builders.",h="Found upon the corpse of Edwin VanCleef deep within the Deadmines, this sealed missive is addressed to Baros...",sec={{t="A Message From the Grave",b="When Edwin VanCleef falls aboard his juggernaut in the subterranean depths of Moonbrook, he leaves behind more than a broken rebellion. Tucked into his clothing is a newly penned, sealed letter. Strangely, the Defias kingpin did not address it to one of his criminal lieutenants or shadowy financiers, but to an official inside the heart of the kingdom he swore to destroy: Baros Alexston, Stormwind's City Architect.",sp=0},{t="Architects of Old",b="Carrying the correspondence to City Hall in Cathedral Square reveals a shared past between the architect and the outlaw. Alexston, once a peer of VanCleef during the ambitious reconstruction of Stormwind following the Second War, reacts with disbelief at the news of Edwin's death. Though horrified by the bandit leader's descent into indiscriminate violence, Alexston acknowledges the root of his bitter crusade: VanCleef was an uncompromising idealist consumed by betrayal, one whose rightful grievance morphed into destructive madness.",sp=1}},faq={{q="Where do I find the Unsent Letter?",a="The item An Unsent Letter drops from Edwin VanCleef, the final boss found aboard the ironclad ship within the Deadmines instance in Westfall.",al={"unsent letter drop","how to get unsent letter","who drops unsent letter"}},{q="Who is Baros Alexston?",a="Baros Alexston is the City Architect of Stormwind. He resides in the City Hall building, located along the northeast edge of Cathedral Square.",al={"baros alexston location","where is baros alexston","city architect stormwind"}},{q="Why was Edwin VanCleef writing to the City Architect?",a="VanCleef and Alexston were fellow stonemasons who worked together rebuilding Stormwind after the Second War. Even after turning to banditry, VanCleef still viewed Alexston as a former peer connected to the work and betrayal of the Stonemasons Guild.",al={"why write baros","vancleef and baros relationship","letter to architect"}},{q="What does the letter reveal about VanCleef?",a="Upon reading it, Alexston notes that VanCleef remained an idealist and a romantic to the end, but one thoroughly poisoned by vengeance. VanCleef believed his violent war against the kingdom was entirely justified by the ruling nobility's refusal to pay the masons.",al={"vancleef motive","what does the letter say","letter lore"}},{q="Do I need to finish the main Defias Brotherhood chain before turning this in?",a="No. While the extended Defias Brotherhood questline leads directly to VanCleef, the Unsent Letter can be looted and completed by any Alliance adventurer who defeats him, regardless of prior quest progression.",al={"quest prerequisite","can i do unsent letter early","do i need defias chain"}},{q="Where does this questline lead next?",a="Delivering the letter prompts Alexston to direct you toward the Stockade to interrogate an imprisoned Defias leader, Bazil Thredd, beginning an investigation into conspirators within Stormwind's own government.",al={"next quest after unsent letter","lescovar chain","what follows baros alexston"},sp=1}},ang={["race:Human"]="For humans of Stormwind, this letter exposes the lingering wounds of the kingdom's reconstruction, proving that the banditry plaguing Westfall was born directly out of political betrayals within their own capital.",["class:Rogue"]="VanCleef was legendary among rogues for his skill as a peerless fighter and organizer; recovering his private correspondence offers a stark look at how easily an operative's discipline can curdle into suicidal obsession.",["faction:Alliance"]="Delivering the letter provides crucial evidence that the Defias threat is not merely a regional outlaw uprising, but a targeted vendetta with deep ties to Stormwind's civic administration."},kw={"baros alexston","cathedral square","city hall","deadmines","defias","edwin vancleef","stonemasons","unsent letter"},rel={"npc:baros-alexston","npc:edwin-vancleef","topic:defias-brotherhood","quest:65","subzone:cathedral-square","zone:deadmines","topic:stormwind-kingdom"},m={start=":An Unsent Letter",["end"]="Baros Alexston",level="22",faction="Alliance",id=373},src={"The Unsent Letter"}}
E["quest:3765"] = {t="quest",n="The Corruption Abroad",z="stormwind",s="Argos Nightwhisper, a night elf envoy visiting Stormwind, seeks capable adventurers to cross the Great Sea and aid his brother in northern Kalimdor. His brother Gershala studies spreading ecological decay in Darkshore, where fresh hands are desperately needed.",h="Argos Nightwhisper, a night elf envoy visiting Stormwind, seeks capable adventurers to cross the Great Sea...",sec={{t="An Envoy in the Human Capital",b="While Stormwind contends with internal turmoil and regional unrest, representatives from the distant kaldorei lands can be found wandering its stone streets. Argos Nightwhisper came seeking seasoned champions willing to look beyond human borders. The kaldorei are relatively new allies to the Eastern Kingdoms, and formal military aid is scarce, leaving family members and researchers to recruit whatever independent champions answer the call.",sp=0},{t="The Call of Darkshore",b="The destination Argos points toward is Auberdine, a misty port town resting on the fog-shrouded coast of Darkshore. There, his brother Gershala conducts vital research into an ominous malaise afflicting the local wildlife and flora. Crossing the ocean to answer the summons requires an arduous trek northward through the wetlands and across the Great Sea, marking a traveler's first real foray into the ancient wilderness of Kalimdor.",sp=0}},faq={{q="Who is Argos Nightwhisper?",a="Argos Nightwhisper is a night elf visitor staying in Stormwind. He serves as an emissary of sorts for his family, specifically recruiting experienced Alliance adventurers to travel across the sea and assist his brother Gershala in Darkshore.",al={"argos","argos nightwhisper","who gives the corruption abroad"}},{q="Where is Gershala Nightwhisper located?",a="Gershala Nightwhisper is stationed in Auberdine, a coastal night elf settlement situated along the western shores of Darkshore in northern Kalimdor.",al={"gershala location","where is gershala","turn in corruption abroad"}},{q="Why does Gershala need help?",a="Gershala is investigating an unnatural corruption spreading across Darkshore's wilderness, infecting the local wildlife, water sources, and vegetation. He requires seasoned champions to help gather samples and investigate the root cause.",al={"why help gershala","what is wrong in darkshore"}},{q="How do I get to Auberdine from Stormwind?",a="Travel north from Stormwind through the Deeprun Tram to Ironforge, journey across Dun Morogh and Loch Modan to the Wetlands, and board the harbor vessel at Menethil Harbor bound for Auberdine in Darkshore.",al={"how to reach auberdine","travel to darkshore from stormwind"}},{q="Can I do this quest if I already went to Darkshore?",a="If you already visited Auberdine and began Gershala's task, 'Researching the Corruption', directly from him, you can no longer pick up or complete this introductory summons from Argos.",al={"missed the corruption abroad","can i still do corruption abroad"}},{q="What is the relationship between Argos and Gershala?",a="Argos and Gershala Nightwhisper are brothers. While Gershala remains on the front lines studying the blight in Darkshore, Argos traveled across the sea to seek out capable allies in Stormwind.",al={"argos and gershala","are argos and gershala related"}}},ang={["faction:Alliance"]="This mission demonstrates the fledgling bonds tying the night elves of Kalimdor to the human kingdom of Stormwind across the sea.",["race:NightElf"]="For night elves far from home, Argos provides a reminder of the troubles plaguing the ancestral forests of northern Kalimdor.",["race:Human"]="Venturing to Darkshore offers human adventurers their first glimpse of ancient kaldorei culture, far removed from the stone castles of Elwynn."},kw={"argos","auberdine","corruption","darkshore","gershala","nightwhisper","stormwind"},rel={"npc:argos-nightwhisper","npc:gershala-nightwhisper","quest:1275","subzone:auberdine","zone:darkshore","topic:stormwind-kingdom"},m={start="Argos Nightwhisper",["end"]="Gershala Nightwhisper",level="24",faction="Alliance",id=3765},src={"The Corruption Abroad"}}
E["quest:389"] = {t="quest",n="Bazil Thredd",z="stormwind",s="Following the discovery of an unsent letter found on Edwin VanCleef, City Architect Baros Alexston directs investigators to Bazil Thredd, the Defias leader's right-hand man. Thredd is currently locked beneath the streets of Stormwind in the high-security Stockade prison, holding crucial insight into the Brotherhood's lingering plots.",h="Following the discovery of an unsent letter found on Edwin VanCleef, City Architect Baros Alexston directs...",sec={{t="A Bitter History",b="When presented with evidence from the Deadmines, Baros Alexston admits his own shared history with Edwin VanCleef. Both were leading craftsmen in the Stonemasons Guild tasked with rebuilding Stormwind from the ashes of the First and Second Wars. After finishing the kingdom's magnificent white walls and towers, the nobility refused to pay the masons their promised wages. While select senior members were offered cushy bureaucratic posts to quiet them, VanCleef refused to abandon the rank-and-file laborers, leading a violent riot out of the city and founding the Defias Brotherhood.",sp=0},{t="A Turn to the Stockade",b="To decipher VanCleef's full design and uncover what the Brotherhood still plans against Stormwind, Alexston points investigators to Bazil Thredd. Once VanCleef's chief lieutenant during the mason uprising, Thredd was captured and confined to the city's prison beneath the canals of the Mage Quarter. However, reaching him proves difficult: upon arriving at the prison gates, Warden Thelwater reveals that the inmates have orchestrated a full-blown rebellion, turning the Stockade into an active warzone.",sp=1}},faq={{q="Who is Bazil Thredd?",a="Bazil Thredd served as Edwin VanCleef's primary lieutenant within the Stonemasons Guild and later the early Defias uprising. Following his capture by the Stormwind authorities, he was imprisoned deep within the Stockade.",al={"bazil thredd lore","who is thredd","thredd backstory"}},{q="Why does Baros Alexston send you to speak with Thredd?",a="After examining the unsent letter recovered from VanCleef's body, Alexston realizes the threat to Stormwind extends beyond the Deadmines. He believes Thredd, as VanCleef's former right-hand man, understands the inner workings and remaining schemes of the Brotherhood better than anyone else.",al={"why talk to thredd","baros alexston motive","why go to stockade"}},{q="Why was the Stonemasons Guild betrayed?",a="After the masons completed the massive reconstruction of Stormwind following the Second War, the House of Nobles refused to honor their financial agreements, leaving the laborers unpaid and destitute. VanCleef rejected quiet bribes to silence him and instead led a riot out of the city gates.",al={"why werent stonemasons paid","defias motive","stonemason riot reason"}},{q="Where is the Stockade located?",a="The Stockade entrance is tucked along the canals in the northeastern section of the Mage Quarter in Stormwind. Warden Thelwater stands just inside the threshold, attempting to hold the line against escaping prisoners.",al={"where is stockade","stockade entrance","how to find warden thelwater"}},{q="What is happening inside the Stockade when you arrive?",a="The prison has descended into outright chaos. Bazil Thredd and his fellow inmates have overpowered the guards, unlocked the holding cells, and seized control of the lower halls, leaving Warden Thelwater struggling to keep the riot from spilling out into the streets of Stormwind.",al={"why is thelwater mad","stockade crisis","what happened in the stockade"}},{q="How did Baros Alexston avoid joining the Defias?",a="Unlike VanCleef, who refused any compromise and chose armed rebellion, Alexston was among the senior guild craftsmen who accepted government employment from the kingdom, eventually rising to become the City Architect.",al={"is baros defias","baros alexston stonemason"}}},ang={["race:Human"]="The rebellion of the Stonemasons Guild highlights the deep, unhealed political fracture between Stormwind's ruling nobility and the commoners who built the city with their own hands.",["faction:Alliance"]="Even with Edwin VanCleef slain, the Defias threat reaches directly into the capital's heart through the unsecured cells of the Stockade.",["class:Rogue"]="Thredd represents the hardened, organized underworld branch of the Defias who traded construction hammers for shanks and street violence."},kw={"baros alexston","bazil thredd","defias","edwin vancleef","stonemasons guild","stormwind","the stockade","unsent letter","warden thelwater"},rel={"npc:baros-alexston","npc:warden-thelwater","zone:stockade","quest:373","quest:391","topic:stonemasons-guild","topic:stormwind-kingdom","subzone:mage-quarter"},m={start="Baros Alexston",["end"]="Warden Thelwater",level="22",faction="Alliance",id=389},src={"Bazil Thredd (quest)"}}
E["quest:392"] = {t="quest",n="The Curious Visitor",z="stormwind",s="Following the containment of the Stockade uprising, Warden Thelwater reveals a troubling discovery regarding the insurgent leader, Bazil Thredd. For months before the riot, Thredd had been receiving regular visits from a mysterious man holding legitimate papers under the name Maelik.",h="Following the containment of the Stockade uprising, Warden Thelwater reveals a troubling discovery regarding...",sec={{t="A Breach in Protocol",b="Bazil Thredd spent the early years of his captivity in the Stormwind Stockade abandoned by his former comrades, or so the guards believed. That changed months before the prison riot, when a quiet visitor began meeting with Thredd once or twice a week. He passed every inspection, carried authorized paperwork, and gave his name as Maelik. Warden Thelwater, realizing these visits likely coordinated the bloody uprising that followed, gathers a physical description and sends adventurers to consult City Architect Baros Alexston to uncover who this visitor truly was.",sp=0},{t="Ties to the Stonemasons",b="Baros Alexston, who worked closely alongside Edwin VanCleef and the Stonemasons Guild before their rebellion, finds himself drawn into the investigation. While the name Maelik rings no bells and the physical description could match countless former craftsmen, the fact that the visitor possessed valid bureaucratic clearance points to something far deeper than mere common criminals slipping past guards. The mystery exposes how deeply embedded Defias sympathizers and agents remain within Stormwind's civic infrastructure.",sp=1}},faq={{q="Who is the curious visitor mentioned in the quest?",a="The visitor claimed his name was Maelik. He visited the prisoner Bazil Thredd once or twice a week for months leading up to the Stockade riot, carrying seemingly legitimate identification papers.",al={"who is maelik","thredd visitor","curious visitor identity"}},{q="Why does Warden Thelwater send you to Baros Alexston?",a="Baros Alexston is Stormwind's City Architect and once worked alongside Edwin VanCleef and the Stonemasons Guild. Because the Defias originated from the Stonemasons, Thelwater hopes Alexston can recognize the visitor from his past guild contacts.",al={"why baros alexston","who is baros","turn in to baros"}},{q="How did Maelik enter the Stockade without being caught?",a="Maelik presented legitimate paperwork that fully cleared prison security checks. The guards had no legal cause to deny him entry, suggesting either a bureaucratic error or corrupt officials aiding his passage from inside the kingdom's administration.",al={"how did visitor get in","maeliks papers","stockade security failure"}},{q="What role did Bazil Thredd play in the prison riots?",a="Bazil Thredd was an imprisoned leader of the Defias Brotherhood inside the Stockade. He organized and led the violent uprising among the inmates, a coordinated effort likely orchestrated through his visits with Maelik.",al={"who is bazil thredd","what did thredd do"}},{q="What happens after Baros Alexston reads the description?",a="Alexston does not recognize the name Maelik or the physical description provided by Thelwater. However, acknowledging that the visitor must be connected within the city, he agrees to investigate further to uncover the stranger's true identity.",al={"does baros recognize maelik","what happens next"}},{q="Why is the visitor important to the investigation of the Defias?",a="The regular visits demonstrate that the Stockade riot was not a spontaneous outburst of lawless rage, but a planned Defias plot enabled by someone with high-level access to Stormwind's official documentation.",al={"defias conspiracy","why does the visitor matter"}}},ang={["race:Human"]="The revelation of forged or sanctioned entry papers exposes the deep vulnerabilities and potential corruption festering inside the Kingdom of Stormwind's own government.",["faction:Alliance"]="Tracking down Bazil Thredd's mysterious contact is critical to rooting out Defias sympathizers operating openly inside the capital city.",["class:Rogue"]="The quiet visitor's ability to walk straight through a maximum-security prison with proper documentation highlights the subtlety and craft of master infiltrators."},kw={"baros alexston","bazil thredd","curious visitor","defias","maelik","stockade","stonemasons","warden thelwater"},rel={"quest:391","npc:warden-thelwater","npc:baros-alexston","topic:defias-brotherhood","topic:stormwind-kingdom","quest:65"},m={start="Warden Thelwater",["end"]="Baros Alexston",level="29",faction="Alliance",id=392},src={"The Curious Visitor"}}
E["quest:393"] = {t="quest",n="Shadow of the Past",z="stormwind",s="Shadow of the Past is an Alliance investigation quest leading from City Architect Baros Alexston to Master Mathias Shaw, head of SI:7. Following inquiries into a mysterious visitor who spoke with the imprisoned Defias leader Bazil Thredd, the trail shifts from public construction scandals into Stormwind's covert intelligence network.",h="Shadow of the Past is an Alliance investigation quest leading from City Architect Baros Alexston to Master...",sec={{t="A Lead in the Shadows",b="After questioning Warden Thelwater regarding suspicious visitors to the Stockade's chief prisoner, Bazil Thredd, investigators hit a dead end with Baros Alexston. While the city architect cannot identify the mysterious figure, he points toward the one man whose business is knowing every secret whispered in the capital: Master Mathias Shaw, leader of the secretive intelligence agency SI:7.",sp=0},{t="Unmasking the Visitor",b="Delivering the sealed physical description to SI:7 headquarters in Old Town yields immediate results. Shaw quickly sees through the visitor's alias of 'Maelik.' Recognizing the marks of a professional killer who casts off names like cloaks, Shaw identifies him as an assassin frequently going by the moniker Marzon.",sp=1},{t="Treachery in the Nobility",b="Shaw reveals that Marzon is currently employed by Lord Gregor Lescovar, a Stormwind nobleman already notorious for deceit. The connection exposes a chilling reality: the criminal uprising of the Defias Brotherhood is not merely a distant rebellion in Westfall, but a conspiracy reaching deep into Stormwind's aristocratic halls.",sp=2}},faq={{q="Who sends you to Mathias Shaw?",a="Baros Alexston, the City Architect of Stormwind, directs you to Mathias Shaw after admitting he cannot identify the visitor described in the Stockade warden's notes. Alexston calls in an old personal favor from Shaw to get the spymaster's attention.",al={"who gives this quest","quest giver shadow of the past"}},{q="Where is Master Mathias Shaw located?",a="Master Mathias Shaw is located inside the SI:7 headquarters in Old Town, Stormwind. The building serves as the secretive nerve center for the crown's rogues, scouts, and intelligence officers.",al={"mathias shaw location","where is shaw","find mathias shaw"}},{q="Who was the mysterious visitor to the Stockade?",a="The visitor gave the name Maelik, but Mathias Shaw identifies him as a notorious assassin often known as Marzon. Shaw notes that professional killers use and discard aliases constantly, and Marzon is simply another mask.",al={"who is maelik","who is thredds visitor","who is the assassin"},sp=1},{q="Why is Lord Gregor Lescovar involved?",a="According to Mathias Shaw, the assassin Marzon is on the payroll of Lord Gregor Lescovar, a Stormwind noble known for crooked dealings. This links the imprisoned Defias leadership directly to Stormwind's aristocracy.",al={"who does marzon work for","lescovar connection"},sp=1},{q="What does SI:7 stand for?",a="SI:7 stands for Stormwind Intelligence, 7th Division. It is the covert operations and espionage arm of the Kingdom of Stormwind, gathering intelligence and executing black-ops missions at home and abroad.",al={"what is si7","si:7 meaning"}},{q="Why does Baros Alexston have pull with SI:7?",a="Baros Alexston mentions that Mathias Shaw owes him a favor, though he deliberately declines to share the details. As the city's chief architect, Alexston likely holds knowledge of Stormwind's subterranean routes, secret passages, and building layouts that proved invaluable to the spy network.",al={"why does shaw owe baros","baros and shaw connection"}}},ang={["class:Rogue"]="Reporting to Master Mathias Shaw in Old Town offers rogues a direct look at the pinnacle of Alliance tradecraft and political surveillance.",["faction:Alliance"]="This leg of the investigation marks the exact point where low-level Defias banditry ties directly into the corrupt nobility of Stormwind City.",["race:Human"]="For humans of Stormwind, this assignment exposes how fractured the kingdom's ruling class has become during King Varian Wrynn's absence."},kw={"baros alexston","bazil thredd","gregor lescovar","maelik","marzon","mathias shaw","shadow of the past","si:7","stormwind"},rel={"npc:mathias-shaw","npc:baros-alexston","quest:392","quest:350","quest:2300","subzone:old-town","topic:stormwind-kingdom"},m={start="Baros Alexston",["end"]="Master Mathias Shaw",level="29",faction="Alliance",id=393},src={"Shadow of the Past (quest)"}}
E["quest:394"] = {t="quest",n="The Head of the Beast",z="stormwind",s="Following the assassination of the treacherous Lord Gregor Lescovar, this assignment directs you from Elling Trias to Master Mathias Shaw in Old Town. Reporting the death of Lescovar cements your standing with Stormwind's clandestine intelligence network.",h="Following the assassination of the treacherous Lord Gregor Lescovar, this assignment directs you from Elling...",sec={{t="A Matter Resolved",b="With Lord Lescovar struck down before his conspiracies against the realm could bear fruit, the immediate danger to Stormwind's leadership has been severed. Cheese merchant and veteran operative Elling Trias immediately directs you away from the crime scene and into the shadows of Old Town, cautioning you not to let courtly praise turn your head.",sp=1},{t="Reporting to the Spymaster",b="In the hidden chambers of Old Town, Master Mathias Shaw oversees the kingdom's covert apparatus through SI:7. Receiving word of Lescovar's demise, Shaw recognizes your skill and ruthlessness, warmly praising your efficiency while acknowledging that true power in Stormwind does not always sit openly in the palace throne room.",sp=0}},faq={{q="What is the purpose of this quest?",a="This brief interlude tasks you with traveling from Elling Trias to Master Mathias Shaw in Stormwind's Old Town to confirm that Lord Gregor Lescovar has been slain.",al={"head of the beast quest","what do i do in head of the beast"}},{q="Who is Mathias Shaw?",a="Mathias Shaw is the Master of SI:7, Stormwind's secretive intelligence agency and assassin guild, operating discreetly out of Old Town.",al={"shaw","master shaw","si7 leader"}},{q="Why does Elling Trias send you to Shaw instead of the palace guard?",a="Trias operates deep within Stormwind's intelligence apparatus. Because Lescovar was a prominent nobleman engaged in high treason, dealing with the aftermath requires secrecy rather than public scandal among the guard.",al={"why shaw not guards","why report to shaw"}},{q="What threat did Lescovar pose to Stormwind?",a="Lord Gregor Lescovar was actively plotting with subversive agents against the crown and the safety of the capital, betraying the realm from within the nobility.",al={"lescovar threat","what did lescovar do"}},{q="What happens after reporting Lescovar's death?",a="Mathias Shaw prepares to close the book on the conspiracy, sending you toward the final resolution of the subversive threat looming over Stormwind.",al={"next quest after head of the beast","what comes next"}},{q="Where can Mathias Shaw be found?",a="Mathias Shaw is located in the command building of SI:7, tucked away within Old Town in the eastern quarters of Stormwind City.",al={"shaw location","where is mathias shaw"}}},ang={["class:Rogue"]="Reporting directly to Mathias Shaw serves as a vital rite of passage, confirming your reliability to the leader of Stormwind's foremost shadow organization.",["faction:Alliance"]="Removing corrupt aristocrats from within Stormwind helps stabilize the realm during King Varian Wrynn's deeply destabilizing absence."},kw={"elling trias","head of the beast","lescovar","mathias shaw","old town","si:7","stormwind"},rel={"quest:434","quest:395","npc:mathias-shaw","npc:elling-trias","subzone:old-town","topic:stormwind-kingdom"},m={start="Elling Trias",["end"]="Master Mathias Shaw",level="31",faction="Alliance",id=394},src={"The Head of the Beast"}}
E["quest:395"] = {t="quest",n="Brotherhood's End",z="stormwind",s="Brotherhood's End marks the aftermath of the clandestine strike against Lord Gregor Lescovar within Stormwind Keep. With the treacherous nobleman dead, Master Mathias Shaw sends you to City Architect Baros Alexston, cautioning you to keep quiet about who actually struck the killing blow.",h="Brotherhood's End marks the aftermath of the clandestine strike against Lord Gregor Lescovar within Stormwind...",sec={{t="Loose Ends in the Shadows",b="Following the assassination of Lord Gregor Lescovar and his Defias handler, Marzon the Silent Blade, Master Mathias Shaw advises extreme caution. Eliminating a high-ranking nobleman inside the royal keep is fraught with political peril, even if Lescovar was neck-deep in treason. Shaw counsels you to share the broad strokes of the Defias conspiracy with Baros Alexston while keeping your own lethal role—and the involvement of the rogue cheese merchant Elling Trias—entirely off the record.",sp=1},{t="A Breath of Relief",b="Baros Alexston, the City Architect who oversaw the reconstruction of Stormwind, greets the news of Lescovar's demise with profound relief. Alexston and other prominent figures in the rebuilding effort were marked targets for Edwin VanCleef's vengeance after the Stonemasons were cast out without pay. With Lescovar silenced and the conspiracy disrupted, Alexston believes the immediate threat of retribution hanging over the kingdom's architects and nobility has finally passed.",sp=0}},faq={{q="What happens in Brotherhood's End?",a="Having eliminated Lord Gregor Lescovar in Stormwind Keep, you report back to Master Mathias Shaw at SI:7. Shaw instructs you to report to City Architect Baros Alexston, who is anxious to hear whether the Defias plot against the city's leaders has been foiled.",al={"what is brotherhoods end","brotherhoods end quest overview","brotherhoods end summary"}},{q="Why does Shaw tell you not to admit to killing Lescovar?",a="Lord Gregor Lescovar was a high nobleman in Stormwind's House of Nobles. Even though he was proven to be colluding with the Defias, publicly admitting to assassinating an aristocrat in the royal keep invites political scandal and retaliatory scrutiny. Shaw knows the cutthroat politics of the city and advises letting the deed remain unattributed.",al={"why hide lescovar death","why lie about lescovar","shaw advice lescovar"}},{q="Why should nobody mention Elling Trias?",a="Elling Trias poses as a simple cheese merchant in the Trade District, but in truth he is a veteran operative closely allied with SI:7 and a former rogue of great renown. Exposing his involvement in uncovering the conspiracy would blow his cover and compromise his extensive underground network.",al={"why hide trias","trias secret","selling trias cheese vendor"},sp=1},{q="Why was Baros Alexston personally concerned about the Defias?",a="Baros Alexston was the primary architect who helped design and oversee the reconstruction of Stormwind alongside Edwin VanCleef and the Stonemasons Guild. When the House of Nobles refused to pay the workers, the masons turned to banditry, and Alexston was placed squarely in their crosshairs as an architect of their betrayal.",al={"why does alexston care","baros alexston vancleef","alexston defias connection"}},{q="Does this quest mark the end of the Defias threat?",a="While it eliminates Edwin VanCleef's key sympathizer within the House of Nobles, it does not erase the Defias presence entirely. However, cutting off Lescovar strikes a critical blow to their infiltration of Stormwind's government and averts an immediate coup from within the city walls.",al={"is the defias destroyed","are the defias dead now","does brotherhood end finish defias"}},{q="Where does this investigation lead next?",a="Relieved by your success in eliminating the conspirators, Baros Alexston prepares a report on the Defias Brotherhood for the King and asks you to deliver it yourself at an audience in Stormwind Keep, in the quest An Audience with the King.",al={"what quest is next","next after brotherhoods end","who do i see next"},sp=1}},ang={["faction:Alliance"]="Unraveling the Defias conspiracy inside Stormwind Keep proves that the kingdom faces subversion not just from bandits across the countryside, but from within its own noble halls.",["class:Rogue"]="Mathias Shaw's warnings highlight the unspoken rule of SI:7 operations: deliver the kingdom's justice in silence, and never take public credit for a noble's blood.",["race:Human"]="For humans of Stormwind, this assignment closes the loop on the Stonemasons' rebellion that began in the city's streets years ago, securing justice without tearing the kingdom apart."},kw={"baros alexston","brotherhood's end","defias","elling trias","gregor lescovar","mathias shaw","si:7","stormwind keep"},rel={"quest:394","quest:396","npc:baros-alexston","topic:defias-brotherhood","topic:stormwind-kingdom","quest:65"},m={start="Master Mathias Shaw",["end"]="Baros Alexston",level="31",faction="Alliance",id=395},src={"Brotherhood's End"}}
E["quest:396"] = {t="quest",n="An Audience with the King",z="stormwind",s="\"An Audience with the King\" is the culmination of the long investigation into the Defias Brotherhood across Westfall and the Deadmines. Carrying the final report prepared by City Architect Baros Alexston, heroes journey to Stormwind Keep to lay the threat to rest before the realm's highest authority. Yet reaching the throne room reveals that royal affairs in the capital are not as straightforward as they seem.",h="\"An Audience with the King\" is the culmination of the long investigation into the Defias Brotherhood across...",sec={{t="A Royal Summons",b="After the defeat of Edwin VanCleef and the dismantling of the conspiracy beneath Moonbrook, the City Architect Baros Alexston compiles an official dossier for the Crown. Alexston insists that the adventurer who broke the guild's criminal enterprise should be the one honored before the monarch. Carrying the detailed report across the grand canals to Stormwind Keep, the messenger arrives expecting an audience with the sovereign of the realm.",sp=0},{t="An Empty Throne",b="Upon stepping into the royal court, the bearer of the report does not find King Varian Wrynn awaiting them. Instead, royal adviser Lady Katrana Prestor receives the dossier on the Crown's behalf. Prestor smoothly dismisses the monarch's absence, explaining that King Varian is away on an extended diplomatic mission and cannot offer congratulations in person. She accepts the report, commends the hero for sparing Stormwind from VanCleef's schemes, and offers a reward in the missing king's name, neatly filing away the grim truth of the brotherhood's uprising.",sp=1}},faq={{q="Why am I delivering this report instead of Baros Alexston?",a="Baros Alexston believes you earned the honor through your fieldwork. Since you tracked the Defias conspiracy through Westfall and stormed the Deadmines yourself, Alexston insists that you personally present the findings and receive the Crown's recognition.",al={"why deliver report","baros alexston report","audience with king delivery"}},{q="Where is King Varian Wrynn?",a="King Varian Wrynn is not present in Stormwind Keep. Officially, royal courtiers explain that the king is away on a secret diplomatic mission, leaving his young son Anduin on the throne under Highlord Bolvar Fordragon's regency.",al={"where is the king","why isnt varian here","where is varian wrynn","missing king"}},{q="Who actually takes the Defias report?",a="Lady Katrana Prestor receives you in the royal court. As a chief adviser to the throne, she accepts Baros Alexston's report, commends you for neutralizing Edwin VanCleef, and provides your reward on behalf of the Crown.",al={"who finishes the quest","who do i talk to in keep","who takes report"}},{q="Does this quest end the Defias Brotherhood questline?",a="Yes. This quest serves as the formal political conclusion to the extensive Defias storyline that begins in early Westfall and leads through the Deadmines dungeon.",al={"end of defias chain","is this the last defias quest","deadmines aftermath"}},{q="Why does Lady Katrana Prestor seem so dismissive of the king's absence?",a="Prestor projects absolute composure to maintain order in the royal court. By assuring visitors that King Varian is simply engaged in distant statecraft, the regency attempts to downplay anxiety regarding the Crown's whereabouts.",al={"why is prestor calm","prestor diplomatic mission","prestor excuse"}},{q="What happens to the Defias Brotherhood after this?",a="With Edwin VanCleef dead and their grand juggernaut project thwarted, the brotherhood's leadership is shattered. However, scattered brigands and remnants still plague Westfall, Redridge, and the alleys of Stormwind.",al={"are defias gone","what happens to defias now","is the brotherhood destroyed"}}},ang={["faction:Alliance"]="Delivering this report marks the resolution of one of the greatest internal crises threatening the Alliance's primary human kingdom.",["race:Human"]="For humans of Stormwind, this audience is a bittersweet milestone: it avenges the terror wrought across Westfall, yet quietly exposes the fragile, kingless state of the realm.",["class:Rogue"]="Stepping into the highest hall of power to report on the downfall of Edwin VanCleef serves as a stark reminder of how thin the line is between a royal operative and an outlaw guildmaster."},kw={"audience with the king","baros alexston","brotherhood's end","defias report","edwin vancleef","katrana prestor","stormwind keep","varian wrynn"},rel={"quest:395","quest:65","npc:baros-alexston","subzone:stormwind-keep","topic:defias-brotherhood","topic:stormwind-kingdom","topic:varian-wrynn"},m={start="Baros Alexston",["end"]="Lady Katrana Prestor",level="31",faction="Alliance",id=396},src={"An Audience with the King"}}
E["quest:397"] = {t="quest",n="You Have Served Us Well",z="stormwind",s="You Have Served Us Well is a warlock quest in Stormwind City. Undertaken on behalf of Zardeth of the Black Claw, warlock practitioners report back to the cabal beneath the Slaughtered Lamb to finalize their service and claim their reward.",h="You Have Served Us Well is a warlock quest in Stormwind City.",sec={{t="A Silence Bought in Shadows",b="Beneath the surface of Stormwind, practitioners of the dark arts operate under precarious tolerance. When noble authorities such as Lord Wishock threaten to expose or disrupt their covert studies, the coven acts decisively. By orchestrating Wishock's demise through a tainted draught, the warlocks preserve their hidden redoubt beneath the Slaughtered Lamb.",sp=0},{t="The Master's Boon",b="Upon receiving news that Wishock partook of his final drink, Zardeth of the Black Claw considers the immediate threat averted. As recompense for keeping the city guard and inquisitive peers at bay, Zardeth entrusts his sniveling servant, an imp named Zggi, with bestowing a dark token of gratitude upon the loyal practitioner.",sp=1}},faq={{q="Who is Zardeth of the Black Claw?",a="Zardeth of the Black Claw is a prominent warlock operating secretly out of Stormwind City. He works to safeguard the city's hidden dark casters from discovery by local nobility, utilizing ruthless measures to eliminate any who pry too closely into their forbidden craft.",al={"who is zardeth","zardeth role","black claw leader"}},{q="What happened to Lord Wishock?",a="Lord Wishock was fed a specially prepared toxic brew concocted by Stormwind's hidden warlocks. His elimination ensures that the noble house will no longer investigate or disturb the dark practitioners conducting rituals beneath the city streets.",al={"did wishock die","what was the brew for","lord wishock fate"},sp=1},{q="Who is Zggi?",a="Zggi is an imp bound in service to Zardeth of the Black Claw. Grudging and covetous, Zggi longs to hoard the master's treasures for himself, but dreads the punishment that would follow any open defiance of Zardeth's commands.",al={"who is the imp zggi","zggi servant"}},{q="Why was Lord Wishock targeted by the warlocks?",a="Wishock posed an active threat of disturbance and exposure to Stormwind's warlock coven. By ending his interference, the warlocks bought uninterrupted safety to pursue demonology and shadow magic unhindered by the nobility.",al={"why kill wishock","wishock threat"}},{q="Where does this quest chain conclude?",a="The quest concludes directly with the imp Zggi, situated near Zardeth of the Black Claw in the warlock sanctum beneath the Slaughtered Lamb in Stormwind's Mage Quarter.",al={"where do i turn in you have served us well","zggi location"}},{q="Why is this task restricted strictly to warlocks?",a="The operation involves delicate internal cabal politics and unlawful assassination. Entrusting such lethal subterfuge only to proven warlock disciples prevents betrayal and keeps the broader Alliance authorities ignorant of the act.",al={"is this warlock only","why warlock quest"}}},ang={["class:Warlock"]="This task demonstrates the ruthless pragmatism required to survive in Stormwind: shielding your coven by eliminating nosy nobles before they turn the city guard against you.",["faction:Alliance"]="Beneath the pristine spires and pious devotion of Stormwind lies a shadowy underbelly where forbidden warlocks secretly assassinate highborn meddlers to protect their presence."},kw={"a noble brew","black claw","imp","lord wishock","stormwind","the slaughtered lamb","zardeth","zggi"},rel={"quest:335","npc:zardeth-of-the-black-claw","topic:stormwind-kingdom"},m={start="Zardeth of the Black Claw",["end"]="Zggi",level="30",faction="Alliance",id=397},src={"You Have Served Us Well"}}
E["quest:399"] = {t="quest",n="Humble Beginnings",z="stormwind",s="Baros Alexston, the City Architect residing in Stormwind's Cathedral Square, seeks help recovering a lost heirloom from his youth. His family's old homestead in Westfall has burned down and fallen into the hands of thieves, leaving behind only buried memories.",h="Baros Alexston, the City Architect residing in Stormwind's Cathedral Square, seeks help recovering a lost...",sec={{t="A Builder's Roots",b="Though Baros Alexston is now an accomplished architect in Stormwind City, his early life was far more modest. Long before he designed stonework and city buildings, he grew up toiling in the fields of Westfall as a farm boy. His journey from tilling rural soil to advising city planners represents a rare ascent in the kingdom, yet he remains deeply attached to the modest beginnings that shaped his path.",sp=0},{t="Tragedy in Westfall",b="Like many homesteads across Westfall, the Alexston Farmstead fell victim to the lawlessness sweeping the region. Bandits and vagrants torched the house, driving Baros's father away from his livelihood. In the chaos of the arson and occupation, family heirlooms were abandoned. Baros asks brave travelers to venture into the ruined, bandit-infested farmstead west of Sentinel Hill to recover his first compass—a sentimental keepsake hidden away before the home fell.",sp=0}},faq={{q="Who is Baros Alexston?",a="Baros Alexston is the City Architect of Stormwind, located near the Cathedral Square. Despite his prestigious position in the capital, he was raised as an ordinary farmer's son in Westfall before leaving the countryside to master the craft of building.",al={"baros alexston","who is baros","city architect"}},{q="Where is the Alexston Farmstead located?",a="The farmstead sits directly west of Sentinel Hill in central Westfall. Like many properties in the area, it has been burned and overrun by thieves and rogues belonging to the Defias-aligned rabble.",al={"alexston farmstead location","where is the farm","alexston farm"}},{q="Why is the compass important to Baros?",a="The compass holds purely sentimental value. It was Baros's very first navigation tool from his boyhood on the farm, symbolizing his journey from rural laborer to architectural planner. Though functionally useless to his current craft, it is an irreplaceable relic of his past.",al={"why compass","what is the compass","simple compass"}},{q="Who burned down the Alexston farm?",a="The farm was razed by the thieves and outlaws terrorizing Westfall. With the kingdom's military spread thin and unable to safeguard outlying homesteads, bandits seized the land and drove out the Alexston family.",al={"who burned the farm","why was farm destroyed","westfall farm burned"}},{q="Where can the compass be found on the farm?",a="The compass was hidden away before the family fled and can be discovered inside a small chest amidst the charred ruins of the main farmhouse.",al={"compass location","where is compass","hidden compass"}},{q="What happened to Baros's father?",a="Baros's father survived the raid on their homestead and fled the farm. Though unable to carry their possessions through the flames and bandits, he remembered where the family hid valuable keepsakes before escaping.",al={"baros father","alexston father","who is baros's dad"}}},ang={["race:Human"]="The fate of the Alexston Farmstead mirrors the slow decline of Westfall's yeomanry, where generations of human farmers have been dispossessed by lawlessness right on Stormwind's doorstep.",["faction:Alliance"]="Venturing into Westfall on behalf of capital city figures highlights the growing disconnect between the safe streets of Stormwind and the unprotected frontier lands nearby."},kw={"alexston farmstead","baros alexston","cathedral square","humble beginnings","sentinel hill","simple compass","stormwind","westfall"},rel={"npc:baros-alexston","subzone:alexston-farmstead","zone:westfall","subzone:cathedral-square","subzone:sentinel-hill","topic:stormwind-kingdom"},m={start="Baros Alexston",level="15",faction="Alliance",id=399},src={"Humble Beginnings"}}
E["quest:434"] = {t="quest",n="The Attack!",z="stormwind",s="\"The Attack!\" is a high-stakes quest in Stormwind Keep involving an undercover operation orchestrated by the gnome tinkerer Tyrion and cheese merchant Elling Trias. Adventurers assist in executing a covert sting within the royal gardens to catch treasonous conspirators red-handed.",h="\"The Attack!\" is a high-stakes quest in Stormwind Keep involving an undercover operation orchestrated by the...",sec={{t="A Garden Ambush",b="Following an investigation orchestrated by the spy Tyrion and cheese merchant Elling Trias, the pieces fall into place inside Stormwind Keep. Using an engineered automaton disguised as Priestess Tyriona, Tyrion infiltrates the keep's library to deliver false information to Lord Gregor Lescovar. Tricked into believing an urgent meeting is required, Lescovar dismisses his guards and steps into the quiet keep garden to rendezvous with Marzon the Silent Blade, an assassin tied to the Defias Brotherhood.",sp=0},{t="Treason in the Keep",b="Hidden in the shadows, investigators listen as Lescovar and Marzon confirm what investigators long suspected: high nobility in Stormwind is actively colluding with the Defias conspiracy threatening the kingdom. Once the treasonous talk concludes, the trap springs. Both Lescovar and the Silent Blade must be eliminated quickly in the courtyard before the royal guards return to find a nobleman dead on the cobblestones. The act firmly severs one of the Defias's deepest footholds inside the seat of power.",sp=1},{t="Shadow Games",b="Though the immediate threat is neutralized, the aftermath leaves uneasy questions. Elling Trias takes immense satisfaction in settling personal scores against Marzon, though he begrudges that his private maneuvering indirectly helps Mathias Shaw and SI:7. Lescovar's death serves as undeniable proof of rot within the court, hinting that the Defias Brotherhood did not operate alone—and that someone among the nobility allowed them to fester.",sp=2}},faq={{q="Who is Lord Gregor Lescovar?",a="Lord Gregor Lescovar is a prominent Stormwind nobleman residing in Stormwind Keep. Beneath his courtly stature, he secretly collaborated with the Defias Brotherhood, using his standing and influence to aid their subversion of the realm from within the palace itself.",al={"lescovar","who is lescovar","gregor lescovar"},sp=1},{q="Who is Marzon the Silent Blade?",a="Marzon the Silent Blade is a lethal assassin representing the Defias Brotherhood. He acts as the direct underground conduit between the outlaws and Lord Lescovar, carrying messages and plotting schemes until lured into Tyrion's garden trap.",al={"marzon","silent blade","who is marzon"},sp=1},{q="Why does Elling Trias care about this operation?",a="While ostensibly just a master of fine cheeses, Elling Trias is an influential rogue with deep ties to Stormwind's underworld. Marzon had targeted people close to Trias, prompting him to orchestrate the assassin's downfall, even if doing so incidentally assisted Mathias Shaw and SI:7.",al={"trias role","why is cheese guy involved","elling trias why"}},{q="How does Tyrion manage to lure Lescovar outside?",a="Tyrion deploys an engineered automaton disguised as Priestess Tyriona. The disguised bot walks past the palace guards into the library to feed Lescovar false intelligence, prompting him to send his guards away and hold a clandestine meeting in the garden.",al={"spybot disguise","tyriona","how does lescovar get lured"},sp=1},{q="Why do the guards not immediately defend Lescovar?",a="Lescovar dismisses his guards before the meeting to keep his illicit Defias dealings secret. This brief window of privacy allows investigators to ambush and execute both Lescovar and Marzon without royal guards intervening.",al={"why don't guards help lescovar","guards lescovar"},sp=1},{q="What happens after Lescovar is slain?",a="With Lescovar and Marzon dead, Elling Trias sends you to Old Town to tell Master Mathias Shaw of SI:7 that the Lescovar threat has been dealt with, in the quest The Head of the Beast.",al={"what next after the attack","head of the beast"},sp=1}},ang={["class:Rogue"]="The mission mirrors the intricate, shadowy operations of the rogue underworld, proving that cheese shops and quiet garden corners often hold more political power than formal councils.",["faction:Alliance"]="Executing Lescovar removes a Defias-aligned traitor from Stormwind Keep, though it exposes dangerous vulnerabilities in the leadership guiding boy-king Anduin.",["race:Human"]="For humans of Stormwind, this ambush reveals the heartbreaking reality that the bandit crisis ravaging Westfall and Redridge is secretly fueled by nobles within their own royal palace."},kw={"defias","elling trias","lescovar","marzon","priestess tyriona","silent blade","spybot","stormwind keep","the attack","tyrion"},rel={"npc:tyrion","npc:elling-trias","quest:394","quest:2746","quest:2300","topic:stormwind-kingdom","topic:alliance"},m={start="Tyrion",["end"]="Elling Trias",level="31",faction="Alliance",id=434},src={"The Attack!"}}
E["quest:543"] = {t="quest",n="The Perenolde Tiara",z="stormwind",s="The Perenolde Tiara is a task commissioned by Count Remington Ridgewell, an aristocrat residing in Stormwind. He hires adventurers to journey north into the treacherous Ruins of Alterac to recover a lost royal heirloom. The crown once belonged to the fallen dynasty of Alterac and is rumored to be held by an ogre mage.",h="The Perenolde Tiara is a task commissioned by Count Remington Ridgewell, an aristocrat residing in Stormwind.",sec={{t="A Relic of a Ruined Kingdom",b="The Perenolde Tiara is an exquisite relic from the fallen human kingdom of Alterac. Crafted by master dwarven jewelers within Ironforge, the ornate headpiece was set with the finest emeralds to adorn the Perenolde ruling family. However, during the Second War, King Aiden Perenolde betrayed the Grand Alliance to the Orcish Horde, leading directly to his kingdom's downfall, conquest, and ultimate collapse into ruin. Amid the chaos and subsequent fall of Alterac City, many of the royal dynasty's greatest treasures vanished into the snowy rubble of the Alterac Mountains.",sp=0},{t="The Miser in the Ruins",b="Rather than residing in an alliance vault or a royal grave, the tiara ended up in the greedy grasp of Grel'borg the Miser. An ogre mage belonging to the Crushridge ogres inhabiting the ruins of Alterac, Grel'borg spends his days picking through the dilapidated stones in search of shiny baubles and abandoned wealth. Count Remington Ridgewell, an avid collector of historical oddities in Stormwind City, learns of the tiara's survival and enlists daring mercenaries to venture deep into ogre-held territory, dispatch the miserly brute, and return the priceless jewel to his personal gallery.",sp=0}},faq={{q="Who was the Perenolde family?",a="The Perenoldes were the royal lineage that ruled the northern human realm of Alterac. During the Second War, King Aiden Perenolde committed high treason by collaborating with the invading Orcish Horde to spare his kingdom. His treachery was uncovered by the Alliance of Lordaeron, leading to Alterac's martial occupation, the dismantling of the throne, and the kingdom's subsequent descent into complete lawlessness and ruin.",al={"house of perenolde","who were the perenoldes","perenolde lore"}},{q="Who made the Perenolde Tiara?",a="The tiara was forged by master jewelers in the dwarven city of Ironforge. Crafted with fine metals and set with lustrous emeralds, it stood as a symbol of nobility and wealth for the ruling house of Alterac before the nation fell from grace.",al={"tiara origin","who crafted perenolde tiara"}},{q="Who holds the tiara now?",a="The tiara fell into the clutches of Grel'borg the Miser, a scavenging ogre mage who roams the snowy Ruins of Alterac in the northern hills, coveting ancient treasures left behind by the ruined human city.",al={"grelborg","who has perenolde tiara","tiara location"}},{q="Why does Count Remington Ridgewell want the tiara?",a="Count Remington Ridgewell is a wealthy nobleman and antiquarian living in Stormwind City. He seeks out renowned artifacts and historic curiosities across Azeroth to expand his prestigious private collection, employing capable mercenaries to retrieve lost treasures from perilous locations.",al={"remington ridgewell motive","why get the tiara"}},{q="Where are the Ruins of Alterac located?",a="The Ruins of Alterac lie in the frigid Alterac Mountains in the north of the Eastern Kingdoms, positioned north of the Hillsbrad Foothills and north of the Durnholde region. The abandoned city is currently infested by hostile Crushridge ogres and Syndicate outlaws.",al={"alterac ruins location","where is alterac"}},{q="What happens to the tiara after you recover it?",a="Upon receiving the muddy and tarnished heirloom, Count Ridgewell arranges for professional restorers to clean and polish it before immediately mounting it as a showpiece within his personal collection.",al={"tiara turn in","tiara fate"},sp=1}},ang={["race:Human"]="For humans of the Alliance, the tiara serves as an uncomfortable reminder of Alterac's betrayal during the Second War, when human royalty sided with the Horde against their own kin.",["race:Dwarf"]="Crafted by the master jewelers of Ironforge, the tiara represents the celebrated craftsmanship of dwarven artisans, whose fine work endured even the collapse of a human kingdom.",["faction:Alliance"]="Venturing north into the lawless Alterac Mountains lets Alliance operatives clear out dangerous Crushridge ogres while recovering priceless historical artifacts for Stormwind nobility."},kw={"alterac","crushridge","grel'borg","miser","perenolde","ridgewell","stormwind","tiara"},rel={"npc:count-remington-ridgewell","subzone:ruins-of-alterac","topic:alterac-kingdom","zone:ironforge","topic:stormwind-kingdom"},m={start="Count Remington Ridgewell",faction="Alliance",id=543},src={"The Perenolde Tiara"}}
E["quest:5634"] = {t="quest",n="Desperate Prayer",z="stormwind",s="Desperate Prayer is a rite of passage for fledgling human priests in Stormwind City. Bestowed by High Priestess Laurena in the Cathedral of Light, it marks an acolyte's dedication to preserving life across the turbulent lands of the Alliance. By completing this spiritual instruction, priests are granted an emergency blessing to heal their own wounds when all else fails.",h="Desperate Prayer is a rite of passage for fledgling human priests in Stormwind City.",sec={{t="A Plea in the Dark",b="Priests serving within the Cathedral of Light are taught to channel their faith outward to shield comrades, mend mortal wounds, and smite evil. Yet even the most devout servants of the Holy Light find themselves isolated, cornered, or pushed to the edge of mortal endurance. Desperate Prayer represents an intimate, emergency communion—a raw cry for divine intervention when an acolyte's personal survival hangs by a thread.",sp=0},{t="The Cathedral's Blessing",b="High Priestess Laurena oversees many of the clergy within Stormwind's Cathedral Square, assessing when an acolyte has proven worthy of deeper doctrinal secrets. By demonstrating true dedication to the virtues of the Light across the kingdom, human initiates receive this sacred lesson not merely as an instrument of survival, but as a solemn affirmation that their continued service remains essential to the realm.",sp=0}},faq={{q="What is the purpose of Desperate Prayer?",a="Desperate Prayer is an emergency invocation of the Holy Light granted to human and dwarf priests. It allows a wounded priest to instantly call down divine energy to mend their own critical injuries without taking time to chant long incantations.",al={"what does desperate prayer do","why desperate prayer","desperate prayer purpose"}},{q="Who grants this lesson in Stormwind?",a="High Priestess Laurena, who ministers inside the grand Cathedral of Light in Stormwind's Cathedral Square, bestows the lesson once an acolyte demonstrates sufficient devotion and experience in the wider world.",al={"who teaches desperate prayer","where to get desperate prayer","high priestess laurena quest"}},{q="Why do priests receive this specific teaching?",a="Priests of the Holy Light often throw themselves into peril to aid others. Desperate Prayer serves as a sacred safeguard, ensuring that when healers find themselves abandoned or gravely hurt, their faith can preserve their own lives.",al={"why do priests get desperate prayer","lore behind desperate prayer"}},{q="Can any adventurer learn Desperate Prayer here?",a="No. This quest and lesson are strictly reserved for priests attuned to the teachings of the Holy Light who study under the guidance of the Church of the Light.",al={"can anyone learn desperate prayer","is this quest priest only"}},{q="Where does this rite take place?",a="It takes place in the Cathedral of Light, the towering spiritual heart of the Alliance situated in the northern district of Stormwind City.",al={"desperate prayer location","where is laurena"}},{q="Is Desperate Prayer unique to human priests?",a="Within Alliance lands, both human and dwarven clergy share access to Desperate Prayer, as both peoples venerate the Holy Light through closely allied clerical traditions centered around Stormwind and Ironforge.",al={"do other races get desperate prayer","dwarf desperate prayer"}}},ang={["class:Priest"]="This rite represents your transition from an apprentice acolyte into an active servant of the Holy Light capable of surviving deadly trials in the field.",["race:Human"]="Human priests receive this teaching directly from the hierarchy of the Cathedral of Light, reinforcing Stormwind's role as the preeminent seat of human faith.",["faction:Alliance"]="The preservation of frontline healers through blessings like Desperate Prayer is vital to sustaining Alliance soldiers across dangerous frontiers."},kw={"cathedral of light","cathedral square","desperate prayer","high priestess laurena","holy light","laurena","priest","stormwind"},rel={"npc:high-priestess-laurena","topic:light"},m={start="High Priestess Laurena",level="10",faction="Alliance",id=5634},src={"Desperate Prayer (Cathedral Square)"}}
E["quest:5635"] = {t="quest",n="Desperate Prayer",z="stormwind",s="Desperate Prayer is an introductory quest for fledgling Alliance priests serving the Church of the Holy Light. After demonstrating initial devotion and discipline in Elwynn Forest, promising acolytes are summoned to the Cathedral of Light in Stormwind to further their sacred training under High Priestess Laurena.",h="Desperate Prayer is an introductory quest for fledgling Alliance priests serving the Church of the Holy Light.",sec={{t="A Summons to the Capital",b="Novice priests serving in the outlying settlements of Elwynn Forest begin their journey under local mentors like Priestess Josetta in Goldshire. When a disciple proves capable in spirit and deeds, word quickly reaches the senior priesthood in the capital. Recognition comes in the form of a direct summons to the grand Cathedral of Light, the spiritual heart of the Kingdom of Stormwind, signaling that the time has come to undertake formal, deeper responsibilities in the faith.",sp=0},{t="Guidance from the High Priestess",b="Upon arriving at the Cathedral, acolytes present themselves to High Priestess Laurena. As one of the preeminent leaders of the Church within the city, Laurena oversees the spiritual foundation and practical training of newly elevated priests. Her instruction prepares devotees for the harsh trials facing the Alliance, imparting critical knowledge of the Light's miracles—including the vital plea for salvation known among human practitioners as Desperate Prayer.",sp=0}},faq={{q="What is the purpose of the quest Desperate Prayer?",a="The quest directs promising level 10 priests from Goldshire to Stormwind's Cathedral of Light, connecting novice practitioners with High Priestess Laurena to advance their sacred training.",al={"desperate prayer quest","what is desperate prayer quest","why do desperate prayer"}},{q="Who gives the quest Desperate Prayer?",a="Priestess Josetta, the priest trainer stationed at the Lion's Pride Inn in Goldshire, offers the summons once you have proven your devotion.",al={"who starts desperate prayer","desperate prayer quest giver"}},{q="Who is High Priestess Laurena?",a="High Priestess Laurena is a senior leader within the Church of the Holy Light, residing inside the Cathedral of Light in Stormwind where she trains advanced acolytes.",al={"who is laurena","high priestess laurena lore"}},{q="Where is the Cathedral of Light located?",a="The Cathedral of Light dominates Cathedral Square in the northern district of Stormwind City, serving as the spiritual center for the kingdom's priesthood and paladins.",al={"where is cathedral of light","cathedral location stormwind"}},{q="Why is the quest named Desperate Prayer?",a="It introduces the priest to their advanced training in Stormwind, where human priests traditionally learn the invocation known as Desperate Prayer—a plea to the Light for immediate, self-preserving deliverance.",al={"why called desperate prayer","desperate prayer name meaning"}},{q="Do other races or classes get this quest?",a="This specific questline is tailored for priests advancing out of Elwynn Forest to begin higher instruction in the capital of Stormwind.",al={"can dwarves do desperate prayer quest","is desperate prayer priest only"}}},ang={["class:Priest"]="This quest marks your official transition from a parish novice in Goldshire to an acknowledged disciple entrusted to the senior leadership of the Cathedral of Light.",["race:Human"]="For humans of the Holy Light, stepping into the towering Cathedral of Light is a profound pilgrimage, affirming your duty to the spiritual heart of the kingdom.",["faction:Alliance"]="The Church of the Holy Light remains one of the strongest cultural and moral pillars binding the Alliance together in an era of looming threats."},kw={"cathedral of light","desperate prayer","goldshire","high priestess laurena","holy light","priest","priestess josetta","stormwind"},rel={"npc:high-priestess-laurena","npc:priestess-josetta","subzone:cathedral-of-light","topic:light","topic:stormwind-kingdom"},m={start="Priestess Josetta",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5635},src={"Desperate Prayer (Goldshire)"}}
E["quest:5637"] = {t="quest",n="Desperate Prayer",z="stormwind",s="Desperate Prayer is a rite of passage quest calling promising dwarven priests from Dun Morogh to the grand Cathedral of Light in Stormwind. High Priestess Laurena summons rising acolytes to advance their spiritual devotion and unlock specialized holy techniques. It marks a priest's transition from local training into the wider service of the Alliance.",h="Desperate Prayer is a rite of passage quest calling promising dwarven priests from Dun Morogh to the grand...",sec={{t="A Summons to the Cathedral",b="Priests who begin their service among the snows of Dun Morogh eventually outgrow the instruction of local mentors like Maxan Anvol in Kharanos. When an acolyte shows true promise, a formal summons arrives from High Priestess Laurena herself. Such direct attention from the leadership of the Cathedral of Light signifies that the young priest is ready for deeper mysteries and greater responsibilities within the faith.",sp=0},{t="Bonds Across Kingdoms",b="While Ironforge maintains its own holy traditions in the Mystic Ward, the Church of the Holy Light in Stormwind serves as a central spiritual heart for humans and dwarves alike. Journeying south via the Deeprun Tram connects dwarven acolytes to the broader ecclesiastical community, solidifying the shared spiritual brotherhood between the two allied kingdoms.",sp=0}},faq={{q="Why is High Priestess Laurena calling dwarven priests to Stormwind?",a="High Priestess Laurena oversees advanced religious instruction at the Cathedral of Light. When local tutors like Maxan Anvol see that an acolyte has mastered basic tenets, they send them to Laurena to receive specialized training in potent techniques like the Desperate Prayer.",al={"why laurena call me","why go to stormwind priest","who is high priestess laurena"}},{q="What is Desperate Prayer in the lore?",a="Desperate Prayer is an emergency invocation practiced by human and dwarven clerics of the Holy Light. When pushed to the brink of death, the priest releases an instinctive, urgent cry of faith that immediately knits wounds and restores vitality.",al={"desperate prayer lore","what is desperate prayer","how does desperate prayer work"}},{q="Where does this quest take place?",a="The summons begins in Kharanos in Dun Morogh, where Maxan Anvol instructs you to travel to Stormwind City. It finishes inside the Cathedral of Light in Stormwind's Cathedral Square, where High Priestess Laurena presides.",al={"quest location","where do i go","where is laurena"}},{q="Why would a dwarf priest train under a human High Priestess?",a="Dwarves and humans share the same faith in the Holy Light, a bond strengthened during the Second War. While dwarven priests often serve in Ironforge's Mystic Ward, the Cathedral of Light in Stormwind is one of the faith's foremost centers, welcoming all Alliance practitioners of the Light.",al={"why human trainer dwarf","dwarf church of light","ironforge vs stormwind light"}},{q="How should a young traveler reach Stormwind from Dun Morogh?",a="The fastest and safest route is through Ironforge's Tinker Town, where the Deeprun Tram provides direct subterranean transit directly beneath the mountains into Stormwind's Dwarven District.",al={"how to get to stormwind","travel to stormwind dwarf","deeprun tram"}},{q="Who is Maxan Anvol?",a="Maxan Anvol is a dwarven priest trainer stationed at Kharanos in Dun Morogh. He watches over fledgling clerics, teaching them fundamentals until they are disciplined enough to study under senior church leadership in Stormwind.",al={"maxan anvol lore","who gave quest","kharanos priest trainer"}}},ang={["class:Priest"]="This quest represents a milestone in your spiritual journey, bridging basic parish duty with advanced holy techniques taught directly by the Church's leadership.",["race:Dwarf"]="Traveling to Stormwind's Cathedral reinforces the shared spiritual covenant between the mountain kingdom of Ironforge and the human realm of Stormwind.",["faction:Alliance"]="Spiritual cooperation between Ironforge and Stormwind ensures that practitioners of the Light stand united across racial borders."},kw={"cathedral of light","desperate prayer","dun morogh","kharanos","laurena","maxan anvol","priest","stormwind"},rel={"npc:high-priestess-laurena","npc:maxan-anvol","subzone:cathedral-of-light","topic:light","topic:stormwind-kingdom"},m={start="Maxan Anvol",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5637},src={"Desperate Prayer (Kharanos)"}}
E["quest:5638"] = {t="quest",n="Desperate Prayer",z="stormwind",s="Desperate Prayer is a rite-of-passage summons for developing priests visiting the Park in Stormwind City. Directed by the night elf priestess Nara Meideros, novice clerics are sent across the canals to the Cathedral of Light to continue their holy instruction under High Priestess Laurena. It marks the moment an initiate transitions from basic field duty to deeper, specialized communion with the Holy Light.",h="Desperate Prayer is a rite-of-passage summons for developing priests visiting the Park in Stormwind City.",sec={{t="A Word in the Park",b="Within the serene grove of the Park, night elf priestesses like Nara Meideros maintain communion with Elune amid the bustle of Stormwind. Yet the bonds of faith among the Alliance's spiritual guides cross cultural divides. When an envoy from the Cathedral Square seeks out a promising student, Nara passes along the summons with quiet encouragement, assuring the initiate that the call carries good tidings rather than cause for alarm.",sp=0},{t="The Call of the Cathedral",b="Upon crossing Cathedral Square and stepping beneath the soaring white stone arches of the Cathedral of Light, the initiate reports to High Priestess Laurena. As one of Stormwind's most senior clerical leaders, Laurena guides young acolytes beyond mere foundational prayers. She imparts the sacred invocation known as Desperate Prayer—a personal plea for divine intervention that can instantly mend grievous wounds when a servant of the Light stands on the precipice of death.",sp=0}},faq={{q="Who sends me on this quest?",a="Priestess Nara Meideros, a night elf cleric located in the Park district of Stormwind City, delivers the message that the Cathedral leadership is looking for you.",al={"quest giver","who gives desperate prayer","nara meideros"}},{q="Who do I need to report to in Stormwind?",a="You must speak with High Priestess Laurena, who resides within the Cathedral of Light in Stormwind's Cathedral Square.",al={"where to go","quest turn in","who is laurena"}},{q="What is the significance of Desperate Prayer?",a="Desperate Prayer represents a vital discipline taught to human and dwarven clerics of the Holy Light. It is an instantaneous invocation that calls down divine grace to instantly revitalize the caster in moments of extreme peril.",al={"what does desperate prayer do","priest ability lore","desperate prayer spell"}},{q="Why is a night elf directing priests to the human cathedral?",a="Though night elf priestesses worship Elune rather than the Holy Light practiced by humans and dwarves, the spiritual orders in Stormwind maintain close contact and mutual respect, sharing word when clerics of the Alliance require training.",al={"why nara meideros","park to cathedral","night elf elune stormwind"}},{q="At what point in training does this summons occur?",a="This summons arrives around the tenth circle of experience, signaling that a young priest has proven capable enough in the field to handle more demanding divine rituals.",al={"what level is this","when do i get desperate prayer"}},{q="Where is the Cathedral of Light located?",a="The Cathedral of Light dominates Cathedral Square, situated in the northern quarter of Stormwind City between the Dwarven District and the Park.",al={"cathedral location","where is cathedral square"}}},ang={["class:Priest"]="This summons marks your formal induction into higher spiritual disciplines, opening the path to master the life-saving invocation of Desperate Prayer.",["race:Human"]="The Cathedral of Light serves as the supreme sanctuary for human worship in the southern Eastern Kingdoms, making Laurena's guidance a cultural and spiritual milestone.",["faction:Alliance"]="The cooperation between Nara Meideros in the Park and the clergy in Cathedral Square highlights the quiet solidarity between Darnassus and Stormwind's holy orders."},kw={"cathedral of light","desperate prayer","high priestess laurena","holy light","nara meideros","priest quest","stormwind","the park"},rel={"npc:high-priestess-laurena","npc:nara-meideros","subzone:cathedral-of-light","topic:light","topic:elune","topic:stormwind-kingdom"},m={start="Nara Meideros",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5638},src={"Desperate Prayer (Park)"}}
E["quest:5676"] = {t="quest",n="Arcane Feedback",z="stormwind",s="Arcane Feedback is a rite of passage for Alliance priests in Stormwind City, granted by High Priestess Laurena in the Cathedral of Light. Reaching a deeper communion with faith, the priest is instructed in wards designed to counter hostile practitioners of the arcane. It represents the Church's practical defense against raw sorcery and rogue spellcasters.",h="Arcane Feedback is a rite of passage for Alliance priests in Stormwind City, granted by High Priestess...",sec={{t="A Shield Against the Arcane",b="Within the sunlit cloisters of the Cathedral of Light, High Priestess Laurena reminds acolytes of an enduring peril: arcane magic. While the Holy Light brings healing, warmth, and divine order, raw magical energies are volatile and often court corruption or catastrophe. To endure against warlocks, renegade sorcerers, and magical beasts, devout priests are taught that faith alone must sometimes be shaped into an active ward against ambient spells.",sp=0},{t="Turn the Torrent Inward",b="Arcane Feedback trains the mind and spirit to punish hostile spellcasters for channeling power against the faithful. Rather than simply deflecting magical volleys, this discipline mirrors arcane energy back into its source, burning through the caster's own mana reserves while causing agony. Laurena imparts this spell to human priests stepping out into the wider world, ensuring the Cathedral's emissaries never travel defenseless against sorcery.",sp=0}},faq={{q="What is the purpose of the quest Arcane Feedback?",a="The quest represents a human priest's growing mastery under the tutelage of the Church of the Light. High Priestess Laurena teaches the practitioner a specific protective rite designed to counter and retaliate against hostile spellcasters.",al={"arcane feedback quest","what is arcane feedback","why do this quest"}},{q="Who offers this quest and where can she be found?",a="High Priestess Laurena offers the quest. She is stationed in the Cathedral of Light, the grand spiritual hub of the Alliance located in the Cathedral Square of Stormwind City.",al={"who gives arcane feedback","arcane feedback quest giver","where is laurena"}},{q="Why does the Church of the Holy Light view arcane magic as an enemy?",a="The Church teaches reliance on moral clarity, devotion, and divine grace. In contrast, arcane magic draws upon volatile, addictive forces that historically attracted demonic incursions and wreaked havoc across Azeroth, leading human priests to view uncontrolled sorcery as an ever-present hazard.",al={"why do priests hate arcane","church vs arcane","is arcane bad"}},{q="How does the Arcane Feedback ward work conceptually?",a="The spell creates a retaliatory aura surrounding the priest. Whenever a hostile spell strikes the ward, the incoming magic triggers a backlash that drains the attacker's mana reserves and inflicts physical shock upon them.",al={"how does arcane feedback work","arcane feedback lore"}},{q="Can any priest learn this from Laurena?",a="In Stormwind, this particular discipline is tailored for human priests as part of their national ecclesiastical traditions, reflecting the specific combat doctrines taught within the Cathedral of Light.",al={"can dwarves learn arcane feedback","who can get arcane feedback","priest racial spell"}},{q="What level is expected of an acolyte undertaking this training?",a="Priests are summoned to learn this technique around their twentieth circle of experience, an age where acolytes leave behind basic church duties to brave dangerous frontier territories.",al={"what level for arcane feedback","arcane feedback level requirement"}}},ang={["class:Priest"]="This rite deepens a priest's tactical repertoire, providing tools to suppress opposing mana users when divine diplomacy fails.",["race:Human"]="Human priests in Stormwind follow the specific doctrinal training of the Cathedral of Light, blending righteous devotion with strict discipline against magic.",["faction:Alliance"]="As tensions rise with renegade cabals and dark practitioners throughout the Eastern Kingdoms, the Alliance relies on its priests to neutralize magical threats."},kw={"anti-magic","arcane feedback","cathedral of light","high priestess laurena","holy light","human priest","laurena","priest","stormwind"},rel={"npc:high-priestess-laurena"},m={start="High Priestess Laurena",level="20",faction="Alliance",id=5676},src={"Arcane Feedback (Stormwind)"}}
E["quest:579"] = {t="quest",n="Stormwind Library",z="stormwind",s="Deep within the Royal Library of Stormwind Keep, head librarian Donyal Tovald manages a collection of historical texts and regional accounts. By order of the young King Anduin Wrynn, funds have been allocated to transcribe copies of these works for citizens and scholars who bring official library scrips. This service allows adventurers to study the history, factions, and legends of Azeroth firsthand.",h="Deep within the Royal Library of Stormwind Keep, head librarian Donyal Tovald manages a collection of...",sec={{t="A Royal Mandate for Knowledge",b="While Highlord Bolvar Fordragon and Lady Katrana Prestor oversee defense and court politics in King Varian's absence, young King Anduin has directed royal resources toward education. Recognizing that understanding history is crucial for the kingdom's future, Anduin sponsored the transcribing of ancient manuscripts and historical journals. The Royal Library, nestled in the halls of Stormwind Keep, serves not merely as a royal vault for state secrets, but as a repository where documented lore is preserved and copied for those in royal service.",sp=0},{t="The Scrip Exchange",b="Transcribing delicate parchment by hand requires significant time, ink, and royal sanction. To manage this distribution, the head librarian Donyal Tovald accepts official library scrips, issued to adventurers and scholars across Alliance territories. In exchange, Tovald provides faithful duplicates of historical tomes, covering everything from the ancient histories of the Eastern Kingdoms to accounts of distant lands, offering context for ongoing conflicts beyond the capital's walls.",sp=0}},faq={{q="What is the purpose of the Stormwind Library quest?",a="This quest allows you to turn in a Library Scrip to head librarian Donyal Tovald in exchange for readable lore books. It provides background history on various Alliance storylines, people, and regions throughout Azeroth.",al={"what does this quest do","stormwind library quest purpose","why do this quest"}},{q="Who is Donyal Tovald?",a="Donyal Tovald is the librarian overseeing the Royal Library in Stormwind Keep. He manages the kingdom's collection of written histories and carries out King Anduin's directive to distribute copies to worthy scholars and adventurers.",al={"who is donyal tovald","librarian stormwind","who gives the books"}},{q="Where do you obtain a Library Scrip?",a="Library Scrips are awarded from specific quests across the Alliance territories when dealing with scholars, magistrates, or officials who reward research and curiosity about the wider world.",al={"where do i get library scrip","how to get library scrip","library scrip source"}},{q="Why is young King Anduin funding the library?",a="King Anduin Wrynn places great personal value on learning and education. Even as a child ruling under the guidance of Regent Bolvar Fordragon, he dedicated royal funds to make copies of the kingdom's historical tomes accessible to the public.",al={"why does anduin care about books","anduin library funding","king anduin books"}},{q="Where is the library located in Stormwind?",a="The Royal Library is located within Stormwind Keep, the massive fortress dominating the eastern portion of the city. You can find Donyal Tovald standing among the high shelves and reading tables inside.",al={"where is stormwind library","royal library location","where is donyal tovald located"}},{q="Can I read the books I receive?",a="Yes. Each book received from the library is an in-game readable item that provides flavor, narrative background, and context for various legends and historical events across the Warcraft world.",al={"are the books readable","can you open the books","do books do anything"}}},ang={["class:Mage"]="For practitioners of the arcane, the Royal Library represents a vital secular archive in the kingdom, preserving non-magical historical accounts that complement the arcane studies conducted in the Mage Quarter.",["faction:Alliance"]="The library preserves the shared triumphs and tragedies of the Alliance of Lordaeron, offering citizens a reminder of the historical bonds between humans, dwarves, gnomes, and high elves.",["race:Human"]="Having lost countless archives when Old Stormwind was sacked during the First War, human scholars place tremendous value on preserving and copying whatever histories survived the kingdom's rebuilding."},kw={"anduin wrynn","books","donyal tovald","library scrip","lore tomes","stormwind keep","stormwind library","transcription"},rel={"npc:donyal-tovald","subzone:library-ironforge","topic:alliance"},m={start="Donyal Tovald",["end"]="Donyal Tovald",level="1",faction="Alliance",id=579},src={"Stormwind Library"}}
E["quest:6261"] = {t="quest",n="Dungar Longdrink",z="stormwind",s="This errand introduces adventurers to Dungar Longdrink, the chief gryphon master of Stormwind. After collecting emergency supplies from Osric Strang, couriers must arrange for swift aerial transport to deliver the gear back to the embattled defenders in Westfall.",h="This errand introduces adventurers to Dungar Longdrink, the chief gryphon master of Stormwind.",sec={{t="A Vital Supply Chain",b="Westfall is strained to its breaking point by Defias outlaws and feral harvest golems, leaving Quartermaster Lewis and the People's Militia desperate for provisions. When Lewis sent word to the capital for fresh equipment, general goods merchant Osric Strang packed up everything requested. Moving military cargo on foot through the bandit-ridden roads of Elwynn and Westfall takes valuable time, making the kingdom's newly forged aerial routes an essential lifeline.",sp=0},{t="The Master of the Roost",b="Perched in the Trade District, Dungar Longdrink coordinates Stormwind's courier and passenger gryphons. The majestic beasts, traditionally raised and handled by Wildhammer dwarves, provide reliable transport across human lands so long as roosts on both ends know each other. By bringing Osric's heavy crate directly to Dungar, couriers learn how aerial logistics work, establishing a direct connection between the capital's stockpiles and frontier outposts like Sentinel Hill.",sp=0}},faq={{q="Who is Dungar Longdrink?",a="Dungar Longdrink is Stormwind City's gryphon master, stationed right outside the Trade District near the flight roost. He manages the capital's courier beasts and oversees passenger travel throughout Alliance territories in southern Lordaeron and Azeroth.",al={"dungar","who is dungar","stormwind gryphon master"}},{q="Why is Osric sending this crate via gryphon?",a="Quartermaster Lewis and the People's Militia in Westfall are desperately low on gear to fight off bandits. Delivering heavy supplies on foot or by wagon would take days and risk ambushes, whereas a trained gryphon can fly Osric's supplies across borders in minutes.",al={"why use gryphon","why not walk","osric crate delivery"}},{q="Who is Thor, and why must I speak to him first?",a="Thor is the gryphon master stationed at Sentinel Hill in Westfall. Gryphons are trained along specific point-to-point routes, meaning Dungar's mounts can only fly you back to Westfall if you have already mapped the path by checking in with Thor on the other end.",al={"who is thor","why visit thor","thor gryphon"}},{q="What happens after Dungar accepts the crate?",a="Once Dungar inspects the delivery, he readies a gryphon for flight, directing you to take the crate directly to Quartermaster Lewis at Sentinel Hill.",al={"what next","return to lewis","next quest"}},{q="Where does this quest fit into the flight chain?",a="It is the third step of an introductory flight network tutorial that begins in Westfall with 'A Swift Message', takes you to Stormwind via 'Continue to Stormwind', meets Dungar, and concludes with 'Return to Lewis'.",al={"quest chain","flight questline","how many quests"}},{q="Why does Stormwind rely on dwarven gryphons?",a="Ever since the Second War brought the Alliance of Lordaeron together with the Wildhammer clan of the Hinterlands, gryphons have served as the supreme scouts and transports for Alliance realms, offering rapid transit that bypassed ruined roads and hostile blockades.",al={"why gryphons in stormwind","alliance gryphons lore"}}},ang={["faction:Alliance"]="Establishing gryphon paths between Stormwind and regional settlements is essential for maintaining order while the kingdom's central army is absent.",["race:Dwarf"]="Dwarven handlers like Dungar Longdrink and Thor are responsible for extending their ancestral bond with gryphons into the heart of the human kingdom.",["race:Human"]="With Westfall neglected by the House of Nobles, individual merchants and local handlers must cooperate directly to keep frontier outposts armed."},kw={"dungar longdrink","gryphon master","osric strang","osric's crate","sentinel hill","stormwind","thor","trade district","westfall"},rel={"npc:osric-strang","quest:6285","quest:6281","quest:6181","subzone:trade-district","npc:thor","zone:westfall","topic:stormwind-kingdom"},m={start="Osric Strang",["end"]="Dungar Longdrink",level="10",faction="Alliance",id=6261},src={"Dungar Longdrink (Classic)"}}
E["quest:690"] = {t="quest",n="Malin's Request",z="stormwind",s="Malin's Request is an Alliance task offered by Archmage Malin in Stormwind City's Mage Quarter. Malin asks seasoned adventurers to travel far north to Refuge Pointe in the Arathi Highlands, where an expedition attempts to recover valuable magical relics left behind during the fall of Stromgarde.",h="Malin's Request is an Alliance task offered by Archmage Malin in Stormwind City's Mage Quarter.",sec={{t="A Master's Lost Belongings",b="Archmage Malin, stationed in the Wizard's Sanctum of Stormwind, acts on behalf of his former mentor, Archmage Trelane. When the martial kingdom of Stromgarde collapsed into chaos and ruin, Trelane made a desperate stand at the Tower of Arathor. Forced to abandon his post as the city fell to hostile forces, Trelane left behind powerful enchanted possessions. Eager to reclaim these lost artifacts before hostile hands seize them, Malin directs capable mercenaries north to reinforce his operatives in the field.",sp=0},{t="The Strained Outpost at Refuge Pointe",b="The road to recovering Trelane's relics leads through Refuge Pointe, the beleaguered bastion of Stromgarde loyalists in the central Arathi Highlands. Malin's primary contact among the defenders is the dwarf Skuerto. However, Refuge Pointe is severely hard-pressed by surrounding Syndicate outlaws, Witherbark trolls, and Boulderfist ogres. Arriving travelers quickly find that Skuerto and the outpost garrison are stretched far too thin to offer a warm reception without immediate assistance.",sp=0}},faq={{q="Who is Archmage Malin?",a="Archmage Malin is a senior human wizard residing in the Wizard's Sanctum of Stormwind. He was once an apprentice to Archmage Trelane of Stromgarde and now coordinates efforts from Stormwind to recover his former master's magical research.",al={"archmage malin","who is malin","malin stormwind"}},{q="Why does Malin need help in Arathi?",a="Stromgarde recently collapsed under siege, forcing Archmage Trelane to flee the Tower of Arathor. Malin's agents in the region are working to recover Trelane's abandoned magical relics, but they are overwhelmed and require reinforcements.",al={"why go to arathi","malin mission purpose","why arathi highlands"}},{q="Where is Skuerto located?",a="Skuerto is a dwarven scout stationed at Refuge Pointe, the fortified Alliance encampment situated along the main trade road through the central Arathi Highlands.",al={"find skuerto","skuerto location","where is refuge pointe"}},{q="What happened to the Tower of Arathor?",a="The Tower of Arathor was an arcane redoubt within Stromgarde. During the kingdom's downfall, Archmage Trelane attempted to hold the fortification against invading Syndicate rogues and Boulderfist ogres, but the defenses failed and he was forced to flee.",al={"tower of arathor fall","what happened to stromgarde","trelane tower"}},{q="What happens after reporting to Skuerto?",a="Skuerto is overwhelmed and dismissive upon arrival, immediately directing you toward his companions at Refuge Pointe to begin recovering Trelane's scattered belongings.",al={"malin request follow up","next quest after malin","skuerto next quest"}},{q="Who is Archmage Trelane?",a="Archmage Trelane is a prominent mage of Stromgarde and the mentor of Archmage Malin. He was one of the key defenders of the Arathi capital before the kingdom fell.",al={"archmage trelane","who is trelane","trelane stromgarde"}}},ang={["class:Mage"]="For mages visiting the Wizard's Sanctum, assisting Malin directly preserves precious arcane research and relics tied to the legacy of Arathor's mages.",["faction:Alliance"]="Refuge Pointe represents the fragile, remaining foothold of the Alliance in Arathi, making any reinforcement sent from Stormwind critical to maintaining the region.",["race:Human"]="Stromgarde was the cradle of human civilization; aiding in the retrieval of its treasures is a matter of honor and historical survival for the sons and daughters of Arathor."},kw={"arathi highlands","malin","refuge pointe","skuerto","stormwind","stromgarde","tower of arathor","trelane","wizard's sanctum"},rel={"npc:archmage-malin","npc:skuerto","subzone:refuge-pointe","zone:arathi","subzone:tower-of-arathor"},m={start="Archmage Malin",["end"]="Skuerto",level="32",faction="Alliance",id=690},src={"Malin's Request"}}
E["quest:7497"] = {t="quest",n="The Journey Has Just Begun",z="stormwind",s="This quest represents the hard-earned recognition of a seasoned artisan following the defeat of Onyxia. Major Mattingly imparts the vital technique required to craft an Onyxia Scale Cloak, turning the fallen broodmother's remains into essential protection against her brother.",h="This quest represents the hard-earned recognition of a seasoned artisan following the defeat of Onyxia.",sec={{t="A Rare Mastery",b="While many champions can claim credit for bringing low the broodmother Onyxia, very few possess both martial prowess and the master leatherworking skill required to work her formidable hide. When a hero with such combined talents reports to Major Mattingly in Stormwind, the officer acknowledges how vital those crafting skills are for the battles yet to come.",sp=0},{t="Protection Against the Black Dragonflight",b="The death of Onyxia does not end the threat of the black dragonflight. Mattingly teaches the artisan how to treat and stitch the broodmother's scales into an Onyxia Scale Cloak. This unique garment provides specialized warding against the devastating, incendiary breath of Onyxia's brother, Nefarian, the Lord of Blackrock.",sp=1}},faq={{q="Who offers the quest The Journey Has Just Begun?",a="Major Mattingly in Stormwind City offers this quest to Alliance heroes who have proven themselves in the campaign against Onyxia and possess master-level leatherworking.",al={"who gives the journey has just begun","where to get journey has just begun","journey has just begun quest giver"}},{q="What does this quest teach?",a="Completing this interaction teaches master leatherworkers the recipe to craft the Onyxia Scale Cloak, an item specifically tailored from Onyxia's scales.",al={"what recipe do i get","onyxia cloak recipe","reward for journey has just begun"}},{q="Why is the Onyxia Scale Cloak necessary?",a="The cloak is specially treated to shield wearers against the deadly, incendiary breath of Nefarian, the Lord of Blackrock, making it indispensable for facing the remaining leaders of the black dragonflight.",al={"why do i need onyxia cloak","what is onyxia scale cloak for","shadow flame protection"}},{q="Who is the Lord of Blackrock mentioned by Major Mattingly?",a="The Lord of Blackrock is Nefarian, a powerful black dragon and the brother of Onyxia. He rules over Blackrock Spire and continues the schemes of the black dragonflight.",al={"who is lord of blackrock","who is nefarian","mattingly dragon warning"}},{q="Why must the hero be a leatherworker to receive this knowledge?",a="The techniques required to harvest, temper, and sew dragon scales without destroying their innate magical warding demand the advanced expertise of a seasoned master leatherworker.",al={"why leatherworking only","can anyone get this quest","leatherworker requirement"}},{q="Does Onyxia's death resolve the black dragon threat in Stormwind?",a="No. While Onyxia herself has been slain, her brother Nefarian still commands Blackrock Mountain and continues plotting against the Alliance and the mortal races.",al={"is stormwind safe now","onyxia dead what next","black dragonflight after onyxia"},sp=1}},ang={["faction:Alliance"]="This quest bridges Stormwind's hard-won victory over Onyxia with the impending offensive against her brother Nefarian at Blackrock Mountain."},kw={"black dragonflight","blackrock","leatherworking","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind"},rel={"npc:major-mattingly","npc:onyxia","topic:black-dragonflight","quest:7781","topic:alliance"},m={start="Major Mattingly",faction="Alliance",id=7497},src={"The Journey Has Just Begun (Alliance)"}}
E["quest:7781"] = {t="quest",n="The Lord of Blackrock",z="stormwind",s="The Lord of Blackrock is an Alliance quest initiated upon claiming the severed head of the black dragon Nefarian within Blackwing Lair. Delivering this monstrous trophy to Grand Admiral Jes-Tereth in Stormwind Keep announces the downfall of the master of Blackrock Mountain. It marks one of the greatest military triumphs the Alliance has celebrated in recent history.",h="The Lord of Blackrock is an Alliance quest initiated upon claiming the severed head of the black dragon...",sec={{t="A Monument to Victory",b="Nefarian, the insidious brood-master of the Black Dragonflight and ruler of Upper Blackrock Spire, has long cast a terrifying shadow over the surrounding human kingdoms. Slaying him is not merely an act of survival; it represents the utter dismantling of his twisted experiments and scheming. Carrying his colossal, battle-scarred head back to Stormwind serves as undeniable proof that the Lord of Blackrock has met his end at the hands of the Alliance's greatest heroes.",sp=0},{t="Audience at Stormwind Keep",b="The grisly prize is brought directly to Grand Admiral Jes-Tereth, one of the foremost military minds attending the throne in Stormwind Keep. The sudden arrival of a dragon's severed head inside the royal court shocks onlookers and commands immediate reverence. For a kingdom already straining under internal political strife and external threats, this victory provides the realm with a momentous morale surge and an unforgettable entry into the annals of Alliance history.",sp=0}},faq={{q="What is the Lord of Blackrock quest about?",a="This quest begins when adventurers claim the severed Head of Nefarian in Blackwing Lair. It directs the victor to carry the monumental trophy back to Stormwind City and present it to Grand Admiral Jes-Tereth on behalf of the kingdom.",al={"lord of blackrock quest","nefarian head quest alliance","head of nefarian stormwind"}},{q="Who is Nefarian?",a="Nefarian is a great black dragon and the son of Deathwing. Ruling from the heights of Blackwing Lair inside Blackrock Mountain, he manipulated the Dark Iron dwarves, commanded the Blackrock orcs, and conducted sinister experiments to create the chromatic dragonflight.",al={"who is nefarian","lord of blackrock","nefarian lore"}},{q="Who is Grand Admiral Jes-Tereth?",a="Grand Admiral Jes-Tereth is a high-ranking naval commander of the Alliance stationed within the royal throne room of Stormwind Keep. She assists Highlord Bolvar Fordragon and the young King Anduin Wrynn in assessing major military threats and state defenses.",al={"jes tereth","who is jes-tereth","grand admiral"}},{q="Why is this trophy brought to Stormwind Keep?",a="Nefarian's dominion in Blackrock Mountain posed a mortal threat to the kingdom of Stormwind and the entire southern continent. Bringing the trophy directly to the kingdom's military leadership confirms the dragon's destruction and allows the realm to rally around the heroic feat.",al={"why stormwind","why bring head to keep","why jes-tereth"}},{q="What happens after giving the head to Jes-Tereth?",a="Grand Admiral Jes-Tereth is astounded by the feat, declaring that the triumph will be permanently recorded in history. This directly leads into the subsequent stage of the event, where the head is mounted publicly for all of Stormwind to see.",al={"what happens next","lord of blackrock part 2","nefarian head turn in"}},{q="Does turning in this head affect the whole city?",a="Yes. When the head of Nefarian is delivered to the capital and hoisted above the city gates, it signals the dragon's demise to all citizens and soldiers present, filling the defenders of Stormwind with triumphant resolve.",al={"city buff","rallying cry","head of nefarian buff"}}},ang={["faction:Alliance"]="Presenting the head of the black dragon Nefarian is one of the crowning martial achievements for the Alliance, decisively crushing the dragonflight's schemes against human territories.",["race:Human"]="Stormwind has suffered countless incursions and plots orchestrated from Blackrock Mountain; seeing its master defeated provides the realm with long-sought retribution and relief."},kw={"blackrock mountain","blackwing lair","grand admiral jes-tereth","head of nefarian","jes-tereth","lord of blackrock","nefarian","stormwind keep"},rel={"topic:stormwind-kingdom","topic:alliance"},m={start="Head of Nefarian",["end"]="Grand Admiral Jes-Tereth",faction="Alliance",id=7781},src={"The Lord of Blackrock (Alliance)"}}
E["quest:7782"] = {t="quest",n="The Lord of Blackrock",z="stormwind",s="This quest represents the final culmination of the campaign against the forces within Blackrock Mountain. After reporting to Grand Admiral Jes-Tereth in Stormwind Keep, heroes are directed to the Valley of Heroes where Field Marshal Stonebridge coordinates a public commemoration at the city gates for all the Alliance to see.",h="This quest represents the final culmination of the campaign against the forces within Blackrock Mountain.",sec={{t="A City's Triumph",b="The campaign against the Blackrock clan and the brood of the Black Dragonflight culminates in a public display of victory. Following the presentation of Nefarian's severed head inside Stormwind Keep, Grand Admiral Jes-Tereth directs the champions across the city to the Valley of Heroes. There, Field Marshal Stonebridge awaits to receive the gruesome trophy and commence citywide celebrations.",sp=1},{t="Rallying the Alliance",b="When Field Marshal Stonebridge hoists the severed head of Nefarian upon the great arches of Stormwind's main entrance, the entire city feels the impact. The display is accompanied by the Rallying Cry of the Dragonslayer, inspiring city defenders, visiting dignitaries, and common citizens alike with the knowledge that the brood of Deathwing has suffered a catastrophic blow.",sp=0}},faq={{q="What happens when you complete this quest?",a="Field Marshal Stonebridge hangs the severed head of Nefarian high upon the stone gateway arch in the Valley of Heroes. This triggers the Rallying Cry of the Dragonslayer buff across Stormwind City, bolstering the combat prowess of all friendly players and guards.",al={"nefarian head quest turn in","what does stonebridge do","rallying cry trigger"},sp=1},{q="Who is Field Marshal Stonebridge?",a="Field Marshal Stonebridge is a senior military officer of the Stormwind army stationed at the Valley of Heroes, near the entrance to Stormwind City. He organizes the public commemoration of major military triumphs, including hoisting the heads of defeated draconic threats.",al={"stonebridge","field marshal stonebridge"}},{q="Why does Grand Admiral Jes-Tereth send you here?",a="After receiving confirmation of Nefarian's defeat in the throne room, Jes-Tereth orders you to bring word to the city gates so the Alliance military can display the victory openly to lift morale across the capital.",al={"jes-tereth","why go to valley of heroes"},sp=1},{q="Does this turn-in affect the whole city?",a="Yes. When Stonebridge takes the trophy, a grand proclamation echoes through Stormwind and the Rallying Cry of the Dragonslayer is cast upon everyone within the city borders.",al={"world buff nefarian","does stormwind get buff"},sp=1},{q="Where is the Valley of Heroes located?",a="The Valley of Heroes is the grand entrance causeway into Stormwind City, lined with towering statues honoring the heroes of the Second War who entered the Dark Portal.",al={"valley of heroes location","where is stonebridge"}},{q="Who was the 'Lord of Blackrock'?",a="The Lord of Blackrock is the black dragon Nefarian, eldest son of Deathwing and ruler of the upper spires of Blackrock Mountain.",al={"who is lord of blackrock","nefarian identity"},sp=2}},ang={["faction:Alliance"]="Displaying Nefarian's head at the Valley of Heroes unites all the Alliance races, reminding citizens from Ironforge, Darnassus, and Gnomeregan that the dark forces plaguing the Eastern Kingdoms can be broken.",["race:Human"]="For the kingdom of Stormwind, defeating the master of Blackrock removes an existential draconic threat lurking right on their northern border.",["class:Warrior"]="The massive martial inspiration provided by the Rallying Cry of the Dragonslayer invigorates fighters heading out to defend the realm."},kw={"blackrock","dragonslayer","jes-tereth","nefarian","rallying cry","stonebridge","stormwind","valley of heroes"},rel={"npc:field-marshal-stonebridge","subzone:valley-of-heroes","zone:stormwind","quest:7781","topic:stormwind-kingdom","topic:alliance"},m={start="Grand Admiral Jes-Tereth",["end"]="Field Marshal Stonebridge",faction="Alliance",id=7782},src={"The Lord of Blackrock (Alliance 2)"}}
E["quest:8311"] = {t="quest",n="Hallow's End Treats for Jesper!",z="stormwind",s="During Hallow's End, a young orphan named Jesper waits outside Stormwind City wishing he could join in the holiday festivities. Confined close to home by Matron Nightingale out of fear of monstrous dangers, he asks Alliance adventurers to go trick-or-treating across the world on his behalf.",h="During Hallow's End, a young orphan named Jesper waits outside Stormwind City wishing he could join in the...",sec={{t="A Sheltered Child",b="Jesper is under the strict care of Matron Nightingale, who manages the care of orphaned youths in Stormwind. Fearing perils outside the safety of the fortress walls, the matron forbids him from wandering far to celebrate Hallow's End. Denied the simple childhood joy of gathering sweets from across Azeroth, Jesper stays near the city gates, hoping passing adventurers might share in the holiday spirit and collect treats in his stead.",sp=0},{t="Tricks for Treats Across the Alliance",b="To gather the holiday spread Jesper dreams of, an adventurer must travel far beyond Elwynn Forest. The quest demands visiting the innkeepers of Stormwind, Ironforge, and Darnassus, as well as the gnome exile Talvash del Kissel. Each adult demands a performance before relinquishing their prize—forcing travelers to cluck like chickens, dance, flex, or prepare for incoming aerial confections in exchange for regional sweets like Stormwind Nougat and Gnomeregan Gumdrops.",sp=0}},faq={{q="Who is Jesper?",a="Jesper is a young orphan living under the watch of Matron Nightingale in Stormwind. During Hallow's End, he longs for holiday candy but is not permitted to travel and gather it himself.",al={"jesper stormwind","orphan jesper","who is jesper"}},{q="Why can't Jesper go trick-or-treating himself?",a="Matron Nightingale keeps him under tight watch out of concern for his safety, refusing to allow him to venture far from the city gates into dangerous lands.",al={"why can't jesper leave","matron nightingale rules","jesper trick or treat"}},{q="Which treats does Jesper want?",a="He requests four distinct regional confections: Stormwind Nougat, Ironforge Mints, Darnassus Marzipan, and Gnomeregan Gumdrops.",al={"jesper treats","hallows end treats list","jesper candy needed"}},{q="Where do you obtain the Gnomeregan Gumdrop?",a="Because Gnomeregan remains irradiated and overrun, the gumdrop is handed out by the gnome refugee Talvash del Kissel, who is currently staying in Ironforge's Mystic Ward.",al={"gnomeregan gumdrop location","who gives gumdrop","talvash candy"}},{q="What tricks do the innkeepers make you perform?",a="Innkeepers demand silly antics in exchange for sweets: flexing your muscles in Stormwind, dancing in Darnassus, clucking like a chicken in Ironforge, and playing catch for Talvash.",al={"hallow's end tricks","innkeeper tricks","trick for treats alliance"}},{q="What does Jesper give you in return for the candy?",a="After receiving the assortment of four holiday candies, Jesper happily trades some pumpkin treats he has saved up for the traveler.",al={"jesper reward","treats for jesper completion"}}},ang={["faction:Alliance"]="This holiday effort ties the distant capitals together, asking heroes to travel from the grand streets of Stormwind to the mountain halls of Ironforge and the boughs of Darnassus to bring joy to an orphaned child.",["race:Gnome"]="With their home lost to troggs and radiation, gnomish participation in the holiday falls to Talvash del Kissel in Ironforge, who ensures Gnomeregan Gumdrops are still shared."},kw={"darnassus","gumdrop","hallow's end","ironforge","jesper","marzipan","nightingale","nougat","stormwind","talvash","trick-or-treat"},rel={"npc:jesper","npc:talvash-del-kissel","quest:8356","quest:8353","quest:8357","quest:8355","zone:ironforge","zone:darnassus"},m={start="Jesper",faction="Alliance",id=8311},src={"Hallow's End Treats for Jesper!"}}
E["quest:8356"] = {t="quest",n="Flexing for Nougat",z="stormwind",s="During the autumn celebration of Hallow's End, adventurers visiting Stormwind City can help a local orphan collect festive sweets. To earn a piece of Stormwind Nougat from Innkeeper Allison at the Gilded Rose, visitors are playfully made to strike a mighty flexing pose before she hands over the treat.",h="During the autumn celebration of Hallow's End, adventurers visiting Stormwind City can help a local orphan...",sec={{t="A Hallow's End Tradition",b="Hallow's End brings a rare sense of levity to the streets of Stormwind. While the holiday's ancient roots acknowledge the turning of seasons and the warding off of dark spirits, common folk celebrate it through disguises, revelry, and trick-or-treating. Innkeepers across the Alliance take part by handing out traditional confections, provided the holiday seekers are willing to perform a harmless trick in exchange for their treat.",sp=0},{t="Entertaining the Innkeeper",b="At the Gilded Rose in the bustling Trade District, Innkeeper Allison ensures no one receives holiday candy for free—even when they are running errands for an orphaned boy like Jesper. Observing whatever gear or attire an adventurer is wearing, Allison playfully comments on their physique and insists they flex their muscles for her amusement. Only once an adventurer puts on a display of strength does she reward them with a piece of chewy Stormwind Nougat.",sp=0}},faq={{q="Why does Innkeeper Allison make people flex?",a="Hallow's End revolves around the tradition of tricks and treats. Because the adventurer is visiting on behalf of an orphan seeking sweets, Innkeeper Allison insists they earn the confection with an entertaining trick—namely, showing off their muscles.",al={"why flex for nougat","what does allison want","flex emote why"}},{q="Where does this quest take place?",a="The request is given and fulfilled entirely within the Gilded Rose inn, located in the heart of Stormwind's Trade District, where Innkeeper Allison tends the tavern counter.",al={"where is flexing for nougat","allison location","gilded rose innkeeper"}},{q="Who is the Stormwind Nougat meant for?",a="The nougat is intended for Jesper, an orphan boy staying in Stormwind. He hopes to taste traditional festival treats from each major Alliance city during Hallow's End.",al={"who gets the nougat","who wants stormwind nougat","jesper candy"}},{q="What is Stormwind Nougat?",a="Stormwind Nougat is a regional confection handed out by Stormwind's innkeepers during Hallow's End, known among festival-goers as one of the quintessential sweets of the human kingdom.",al={"stormwind nougat lore","hallow's end nougat","stormwind candy"}},{q="Can Horde players obtain this treat from Allison?",a="No. Innkeeper Allison resides deep within Alliance-controlled Stormwind City and caters only to Alliance members. Horde adventurers perform their own festive antics for innkeepers in their own capital cities.",al={"can horde flex for nougat","horde version of nougat"}},{q="Does this quest happen year-round?",a="No. Innkeeper Allison only offers this request during the seasonal festival of Hallow's End, when trick-or-treating customs take over the cities.",al={"when is flexing for nougat available","is this quest seasonal","hallows end timing"}}},ang={["faction:Alliance"]="The playful exchange highlights the lighter community spirit that flourishes within Stormwind during seasonal festivals like Hallow's End, bringing citizens and wandering heroes together for a good laugh.",["race:Human"]="For humans in Stormwind, indulging children and exchanging tricks for treats is a cherished seasonal custom that offers brief relief from the darker perils facing the kingdom.",["class:Warrior"]="For brawny warriors accustomed to bloody battlefields, showing off arm muscles at an innkeeper's behest makes for a harmless, if slightly undignified, display of strength."},kw={"flexing for nougat","gilded rose","hallow's end","innkeeper allison","jesper","stormwind city","stormwind nougat","trick or treat"},rel={"npc:innkeeper-allison","npc:jesper","quest:8311","topic:stormwind-kingdom"},m={start="Innkeeper Allison",faction="Alliance",id=8356},src={"Flexing for Nougat (Alliance)"}}
E["quest:8569"] = {t="quest",n="Past Efforts in Warsong Gulch",z="stormwind",s="Past Efforts in Warsong Gulch is a military commendation turned in to capital city officers in recognition of service on the front lines. Rather than celebrating outright conquest, it honors veterans who offered valiant struggle and sacrifice amidst the contested woods of Ashenvale. City commanders accept these tokens to sustain war morale and reward dedication across both factions.",h="Past Efforts in Warsong Gulch is a military commendation turned in to capital city officers in recognition of...",sec={{t="Honoring the Fallen and the Valiant",b="War between the Silverwing Sentinels and the Warsong Outriders rarely yields clean or effortless victories. Across the southern borders of Ashenvale, skirmishes are brutal, bloody, and often end without decisive triumph. Recognizing that morale cannot hinge entirely on unblemished success, commanders in Stormwind, Orgrimmar, and other capitals instituted honors for steadfast service. The Ribbon of Sacrifice commemorates those who threw themselves into the fray regardless of the odds.",sp=0},{t="The War Effort at Home",b="Capital officials such as the Alliance Brigadier Generals and Horde Warbringers manage mobilization far behind the front lines. While recruiters direct new blood toward battlefields like Warsong Gulch, quartermasters and tacticians must account for returning fighters who endured grueling campaigns. By acknowledging individual courage and sacrifices in stalemate or defeat, leadership ensures that frontline soldiers remain committed to holding Ashenvale.",sp=0}},faq={{q="What is the purpose of this commendation?",a="The commendation acknowledges frontline combatants who gave everything during engagements in Warsong Gulch. Capital commanders accept proof of heroic struggle to reward perseverance and sustain war morale across the realm.",al={"why do past efforts","past efforts purpose","what does past efforts mean"}},{q="Who accepts these tokens of sacrifice?",a="Senior military liaisons stationed in major cities accept them, including Alliance Brigadier Generals in places like Stormwind and Horde Warbringers in cities like Orgrimmar.",al={"who takes past efforts","where to turn in past efforts","who is the brigadier general"}},{q="Why does the military reward efforts that did not lead to victory?",a="Commanders understand that relentless combat in the forests of Ashenvale exacts a steep toll. Rewarding dedication and grit reminds combatants that their blood and sacrifice are valued even when the battle outcome falls short of total victory.",al={"why reward ribbon of sacrifice","why reward loss","heroic effort meaning"}},{q="Where does the conflict of Warsong Gulch take place?",a="Warsong Gulch lies along the southern border of Ashenvale, where the orcish Warsong Outriders gather lumber while clashing against the fierce resistance of the night elf Silverwing Sentinels.",al={"where is warsong gulch","warsong gulch location","what is warsong gulch"}},{q="Can members of both the Alliance and Horde undertake this?",a="Yes. Both factions maintain equivalent military leaderships in their respective capitals to honor the soldiers returning from the bloody logging skirmishes in Ashenvale.",al={"is this both factions","horde or alliance past efforts","can horde turn this in"}},{q="What does the Ribbon of Sacrifice represent?",a="The Ribbon of Sacrifice is an emblem bestowed upon or carried by combatants who endured fierce clashes in Warsong Gulch, testifying to their unwavering willingness to fight on behalf of their people.",al={"ribbon of sacrifice lore","what is ribbon of sacrifice","sacrifice ribbon"}}},ang={["faction:Alliance"]="For Alliance forces, turning in ribbons to the Brigadier General reaffirms their pledge to defend the ancient forests and support their night elven allies against Warsong aggression.",["faction:Horde"]="For the Horde, delivering tokens to city Warbringers proves that the blood spilled securing wood and survival in Ashenvale was not offered in vain.",["class:Warrior"]="Frontline combatants who weathered the brutal melee in the gulch understand better than anyone that true discipline lies in fighting fiercely even when victory hangs in the balance."},kw={"ashenvale","brigadier general","orgrimmar","past efforts","ribbon of sacrifice","stormwind","warbringer","warsong gulch"},rel={"topic:alliance","topic:horde"},m={start="Alliance Brigadier General,  Horde Warbringer",level="1",faction="Both",id=8569},src={"Past Efforts in Warsong Gulch"}}
E["quest:9260"] = {t="quest",n="Investigate the Scourge of Stormwind",z="stormwind",s="The Scourge invasion has brought the horrors of the Lich King directly to the gates of Stormwind. Outside the capital's walls, necropolises shadow the land while undead abominations and cultists conjure dark magic. Lieutenant Orrin enlists capable defenders to cull the invaders, gather Necrotic Stones, and decipher the sinister runic circles pulsing at their encampments.",h="The Scourge invasion has brought the horrors of the Lich King directly to the gates of Stormwind.",sec={{t="Undead at the Capital's Threshold",b="The presence of Scourge forces so close to Stormwind City is an unsettling shock for the kingdom. Floating necropolises loom overhead while shambling undead and sinister cultists establish footholds right on the doorstep of humanity's greatest bastion. Lieutenant Orrin rallies defenders outside the city to push back these invading horrors before they can overwhelm the capital's perimeter.",sp=0},{t="The Whispering Runes",b="Beyond simply fighting off the walking dead, the mission requires investigating the glowing runic circles etched into the dirt around the enemy encampments. These occult circles crackle with the same fell magic radiating from the necropolises above. Venturing into their glow reveals eerie whispers lingering on the air—unnatural voices that indicate the circles serve as conduits of dark communication coordinating the invasion.",sp=0}},faq={{q="Who is Lieutenant Orrin?",a="Lieutenant Orrin is an officer coordinating defenses outside Stormwind. Operating alongside the Argent Dawn, he organizes local fighters to gather intelligence and dismantle the Scourge footholds threatening the city.",al={"orrin","lieutenant orrin","who gives this quest"}},{q="Why is the Scourge attacking Stormwind?",a="The Lich King has dispatched airborne necropolises and invasion forces across Azeroth to spread terror and swell the ranks of the undead. Stormwind, as a principal seat of living resistance, makes a prime target for these assaults.",al={"why scourge here","scourge invasion stormwind","why attack stormwind"}},{q="What are the glowing runic circles?",a="The runic circles are ritual arrays established by the Scourge near their forward encampments. They pulse with dark necromantic power and whisper with unnatural voices, serving as magical relays used by the invaders for occult communication.",al={"runic circles","glowing runes","what do circles do"}},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones are magical foci carried by the lesser forces of the Scourge invasion. They radiate residual necrotic energies and serve both as proof of dispatched invaders and as curiosities of interest to the Argent Dawn.",al={"dim necrotic stone","necrotic stones","what are necrotic stones"}},{q="What role does the Argent Dawn play in this mission?",a="The Argent Dawn is an independent order dedicated to eradicating the Scourge wherever it appears. Lieutenant Orrin works on their behalf, securing intelligence and stones to aid their broader war against the Lich King's armies.",al={"argent dawn","argent dawn connection"}},{q="Are the runic circles dangerous to approach?",a="While the circles exude unsettling energies and emit discordant whispers, scouts who approach them carefully can glean crucial insight into the Scourge's communications without losing their sanity.",al={"are runes safe","whispers in runes"}}},ang={["faction:Alliance"]="The defense of Stormwind's gates against the Scourge invasion is a matter of sheer survival for the Alliance, proving that even their southern stronghold is within the Lich King's reach.",["class:Paladin"]="Confronting the Scourge right outside Stormwind gives Paladins an urgent duty to unleash holy wrath upon the necromantic circles and protect the kingdom's populace.",["class:Priest"]="The twisted whisperings inside the invasion runes offer Priests direct insight into the corrupting shadow magic binding the Scourge's frontline forces."},kw={"argent dawn","invasion","lich king","lieutenant orrin","necropolis","necrotic stones","runic circles","scourge","stormwind"},rel={"npc:lieutenant-orrin","topic:scourge","topic:argent-dawn","topic:stormwind-kingdom","topic:lich-king"},m={start="Lieutenant Orrin",level="6",faction="Alliance",id=9260},src={"Investigate the Scourge of Stormwind"}}
E["subzone:canals-stormwind-city"] = {t="subzone",n="Canals (Stormwind City)",z="stormwind",s="The Canals are a network of stone-lined waterways weaving through Stormwind City, separating its distinct districts. They serve as quiet thoroughfares for pedestrians and anglers, while quietly harboring hidden hazards and the entrance to the city's prison.",h="The Canals are a network of stone-lined waterways weaving through Stormwind City, separating its distinct...",sec={{t="Arteries of the Capital",b="The Canals link and define the districts of Stormwind, dividing the bustling markets of the Trade District from the aged alleys of Old Town, the cathedral gardens, and the Dwarven District. Stone bridges, archways, and waterside walkways frame quiet establishments like the Gallina Winery, tailor shops, and quiet residential homes. In addition to serving local merchants and recreational fishermen, the waterways conceal the fortified entrance to the Stockade, where Stormwind's most dangerous criminals and rebels are held beneath street level.",sp=0},{t="A Gruesome History and Lurking Shadows",b="The placid surface of the waterways belies a violent past. Following the sack of Stormwind during the First War, the canals were discovered choked with rubble, timber, and the corpses of slaughtered defenders. When the Alliance of Lordaeron liberated the ruins, soldiers undertook the grim labor of clearing the waterways and burying the dead before rebuilding began. Today, while cleaned and restored, the depths retain an air of mystery, fueled by city rumors of a massive albino crocolisk prowling beneath the docks.",sp=0}},faq={{q="What happened to the canals during the First War?",a="When the Orcish Horde conquered and sacked Stormwind in the First War, the waterways were left filled with broken stone, timber, and rotting bodies. The retaking forces of the Alliance of Lordaeron had to painstakingly dredge the canals and properly bury the fallen before the city could be rebuilt.",al={"canal history","canals first war","stormwind sack canals"}},{q="Is there really a monster in the Stormwind canals?",a="Yes. Persistent urban legends tell of a massive white crocolisk lurking in the waterways. City guards and residents often dismiss it as tavern gossip, but watchful fishermen know the beast is very real.",al={"stormwind crocodile","canal alligator","sewer beast","white crocolisk"}},{q="Where is the entrance to the Stockade located?",a="The Stockade entrance is located along the northernmost stretch of the canal surrounding the Mage Quarter, guarded heavily by the Stormwind City Guard.",al={"where is stockade","stockade entrance","how to get to stockade"}},{q="Can players swim through the canals to travel around Stormwind?",a="Swimming the canals is entirely possible, though getting back out onto the street requires finding stone stairs or docks spaced along the waterside paths.",al={"swimming in canals","travel by water stormwind","water route stormwind"}}},ang={["profession:Cooking"]="The quiet canal banks provide convenient spots for aspiring chefs to practice fishing for fresh catches without ever leaving the safety of the capital's walls.",["faction:Alliance"]="The canals stand as a testament to the rebuilding of the capital by the Alliance of Lordaeron, having transformed the choked, corpse-ridden ruins of the First War back into a functional, picturesque city."},kw={"canal district","canals","crocolisk","gallina","sewers","stockade","stormwind","waterways"},rel={"zone:stormwind","zone:stockade","subzone:trade-district","subzone:old-town","subzone:dwarven-district","topic:first-war","topic:alliance-of-lordaeron","quest:66"},src={"Canals (Stormwind City)"}}
E["subzone:cathedral-of-light"] = {t="subzone",n="Cathedral of Light",z="stormwind",s="The Cathedral of Light is the spiritual heart of Stormwind City and the primary sanctuary of the Church of the Holy Light. Standing tall over Cathedral Square, it serves as the central bastion for human priesthood and the Knights of the Silver Hand.",h="The Cathedral of Light is the spiritual heart of Stormwind City and the primary sanctuary of the Church of...",sec={{t="Sanctuary of the Faithful",b="Rebuilt after its devastation during the First War under the guidance of Archbishop Alonsus Faol and then-Bishop Benedictus, the Cathedral of Light stands as a towering beacon of resilience. Its vast halls and subterranean catacombs sheltered desperate refugees during the darkest hours of Stormwind's reconstruction. With the fall of Lordaeron to the Scourge during the Third War, the seat of the Church shifted south to Stormwind. Today, Archbishop Benedictus shepherds the faithful from this grand hall, providing spiritual guidance to the entire Alliance.",sp=0},{t="Halls of Devotion and Arms",b="Beyond serving as a house of prayer and healing, the cathedral acts as the primary headquarters for the remaining Knights of the Silver Hand in the southern kingdoms. High-ranking figures such as Lord Grayson Shadowbreaker and Duthorian Rall train promising squires through the sacred trials of the Tome of Valor and the Tome of Divinity. Alongside them, High Priestess Laurena guides devout acolytes in the deepest tenets of the Light, preparing holy champions to defend the realm against the rising threat of the Defias Brotherhood and the Scourge.",sp=0}},faq={{q="Who leads the Church inside the cathedral?",a="Archbishop Benedictus serves as the head of the Church of the Holy Light. Following the fall of Lordaeron and the demise of Archbishop Alonsus Faol, Benedictus assumed spiritual leadership over the reformed Church from his dais in Stormwind.",al={"cathedral leader","who is the archbishop","who leads the church"}},{q="What is the cathedral's connection to the paladins?",a="The cathedral serves as the operational headquarters of the Knights of the Silver Hand in the kingdom of Stormwind. Renowned paladins like Lord Grayson Shadowbreaker and Duthorian Rall instruct new squires, bestow sacred tomes, and direct crusaders against enemies of the realm.",al={"silver hand stormwind","paladin order stormwind","why are paladins here"}},{q="What lies beneath the cathedral floor?",a="Beneath the main sanctuary lie ancient catacombs. Historically used as a shelter for refugees during the First and Second Wars, they now serve as the final resting place for honored heroes, priests, and paladins.",al={"cathedral basement","cathedral catacombs","what is under the cathedral"}},{q="Where did the cathedral's bell come from?",a="The great bell tolling from the cathedral was forged upon the Great Forge in Ironforge. Crafted alongside a twin bell meant for Lordaeron, it was gifted to humanity by the dwarves as a testament to the enduring friendship between their kingdoms.",al={"cathedral bell lore","who made the bell"}}},ang={["class:Paladin"]="The Cathedral of Light serves as your principal order hall in Stormwind, where mentors like Duthorian Rall and Lord Grayson Shadowbreaker guide you through the sacred trials of the Tomes of Valor and Divinity.",["class:Priest"]="As the supreme seat of the Church of the Holy Light in the southern kingdoms, the cathedral is where High Priestess Laurena and Archbishop Benedictus nurture your spiritual devotion and sacred healing arts."},kw={"benedictus","cathedral of light","cathedral square","duthorian rall","holy light","laurena","shadowbreaker","silver hand","stormwind"},rel={"subzone:cathedral-square","topic:church-of-the-holy-light","topic:knights-of-the-silver-hand","npc:archbishop-benedictus","npc:lord-grayson-shadowbreaker","npc:high-priestess-laurena","npc:duthorian-rall","zone:stormwind"},src={"Cathedral of Light"}}
E["subzone:cathedral-square"] = {t="subzone",n="Cathedral Square",z="stormwind",s="Cathedral Square is the spiritual and civic heart of Stormwind City, dominated by the majestic Cathedral of Light. Beyond serving as a place of worship and devotion, the bustling plaza houses municipal institutions like City Hall, the city orphanage, and the regional headquarters of the Argent Dawn.",h="Cathedral Square is the spiritual and civic heart of Stormwind City, dominated by the majestic Cathedral of...",sec={{t="The Holy District",b="Situated northwest of the Trade District and southwest of the Dwarven District, Cathedral Square serves as the epicenter of faith in the Kingdom of Stormwind. Dominating the skyline is the Cathedral of Light, the preeminent sanctuary for followers of the Holy Light across Azeroth. Priests, paladins, and healers gather here to study, pray, and train. Between the cathedral's imposing spires and the open plaza lies a tranquil green space centered around a gazebo and the quiet grounds of the Stormwind City Cemetery to the north. Citizens, pilgrims, and local schoolchildren led by School Mistress Danna regularly mingle in the square for conversation and contemplation.",sp=0},{t="Civic Heart and Holy Order",b="The district is not merely reserved for prayer; it is one of the capital's busiest civic centers. The square houses the Stormwind Orphanage as well as City Hall, anchoring the administrative life of the kingdom. Specialized armorers and weaponsmiths catering to holy crusaders, such as Righteous Plates and Just Maces, line the avenues. It also serves as the base of operations for the Argent Dawn within Stormwind, where recruiters and representatives coordinate relief efforts and rally champions against the encroaching threats of the Scourge in the northern kingdoms.",sp=0}},faq={{q="What is Cathedral Square?",a="Cathedral Square is a major district in Stormwind City centered on the Cathedral of Light. It serves as both the spiritual hub for practitioners of the Light and a vital civic center housing City Hall, the local orphanage, and various shops.",al={"cathedral district","holy district","what is this place"}},{q="Who trains in Cathedral Square?",a="Priests and Paladins of the Alliance come to Cathedral Square and the Cathedral of Light to hone their skills and study sacred doctrines. Medics and caregivers also study here under First Aid trainers.",al={"class trainers here","who trains here","paladin priest trainers"}},{q="Why is the Argent Dawn located here?",a="The Argent Dawn maintains a prominent embassy in Cathedral Square to recruit able-bodied champions and coordinate logistical support from Stormwind for their relentless crusade against the Scourge in the Plaguelands.",al={"argent dawn stormwind","argent dawn presence"}},{q="Where does Cathedral Square lead?",a="Bridges and canal paths link Cathedral Square directly to the bustling Trade District to the southeast, the industrial Dwarven District to the northeast, and the quiet gardens of the Park to the southwest.",al={"connected districts","where does this go"}}},ang={["class:Paladin"]="For paladins, Cathedral Square is the fountainhead of faith and duty, housing mentors, sacred vows, and specialized armorers tailored to holy warriors.",["class:Priest"]="The quiet halls and towering spires of the square offer priests a tranquil sanctuary to commune with the Holy Light, advance their spiritual studies, and minister to the citizens of Stormwind."},kw={"argent dawn","cathedral of light","cathedral square","city hall","holy district","orphanage","paladin","priest","stormwind"},rel={"subzone:cathedral-of-light","zone:stormwind","topic:argent-dawn","topic:light","subzone:trade-district","subzone:dwarven-district","subzone:park"},src={"Cathedral Square"}}
E["subzone:champions-hall"] = {t="subzone",n="Champions' Hall",z="stormwind",s="Tucked away in the southern reaches of Old Town, the Champions' Hall serves as the officer's barracks and supply armory for the Alliance's decorated veterans in Stormwind. Beyond its threshold, quartermasters dispense specialized weapons, plate, and regalia to proven warriors of the faction. Access is strictly guarded, reserved only for officers who have demonstrated valor on the field of war.",h="Tucked away in the southern reaches of Old Town, the Champions' Hall serves as the officer's barracks and...",sec={{t="The Alliance Officer's Barracks",b="Hidden behind a guarded threshold in Old Town, the Champions' Hall is a restricted haven for the Alliance's most distinguished combatants. Military commanders gather here over tactical maps of Azeroth to confer on ongoing campaigns, flanked by armaments and the grand insignias of rank. Only soldiers who have climbed the Alliance hierarchy to achieve officer status—specifically the rank of Knight or higher—are permitted entry. Inside, military quartermasters supply battle-hardened soldiers with elite arms, armor, and mounts crafted specifically to turn the tide against the Horde in contested zones across the world.",sp=0}},faq={{q="Where is the Champions' Hall located?",a="The Champions' Hall is located in the southern section of Old Town in Stormwind City, tucked away behind a guarded entrance.",al={"where is champions hall","pvp vendor stormwind location","how to find champions hall"}},{q="Who is allowed inside the Champions' Hall?",a="Only Alliance veterans who have earned the military rank of Knight (Rank 6) or higher through the faction's honor system are granted passage through the entrance portal. Unproven recruits and civilians are barred at the threshold.",al={"can anyone enter","champions hall requirements","why cant i enter champions hall"}},{q="What is inside the Champions' Hall?",a="The hall contains quartermasters offering officer-tier weapons, armor, insignia, and specialized war mounts. Alliance tacticians and generals also congregate around war tables lined with regional maps of Azeroth.",al={"what does champions hall have","what vendors are in champions hall","champions hall rewards"}},{q="What is the Horde equivalent of this building?",a="The Horde counterpart is the Hall of Legends, situated in Orgrimmar, which provides identical military supply services to decorated warriors of the Horde.",al={"horde version of champions hall","orgrimmar pvp room","horde pvp barracks"}}},ang={["faction:Alliance"]="The hall stands as the premier symbol of Alliance military merit in Stormwind, honoring those who dedicate their lives to repelling Horde incursions.",["class:Warrior"]="For front-line combatants, the hall represents the ultimate military stockpile, offering heavy battle gear and armaments reserved only for proven battlefield leaders."},kw={"champions hall","grand marshal","knight","officer barracks","old town","pvp vendors","quartermaster","stormwind"},rel={"subzone:old-town","zone:stormwind","subzone:hall-of-legends","topic:alliance","topic:horde","topic:stormwind-kingdom"},src={"Champions' Hall"}}
E["subzone:command-center"] = {t="subzone",n="Command Center",z="stormwind",s="The Command Center, often referred to as the Stormwind Barracks, stands in the heart of Old Town as the operational headquarters for the city's military officers. In peacetime, it houses the standing army, but with Stormwind's forces dispatched to distant frontiers, it currently operates with a seasoned skeleton crew focused on drilling recruits and local militia.",h="The Command Center, often referred to as the Stormwind Barracks, stands in the heart of Old Town as the...",sec={{t="A Thin Line of Defense",b="Situated within the weathered streets of Old Town, the Command Center serves as the primary garrison and martial training ground for the kingdom of Stormwind. Normally packed with regular infantry and ranking officers, the facility is uncharacteristically sparse. With much of the royal army committed to campaigns abroad, the barracks relies on a veteran cadre of instructors—including Ander Germaine and martial artist Wu Shen—to train fresh warriors, while figures like Wulf Hansreim drill marksmen to bolster the city's defenses.",sp=0},{t="Old Town's Martial Hub",b="Guards throughout Stormwind often direct newcomers to the 'Barracks' when seeking instruction in heavy arms and tactical combat. The building's proximity to both the Pig and Whistle Tavern and the shadowy operations elsewhere in Old Town makes it an essential anchor of order in a district known for tavern brawls and roguish activity.",sp=0}},faq={{q="Why is the Command Center so empty?",a="Most of Stormwind's standing army has been deployed to distant outposts and foreign battlefields across the world. The Command Center currently maintains only a skeleton crew of seasoned veterans to instruct new recruits and organize local defense.",al={"why few guards here","where is stormwind army","barracks empty"}},{q="Is the Command Center the same as the Stormwind Barracks?",a="Yes. While officially designated the Command Center, city guards and local residents routinely refer to the building as the Stormwind Barracks when giving directions.",al={"stormwind barracks","are command center and barracks the same","barracks location"}},{q="Who leads the training here?",a="Ander Germaine coordinates and trains the city's warriors alongside instructors like Wu Shen and Ilsa Corbin, while Wulf Hansreim oversees hunter and marksman training.",al={"who trains warriors here","warrior trainer command center","who runs the barracks"}},{q="Where is the Command Center located?",a="The Command Center is located in Old Town, situated near the Pig and Whistle Tavern and central to the district's training facilities.",al={"where is command center","command center location","how to find command center"}}},ang={["class:Warrior"]="The Command Center is the primary hub in Stormwind for warrior training, where veterans like Ander Germaine and Wu Shen hone recruits into disciplined frontline soldiers.",["class:Hunter"]="Marksmen visiting Stormwind report to the Command Center to learn techniques from veteran trainers such as Wulf Hansreim."},kw={"ander germaine","barracks","command center","hunter trainer","old town","stormwind barracks","warrior trainer","wu shen","wulf hansreim"},rel={"subzone:old-town","zone:stormwind","subzone:pig-and-whistle-tavern","quest:2300","topic:stormwind-kingdom","topic:alliance"},src={"Command Center"}}
E["subzone:cut-throat-alley"] = {t="subzone",n="Cut-Throat Alley",z="stormwind",s="Cut-Throat Alley is a secluded, unpopulated back corner of Stormwind City hidden away behind the canal shops. Tucked behind a storefront called the Shady Lady near the Dwarven District border, it consists of a quiet courtyard and an empty residence cut off from normal city foot traffic.",h="Cut-Throat Alley is a secluded, unpopulated back corner of Stormwind City hidden away behind the canal shops.",sec={{t="A Secluded Nook",b="Cut-Throat Alley is one of Stormwind's quietest and most secretive corners. Though technically charted alongside the Dwarven District, it shares none of the district's roaring forge fires or heavy soot. The alley cannot be reached from any of the city's main avenues; the only foot path leads straight through the Shady Lady, a small shop lining the canals just south of the bridge from Cathedral Square. Beyond the shop door lies a small paved dead-end lined with stacked crates, forgotten barrels, and a single unoccupied two-story residence. Completely hidden from passing guards and ordinary citizens, it sits entirely silent amidst the bustle of the capital.",sp=0}},faq={{q="How do you get to Cut-Throat Alley?",a="Head to the canal front along the edge of the Dwarven District, just south of the footbridge leading to Cathedral Square. Look for a shop named the Shady Lady. Walking straight through the back of this establishment brings you right out into the tucked-away alley.",al={"find cut throat alley","cut throat alley location","where is cut-throat alley","how to enter cut-throat alley"}},{q="Why does the map call this the Dwarven District?",a="The outdoor passage shares the broader Dwarven District subzone label on common maps. The name 'Cut-Throat Alley' only reveals itself on your compass once you step inside the empty two-story home at the back of the lot.",al={"minimap dwarven district","why does it say dwarven district","cut-throat alley name bug"}},{q="Is anyone living in Cut-Throat Alley?",a="No. The alley and its lone two-story house are completely abandoned. Aside from stacked cargo crates and empty barrels, there are no residents, shopkeepers, or city watchmen stationed here.",al={"cut throat alley npcs","who lives in cut throat alley","empty house cut throat alley"}},{q="Are there any quests in Cut-Throat Alley?",a="There are no formal duties or civic assignments that lead into the alley. It serves purely as an overlooked, secluded backdrop within the capital.",al={"cut throat alley quests","cut throat alley storyline"}}},ang={["class:Rogue"]="Accessible only through the rear door of a shady canal shop, this unpatrolled dead-end offers an ideal hideout for anyone who prefers to stay out of sight of the Stormwind City Guard."},kw={"cathedral square","cut-throat alley","dwarven district","secret alley","shady lady","stormwind canals"},rel={"subzone:dwarven-district","subzone:canals-stormwind-city","subzone:cathedral-square","topic:stormwind-kingdom","topic:alliance"},src={"Cut-Throat Alley"}}
E["subzone:dwarven-district"] = {t="subzone",n="Dwarven District",z="stormwind",s="Tucked into the northern corner of Stormwind City, the Dwarven District is a bustling industrial enclave filled with roaring furnaces, ringing anvils, and thick smog. Established by Ironforge craftsmen who arrived to help rebuild the capital after the Second War, it serves as the beating mechanical heart of the city.",h="Tucked into the northern corner of Stormwind City, the Dwarven District is a bustling industrial enclave...",sec={{t="A Home Away from Khaz Modan",b="Following the devastation of the Second War, King Magni Bronzebeard sent hundreds of dwarven artisans, stonemasons, and engineers south to assist their human allies in rebuilding Stormwind. Rather than dispersing throughout the capital, they established their own enclave in the northern quarter. Today, the district retains the unmistakable character of Ironforge, dominated by heavy stone masonry, sprawling smelting operations, and bustling craft shops. Between the heat of Potts' Plates and the tavern chatter of The Golden Keg, the enclave provides a familiar haven for travelers from Khaz Modan. It also houses the Stormwind portal to the Deeprun Tram, tethering the human capital directly to Ironforge.",sp=0}},faq={{q="Why is there a dwarven enclave in Stormwind?",a="After Stormwind was destroyed during the First War and retaken in the Second War, King Magni Bronzebeard sent dwarven craftsmen and laborers south to aid in the capital's reconstruction. The workers settled in this northern sector, building workshops and homes suited to their tastes.",al={"why dwarves in stormwind","dwarf area origin","why is it called dwarven district"}},{q="How do you get to Ironforge from here?",a="On the eastern side of the district, an open arched tunnel leads directly into the Deeprun Tram station. This subterranean marvel connects Stormwind to Ironforge within minutes.",al={"how to get to ironforge","where is the tram","deeprun tram entrance"}},{q="What professions are trained in the Dwarven District?",a="Given its industrial character, the district is the city's premier hub for mining, blacksmithing, and engineering. It features heavy forges, anvils, and dedicated trainers for these craft disciplines.",al={"professions dwarven district","trainers in dwarven district","blacksmith trainer stormwind"}},{q="Where can hunters train in Stormwind?",a="Stormwind's hunters make their headquarters in the Dwarven District's Hunter's Guild, fittingly sharing quarters and trade supplies alongside dwarven marksmen.",al={"hunter trainer stormwind","hunter lodge","stormwind hunter guild"}}},ang={["race:Dwarf"]="For dwarves far from Khaz Modan, this district offers a familiar comfort: the roar of working blast furnaces, stout ale at The Golden Keg, and quick passage back to Ironforge.",["profession:Blacksmithing"]="The district provides Stormwind's most capable smithing facilities, equipped with expansive smelting forges, sturdy anvils, and veteran instructors."},kw={"deeprun tram","dwarven district","hunters guild","ironforge","magni bronzebeard","potts plates","stormwind","the golden keg"},rel={"subzone:deeprun-tram","zone:stormwind","zone:ironforge","subzone:cathedral-square","subzone:old-town","subzone:cut-throat-alley","topic:second-war"},src={"Dwarven District"}}
E["subzone:gryphon-roost"] = {t="subzone",n="Gryphon Roost",z="stormwind",s="Perched along the ramparts just east of Stormwind's Trade District, the Gryphon Roost serves as the capital's primary transit hub for aerial travel. Managed by skilled Wildhammer handlers, it houses the majestic beasts that ferry couriers, soldiers, and adventurers across the Eastern Kingdoms.",h="Perched along the ramparts just east of Stormwind's Trade District, the Gryphon Roost serves as the capital's...",sec={{t="Gateway to the Skies",b="Situated atop the fortifications overlooking the Trade District canal, the Gryphon Roost connects the capital with outlying Alliance garrisons and settlements throughout the Eastern Kingdoms. The flight network is orchestrated by the seasoned master Dungar Longdrink, who coordinates routes to Ironforge, Lakeshire, Sentinel Hill, and beyond. Alongside Dungar, Wildhammer kin tend to the sturdy beasts, seeing to their care, breeding, and harness training high above the bustling cobblestones below.",sp=0},{t="A Touch of the Aerie",b="While Stormwind is predominantly a kingdom of men, the presence of gryphons and their handlers brings a bit of Hinterlands tradition directly into the city walls. Gryphons have long been revered partners of the Wildhammer clan, who introduced aerial warfare and transport to the broader Alliance during the Second War. Here on the roost, the salty smell of leather, feed, and fresh winds creates a distinct frontier atmosphere amid the city's stone masonry.",sp=0}},faq={{q="Where is the Gryphon Roost located in Stormwind?",a="The roost is perched on the eastern ramparts accessible via a stairway directly leading up from the Trade District, overlooking the canals between the Trade District and Old Town.",al={"where is the roost","stormwind flight master location","find gryphon roost"}},{q="Who manages the roost's flights?",a="Dungar Longdrink, a dwarven flight master, oversees the roost. He organizes routes and rents out trained gryphons to travelers bound for allied settlements across the continent.",al={"who is the flight master","stormwind flight master","dungar longdrink"}},{q="Why are dwarves running the roost in a human city?",a="The Wildhammer dwarves are the traditional masters of gryphon taming and riding. Stormwind relies on their unmatched expertise to care for, breed, and train the beasts for reliable military and civilian transport.",al={"why dwarves in stormwind roost","wildhammer in stormwind","dwarven gryphons"}},{q="Where can the gryphons fly from here?",a="Gryphons dispatched from Stormwind connect primarily to regional settlements in Elwynn, Westfall, Redridge, and Duskwood, as well as longer overland routes leading north to Ironforge and the Wetlands.",al={"flight paths from stormwind","where do gryphons go","roost flight connections"}}},ang={["race:Dwarf"]="The Gryphon Roost serves as an essential bridge between dwarven aviation traditions and the human capital, with Wildhammer expertise keeping Stormwind connected to Khaz Modan.",["faction:Alliance"]="Aerial courier lines operating out of the roost are vital for coordinating Alliance responses across troubled territories like Westfall and Redridge."},kw={"dungar longdrink","flight master","gryphon roost","stormwind flight","trade district","wildhammer"},rel={"zone:stormwind","quest:6261","subzone:trade-district","topic:stormwind-kingdom"},src={"Gryphon Roost"}}
E["subzone:mage-quarter"] = {t="subzone",n="Mage Quarter",z="stormwind",s="The Mage Quarter forms the arcane heart of Stormwind City, resting across the canals in the capital's southwestern corner. Towering over its cobblestone streets and esoteric specialty shops stands the Wizard's Sanctum, where the kingdom's conjurers hone their craft. Beneath the district's scholarly surface also lie shadowy recesses, harboring practitioners of far darker arts.",h="The Mage Quarter forms the arcane heart of Stormwind City, resting across the canals in the capital's...",sec={{t="Sanctum of the Arcane",b="Reachable by bridges crossing the canals from Cathedral Square or the Trade District, the Mage Quarter caters entirely to the mystical needs of the Alliance. Centered around the spire of the Wizard's Sanctum, human and allied spellcasters gather to study the weave of arcane magic and train apprentices. The surrounding streets are crowded with purveyors of tailoring cloth, reagents, alchemical supplies, and enchanted staves, creating an insular district dedicated to research and the defense of the kingdom.",sp=0},{t="Secrets Beneath the Surface",b="Not all sorcery practiced in the quarter is approved by the kingdom's high conjurers. While establishments like The Blue Recluse offer quiet refuge for scholars, the infamous Slaughtered Lamb tavern conceals a covert coven of warlocks in its subterranean crypts. There, out of sight of the city guard and the holy eyes of Cathedral Square, demonologists study forbidden fel rites and bind otherworldly entities while masquerading beneath the district's general tolerance of mystic anomalies.",sp=1}},faq={{q="What is the Wizard's Sanctum?",a="The Wizard's Sanctum is the prominent tower dominating the Mage Quarter. It serves as the primary academy, library, and training grounds for Stormwind's mages, housing scholars, mystic trainers, and defensive spellcasters tasked with protecting the capital.",al={"mage tower","wizards sanctum","mage sanctum stormwind"}},{q="Where can warlocks train in the Mage Quarter?",a="Warlocks gather secretly beneath The Slaughtered Lamb, an unassuming tavern in the quarter. Down in its crypts and hidden cellars, practitioners of fel magic can study dark rituals, summon demons, and train outside the scrutiny of the city guard.",al={"warlock trainer location","slaughtered lamb basement","stormwind warlock trainers"}},{q="What kind of shops are in the Mage Quarter?",a="The district is filled with specialty trades catering to casters and crafters. Visitors can find tailoring shops like Duncan's Textiles and Larson Clothiers, alchemy and herbalism merchants, enchanting vendors, pyrotechnic suppliers, and staff merchants.",al={"mage quarter vendors","what shops are here","stores in mage quarter"}},{q="How do you reach the Mage Quarter?",a="The Mage Quarter occupies the southwestern corner of Stormwind City. It can be accessed directly by crossing the bridges that span the Canals from either the Trade District or Cathedral Square.",al={"where is mage quarter","how to get to mage quarter","directions to mage quarter"}}},ang={["class:Mage"]="The district serves as your central home in Stormwind, offering master trainers and spell reagents inside the Wizard's Sanctum.",["class:Warlock"]="Beneath the public guise of The Slaughtered Lamb tavern lies the hidden coven where practitioners of the dark arts convene to train and summon minions in secret."},kw={"arcane","blue recluse","canals","mage quarter","slaughtered lamb","stormwind","wizard's sanctum"},rel={"zone:stormwind","subzone:slaughtered-lamb","subzone:canals-stormwind-city","subzone:trade-district","subzone:cathedral-square","zone:blastedlands","topic:alliance"},src={"Mage Quarter"}}
E["subzone:northern-elwynn-mountains"] = {t="subzone",n="Northern Elwynn Mountains",z="stormwind",s="The Northern Elwynn Mountains form the rugged, towering northern border of Stormwind City and Elwynn Forest. These jagged peaks shelter the kingdom's capital from the untamed wildlands of the north, rising high above the city ramparts and coastline.",h="The Northern Elwynn Mountains form the rugged, towering northern border of Stormwind City and Elwynn Forest.",sec={{t="A Natural Bulwark",b="The craggy ridges of the Northern Elwynn Mountains cradle the city of Stormwind along its northern edge. Serving as a massive natural barricade, the range shields the kingdom's capital from overland invasion and bounds the northern perimeter of the coastal cliffs and the surrounding forest. Though largely sheer rock faces, these high bluffs watch silently over the bustling streets, fortified walls, and winding waterways below.",sp=0}},faq={{q="Where are the Northern Elwynn Mountains located?",a="They lie directly along the northern periphery of Stormwind City, rising behind the city's coastal cliffs and defining the northernmost geographic boundary of the Elwynn region.",al={"northern elwynn mountains location","where is northern elwynn mountains","where are the northern mountains"}},{q="What borders the Northern Elwynn Mountains?",a="The mountains sit directly adjacent to the northern edges of Stormwind City, Elwynn Forest, and the surrounding Stormwind outskirts.",al={"northern elwynn mountains borders","what is near northern elwynn mountains"}},{q="Is there a settlement in these mountains?",a="No. The mountains consist of rugged, uninhabited rock faces and high ridges that serve primarily as a defensive natural barrier rather than populated land.",al={"who lives in the northern elwynn mountains","are there towns in northern elwynn mountains"}}},ang={["faction:Alliance"]="These looming heights provide a crucial geographic shield for the Alliance's primary stronghold in the Eastern Kingdoms, preventing easy overland access to Stormwind from the north."},kw={"cliffs","elwynn","mountains","northern elwynn mountains","ridge","stormwind"},rel={"zone:stormwind","zone:elwynn","topic:stormwind-kingdom"},src={"Northern Elwynn Mountains"}}
E["subzone:old-town"] = {t="subzone",n="Old Town",z="stormwind",s="Old Town is the oldest and grittiest quarter of Stormwind City, having largely survived the destruction of the First War intact. Rather than gleaming stone plazas, its narrow alleys feature weathered brick, working-class tenements, and bustling military facilities. It serves as home to the kingdom's military Command Center as well as the clandestine headquarters of SI:7.",h="Old Town is the oldest and grittiest quarter of Stormwind City, having largely survived the destruction of...",sec={{t="A Relic of the Old Kingdom",b="While the rest of Stormwind was painstakingly rebuilt from the ground up by the Stonemasons following the First War, Old Town escaped total ruin. Because it did not require wholesale reconstruction, it never received the pristine marble facades and grand canals seen in the Trade District or Cathedral Square. Instead, it remains a rustic, crowded quarter where working folk, laborers, and the city's poorest residents reside. Its cobbled streets are narrower, dirtier, and far more chaotic than the rest of the capital, yet they preserve the authentic atmosphere of pre-war Stormwind.",sp=0},{t="Soldiers, Spies, and Taverns",b="Behind its weathered tenements, Old Town functions as the martial backbone of the Alliance capital. The Command Center houses Stormwind's military officers, barracks, and combat trainers, alongside the Champions' Hall where the Alliance's finest warriors gather. Tucked away toward the district's edge sits the covert compound of SI:7, the kingdom's secretive intelligence agency led by Master Mathias Shaw. Off-duty footmen and shadowy operatives alike gather at the Pig and Whistle Tavern, rubbing shoulders in one of the city's liveliest watering holes.",sp=0}},faq={{q="Why does Old Town look so much dirtier than the rest of Stormwind?",a="Old Town largely survived the Horde's razing of Stormwind during the First War. Because it was not leveled, the Stonemasons did not rebuild it from scratch, meaning it missed out on the pristine new masonry and grand architecture granted to the rest of the city.",al={"why is old town run down","old town poverty","why is old town gross"}},{q="What is SI:7 and where is it located?",a="SI:7 is the secretive intelligence agency of Stormwind and the Alliance, overseen by Master Mathias Shaw. Their covert headquarters is tucked away in the back of Old Town, past the training yards and military stables.",al={"si7 location","what is si:7","stormwind spies"}},{q="What is the Command Center in Old Town used for?",a="The Command Center serves as the primary garrison and headquarters for Stormwind's military. Inside and around its yard, officers coordinate city defenses, while warriors and hunters train alongside stable masters and riding instructors.",al={"command center purpose","old town barracks","stormwind military headquarters"}},{q="Where is the tavern in Old Town?",a="The local watering hole is the Pig and Whistle Tavern, located near the center of the district. It is famous for hosting hungry soldiers, adventurers, and travelers looking for hearty cooking recipes.",al={"old town inn","pig and whistle location","where is pig and whistle"}}},ang={["class:Rogue"]="Old Town is your natural sanctuary in the capital; behind its ordinary alleys lies the headquarters of SI:7, where master spies and covert handlers offer guidance.",["class:Warrior"]="The Command Center and Champions' Hall make Old Town the premier gathering place in Stormwind for battle-tested veterans seeking gear and combat training."},kw={"champions hall","command center","first war","mathias shaw","old town","pig and whistle","si:7","stormwind"},rel={"zone:stormwind","subzone:command-center","npc:mathias-shaw","subzone:pig-and-whistle-tavern","subzone:champions-hall","subzone:trade-district","subzone:dwarven-district","topic:first-war"},src={"Old Town"}}
E["subzone:park"] = {t="subzone",n="Park",z="stormwind",s="Tucked along the western edge of Stormwind City between Cathedral Square and the Mage Quarter, the Park is a lush sanctuary of greenery and quiet reflection. Devoted to nature and leisure amidst the bustling stone capital, it serves as the primary haven for visiting night elves and houses the only druid trainers in the Eastern Kingdoms.",h="Tucked along the western edge of Stormwind City between Cathedral Square and the Mage Quarter, the Park is a...",sec={{t="A Grove in the Stone Capital",b="While the rest of Stormwind is dominated by cobbled walkways, towering limestone ramparts, and crowded market stalls, the Park offers a tranquil breath of wilderness. Originally established as a quiet place of recreation for the city's populace, it naturally transformed into an enclave for night elf emissaries and travelers arriving from across the Great Sea. Sheltered beneath shaded canopies and surrounding a central Moonwell, the district brings a sliver of Kalimdor's sacred glades into the heart of the human kingdom.",sp=0},{t="Sanctuary and Fellowship",b="For the night elves, the Park is a vital foothold in foreign lands. Here, Kaldorei priests such as Nara Meideros tend to visiting pilgrims, and druidic mentors offer their guidance to those devoted to the wild. The district also serves as a peaceful retreat where weary adventurers rest their eyes from the clatter of the Trade District and the solemn duties of the Cathedral.",sp=0}},faq={{q="Where is the Park located in Stormwind?",a="The Park sits along the far western edge of Stormwind City. You can reach its verdant paths by heading southwest from Cathedral Square or northwest from the Mage Quarter.",al={"where is the park","how to get to the park","park location"}},{q="Why are there so many night elves in the Park?",a="The Park was embraced as a refuge by visiting night elves who sought relief from Stormwind's towering stone streets. Its lush groves and serene atmosphere reminded them of their home forests, leading them to settle here and even establish a Moonwell in the square.",al={"why night elves here","stormwind night elf district","kaldorei district"}},{q="Can I train druid abilities here?",a="Yes. The Park is currently the only place anywhere in the Eastern Kingdoms where Alliance druid trainers are stationed, offering guidance and training to Kaldorei practitioners away from Kalimdor.",al={"druid trainers stormwind","where to train druid eastern kingdoms","park druid training"}},{q="What is the glowing pool in the center of the Park?",a="The pool in the middle of the Park is a consecrated night elven Moonwell, created by Kaldorei visitors to serve as a sacred font of spiritual peace and lunar power amidst the human city.",al={"park moonwell","glowing fountain park","pool in the park"}}},ang={["race:NightElf"]="For night elves traveling across the sea, the Park provides a welcome taste of home, centered around a glowing Moonwell and familiar teachers of Elune and the wild.",["class:Druid"]="This tranquil enclave is your sole sanctuary for training and counsel across all of the Eastern Kingdoms."},kw={"druid","kaldorei","moonwell","nara meideros","night elf","park","stormwind"},rel={"zone:stormwind","subzone:cathedral-square","subzone:mage-quarter","topic:night-elf","topic:druid","npc:nara-meideros","npc:argos-nightwhisper","quest:3765"},src={"Park"}}
E["subzone:petitioner-s-chamber"] = {t="subzone",n="Petitioner's Chamber",z="stormwind",s="The Petitioner's Chamber, also known as the Hall of Petitioners, is an antechamber situated just off the main entrance ramp of Stormwind Keep. It serves as an official waiting room for nobility, church dignitaries, and visiting subjects seeking an audience with the crown. Those lingering here often pass the hours mingling, drinking, or waiting upon the regent's pleasure.",h="The Petitioner's Chamber, also known as the Hall of Petitioners, is an antechamber situated just off the main...",sec={{t="A Room of Waiting and Influence",b="Found immediately to the right upon ascending into Stormwind Keep, the Petitioner's Chamber is where matters of state meet everyday bureaucracy. Nobles such as Count Remington Ridgewell and high-ranking clergy like Bishop DeLavey pass their time in these halls while waiting for an audience with the boy-king Anduin Wrynn and Highlord Bolvar Fordragon. Behind the polished veneer of courtly etiquette, it is an ideal corner of the castle for gossip, quiet lobbying, and discerning who truly holds influence within the realm.",sp=0}},faq={{q="Where is the Petitioner's Chamber located?",a="The chamber is located inside Stormwind Keep. As soon as you ascend the grand entrance ramp into the keep, it is the first room directly on your right.",al={"where is petitioners chamber","how to find petitioner chamber","petitioner room location"}},{q="Who gathers in this room?",a="The room is frequented by petitioners, court attendees, and nobles seeking the ear of the throne, including figures like Count Remington Ridgewell, Caledra Dawnbreeze, and Bishop DeLavey of the Church of the Holy Light.",al={"who is in petitioners chamber","npcs in petitioner chamber","who waits here"}},{q="Why is it also called the Hall of Petitioners?",a="Its formal function is to host subjects who have submitted formal petitions to the crown. Visitors must wait here until the regent, Highlord Bolvar Fordragon, or the royal council grants them admittance to the throne room.",al={"hall of petitioners","why called hall of petitioners","petitioners hall"}},{q="What happens here during city quests?",a="The chamber is primarily visited when delivering goods or speaking with nobles and clergy stationed within the keep, such as running errands to supply refined drinks like port for thirsty aristocrats waiting on court business.",al={"petitioner chamber quests","what quests lead here"}}},ang={["faction:Alliance"]="For Alliance loyalists, this chamber represents the administrative bottleneck of Stormwind, where domestic appeals, church affairs, and noble requests await the royal council's scarce attention.",["class:Priest"]="With Bishop DeLavey often stationed in this antechamber, the room serves as an intersection between the Holy Light's administrative hierarchy and the royal court."},kw={"bishop delavey","caledra dawnbreeze","count remington ridgewell","hall of petitioners","petitioners chamber","stormwind keep"},rel={"subzone:stormwind-keep","npc:count-remington-ridgewell","npc:bishop-delavey","quest:335","topic:stormwind-kingdom","topic:alliance"},src={"Petitioner's Chamber"}}
E["subzone:pig-and-whistle-tavern"] = {t="subzone",n="Pig and Whistle Tavern",z="stormwind",s="The Pig and Whistle Tavern is a bustling inn nestled within Stormwind City's rugged Old Town district. It serves as a favored gathering spot for Alliance travelers, local laborers, and weathered veterans recalling the kingdom's past conflicts.",h="The Pig and Whistle Tavern is a bustling inn nestled within Stormwind City's rugged Old Town district.",sec={{t="A Refuge in Old Town",b="Situated amidst the gritty, winding alleys of Old Town, the Pig and Whistle Tavern offers warmth, ale, and lodging to those who walk the capital's rougher quarter. While the nobles of the city congregate in cathedral squares and marble plazas, this establishment caters to common citizens, working folk, and travelers fresh from the road. Inside, patrons can find merchants like the renowned recipe vendor Kendor Kabonka, alongside grizzled veterans who nurse their tankards while trading memories of the First and Second Wars.",sp=0}},faq={{q="Where is the Pig and Whistle Tavern located?",a="The Pig and Whistle Tavern stands in Old Town, the eastern district of Stormwind City known for its military barracks, rogue dens, and working-class quarters.",al={"where is pig and whistle","pig and whistle location","old town tavern"}},{q="Who frequents the tavern?",a="The inn is popular among travelers, guards off duty, and veteran soldiers swapping stories of the First and Second Wars, alongside notable merchants like the Master of Cooking recipes, Kendor Kabonka.",al={"who is in pig and whistle","pig and whistle patrons"}},{q="What services does the tavern provide?",a="The Pig and Whistle functions as a full-service inn, allowing weary travelers to set their hearthstone, rest, and purchase food, drink, and specialized culinary recipes.",al={"is pig and whistle an inn","pig and whistle services"}}},ang={["profession:Cooking"]="Culinary artisans often make a pilgrimage to the tavern to seek out Kendor Kabonka, who sells an unmatched collection of rare cooking recipes from across Azeroth.",["faction:Alliance"]="For Alliance soldiers and travelers passing through the capital, the tavern offers a welcoming, unpretentious hearth and camaraderie with veterans of the realm's earlier wars."},kw={"cooking","inn","kendor kabonka","old town","pig and whistle","stormwind","tavern"},rel={"subzone:old-town","zone:stormwind","topic:stormwind-kingdom","topic:second-war","topic:alliance"},src={"Pig and Whistle Tavern"}}
E["subzone:royal-gallery"] = {t="subzone",n="Royal Gallery",z="stormwind",s="Tucked away inside Stormwind Keep past the courtyard garden, the Royal Gallery serves as a quiet hall of remembrance. It displays magnificent statues and fine works of art honoring prominent figures from the kingdom's history and the Grand Alliance.",h="Tucked away inside Stormwind Keep past the courtyard garden, the Royal Gallery serves as a quiet hall of...",sec={{t="A Hall of Heroes",b="The Royal Gallery sits adjacent to the Royal Library, just beyond the verdant interior garden of Stormwind Keep. The hall houses statues of towering figures who shaped the realm: King Llane Wrynn, the fallen ruler of Stormwind; Grand Admiral Daelin Proudmoore of Kul Tiras; and Mara Fordragon, ancestor of the current Regent. It serves as both a private museum of noble heritage and a quiet retreat for courtly visitors like Lady Dena Kennedy.",sp=0}},faq={{q="Where is the Royal Gallery located?",a="The Royal Gallery is located inside Stormwind Keep. Head through the keep past the small interior courtyard park, situated right next to the Royal Library.",al={"royal gallery location","how to get to royal gallery","where is it"}},{q="Which historical figures are commemorated here?",a="The gallery features grand statues honoring King Llane Wrynn, Grand Admiral Daelin Proudmoore, and Mara Fordragon, celebrating the lineage and valor of the kingdom and its closest allies.",al={"statues in royal gallery","who are the statues of","who is honored here"}},{q="Who can be found visiting the gallery?",a="Lady Dena Kennedy can frequently be found admiring the fine art and reflective atmosphere of the gallery.",al={"who is here","npcs in royal gallery","lady dena kennedy"}},{q="What is the difference between the Royal Gallery and the Royal Library?",a="While situated immediately next to one another in the royal wing of Stormwind Keep, they are distinct chambers. The library houses royal archives and scholars, while the gallery focuses on fine art and memorial sculpture.",al={"royal gallery vs library","is it part of the library"}}},ang={["faction:Alliance"]="The gallery stands as a quiet monument to the sacrifices of the Alliance, paying homage to legendary leaders like Daelin Proudmoore and King Llane.",["race:Human"]="For humans of Stormwind, this hall honors the legacy of House Wrynn and House Fordragon, preserving their royal heritage within the keep."},kw={"daelin proudmoore","dena kennedy","llane wrynn","mara fordragon","royal gallery","statues","stormwind keep"},rel={"subzone:stormwind-keep","subzone:royal-library","topic:stormwind-kingdom"},src={"Royal Gallery"}}
E["subzone:royal-library"] = {t="subzone",n="Royal Library",z="stormwind",s="Tucked deep within the stone wing of Stormwind Keep, the Royal Library preserves the collective memory, chronicle scrolls, and treatises of the kingdom. Under the watchful eye of Head Librarian Milton Sheaf, its shelves hold crucial records of ancient wars, lost legends, and the realms beyond the sea.",h="Tucked deep within the stone wing of Stormwind Keep, the Royal Library preserves the collective memory...",sec={{t="A Repository of the Realm",b="While Stormwind Keep bristles with armored guards and courtly intrigue, its Royal Library offers an island of scholarly quiet. Overseen by Milton Sheaf, the hall serves as the premier archive of southern human history, preserving surviving texts from before the First War alongside recent military chronicles and recovered tomes. Alliance scholars, priests, and travelers are free to browse its open treatises, which cover everything from the formation of the original Alliance of Lordaeron to the recent emergence of Thrall's Horde in Kalimdor.",sp=0},{t="Shadows Among the Shelves",b="The library has not always remained unmolested by outside conflicts. Following the Second War, the dangerous Book of Medivh was stored within its vaults, drawing Alterac infiltrators and death knights sent by Ner'zhul in a brazen castle raid.",sp=0}},faq={{q="Where is the Royal Library located?",a="It is located inside Stormwind Keep, the royal fortress resting in the eastern sector of Stormwind City. Once through the keep's grand foyer, take the corridors leading into the scholar and archive wings.",al={"where is the library","stormwind library location","how to find library"}},{q="Who runs the library?",a="Milton Sheaf serves as the head librarian. He manages the archive's records and assists scholars and adventurers seeking missing volumes or specific kingdom treatises.",al={"who is the librarian","head librarian","milton sheaf"}},{q="What kinds of books can be read here?",a="Visitors can read historical works covering the Alliance of Lordaeron, the Guardians of Tirisfal, the aftermath of the Second War, and reports regarding the New Horde, alongside regional histories of Stormwind and Alterac.",al={"books in library","readable lore books","what to read"}},{q="Why was the Book of Medivh kept here?",a="After the defeat of the Horde in the Second War, the dangerous spellbook was secured within the Royal Library for safekeeping. However, Alterac conspirators stole it, crossing paths with Teron Gorefiend's death knights who were staging an assault to claim it for Ner'zhul.",al={"book of medivh stormwind","medivh book stolen"}}},ang={["class:Mage"]="For scholars of the arcane, the library offers rare primary sources on Tirisfal's past, ancient dragon hunts, and the legacy of the Last Guardian.",["faction:Alliance"]="The shelves preserve the foundational treaties and war chronicles that bind the human, dwarven, and elven peoples across generations of conflict."},kw={"book of medivh","mathias shaw","milton sheaf","royal library","stormwind keep","stormwind library"},rel={"subzone:stormwind-keep","zone:stormwind","npc:milton-sheaf","quest:579","quest:337","topic:medivh","npc:mathias-shaw","topic:second-war"},src={"Royal Library"}}
E["subzone:si-7-stormwind-city"] = {t="subzone",n="SI:7 (Stormwind City)",z="stormwind",s="Tucked away in the eastern corner of Old Town, this unassuming stone manor houses the headquarters of SI:7, the kingdom of Stormwind's elite intelligence and espionage service. Behind its heavy doors, spymaster Master Mathias Shaw and his senior operatives quietly monitor threats to the realm, coordinating undercover agents across the kingdom.",h="Tucked away in the eastern corner of Old Town, this unassuming stone manor houses the headquarters of SI:7...",sec={{t="Heart of the Kingdom's Espionage",b="To the casual passerby in Old Town, this fortified stone structure looks little different from a standard manor or military barracks. In truth, it serves as the nerve center for Stormwind Intelligence, Section 7. Directed by Master Mathias Shaw, SI:7 gathers intelligence, conducts surveillance, and executes covert operations to protect the kingdom from subversion. While the city guard patrols the open cobblestones and the Royal Guard defends King's Square, SI:7 works in the margins, training handlers and dispatching stealthy operatives against foreign enemies, saboteurs, and domestic unrest alike.",sp=0},{t="A Watchful Eye on the Shadows",b="With King Varian Wrynn mysteriously missing and the Defias Brotherhood spreading chaos through Westfall and Duskwood, the headquarters hums with constant covert activity. Intelligence reports funnel into the building from deep-cover scouts across human lands. Down in the cellars and weapon-lined training rooms, lethal techniques are refined and missions assigned to counter threats long before they can reach the boy-king's throne room.",sp=1}},faq={{q="What is SI:7?",a="SI:7 stands for Stormwind Intelligence, Section 7. It is the premier covert espionage, reconnaissance, and assassination agency serving the Crown of Stormwind.",al={"what is si7","who are si:7","si 7 meaning"}},{q="Who leads SI:7 in Stormwind?",a="Master Mathias Shaw leads the organization from within the building. Mathias oversees all field assignments, intelligence networks, and strategic reconnaissance for the crown.",al={"who is the leader of si7","si7 boss","who runs si:7"}},{q="Where in the city is this building located?",a="The headquarters is situated in Old Town, tucked along the southeastern edge of the district near the canal and training yards.",al={"where is si7","si7 location","how to get to si7"}},{q="Why is SI:7 so interested in Westfall?",a="SI:7 tracks subversive activities throughout Stormwind's territories, and the Defias Brotherhood represents the most dangerous insurrection within the realm. Shaw's operatives have placed undercover agents and scouts throughout Westfall to pinpoint their leadership and disrupt their supply lines.",al={"defias brotherhood si7","why is si7 watching defias"}}},ang={["class:Rogue"]="For Alliance rogues, the SI:7 building is a vital professional hub offering advanced class training, poison supplies, and clandestine assignments direct from Spymaster Mathias Shaw.",["faction:Alliance"]="As the unseen foundation of Stormwind's defense, SI:7's intelligence network provides the Alliance military with crucial reconnaissance against threats to the throne."},kw={"barracks","defias","espionage","mathias shaw","old town","rogues","si7","si:7","spymaster","stormwind"},rel={"npc:mathias-shaw","subzone:old-town","zone:stormwind","quest:2300","quest:65","topic:defias-brotherhood","topic:stormwind-kingdom","subzone:ravenholdt-manor"},src={"SI:7 (Stormwind City)"}}
E["subzone:slaughtered-lamb"] = {t="subzone",n="Slaughtered Lamb",z="stormwind",s="Tucked away in Stormwind's Mage Quarter, the Slaughtered Lamb appears to be nothing more than a quiet, seedy tavern. Beneath its floorboards, however, sprawling catacombs hide the sanctum and training grounds of the Alliance's illicit warlocks.",h="Tucked away in Stormwind's Mage Quarter, the Slaughtered Lamb appears to be nothing more than a quiet, seedy...",sec={{t="A Thin Disguise",b="On the surface, the Slaughtered Lamb offers little more than dark corners and sparse patronage, attended by barkeep Jarel Moor, who warns casual visitors to stay away from the shadows. That warning is literal. Descending through the back passages reveals a subterranean complex of crypts and summoning circles, where human warlocks and transfer practitioners from Khaz Modan openly study fel arcana sheltered from the disapproving eyes of the Church of the Holy Light and the Kirin Tor.",sp=0},{t="The Noble's Tab",b="Operating a fel coventry in the heart of the capital invites constant peril. When Lord Baurles K. Wishock discovered the warlocks lurking in the basement, he threatened to rally the House of Nobles and petition the throne for a full investigation. In truth, the aristocrat was merely trying to dodge a ruinous bar tab. Before his agitation could draw real scrutiny, Zardeth of the Black Claw arranged for Wishock to drink a fatal concoction, permanently silencing the meddler and preserving the haven's secrets.",sp=1}},faq={{q="What actually goes on under the Slaughtered Lamb?",a="The catacombs beneath the tavern serve as the hidden sanctum for Stormwind's warlocks. Practitioners of demonology and shadow magic gather there to teach apprentices, conduct summonings, and practice fel arts forbidden in the streets above.",al={"what is under slaughtered lamb","slaughtered lamb basement","who is in slaughtered lamb"}},{q="Does the Stormwind City Guard know about the warlocks?",a="The tavern operates under a precarious veil of plausible deniability. Fel magic is viewed with deep distrust by the Church of the Holy Light and the Mage Academy, forcing the coven to operate in secrecy and aggressively quiet anyone who threatens to expose them to the royal authorities.",al={"do guards know about warlocks","why aren't warlocks arrested","is slaughtered lamb illegal"}},{q="Who was Lord Wishock, and what happened to him?",a="Lord Baurles K. Wishock was an influential nobleman who ran up an enormous bar tab at the tavern. To escape paying his debts, he threatened to petition the House of Nobles to raid the warlock sanctum below. In response, Zardeth of the Black Claw orchestrated his discreet poisoning, protecting the coven.",al={"baurles wishock","lord wishock fate","who is wishock"},sp=1},{q="Why do dwarven and gnome warlocks come here?",a="Practitioners of dark magic are heavily persecuted in Ironforge. Aspiring warlocks from Khaz Modan are frequently directed to the Slaughtered Lamb to complete their training in the safety of Stormwind's hidden network.",al={"gnome warlocks stormwind","khaz modan warlocks"}}},ang={["class:Warlock"]="The catacombs below are your primary sanctuary in Stormwind, offering class trainers, demon-binding rituals, and tasks essential to mastering the dark arts.",["faction:Alliance"]="While the Alliance champions the Light and order, the Slaughtered Lamb reveals the kingdom's unspoken willingness to tolerate dark magic in its shadow."},kw={"catacombs","jarel moor","mage quarter","slaughtered lamb","stormwind","warlock","wishock","zardeth"},rel={"subzone:mage-quarter","zone:stormwind","quest:1715","quest:335","quest:397","npc:zardeth-of-the-black-claw","npc:lord-baurles-k-wishock","topic:house-of-nobles"},src={"Slaughtered Lamb"}}
E["subzone:stormwind-keep"] = {t="subzone",n="Stormwind Keep",z="stormwind",s="Stormwind Keep stands high above the capital as the stone fortress and seat of power for the Kingdom of Stormwind. Rebuilt after its ruin in the First War, it currently houses the royal court of the young boy-king Anduin Wrynn and his regent, Highlord Bolvar Fordragon.",h="Stormwind Keep stands high above the capital as the stone fortress and seat of power for the Kingdom of...",sec={{t="The Rebuilt Citadel",b="Perched upon a plateau overlooking the entire city, Stormwind Keep serves as both a palace and a military bastion. The original stronghold was burned to the ground by the Old Horde when King Llane was assassinated near the end of the First War. Raised anew upon the old foundations after the Alliance reclaimed the kingdom, the reconstructed keep houses not only the grand throne room and the War Room, but peaceful garden courtyards and the expansive Royal Library.",sp=0},{t="A Divided Court",b="Behind the keep's banners and polished stone lies an uneasy peace. With King Varian Wrynn mysteriously missing en route to a diplomatic summit at Theramore, governance rests on ten-year-old King Anduin Wrynn. Effective rule falls to Highlord Bolvar Fordragon and the noble Lady Katrana Prestor. While Bolvar handles defense and military affairs, court politics remain paralyzed by aristocratic infighting, leaving the outlying territories vulnerable and the crown deeply distracted.",sp=1}},faq={{q="Who rules in Stormwind Keep right now?",a="King Anduin Wrynn technically holds the throne, but because he is only ten years old, Highlord Bolvar Fordragon governs as regent alongside Lady Katrana Prestor as royal advisor.",al={"who is in charge","who leads stormwind","who is the king"}},{q="What happened to King Varian Wrynn?",a="King Varian vanished under mysterious circumstances while traveling across the sea to a peace conference in Theramore. His sudden disappearance left the throne vacant, forcing Bolvar and the court to crown young Anduin to ensure political stability.",al={"where is varian","varian missing","what happened to the king"}},{q="Was the keep destroyed in the First War?",a="Yes. Following the murder of King Llane Wrynn by Garona, the Old Horde overwhelmed the city and completely razed the keep. The current fortress was rebuilt upon the ancient foundations after the Alliance prevailed in the Second War.",al={"did the orcs destroy the keep","first war castle destruction"}},{q="What major wings can be visited inside the keep?",a="The complex contains the main throne room, the War Room directly behind it, the Petitioner's Chamber for visiting supplicants, an open garden courtyard, the Royal Gallery, and the Royal Library.",al={"keep rooms","what is inside the keep","wings of stormwind keep"}}},ang={["faction:Alliance"]="The keep is the heart of the Alliance's eastern military command, where Bolvar Fordragon and the marshals direct defenses against rising threats across Elwynn, Westfall, and beyond.",["race:Human"]="Rebuilt from ashes after the devastation of the First War, the fortress stands as a testament to the resilience and pride of Stormwind's people."},kw={"anduin wrynn","bolvar fordragon","castle stormwind","katrana prestor","royal library","stormwind keep","throne room","war room"},rel={"topic:varian-wrynn","subzone:war-room","subzone:royal-library","subzone:petitioner-s-chamber","topic:stormwind-kingdom","topic:first-war"},src={"Stormwind Keep"}}
E["subzone:stormwind-stockade"] = {t="subzone",n="Stormwind Stockade",z="stormwind",s="Tucked away beneath the canals along the northern edge of the Mage Quarter, the Stockade serves as Stormwind's high-security penitentiary. Intended to lock away murderers, political dissidents, and foreign enemies, the subterranean fortress has recently collapsed into total chaos following a coordinated inmate rebellion.",h="Tucked away beneath the canals along the northern edge of the Mage Quarter, the Stockade serves as...",sec={{t="A Prison Under Siege",b="Ordinarily overseen by Warden Thelwater, the Stockade is where the kingdom deposits its most volatile prisoners, ranging from cutthroats and Defias operatives to captured Blackrock orcs and Dark Iron dwarves. However, a violent uprising orchestrated by the cunning Defias conspirator Bazil Thredd has entirely displaced the prison guards. The inmates now roam freely in the lower cells, turning the fortress into a fortress of riots. Thelwater, having barely secured the entry thresholds, relies on independent adventurers to plunge into the subterranean corridors and suppress the revolt before it spills out into the canals.",sp=0},{t="Bureaucracy and Backroom Schemes",b="The Stockade holds more than ordinary street convicts; it has long served as a bargaining chip for the kingdom's corrupt House of Nobles. Murderers and high-value prisoners who received death sentences elsewhere—such as the graverobber Dextren Ward from Duskwood or the Blackrock warlord Targorr the Dread from Redridge—have had their executions delayed by aristocratic interference to serve as political pawns. Even neighboring Ironforge has taken notice, covertly hiring mercenaries to execute dangerous inmates like Kam Deepfury when human bureaucracy stalls rightful justice.",sp=1}},faq={{q="Where is the entrance to the Stockade located?",a="The entrance sits along the canal district in Stormwind City, tucked on the northern bend right next to the bridge leading into the Mage Quarter. A guarded doorway leads down a stone stairwell directly into the subterranean cells.",al={"stockade entrance","how to get to stockades","stockade location"}},{q="Who started the riot inside the prison?",a="The revolt was planned and ignited by Bazil Thredd, a high-ranking Defias Brotherhood ringleader imprisoned within the compound. Under his command, the prisoners overpowered the guards, seized armaments, and established total control of the underground cellblocks.",al={"who is bazil thredd","who leads the stockade riot","who runs the stockade"}},{q="Why are there orcs and Dark Iron dwarves in a Stormwind jail?",a="Stormwind captures high-priority hostiles from across its contested territories. Notably, Targorr the Dread was seized from the Redridge Mountains, and Kam Deepfury represents the Dark Iron threat. Rather than being swiftly executed, many were brought here as military prisoners or kept alive by noble decree for political leverage.",al={"why are there orcs in stockades","dark iron prisoners stockade"}},{q="Why are Duskwood and Redridge asking people to kill prisoners here?",a="Outlying settlements like Darkshire and Lakeshire sentenced criminals like Dextren Ward and Targorr the Dread to die, only to see the House of Nobles stay their executions. Frustrated by Stormwind's bureaucratic meddling, local leaders quietly enlist sellswords to bypass royal paperwork and finish the job.",al={"duskwood stockade quest","crime and punishment","what comes around"}}},ang={["faction:Alliance"]="The Stockade sits directly in the capital, making its suppression vital to civil defense; clearing its halls exposes just how heavily the Defias Brotherhood has penetrated Stormwind.",["class:Rogue"]="The riot lays bare the operations of the Defias Brotherhood and Bazil Thredd, offering a glimpse into how deeply organized the criminal underworld has become right under the crown's nose."},kw={"bazil thredd","canals","defias","dextren ward","kam deepfury","prison","riot","stockade","stormwind","targorr","warden thelwater"},rel={"zone:stockade","zone:stormwind","npc:warden-thelwater","quest:389","quest:391","topic:defias-brotherhood","npc:targorr-the-dread","npc:dextren-ward"},src={"Stormwind Stockade"}}
E["subzone:stormwind-stockade-classic"] = {t="subzone",n="Stormwind Stockade (Classic)",z="stormwind",s="The Stormwind Stockade is a fortified underground prison beneath the canal district of Stormwind City. Originally built to contain petty criminals, violent mercenaries, and political subversives, it has recently plunged into chaos following a violent inmate revolt.",h="The Stormwind Stockade is a fortified underground prison beneath the canal district of Stormwind City.",sec={{t="A Prison in Revolt",b="Tucked away off the canals between Old Town and the Mage Quarter, the Stockade serves as the primary penal facility of the Kingdom of Stormwind. Presided over by Warden Thelwater, the subterranean complex houses an assortment of the realm's most dangerous malefactors: cutthroats of the Defias Brotherhood, a marauding Blackrock orc, an ogre, and even an infiltrating Dark Iron dwarf. Recently, a coordinated prison riot orchestrated by the cunning felon Bazil Thredd overwhelmed the garrison, driving out surviving guards and leaving the convicts in full control of the interior halls.",sp=0},{t="Bureaucracy and Retribution",b="The disaster within the Stockade exposes deep cracks in Stormwind's governance. Several notorious inmates, such as the Blackrock terror Targorr the Dread and the ghoul-hunting grave robber Dextren Ward, had long been sentenced to death, yet were kept alive due to endless stays of execution arranged by influential nobles. Frustrated by aristocratic stalling, neighboring settlements like Lakeshire and Darkshire, alongside the dwarven garrison at Dun Modr, have circumvented royal channels entirely, contracting outside adventurers to march in and execute key ringleaders amidst the bedlam.",sp=1}},faq={{q="Where is the Stockade located?",a="The Stockade entrance is situated inside Stormwind City along the northern canal bank, bridging the passage between Old Town and the Cathedral and Mage districts.",al={"stockade entrance","how to get to stockade","stockade location"}},{q="Who is currently running the prison?",a="While Warden Thelwater is the official warden, he was driven out during the rebellion. The facility is currently under the de facto control of the prisoner who instigated the uprising, Bazil Thredd, alongside allied Defias rioters.",al={"who is in charge of stockade","stockade boss","bazil thredd"}},{q="Why are there orcs and Dark Iron dwarves locked up in Stormwind?",a="Stormwind holds high-value prisoners of war and saboteurs here. Targorr the Dread is a captured Blackrock orc raider from the nearby mountains, while Kam Deepfury is a hostile Dark Iron dwarf imprisoned for subversion against the Alliance.",al={"why are there orcs in stockade","kam deepfury","targorr the dread"}},{q="Why were condemned murderers kept alive instead of executed?",a="Bureaucracy and political interference from high-ranking Stormwind nobles repeatedly stalled executions for convicts like Dextren Ward and Targorr, sparking outrage from outer territories such as Redridge and Duskwood.",al={"why werent they executed","stormwind nobles","dextren ward execution"}}},ang={["faction:Alliance"]="The riot directly beneath the capital's streets is an acute humiliation for Highlord Bolvar Fordragon's administration, showing how vulnerable Stormwind is from within while the king remains absent.",["race:Human"]="For humans of the outlying towns, the Stockade's dysfunction proves that the House of Nobles cares far more for legal red tape in the capital than protecting border settlements from murderers."},kw={"bazil thredd","defias","dextren ward","kam deepfury","prison","stockade","stormwind stockade","targorr the dread","uprising","warden thelwater"},rel={"zone:stockade","npc:warden-thelwater","topic:defias-brotherhood","npc:targorr-the-dread","npc:kam-deepfury","npc:dextren-ward","zone:stormwind"},src={"Stormwind Stockade (Classic)"}}
E["subzone:trade-district"] = {t="subzone",n="Trade District",z="stormwind",s="The Trade District is the bustling commercial heart of Stormwind City, located immediately past the main gates and the Valley of Heroes. It serves as the primary hub for adventurers and citizens alike, housing the city's central bank, auction house, guild registry, and diverse merchant shops.",h="The Trade District is the bustling commercial heart of Stormwind City, located immediately past the main...",sec={{t="The Crossroads of Commerce",b="Crossing beneath the stone arches from the Valley of Heroes brings travelers directly into the Trade District. This vibrant open plaza acts as Stormwind's primary marketplace and logistical hub. At its center stands the Auction House, flanked nearby by the Stormwind Counting House, the city's main bank, and the popular tavern known as The Gilded Rose. The district directly bridges the gap between the military enclave of Old Town, the serene Cathedral Square, and the arcane avenues of the Mage Quarter, ensuring that coin, raw goods, and adventuring supplies circulate swiftly through the realm.",sp=0},{t="Bazaars and Guild Halls",b="Every essential commodity can be acquired along the paved avenues and flanking canals. Weapon smiths at Weller's Arsenal and Lionheart Armory supply blades and mail, fletchers peddle bows at The Empty Quiver, and artisanal stalls offer everything from fresh flowers to fine aged vintages from the Gallina Winery. Just inside the gates, the Stormwind Visitor's Center coordinates newly registered charters and tabard designs for organized adventuring guilds, while an elevated ramp on the eastern side climbs toward the Gryphon Roost, linking the capital's mercantile life to the rest of the Alliance territories.",sp=0}},faq={{q="Where is the Trade District located?",a="The Trade District sits just past the city's main entrance gates and the Valley of Heroes. It connects directly to Cathedral Square to the northwest, Old Town to the east, and the Mage Quarter across the canals to the southwest.",al={"trade district location","where is trade district","how to get to trade district"}},{q="Where can I find the bank and the inn?",a="The Stormwind Counting House (the primary city bank) and The Gilded Rose inn are situated along the southwest perimeter of the Trade District, directly convenient to the main thoroughfare.",al={"trade district bank","gilded rose location","stormwind bank trade district"}},{q="Where do I register a guild or design a tabard in Stormwind?",a="The Stormwind Visitor's Center, located on your left immediately upon entering the Trade District from the city gates, houses the Guild Master and tabard design services.",al={"guild master stormwind","guild registrar","make a guild"}},{q="Where can I take a gryphon flight from the Trade District?",a="A stone ramp on the eastern side of the Trade District leads directly up to the Gryphon Roost, where the flight master dispatches gryphons across the kingdom and beyond.",al={"flight master stormwind","gryphon roost stormwind","where is flight master"}}},ang={["faction:Alliance"]="For Alliance champions, the Trade District is the quintessential hub for banking, trading at the Auction House, organizing guilds, and taking flight across the Eastern Kingdoms."},kw={"auction house","bazaar","counting house","gilded rose","gryphon roost","stormwind","trade district","visitor center"},rel={"zone:stormwind","subzone:valley-of-heroes","subzone:gryphon-roost","subzone:cathedral-square","subzone:old-town","subzone:mage-quarter","subzone:canals-stormwind-city"},src={"Trade District"}}
E["subzone:valley-of-heroes"] = {t="subzone",n="Valley of Heroes",z="stormwind",s="The Valley of Heroes forms the monumental southern entrance to Stormwind City, carrying travellers across a stone bridge spanning the moat. Flanked by towering statues honoring the leaders of the Alliance Expedition to Draenor, it serves as both an awe-inspiring welcome and a heavily fortified checkpoint.",h="The Valley of Heroes forms the monumental southern entrance to Stormwind City, carrying travellers across a...",sec={{t="A Monument to the Lost",b="Erected during the grand rebuilding of Stormwind following the Second War, the statues lining the causeway commemorate the commanders of the Alliance Expedition. These champions marched through the Dark Portal into the orcish homeworld of Draenor to seal the rift forever, giving their lives so Azeroth might survive. Visitors proceeding north toward the Trade District pass beneath the visages of Archmage Khadgar, Kurdran Wildhammer, Ranger-Captain Alleria Windrunner, Force Commander Danath Trollbane, and High General Turalyon.",sp=0},{t="The City Bastion",b="Beyond its ceremonial role, the valley is the primary defensive choke point guarding Stormwind from overland invasion. The approaches are overseen by General Marcus Jonathan, commander of the city guard, who monitors all traffic entering and departing through the great gates astride his steed. Flanking commanders, including Major Mattingly and Field Marshal Stonebridge, maintain vigilance alongside rows of seasoned guards, ensuring the capital remains secure against external threats.",sp=0}},faq={{q="Who are the statues lining the path?",a="The five colossal monuments depict the legendary commanders of the Sons of Lothar who led the Alliance Expedition to Draenor: High General Turalyon, Ranger-Captain Alleria Windrunner, Archmage Khadgar, Kurdran Wildhammer, and Force Commander Danath Trollbane.",al={"statues in stormwind","who are the heroes","valley statues","names on statues"}},{q="Why were these monuments placed at the city gate?",a="Constructed during the city's restoration after the Second War, the statues serve as an enduring tribute to the heroes assumed lost during the destruction of Draenor. They remind all who enter of the steep price paid to keep the kingdom safe.",al={"why build statues here","valley of heroes purpose"}},{q="Who commands the guards stationed at the entrance?",a="General Marcus Jonathan, the supreme commander of the Stormwind City Guard, oversees the security of the valley directly from the front lines, supported by officers such as Major Mattingly and Field Marshal Stonebridge.",al={"guard captain","who is the guy on the horse","who leads stormwind defense"}},{q="Where does the Valley of Heroes lead?",a="Heading north over the bridge brings travelers directly into Stormwind City's bustling Trade District, while heading south exits the gates into the pastoral forests of Elwynn.",al={"where does bridge go","directions stormwind gate"}}},ang={["faction:Alliance"]="Every citizen of the Grand Alliance reveres the valley as a solemn testament to racial cooperation, honoring human, high elven, and dwarven martyrs side by side.",["class:Paladin"]="The statue of General Turalyon stands as a profound inspiration to paladins, immortalizing one of the original champions of the Knights of the Silver Hand."},kw={"alleria","danath","khadgar","kurdran","marcus jonathan","stormwind gate","turalyon","valley of heroes"},rel={"subzone:stormwind-gate","zone:stormwind","zone:elwynn","subzone:trade-district","npc:general-marcus-jonathan","topic:alliance","topic:second-war","subzone:dark-portal"},src={"Valley of Heroes"}}
E["subzone:war-room"] = {t="subzone",n="War Room",z="stormwind",s="Tucked deep inside Stormwind Keep, the War Room serves as the strategic nerve center of the Alliance military. Ringed with armaments, historical war tomes, and tactical charts, it is where generals and strategists monitor distant fronts and coordinate the defense of the kingdom.",h="Tucked deep inside Stormwind Keep, the War Room serves as the strategic nerve center of the Alliance military.",sec={{t="Nerve Center of the Keep",b="Branching off from the grand chambers of Stormwind Keep, the War Room is outfitted specifically for military logistics and high-level campaign planning. Its stone walls are decorated with rows of armaments, including swords, blunderbusses, and even heavy artillery cannons. Piles of military treatises and historical chronicles—such as accounts of the Second War, the Fall of Stormwind, and the Battle of Grim Batol—stand stacked on nearby tables. At the room's core lies a large tactical map table, allowing commanders and battlemasters to assess Alliance deployments across Azeroth while the royal court handles matters of state just steps away.",sp=0}},faq={{q="Where is the War Room located?",a="The War Room is located inside Stormwind Keep, situated beyond the central corridors of the royal fortress. It is easily recognized by its heavy fortifications, weapon racks, and large tactical strategy table.",al={"war room location","how to find war room","where is the map room"}},{q="What is the purpose of this room?",a="It serves as the strategic planning headquarters for the Alliance military within Stormwind. High commanders and battlemasters gather here to review intelligence, coordinate troop movements, and study historical and ongoing conflicts.",al={"what is war room for","war room purpose","why does the keep have a war room"}},{q="What historical lore can be found here?",a="The room houses several important Alliance historical volumes detailing pivotal conflicts, including accounts of the Dark Portal and the Fall of Stormwind, the Battle of Grim Batol, and the War of the Spider.",al={"war room books","books in stormwind keep","historical tomes war room"}}},ang={["faction:Alliance"]="For Alliance soldiers and champions, the War Room represents the tactical brain of the realm's defense against lingering threats across the Eastern Kingdoms and beyond.",["class:Warrior"]="Surrounded by heavy munitions and strategic maps, martial commanders will appreciate the thorough military organization maintained inside the keep."},kw={"battlemasters","dark portal","grim batol","map room","stormwind keep","strategy table","war room"},rel={"subzone:stormwind-keep","zone:stormwind","topic:stormwind-kingdom","topic:alliance","subzone:grim-batol","subzone:dark-portal"},src={"War Room"}}
E["topic:terenas-menethil-ii"] = {t="topic",n="Terenas Menethil II",z="stormwind",s="King Terenas Menethil II was the venerable sovereign of Lordaeron who ruled for over five decades and forged the original Alliance of Lordaeron during the Second War. Renowned as a wise and diplomatic leader, he shielded humanity from the initial Horde invasion and sheltered the young Prince Varian Wrynn. His tragic murder by his corrupted son, Prince Arthas, directly triggered the collapse of Lordaeron to the Scourge.",h="King Terenas Menethil II was the venerable sovereign of Lordaeron who ruled for over five decades and forged...",sec={{t="Architect of the Alliance",b="When refugees from Stormwind arrived in the north led by Sir Anduin Lothar, King Terenas Menethil II answered their call. Convening the monarchs of the fractured human kingdoms alongside envoys from Ironforge and Quel'Thalas, Terenas orchestrated the formation of the Alliance of Lordaeron. Rather than seizing military command for himself, he wisely nominated Lothar as supreme commander, uniting humanity's kingdoms for the first time in millennia to triumph over the Old Horde.",sp=0},{t="The Strains of Victory",b="In the wake of the Second War, Terenas insisted upon placing surviving orcs into internment camps rather than executing them, believing that peace could be preserved if their demonic fury dissipated. This humane but costly decision placed staggering taxes on Lordaeron's allies. Gilneas sealed itself behind the Greymane Wall, Stromgarde seceded over political disputes, and the high elves withdrew entirely, leaving Terenas to shoulder the burden with a fracturing coalition.",sp=0},{t="The Fall of the Throne",b="In his twilight years, Terenas faced rising orc revolts led by Thrall, whispers of northern death cults, and a mysterious plague. When a wandering prophet warned the king to abandon Lordaeron and flee across the sea to Kalimdor, Terenas dismissed him as a madman. Shortly after, Prince Arthas returned from his northern campaign hailed as a victor. In the midst of the royal celebrations, Arthas knelt before his father, drew the runeblade Frostmourne, and ran Terenas through the heart, shattering the kingdom forever.",sp=2}},faq={{q="Who was King Terenas Menethil II?",a="He was the benevolent and revered monarch of the kingdom of Lordaeron. Ruling for more than fifty years, he stood at the center of northern politics, founded the Alliance of Lordaeron to battle the Horde in the Second War, and governed from Capital City until his murder.",al={"who is terenas","terenas menethil","king of lordaeron"}},{q="How did Terenas die?",a="Terenas was murdered directly in his own throne room by his son, Prince Arthas Menethil. Arthas, having succumbed to madness and corruption through the runeblade Frostmourne during his expedition to Northrend, returned to Capital City under the guise of victory and impaled his father through the heart.",al={"how did terenas die","arthas kills dad","terenas death"}},{q="What was Terenas's relationship with Stormwind?",a="Terenas played a pivotal role in Stormwind's survival. When the southern kingdom fell during the First War, he gave haven to its survivors and raised Prince Varian Wrynn alongside his own son Arthas, treating young Varian like a second son until Stormwind could be reclaimed and rebuilt.",al={"terenas and stormwind","terenas and varian","did terenas help stormwind"}},{q="Why did the Alliance of Lordaeron break apart under his rule?",a="Following the Second War, Terenas chose to imprison captive orcs in internment camps rather than execute them. The massive financial cost of these camps incited bitter outrage among the member realms. Gilneas constructed the Greymane Wall to isolate itself, Stromgarde departed over policy disputes, and the elves of Quel'Thalas withdrew entirely.",al={"why did alliance break","why did kingdoms leave lordaeron","internment camp taxes"}},{q="Did Terenas know about the Plague of Undeath?",a="Terenas was aware of strange cults and a spreading sickness in the north, but he underestimated the threat. Dalaran urged him to institute a strict quarantine of northern towns, yet Terenas hesitated, fearing further suffering for his people. He dispatched Prince Arthas and Uther the Lightbringer to investigate, unaware of the trap that awaited them.",al={"did terenas know about plague","terenas plague response"}},{q="Why didn't Terenas listen to the mysterious Prophet?",a="When a cloaked prophet appeared in his council chamber imploring him to evacuate Lordaeron's citizens west to Kalimdor, Terenas dismissed him as an unhinged zealot. Terenas believed that his armies, paladins, and sturdy kingdom could endure whatever trials approached, sealing the kingdom's doom.",al={"terenas and prophet","medivh and terenas","why didnt terenas flee"}}},ang={["race:Human"]="Humanity remembers King Terenas as a legendary patriarch who united the seven kingdoms against impossible odds, making his sudden betrayal and death at the hands of his own son an enduring national tragedy.",["faction:Alliance"]="The Grand Alliance of today owes its heritage to the coalition Terenas forged with Anduin Lothar to turn back the Old Horde during the Second War.",["class:Paladin"]="Terenas worked alongside Archbishop Alonsus Faol and Uther the Lightbringer to foster the Knights of the Silver Hand, guiding his own son into the order.",["race:Undead"]="For the Forsaken who once called Capital City home, Terenas was their last living sovereign, whose fall doomed the realm to the Scourge."},kw={"alliance of lordaeron","arthas","capital city","frostmourne","lordaeron","menethil","second war","terenas","third war","uther"},rel={"topic:lordaeron","topic:alliance-of-lordaeron","topic:second-war","topic:third-war","topic:varian-wrynn","topic:anduin-lothar","topic:scourge","subzone:greymane-wall"},src={"Terenas Menethil II"}}
E["zone:stormwind"] = {t="city",n="Stormwind City",z="stormwind",s="Stormwind City is the bustling capital of the Kingdom of Stormwind and the premier human bastion in the world following the fall of Lordaeron. Rebuilt from ashes by the Stonemasons Guild after its destruction in the First War, its magnificent white stone districts now house the heart of the Grand Alliance. Beneath its majestic canals and cathedrals, however, the city grapples with the sudden disappearance of King Varian Wrynn and brewing political intrigue.",h="Stormwind City is the bustling capital of the Kingdom of Stormwind and the premier human bastion in the world...",sec={{t="Rise from the Ashes",b="Founded over a millennium ago by the descendants of the Arathi, Stormwind stood for generations as a flourishing, self-sufficient realm. That golden era ended when the Orcish Horde poured through the Dark Portal, laying waste to the southern continent and razing the capital to the ground in the First War. Survivors led by Sir Anduin Lothar fled north across the Great Sea to Lordaeron. Following the Horde's defeat in the Second War, King Terenas Menethil II and the Alliance funded a complete reconstruction. The Stonemasons Guild painstakingly rebuilt the capital into New Stormwind—a gleaming citadel of polished white stone and canal-laced boroughs.",sp=0},{t="A Divided Court",b="Despite its outward majesty, the capital is locked in domestic turmoil. A dispute between the House of Nobles and the Stonemasons Guild over wages left the kingdom paralyzed by debt. The ensuing rioting claimed the life of Queen Tiffin Wrynn and drove the exiled artisans into criminality as the Defias Brotherhood. Now, King Varian Wrynn has mysteriously vanished en route to a diplomatic summit. To avert panic, the crown was placed upon his young son, ten-year-old Prince Anduin Wrynn, with Highlord Bolvar Fordragon ruling as Regent and military commander alongside royal advisor Lady Katrana Prestor.",sp=0},{t="Heart of the Grand Alliance",b="With Lordaeron overrun by the Scourge, Stormwind has inherited the mantle of humanity's greatest haven and the epicenter of the Alliance. It connects directly to the dwarven kingdom of Ironforge via High Tinker Mekkatorque's subterranean Deeprun Tram. Visitors crossing the Valley of Heroes are greeted by towering statues of the Sons of Lothar who vanished beyond the Dark Portal. From the spiritual beacon of the Cathedral of Light to the arcane studies within the Wizard's Sanctum, Stormwind stands as the supreme hub of trade, culture, and defense across the southern seas.",sp=0},{t="Shadows in the Keep",b="The discord plaguing the kingdom is no mere administrative accident. Lady Katrana Prestor has covertly guided the decisions of the House of Nobles, inflaming hostility with the stonemasons and willfully neglecting appeals for military relief from outlying settlements like Westfall and Redridge. By whispering poison into the ears of Highlord Bolvar and dividing the realm's attention, she works to keep Stormwind’s legions idle and divided while unrest festering beyond the city walls threatens the throne itself.",sp=2}},faq={{q="Who rules Stormwind right now?",a="Ten-year-old Prince Anduin Wrynn holds the crown, but actual governance is handled by Highlord Bolvar Fordragon, who acts as Regent of Stormwind and supreme commander of its military. Bolvar relies heavily on the counsel of royal advisor Lady Katrana Prestor while King Varian Wrynn remains missing.",al={"current king","who is the king","who leads stormwind","king of stormwind"}},{q="What happened to King Varian Wrynn?",a="King Varian vanished under suspicious circumstances while traveling by ship to a diplomatic summit in Theramore. His disappearance was kept quiet to maintain stability, though rumors run rampant through the streets and countryside.",al={"where is varian","missing king","varian gone","varian wrynn missing"}},{q="Why was the city rebuilt, and by whom?",a="The original city was burned to the ground by the Orcish Horde during the First War. After the Second War, the Stonemasons Guild, led by master craftsman Edwin VanCleef, painstakingly rebuilt the capital out of gleaming white stone with financial backing from the Alliance of Lordaeron.",al={"who rebuilt stormwind","stonemasons guild","new stormwind","city rebuilding"}},{q="Why did the stonemasons rebel against the crown?",a="The House of Nobles amassed heavy debts expanding Stormwind's military and refused to pay the Stonemasons Guild their promised wages. When Edwin VanCleef demanded restitution, the nobles disbanded the guild. The workers rioted, Queen Tiffin Wrynn was killed by a thrown rock, and the exiled stonemasons formed the Defias Brotherhood.",al={"defias origin","why defias mad","stonemasons riot","queen tiffin death"}},{q="Who are the giant statues in the Valley of Heroes?",a="The statues honor the Sons of Lothar: General Turalyon, Ranger Captain Alleria Windrunner, Archmage Khadgar, Kurdran Wildhammer, and Danath Trollbane. They were raised to commemorate the heroes who ventured through the Dark Portal to draenor to seal the rift and protect Azeroth.",al={"statues at the entrance","valley of heroes statues","sons of lothar statues"}},{q="How does Stormwind connect to Ironforge?",a="Stormwind is connected to Ironforge by the Deeprun Tram, a subterranean railway built by High Tinker Gelbin Mekkatorque and commissioned by King Magni Bronzebeard to enable swift trade and rapid military reinforcement between both capitals.",al={"deeprun tram","train to ironforge","how to get to ironforge"}},{q="Why isn't Stormwind sending troops to help Westfall and Redridge?",a="The royal court, heavily advised by Lady Katrana Prestor, insists the city cannot spare troops from its own walls and immediate borders. With the kingdom's finances stressed and political infighting paralyzing the House of Nobles, regional towns have been abandoned to rely on local militias.",al={"stormwind army missing","why no help for westfall","reinforcements refused"}}},ang={["race:Human"]="Stormwind stands as your people's last great seat of sovereign power following the destruction of Lordaeron, Alterac, and Dalaran in the north.",["faction:Alliance"]="As the most populous metropolis within the Grand Alliance, Stormwind provides naval might, spiritual grounding, and vital diplomatic leadership.",["class:Paladin"]="The Cathedral of Light serves as the supreme sanctuary of your faith in the south, training knights of the Silver Hand and upholding justice.",["class:Rogue"]="Beneath the pristine stone streets lies the SI:7 headquarters in Old Town, operating the Alliance's primary intelligence and espionage network.",["race:Dwarf"]="Through the Deeprun Tram, your kin in the Dwarven District maintain deep commercial ties and forge brotherly military bonds with the human kingdom."},kw={"anduin","bolvar","cathedral","deeprun","prestor","stonemasons","stormwind","vancleef","wrynn"},rel={"topic:stormwind-kingdom","subzone:stormwind-keep","subzone:valley-of-heroes","subzone:cathedral-of-light","subzone:deeprun-tram","topic:defias-brotherhood"},src={"Stormwind City"}}
